# 1. Canlı İşlem Konsolunu Başlat ve Yapılandır
try {
    $host.UI.RawUI.WindowTitle = "TemizWin - Canlı İşlem Günlüğü"
} catch {}

Write-Host "=====================================================================" -ForegroundColor Cyan
Write-Host "                    TEMIZWIN - CANLI ISLEM GUNLUGU                   " -ForegroundColor Yellow
Write-Host "         Windows 10/11 Hizli Bakim, Temizlik ve Optimizasyon         " -ForegroundColor Cyan
Write-Host "=====================================================================" -ForegroundColor Cyan

# 2. Yonetici Yetkisi Kontrolu ve Otomatik Yukseltme (Self-Elevation)
$script:isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $script:isAdmin) {
    try {
        Write-Host "[!] Yonetici yetkisi gerekiyor. UAC yetki yukseltme penceresi aciliyor..." -ForegroundColor Yellow
        $scriptPath = $PSCommandPath
        if (-not $scriptPath -or -not (Test-Path $scriptPath)) {
            $scriptPath = $MyInvocation.MyCommand.Path
        }
        if (-not $scriptPath -or -not (Test-Path $scriptPath)) {
            $scriptPath = Join-Path $PSScriptRoot "TemizWin.ps1"
        }
        try {
            Start-Process powershell.exe -ArgumentList "-NoExit -STA -NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`"" -Verb RunAs
            exit
        } catch {
            (New-Object -ComObject Shell.Application).ShellExecute("powershell.exe", "-NoExit -STA -NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`"", "", "runas", 1)
            exit
        }
    } catch {
        exit
    }
}

Write-Host "[*] Yonetici Yetkisi: Aktif (Administrator)" -ForegroundColor Green
Write-Host "[*] Grafik Arayuz (WPF) baslatiliyor, lutfen bekleyin..." -ForegroundColor Gray

# ------------------------------------------------------------------------------
# 3. Küresel Durum Bayrakları
# ------------------------------------------------------------------------------
$script:isHealthRunning = $false
$script:isCleaningRunning = $false

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Drawing, System.Windows.Forms, Microsoft.VisualBasic, System.Xml -ErrorAction SilentlyContinue
if (-not ("SRClient" -as [type])) {
    Add-Type -TypeDefinition @"
    using System;
    using System.Runtime.InteropServices;

    public static class SRClient {
        [DllImport("srclient.dll")]
        public static extern int SRRemoveRestorePoint(int index);
    }
"@ -ErrorAction SilentlyContinue
}

if (-not ("Win32Mem" -as [type]) -or -not ("ShellNotifyHelper" -as [type])) {
    Add-Type -TypeDefinition @"
    using System;
    using System.Runtime.InteropServices;

    public static class Win32Mem {
        [DllImport("ntdll.dll")]
        public static extern uint NtSetSystemInformation(int InfoClass, IntPtr Info, int Length);

        [DllImport("advapi32.dll", SetLastError = true)]
        public static extern bool OpenProcessToken(IntPtr ProcessHandle, uint DesiredAccess, out IntPtr TokenHandle);

        [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Auto)]
        public static extern bool LookupPrivilegeValue(string lpSystemName, string lpName, out long lpLuid);

        [DllImport("advapi32.dll", SetLastError = true)]
        public static extern bool AdjustTokenPrivileges(IntPtr TokenHandle, bool DisableAllPrivileges, ref TOKEN_PRIVILEGES NewState, int BufferLength, IntPtr PreviousState, IntPtr ReturnLength);

        [DllImport("kernel32.dll")]
        public static extern IntPtr GetCurrentProcess();

        [DllImport("kernel32.dll")]
        public static extern bool CloseHandle(IntPtr handle);
        [StructLayout(LayoutKind.Sequential, Pack = 1)]
        public struct TOKEN_PRIVILEGES {
            public int PrivilegeCount;
            public long Luid;
            public int Attributes;
        }

        public const int SystemMemoryListInformation = 80;
        public const int MemoryPurgeStandbyList = 4;

        public static bool SetPrivilege(string privilege) {
            IntPtr hToken;
            if (!OpenProcessToken(GetCurrentProcess(), 0x0028, out hToken)) return false;
            try {
                long luid;
                if (!LookupPrivilegeValue(null, privilege, out luid)) return false;
                TOKEN_PRIVILEGES tp = new TOKEN_PRIVILEGES();
                tp.PrivilegeCount = 1;
                tp.Luid = luid;
                tp.Attributes = 0x00000002;
                return AdjustTokenPrivileges(hToken, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero);
            } catch {
                return false;
            } finally {
                CloseHandle(hToken);
            }
        }

        public static bool PurgeStandbyList() {
            SetPrivilege("SeProfileSingleProcessPrivilege");
            SetPrivilege("SeIncreaseQuotaPrivilege");
            int command = MemoryPurgeStandbyList;
            GCHandle gcHandle = GCHandle.Alloc(command, GCHandleType.Pinned);
            try {
                uint result = NtSetSystemInformation(SystemMemoryListInformation, gcHandle.AddrOfPinnedObject(), Marshal.SizeOf(command));
                return (result == 0);
            } catch {
                return false;
            } finally {
                gcHandle.Free();
            }
        }
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct ANIMATIONINFO {
        public uint cbSize;
        public int iMinAnimate;
    }

    public static class ShellNotifyHelper {
        [DllImport("shell32.dll")]
        public static extern void SHChangeNotify(int wEventId, int uFlags, IntPtr dwItem1, IntPtr dwItem2);

        [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Auto)]
        public static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam, uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);

        [DllImport("user32.dll", CharSet = CharSet.Auto)]
        public static extern bool UpdatePerUserSystemParameters();

        [DllImport("user32.dll", SetLastError = true)]
        public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, ref ANIMATIONINFO pvParam, uint fWinIni);

        [DllImport("user32.dll", SetLastError = true)]
        public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, ref int pvParam, uint fWinIni);

        public static void SetAnimations(bool enable) {
            int val = enable ? 1 : 0;
            ANIMATIONINFO ai = new ANIMATIONINFO();
            ai.cbSize = 8;
            ai.iMinAnimate = val;
            try { SystemParametersInfo(0x0049, 8, ref ai, 0x02); } catch {}
            try { SystemParametersInfo(0x1042, 0, ref val, 0x02); } catch {}
            try { SystemParametersInfo(0x1003, 0, ref val, 0x02); } catch {}
            try { SystemParametersInfo(0x1005, 0, ref val, 0x02); } catch {}
            try { SystemParametersInfo(0x1017, 0, ref val, 0x02); } catch {}
        }
    }
"@ -ErrorAction SilentlyContinue
}

# ------------------------------------------------------------------------------
# Canlı Komut Akışı (Live Verbose / Debug Console Logger)
# ------------------------------------------------------------------------------
function Write-CmdLog([string]$tag, [string]$cmd, [string]$color = "Cyan") {
    $time = (Get-Date).ToString("HH:mm:ss")
    Write-Host "[$time] " -NoNewline -ForegroundColor DarkGray
    Write-Host "[$tag] " -NoNewline -ForegroundColor $color
    Write-Host $cmd -ForegroundColor Gray
}

# ------------------------------------------------------------------------------
# 3. WPF Arayüz Tasarımı (XAML)
# ------------------------------------------------------------------------------
[string]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="TemizWin"
        Height="740" Width="1020" MinHeight="700" MinWidth="960"
        WindowStartupLocation="CenterScreen"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent" ShowInTaskbar="True"
        FontFamily="Segoe UI" FontSize="13">

    <Window.Resources>
        <!-- Varsayılan Yazı Rengi -->
        <Style TargetType="TextBlock">
            <Setter Property="Foreground" Value="#F8FAFC"/>
        </Style>

        <!-- Pencere Kontrol Butonları -->
        <Style x:Key="WinCtrlBtn" TargetType="Button">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="#94A3B8"/>
            <Setter Property="FontSize" Value="14"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Width" Value="36"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bdr" Background="{TemplateBinding Background}" CornerRadius="6">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdr" Property="Background" Value="#22283A"/>
                                <Setter Property="Foreground" Value="#FFFFFF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="WinCloseBtn" TargetType="Button" BasedOn="{StaticResource WinCtrlBtn}">
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bdr" Background="{TemplateBinding Background}" CornerRadius="6">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdr" Property="Background" Value="#EF4444"/>
                                <Setter Property="Foreground" Value="#FFFFFF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Önayar Butonları (Chip) -->
        <Style x:Key="PresetChip" TargetType="Button">
            <Setter Property="Background" Value="#171A26"/>
            <Setter Property="Foreground" Value="#94A3B8"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Height" Value="32"/>
            <Setter Property="Padding" Value="14,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bdr" Background="{TemplateBinding Background}" CornerRadius="8" BorderBrush="#252C40" BorderThickness="1" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdr" Property="Background" Value="#22283C"/>
                                <Setter TargetName="bdr" Property="BorderBrush" Value="#38BDF8"/>
                                <Setter Property="Foreground" Value="#FFFFFF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Ana Ekran Menü Kartı Butonu -->
        <Style x:Key="MenuActionCard" TargetType="Button">
            <Setter Property="Background" Value="#111420"/>
            <Setter Property="BorderBrush" Value="#1D2338"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bdr" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="14" Padding="20">
                            <ContentPresenter/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdr" Property="Background" Value="#161B2E"/>
                                <Setter TargetName="bdr" Property="BorderBrush" Value="#4F46E5"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Birincil Eylem Butonu (Vurgulu) -->
        <Style x:Key="PrimaryBtn" TargetType="Button">
            <Setter Property="Background" Value="#4F46E5"/>
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Height" Value="36"/>
            <Setter Property="Padding" Value="18,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bdr" Background="{TemplateBinding Background}" CornerRadius="8" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdr" Property="Background" Value="#6366F1"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bdr" Property="Background" Value="#252A40"/>
                                <Setter Property="Foreground" Value="#64748B"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Sağlık Kartı Eylem Butonu -->
        <Style x:Key="ActionCardBtn" TargetType="Button">
            <Setter Property="Background" Value="#181E32"/>
            <Setter Property="Foreground" Value="#38BDF8"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="Padding" Value="12,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bdr" Background="{TemplateBinding Background}" CornerRadius="6" BorderBrush="#252E4A" BorderThickness="1" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdr" Property="Background" Value="#222B48"/>
                                <Setter TargetName="bdr" Property="BorderBrush" Value="#38BDF8"/>
                                <Setter Property="Foreground" Value="#FFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bdr" Property="Background" Value="#121624"/>
                                <Setter Property="Foreground" Value="#475569"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- CheckBox Özel Tasarımı -->
        <Style TargetType="CheckBox">
            <Setter Property="Foreground" Value="#F8FAFC"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="CheckBox">
                        <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                            <Border x:Name="bdrCheck" Width="18" Height="18" Background="#141826" BorderBrush="#2C3550" BorderThickness="1.5" CornerRadius="5" VerticalAlignment="Center">
                                <Path x:Name="chkTick" Data="M 3,9 L 7,13 L 15,4" Stroke="#FFFFFF" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Visibility="Collapsed" Margin="1"/>
                            </Border>
                            <ContentPresenter Margin="10,0,0,0" VerticalAlignment="Center"/>
                        </StackPanel>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="bdrCheck" Property="Background" Value="#4F46E5"/>
                                <Setter TargetName="bdrCheck" Property="BorderBrush" Value="#6366F1"/>
                                <Setter TargetName="chkTick" Property="Visibility" Value="Visible"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bdrCheck" Property="BorderBrush" Value="#6366F1"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Özel ScrollBar Tasarımı -->
        <Style TargetType="ScrollBar">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Width" Value="8"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ScrollBar">
                        <Grid Background="Transparent">
                            <Track x:Name="PART_Track" IsDirectionReversed="True">
                                <Track.Thumb>
                                    <Thumb>
                                        <Thumb.Template>
                                            <ControlTemplate TargetType="Thumb">
                                                <Border Background="#252D42" CornerRadius="4"/>
                                            </ControlTemplate>
                                        </Thumb.Template>
                                    </Thumb>
                                </Track.Thumb>
                            </Track>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
    
        <!-- Modern Dark ComboBox Toggle Button -->
        <ControlTemplate x:Key="DarkComboBoxToggleButton" TargetType="ToggleButton">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition />
                    <ColumnDefinition Width="28" />
                </Grid.ColumnDefinitions>
                <Border x:Name="Border" Grid.ColumnSpan="2" CornerRadius="6" Background="#161B2A" BorderBrush="#2D374D" BorderThickness="1" />
                <Path x:Name="Arrow" Grid.Column="1" HorizontalAlignment="Center" VerticalAlignment="Center" Data="M 0 0 L 4 4 L 8 0 Z" Fill="#38BDF8" StrokeThickness="1"/>
            </Grid>
            <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="true">
                    <Setter TargetName="Border" Property="BorderBrush" Value="#38BDF8" />
                    <Setter TargetName="Border" Property="Background" Value="#1C2337" />
                </Trigger>
            </ControlTemplate.Triggers>
        </ControlTemplate>

        <!-- Modern Dark ComboBox Item Style -->
        <Style x:Key="DarkComboBoxItem" TargetType="ComboBoxItem">
            <Setter Property="Background" Value="#161B2A"/>
            <Setter Property="Foreground" Value="#F8FAFC"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Padding" Value="10,7"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBoxItem">
                        <Border x:Name="ItemBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
                            <ContentPresenter />
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="ItemBorder" Property="Background" Value="#1E293B"/>
                                <Setter Property="Foreground" Value="#38BDF8"/>
                            </Trigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="ItemBorder" Property="Background" Value="#0F3858"/>
                                <Setter Property="Foreground" Value="#38BDF8"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Modern Dark ComboBox Style -->
        <Style x:Key="DarkComboBox" TargetType="ComboBox">
            <Setter Property="SnapsToDevicePixels" Value="true"/>
            <Setter Property="OverridesDefaultStyle" Value="true"/>
            <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Auto"/>
            <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Auto"/>
            <Setter Property="ScrollViewer.CanContentScroll" Value="true"/>
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="ItemContainerStyle" Value="{StaticResource DarkComboBoxItem}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBox">
                        <Grid>
                            <ToggleButton x:Name="ToggleButton" Template="{StaticResource DarkComboBoxToggleButton}" Grid.Column="2" Focusable="false"
                                          IsChecked="{Binding Path=IsDropDownOpen,Mode=TwoWay,RelativeSource={RelativeSource TemplatedParent}}" ClickMode="Press"/>
                            <ContentPresenter x:Name="ContentSite" IsHitTestVisible="False" Content="{TemplateBinding SelectionBoxItem}"
                                              ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}"
                                              Margin="12,5,28,5" VerticalAlignment="Center" HorizontalAlignment="Left" />
                            <Popup x:Name="Popup" Placement="Bottom" IsOpen="{TemplateBinding IsDropDownOpen}" AllowsTransparency="True" Focusable="False" PopupAnimation="Slide">
                                <Grid x:Name="DropDown" SnapsToDevicePixels="True" MinWidth="{TemplateBinding ActualWidth}" MaxHeight="{TemplateBinding MaxDropDownHeight}">
                                    <Border x:Name="DropDownBorder" Background="#161B2A" BorderThickness="1" BorderBrush="#2D374D" CornerRadius="6" Margin="0,3,0,0">
                                        <ScrollViewer Margin="2" SnapsToDevicePixels="True">
                                            <StackPanel IsItemsHost="True" />
                                        </ScrollViewer>
                                    </Border>
                                </Grid>
                            </Popup>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Modern Fluent Aç/Kapat Toggle Switch Stili -->
        <Style x:Key="ModernToggleSwitch" TargetType="CheckBox">
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="CheckBox">
                        <Grid Background="Transparent">
                            <Border x:Name="Track" Width="44" Height="24" CornerRadius="12" Background="#2A334A" BorderBrush="#3B4866" BorderThickness="1" SnapsToDevicePixels="True">
                                <Ellipse x:Name="Thumb" Width="18" Height="18" Fill="#94A3B8" HorizontalAlignment="Left" Margin="2,0,0,0"/>
                            </Border>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="Track" Property="Background" Value="#059669"/>
                                <Setter TargetName="Track" Property="BorderBrush" Value="#10B981"/>
                                <Setter TargetName="Thumb" Property="Fill" Value="#FFFFFF"/>
                                <Setter TargetName="Thumb" Property="HorizontalAlignment" Value="Right"/>
                                <Setter TargetName="Thumb" Property="Margin" Value="0,0,2,0"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Track" Property="Opacity" Value="0.9"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
</Window.Resources>

    <!-- Ana Pencere Gövdesi (Karanlık Cam Arkaplan + Yuvarlatılmış Köşeler) -->
    <Border Background="#0C0E14" BorderBrush="#1C2132" BorderThickness="1" CornerRadius="14">
        <Grid>
            <Grid.RowDefinitions>
                <RowDefinition Height="46"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
            </Grid.RowDefinitions>

            <!-- 1. BAŞLIK ÇUBUĞU (Sürüklenebilir) -->
            <Grid Grid.Row="0" x:Name="pnlTitleBar" Background="#0C0E14">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <!-- Logo ve Başlık -->
                <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center" Margin="18,0,0,0">
                    <Border Background="#4F46E5" Width="26" Height="26" CornerRadius="7" Margin="0,0,10,0">
                        <TextBlock Text="🛡️" FontSize="14" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <TextBlock Text="TemizWin" FontWeight="Bold" FontSize="15" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                    <TextBlock Text="PC Arındırıcı HK" FontSize="11" Foreground="#64748B" VerticalAlignment="Center" Margin="8,2,0,0"/>

                    <!-- Yönetici Rozeti -->
                    <Border x:Name="pnlAdminBadge" Background="#0D2E1F" BorderBrush="#10B981" BorderThickness="1" CornerRadius="6" Padding="8,2" Margin="14,0,0,0">
                        <TextBlock x:Name="lblAdminBadge" Text="🛡️ Yönetici modu" FontSize="11" FontWeight="SemiBold" Foreground="#34D399"/>
                    </Border>
                </StackPanel>

                <!-- Sağ Üst: RAM Optimize Rozeti, Saat & Kontrol Butonları -->
                <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,12,0">
                    <!-- Canlı RAM Rozeti & Boşalt Butonu -->
                    <Border Background="#131724" BorderBrush="#222C42" BorderThickness="1" CornerRadius="6" Padding="8,2" Margin="0,0,14,0" VerticalAlignment="Center">
                        <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                            <TextBlock Text="🧠 RAM: " FontSize="11" Foreground="#94A3B8" FontWeight="SemiBold" VerticalAlignment="Center"/>
                            <TextBlock x:Name="lblMainRamUsage" Text="Taranıyor..." FontSize="11" Foreground="#38BDF8" FontWeight="Bold" Margin="0,0,8,0" VerticalAlignment="Center"/>
                            <Button x:Name="btnOptimizeRam" Content="⚡ Boşalt" Height="22" Padding="8,0" VerticalAlignment="Center" Cursor="Hand" ToolTip="Uygulamaları yavaşlatmadan Windows bekleme (Standby) bellek önbelleğini temizler">
                                <Button.Style>
                                    <Style TargetType="Button">
                                        <Setter Property="Background" Value="#1E293B"/>
                                        <Setter Property="Foreground" Value="#38BDF8"/>
                                        <Setter Property="BorderBrush" Value="#38BDF8"/>
                                        <Setter Property="BorderThickness" Value="1"/>
                                        <Setter Property="FontSize" Value="10"/>
                                        <Setter Property="FontWeight" Value="Bold"/>
                                        <Setter Property="Cursor" Value="Hand"/>
                                        <Setter Property="Template">
                                            <Setter.Value>
                                                <ControlTemplate TargetType="Button">
                                                    <Border x:Name="bdr" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="4" Padding="{TemplateBinding Padding}">
                                                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                                    </Border>
                                                    <ControlTemplate.Triggers>
                                                        <Trigger Property="IsMouseOver" Value="True">
                                                            <Setter TargetName="bdr" Property="Background" Value="#0284C7"/>
                                                            <Setter TargetName="bdr" Property="BorderBrush" Value="#38BDF8"/>
                                                            <Setter Property="Foreground" Value="#FFFFFF"/>
                                                        </Trigger>
                                                        <Trigger Property="IsPressed" Value="True">
                                                            <Setter TargetName="bdr" Property="Background" Value="#0369A1"/>
                                                        </Trigger>
                                                        <Trigger Property="IsEnabled" Value="False">
                                                            <Setter TargetName="bdr" Property="Opacity" Value="0.6"/>
                                                        </Trigger>
                                                    </ControlTemplate.Triggers>
                                                </ControlTemplate>
                                            </Setter.Value>
                                        </Setter>
                                    </Style>
                                </Button.Style>
                            </Button>
                        </StackPanel>
                    </Border>

                    <TextBlock x:Name="lblClock" Text="00:00:00" FontSize="12" Foreground="#64748B" VerticalAlignment="Center" Margin="0,0,14,0"/>
                    <Button x:Name="btnAbout" Content="ℹ" Width="26" Height="26" Background="#161B2A" Foreground="#38BDF8" BorderBrush="#25334D" BorderThickness="1" Margin="0,0,12,0" Cursor="Hand" FontWeight="Bold" FontSize="12" ToolTip="Hakkında &amp; Masaüstü Kısayolu">
                        <Button.Resources>
                            <Style TargetType="Border">
                                <Setter Property="CornerRadius" Value="13"/>
                            </Style>
                        </Button.Resources>
                    </Button>
                    <Button x:Name="btnWinMinimize" Style="{StaticResource WinCtrlBtn}" Content="—"/>
                    <Button x:Name="btnWinClose" Style="{StaticResource WinCloseBtn}" Content="✕"/>
                </StackPanel>
            </Grid>

            <!-- 2. ÜST BİLGİ KARTLARI (ÖZET KUTULARI - GÖRSELDEKİ BİREBİR YAPI) -->
            <Grid Grid.Row="1" Margin="24,10,24,16">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>

                <!-- Kart 1: Boş Alan (C:) -->
                <Border x:Name="btnCardFreeSpace" Grid.Column="0" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="0,0,8,0" Cursor="Hand" ToolTip="Büyük dosyaları bulmak ve disk analizi için tıklayın">
                    <DockPanel LastChildFill="True">
                        <Border DockPanel.Dock="Right" Background="#16293A" CornerRadius="6" Padding="6,2" VerticalAlignment="Center">
                            <TextBlock Text="Analiz 🔍" FontSize="10" FontWeight="Bold" Foreground="#38BDF8"/>
                        </Border>
                        <StackPanel>
                            <DockPanel LastChildFill="False">
                                <TextBlock Text="Boş alan" FontSize="11" Foreground="#64748B" FontWeight="SemiBold" VerticalAlignment="Center"/>
                                <Border x:Name="btnHeaderDriveBadge" Background="#162234" BorderBrush="#25334D" BorderThickness="1" CornerRadius="4" Padding="6,1" Margin="6,0,0,0" VerticalAlignment="Center" Cursor="Hand" ToolTip="Sürücüyü değiştirmek için tıklayın (C:, D:, E:...)">
                                    <TextBlock x:Name="lblSelectedDriveName" Text="C: ▾" FontSize="10" FontWeight="Bold" Foreground="#38BDF8"/>
                                </Border>
                            </DockPanel>
                            <TextBlock x:Name="lblFreeSpaceC" Text="--- GB" FontSize="20" FontWeight="Bold" Foreground="#38BDF8" Margin="0,4,0,0"/>
                        </StackPanel>
                    </DockPanel>
                </Border>

                <!-- Kart 2: Seçilen Temizlik Boyutu (Tıklanabilir Sistem Temizliği) -->
                <Border x:Name="btnCardClean" Grid.Column="1" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="4,0,4,0" Cursor="Hand" ToolTip="Sistem temizliği seçeneklerini görmek ve temizlik yapmak için tıklayın">
                    <DockPanel LastChildFill="True">
                        <Border DockPanel.Dock="Right" Background="#0C2E24" CornerRadius="6" Padding="6,2" VerticalAlignment="Center">
                            <TextBlock Text="Temizle 🧹" FontSize="10" FontWeight="Bold" Foreground="#10B981"/>
                        </Border>
                        <StackPanel>
                            <TextBlock Text="Temizlenebilir (Seçilen)" FontSize="11" Foreground="#64748B" FontWeight="SemiBold"/>
                            <TextBlock x:Name="lblLiveSelectedSize" Text="0 KB" FontSize="20" FontWeight="Bold" Foreground="#10B981" Margin="0,4,0,0"/>
                        </StackPanel>
                    </DockPanel>
                </Border>

                <!-- Kart 3: Güncellenecek Program Sayısı (Tıklanabilir Yazılım Güncelleyici) -->
                <Border x:Name="btnCardUpdate" Grid.Column="2" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="4,0,4,0" Cursor="Hand" ToolTip="Yazılım güncellemelerini görmek ve güncellemek için tıklayın">
                    <DockPanel LastChildFill="True">
                        <Border DockPanel.Dock="Right" Background="#352410" CornerRadius="6" Padding="6,2" VerticalAlignment="Center">
                            <TextBlock Text="Güncelle 🚀" FontSize="10" FontWeight="Bold" Foreground="#F59E0B"/>
                        </Border>
                        <StackPanel>
                            <TextBlock Text="Güncellenecek" FontSize="11" Foreground="#64748B" FontWeight="SemiBold"/>
                            <TextBlock x:Name="lblAvailableUpdates" Text="Taranıyor..." FontSize="20" FontWeight="Bold" Foreground="#F59E0B" Margin="0,4,0,0"/>
                        </StackPanel>
                    </DockPanel>
                </Border>

                <!-- Kart 4: Açılış Programı Sayısı (Tıklanabilir Başlangıç Yöneticisi) -->
                <Border x:Name="btnCardStartup" Grid.Column="3" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="8,0,0,0" Cursor="Hand" ToolTip="Başlangıç programlarını yönetmek için tıklayın">
                    <DockPanel LastChildFill="True">
                        <Border DockPanel.Dock="Right" Background="#261A35" CornerRadius="6" Padding="6,2" VerticalAlignment="Center">
                            <TextBlock Text="Yönet →" FontSize="10" FontWeight="Bold" Foreground="#C084FC"/>
                        </Border>
                        <StackPanel>
                            <TextBlock Text="Açılış programı" FontSize="11" Foreground="#64748B" FontWeight="SemiBold"/>
                            <TextBlock x:Name="lblStartupCount" Text="-- program" FontSize="20" FontWeight="Bold" Foreground="#C084FC" Margin="0,4,0,0"/>
                        </StackPanel>
                    </DockPanel>
                </Border>
            </Grid>

            <!-- 3. ANA İÇERİK ALANI (GÖRÜNÜMLER ARASI GEÇİŞ) -->
            <Grid Grid.Row="2" Margin="24,0,24,20">

                <!-- GÖRÜNÜM 1: ANA EKRAN (3 BÜYÜK MODÜL KARTI VE HIZLI ÇALIŞTIR) -->
                <Grid x:Name="viewMain" Visibility="Visible">
                    <!-- 8 Modül Kartı (4x2 Grid) -->
                    <Grid>
                        <Grid.RowDefinitions>
                            <RowDefinition Height="*"/>
                            <RowDefinition Height="*"/>
                        </Grid.RowDefinitions>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>

                        <!-- Modül 1: Temizlik (Satır 0 / Sütun 0) -->
                        <Button x:Name="btnNavClean" Grid.Row="0" Grid.Column="0" Style="{StaticResource MenuActionCard}" Margin="0,0,4,6">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#1E1B4B" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🧹" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Sistem Temizliği" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Gereksiz geçici dosyaları, önbellekleri ve kalıntıları temizle." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#12102E" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Temizlik Paneli →" FontSize="10" FontWeight="SemiBold" Foreground="#818CF8"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 2: Büyük Dosya Analizcisi (Satır 0 / Sütun 1) -->
                        <Button x:Name="btnNavAnalyzer" Grid.Row="0" Grid.Column="1" Style="{StaticResource MenuActionCard}" Margin="4,0,4,6">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#0C4A6E" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🔍" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Büyük Dosyalar" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Diskteki devasa dosyaları (film, ISO, arşiv) hızlıca yönet." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#16293A" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Disk Analizi →" FontSize="10" FontWeight="SemiBold" Foreground="#38BDF8"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 3: Bloatware Kaldırıcı (Satır 0 / Sütun 2) -->
                        <Button x:Name="btnNavBloatware" Grid.Row="0" Grid.Column="2" Style="{StaticResource MenuActionCard}" Margin="4,0,4,6">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#4C0519" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🗑️" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Bloatware Kaldırıcı" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Gereksiz yerleşik Windows mağaza uygulamalarını kaldır." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#2B0E17" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Uygulama Temizliği →" FontSize="10" FontWeight="SemiBold" Foreground="#FB7185"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 4: Başlangıç Programları (Satır 0 / Sütun 3) -->
                        <Button x:Name="btnNavStartup" Grid.Row="0" Grid.Column="3" Style="{StaticResource MenuActionCard}" Margin="4,0,0,6">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#2E1065" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🚀" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Açılış Programları" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Bilgisayar açılışında başlayan uygulamaları yönet, hızı artır." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#1E0A40" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Açılış Yöneticisi →" FontSize="10" FontWeight="SemiBold" Foreground="#C084FC"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 5: Sistem İnce Ayarları (Satır 1 / Sütun 0) -->
                        <Button x:Name="btnNavTweaks" Grid.Row="1" Grid.Column="0" Style="{StaticResource MenuActionCard}" Margin="0,6,4,0">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#312E81" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🛡️" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Sistem İnce Ayarları" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Gizlilik, telemetri, yapay zeka ve sağ tık menü ayarları." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#1E1B4B" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="İnce Ayarlar →" FontSize="10" FontWeight="SemiBold" Foreground="#818CF8"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 6: Performans ve Oyun Modu (Satır 1 / Sütun 1) -->
                        <Button x:Name="btnNavPerformance" Grid.Row="1" Grid.Column="1" Style="{StaticResource MenuActionCard}" Margin="4,6,4,0">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#451A03" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="⚡" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Performans ve Oyun" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Oyun modu, arka plan yükü, gecikme ve FPS artırıcı ayarlar." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#2E1303" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Oyun Merkezi →" FontSize="10" FontWeight="SemiBold" Foreground="#F59E0B"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 7: Sistem Sağlığı (Satır 1 / Sütun 2) -->
                        <Button x:Name="btnNavHealth" Grid.Row="1" Grid.Column="2" Style="{StaticResource MenuActionCard}" Margin="4,6,4,0">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#064E3B" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🩺" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Sistem Sağlığı" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="SFC onarım, DISM imaj sağlığı, disk kontrolü ve ağ." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#113328" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Sağlık Merkezi →" FontSize="10" FontWeight="SemiBold" Foreground="#34D399"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>

                        <!-- Modül 8: Yazılım Güncelleme (Satır 1 / Sütun 3) -->
                        <Button x:Name="btnNavUpdate" Grid.Row="1" Grid.Column="3" Style="{StaticResource MenuActionCard}" Margin="4,6,0,0">
                            <StackPanel VerticalAlignment="Center">
                                <Border Background="#14532D" Width="48" Height="48" CornerRadius="12" HorizontalAlignment="Left" Margin="0,0,0,12">
                                    <TextBlock Text="🔄" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <TextBlock Text="Yazılım Güncelleme" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF"/>
                                <TextBlock Text="Winget ile kurulu programları ve Store uygulamalarını güncelle." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,4,0,12"/>
                                <StackPanel Orientation="Horizontal">
                                    <Border Background="#0D331C" CornerRadius="6" Padding="8,4">
                                        <TextBlock Text="Güncelleme Paneli →" FontSize="10" FontWeight="SemiBold" Foreground="#4ADE80"/>
                                    </Border>
                                </StackPanel>
                            </StackPanel>
                        </Button>
                    </Grid>
                </Grid>

                <Grid x:Name="viewClean" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Satır 0: Üst Navigasyon ve Eylem Butonları (Geniş & Ferah) -->
                    <DockPanel Grid.Row="0" Margin="0,0,0,10" LastChildFill="True">
                        <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                            <Border Background="#1C2234" CornerRadius="8" Padding="12,4" Margin="0,0,10,0" VerticalAlignment="Center">
                                <TextBlock x:Name="lblCleanBadge" Text="Seçilen: 0 KB" FontWeight="Bold" Foreground="#38BDF8" FontSize="12"/>
                            </Border>
                            <CheckBox x:Name="chkRestorePointClean" Content="Geri Yükleme Noktası Oluştur" Foreground="#94A3B8" VerticalAlignment="Center" Margin="0,0,14,0" IsChecked="False"/>
                            <Button x:Name="btnExecuteClean" Style="{StaticResource PrimaryBtn}" Content="🧹  Seçilenleri Temizle"/>
                        </StackPanel>

                        <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                            <Button x:Name="btnBackFromClean" Style="{StaticResource PresetChip}" Content="← Ana Ekrana Dön" Margin="0,0,12,0"/>
                            <TextBlock Text="🧹  Sistem Temizliği" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                        </StackPanel>
                    </DockPanel>

                    <!-- Satır 1: Hızlı Seçim ve Tarama Önayarları (Sıkışma ve Kırpılma Tamamen Çözüldü) -->
                    <DockPanel Grid.Row="1" Margin="0,0,0,12" LastChildFill="True">
                        <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                            <TextBlock Text="Hızlı Seçim:" FontSize="11" FontWeight="SemiBold" Foreground="#64748B" VerticalAlignment="Center" Margin="0,0,10,0"/>
                            <Button x:Name="btnCleanSafeSelect" Style="{StaticResource PresetChip}" Content="⚡ Önerilen Güvenli Seçim" Margin="0,0,8,0"/>
                            <Button x:Name="btnCleanClearAll" Style="{StaticResource PresetChip}" Content="🧹 Seçimi Sıfırla" Margin="0,0,8,0"/>
                            <Button x:Name="btnCleanRescan" Style="{StaticResource PresetChip}" Content="🔄 Boyutları Tara"/>
                        </StackPanel>
                    </DockPanel>

                    <!-- Satır 2: Kaydırılabilir 25 Temizlik Maddesi -->
                    <Border Grid.Row="2" Background="#111420" BorderBrush="#1F2538" BorderThickness="1" CornerRadius="10" Padding="14">
                        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                            <StackPanel Margin="0,0,8,0">

                                <!-- KATEGORİ 1: SİSTEM VE GEÇİCİ DOSYALAR -->
                                <TextBlock Text="📁 SİSTEM VE GEÇİCİ DOSYALAR" FontWeight="Bold" FontSize="11" Foreground="#64748B" Margin="0,0,0,8"/>

                                <!-- %TEMP% ve C:\Windows\Temp -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeTemp" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                        </Border>
                                        <CheckBox x:Name="chkTemp" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="%TEMP% ve C:\Windows\Temp" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Uygulama ve Windows geçici çalışma dosyaları" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Windows Update İndirme Önbelleği -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeWinUpdate" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                        </Border>
                                        <CheckBox x:Name="chkWinUpdate" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Windows Update İndirme Önbelleği" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="İndirilmiş ve kurulmuş eski güncelleme yükleyicileri (wuauserv servisi güvenle yönetilir)" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Geri Dönüşüm Kutusu -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeRecycle" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                        </Border>
                                        <CheckBox x:Name="chkRecycle" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Geri Dönüşüm Kutusu" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Tüm sürücülerdeki silinmiş dosyaları kalıcı olarak boşaltır" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Olay Günlükleri -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeEventLogs" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                        </Border>
                                        <CheckBox x:Name="chkEventLogs" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Windows Olay ve Sistem Günlükleri (Event Logs / CBS / DISM)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Sistem hata raporları, CBS güncelleme kayıtları ve olay günlükleri" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- WinSxS Bileşen Temizliği -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock Text="DISM" FontSize="11" FontWeight="Bold" Foreground="#C084FC"/>
                                        </Border>
                                        <CheckBox x:Name="chkWsxx" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="WinSxS Derin Bileşen Temizliği (DISM /ResetBase)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Eski güncelleme yedeklerini temizler, diskte maksimum yer açar" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Teslim İyileştirme Dosyaları (Delivery Optimization) -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
