                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Tarayıcı Ziyaret ve İndirme Geçmişi" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Ziyaret edilen web siteleri (Ctrl+H) ve indirme geçmişi (Chrome, Edge, Brave, Opera, Firefox - Şifrelere dokunmaz)" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Tarayıcı Çerezleri ve Açık Oturumlar -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeBrowserCookies" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#F59E0B"/>
                                        </Border>
                                        <CheckBox x:Name="chkBrowserCookies" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Tarayıcı Çerezleri ve Açık Oturumlar (Cookies)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Web sitelerindeki tüm açık hesap oturumlarını kapatır (Google, YouTube vb. çıkış yapılır; şifreleriniz silinmez)" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Kayıtlı Şifreler ve Otomatik Doldurma -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,16">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#2E151B" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeBrowserPasswords" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#EF4444"/>
                                        </Border>
                                        <CheckBox x:Name="chkBrowserPasswords" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Kayıtlı Şifreler ve Otomatik Doldurma Verileri ⚠️" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="DİKKAT: Tarayıcılarda kayıtlı tüm hesap şifrelerini, kullanıcı adlarını, form ve adres otomatik doldurma verilerini KALICI olarak siler!" FontSize="11" Foreground="#EF4444"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>


                                <!-- KATEGORİ 3: OYUN & SHADER ÖNBELLEKLERİ -->
                                <TextBlock Text="🎮 OYUN VE GRAFİK SHADER ÖNBELLEKLERİ" FontWeight="Bold" FontSize="11" Foreground="#64748B" Margin="0,4,0,8"/>

                                <!-- Shader Cache (NVIDIA, AMD, DirectX) -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeShader" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                        </Border>
                                        <CheckBox x:Name="chkShader" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Grafik Shader Önbelleği (NVIDIA, AMD, DirectX)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Derlenmiş shader kalıntıları (Not: Oyunlar ilk açılışta 1 kez yeniden derleyebilir)" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Oyun İstemcileri Arayüz Önbelleği -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,16">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock x:Name="lblSizeGameClients" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                        </Border>
                                        <CheckBox x:Name="chkGameClients" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Oyun İstemcileri Arayüz Önbelleği (Steam, Epic, EA App)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="Yalnızca HTML/web arayüzü ve loglar (Oyun dosyalarına, kayıtlarına ve save'lere dokunulmaz)" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>


                                <!-- KATEGORİ 4: GİZLİLİK VE BİLGİSAYAR KULLANIM İZLEMELERİ (AÇILIR AKORDİYON MENÜ) -->
                                <TextBlock Text="🔒 GİZLİLİK VE BİLGİSAYAR KULLANIM İZLEMELERİ" FontWeight="Bold" FontSize="11" Foreground="#64748B" Margin="0,4,0,8"/>

                                <Border x:Name="bdrGroupTraces" Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Margin="0,0,0,8">
                                    <StackPanel>
                                        <!-- Başlık Satırı -->
                                        <Border x:Name="bdrHeaderTraces" Padding="12,10" Background="Transparent" Cursor="Hand">
                                            <DockPanel LastChildFill="True">
                                                <!-- Sağ Taraf: Rozet ve Ok Butonu -->
                                                <StackPanel Orientation="Horizontal" DockPanel.Dock="Right" VerticalAlignment="Center">
                                                    <Border Background="#1D2338" CornerRadius="6" Padding="10,3" Margin="0,0,8,0">
                                                        <TextBlock x:Name="lblSizeGroupTraces" Text="Hesaplanıyor..." FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                                    </Border>
                                                    <Button x:Name="btnToggleTraces" Content="⌄" FontSize="14" FontWeight="Bold" Foreground="#94A3B8" Background="#1F263B" BorderThickness="0" Width="28" Height="26" Cursor="Hand">
                                                        <Button.Resources>
                                                            <Style TargetType="Border"><Setter Property="CornerRadius" Value="6"/></Style>
                                                        </Button.Resources>
                                                    </Button>
                                                </StackPanel>
                                                <!-- Sol Taraf: Grup Checkbox ve Başlık -->
                                                <CheckBox x:Name="chkGroupTraces" IsChecked="False" VerticalAlignment="Center">
                                                    <StackPanel Margin="6,0,0,0">
                                                        <TextBlock Text="🔍 Bilgisayar Kullanım İzlemeleri" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                        <TextBlock Text="Sistem olay izleri, son açılanlar, Çalıştır ve tarayıcı arama izleri" FontSize="11" Foreground="#94A3B8"/>
                                                    </StackPanel>
                                                </CheckBox>
                                            </DockPanel>
                                        </Border>

                                        <!-- Açılır Çocuk Paneli (Varsayılan: Gizli) -->
                                        <Border x:Name="pnlTracesChildren" Visibility="Collapsed" BorderBrush="#1F263D" BorderThickness="0,1,0,0" Background="#121624" Padding="12,10,12,6" CornerRadius="0,0,8,8">
                                            <StackPanel>
                                                <!-- 1. Sistem Kullanım İzlemeleri -->
                                                <Border x:Name="bdrTraceSystem" Background="#161B2B" BorderBrush="#20273D" BorderThickness="1" CornerRadius="7" Padding="10,8" Margin="0,0,0,6">
                                                    <DockPanel LastChildFill="True">
                                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="5" Padding="8,2" VerticalAlignment="Center">
                                                            <TextBlock x:Name="lblSizeTraceSystem" Text="0 KB" FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                                        </Border>
                                                        <CheckBox x:Name="chkTraceSystem" IsChecked="False" VerticalAlignment="Center">
                                                            <StackPanel Orientation="Horizontal" Margin="6,0,0,0">
                                                                <TextBlock Text="🪟" FontSize="14" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                                                <StackPanel VerticalAlignment="Center">
                                                                    <TextBlock Text="Sistem Kullanım İzlemeleri" FontWeight="SemiBold" Foreground="#FFFFFF" FontSize="12"/>
                                                                    <TextBlock Text="Windows Olay İzleme (ETL) günlükleri, son açılanlar, Çalıştır ve pano izleri" FontSize="10.5" Foreground="#94A3B8"/>
                                                                </StackPanel>
                                                            </StackPanel>
                                                        </CheckBox>
                                                    </DockPanel>
                                                </Border>

                                                <!-- 2. Chrome Kullanım İzlemeleri -->
                                                <Border x:Name="bdrTraceChrome" Background="#161B2B" BorderBrush="#20273D" BorderThickness="1" CornerRadius="7" Padding="10,8" Margin="0,0,0,6">
                                                    <DockPanel LastChildFill="True">
                                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="5" Padding="8,2" VerticalAlignment="Center">
                                                            <TextBlock x:Name="lblSizeTraceChrome" Text="0 KB" FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                                        </Border>
                                                        <CheckBox x:Name="chkTraceChrome" IsChecked="False" VerticalAlignment="Center">
                                                            <StackPanel Orientation="Horizontal" Margin="6,0,0,0">
                                                                <Image x:Name="imgTraceChrome" Width="18" Height="18" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                                                <StackPanel VerticalAlignment="Center">
                                                                    <TextBlock Text="Chrome Kullanım İzlemeleri" FontWeight="SemiBold" Foreground="#FFFFFF" FontSize="12"/>
                                                                    <TextBlock Text="Ziyaret edilen bağlantılar, arama ve indirme geçmişi" FontSize="10.5" Foreground="#94A3B8"/>
                                                                </StackPanel>
                                                            </StackPanel>
                                                        </CheckBox>
                                                    </DockPanel>
                                                </Border>

                                                <!-- 3. Edge Kullanım İzlemeleri -->
                                                <Border x:Name="bdrTraceEdge" Background="#161B2B" BorderBrush="#20273D" BorderThickness="1" CornerRadius="7" Padding="10,8" Margin="0,0,0,6">
                                                    <DockPanel LastChildFill="True">
                                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="5" Padding="8,2" VerticalAlignment="Center">
                                                            <TextBlock x:Name="lblSizeTraceEdge" Text="0 KB" FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                                        </Border>
                                                        <CheckBox x:Name="chkTraceEdge" IsChecked="False" VerticalAlignment="Center">
                                                            <StackPanel Orientation="Horizontal" Margin="6,0,0,0">
                                                                <Image x:Name="imgTraceEdge" Width="18" Height="18" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                                                <StackPanel VerticalAlignment="Center">
                                                                    <TextBlock Text="Edge Kullanım İzlemeleri" FontWeight="SemiBold" Foreground="#FFFFFF" FontSize="12"/>
                                                                    <TextBlock Text="Ziyaret edilen bağlantılar, arama ve indirme geçmişi" FontSize="10.5" Foreground="#94A3B8"/>
                                                                </StackPanel>
                                                            </StackPanel>
                                                        </CheckBox>
                                                    </DockPanel>
                                                </Border>

                                                <!-- 4. Brave Kullanım İzlemeleri -->
                                                <Border x:Name="bdrTraceBrave" Background="#161B2B" BorderBrush="#20273D" BorderThickness="1" CornerRadius="7" Padding="10,8" Margin="0,0,0,4">
                                                    <DockPanel LastChildFill="True">
                                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="5" Padding="8,2" VerticalAlignment="Center">
                                                            <TextBlock x:Name="lblSizeTraceBrave" Text="0 KB" FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                                        </Border>
                                                        <CheckBox x:Name="chkTraceBrave" IsChecked="False" VerticalAlignment="Center">
                                                            <StackPanel Orientation="Horizontal" Margin="6,0,0,0">
                                                                <Image x:Name="imgTraceBrave" Width="18" Height="18" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                                                <StackPanel VerticalAlignment="Center">
                                                                    <TextBlock Text="Brave Kullanım İzlemeleri" FontWeight="SemiBold" Foreground="#FFFFFF" FontSize="12"/>
                                                                    <TextBlock Text="Ziyaret edilen bağlantılar, arama ve indirme geçmişi" FontSize="10.5" Foreground="#94A3B8"/>
                                                                </StackPanel>
                                                            </StackPanel>
                                                        </CheckBox>
                                                    </DockPanel>
                                                </Border>
                                            </StackPanel>
                                        </Border>
                                    </StackPanel>
                                </Border>

                                <!-- DNS Çözümleyici Önbelleği -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock Text="Sıfırla" FontSize="11" FontWeight="Bold" Foreground="#34D399"/>
                                        </Border>
                                        <CheckBox x:Name="chkDns" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="DNS Çözümleyici Önbelleği (Flush DNS)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="İnternet bağlantı tıkanıklıklarını çözer, DNS kayıtlarını yeniler" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Eski Geri Yükleme Noktaları -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <DockPanel LastChildFill="True">
                                        <Border DockPanel.Dock="Right" Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                            <TextBlock Text="VSS" FontSize="11" FontWeight="Bold" Foreground="#C084FC"/>
                                        </Border>
                                        <CheckBox x:Name="chkOldRestore" IsChecked="False" VerticalAlignment="Center">
                                            <StackPanel Margin="6,0,0,0">
                                                <TextBlock Text="Eski Geri Yükleme Noktaları" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                <TextBlock Text="En güncel olan geri yükleme noktası hariç tüm eskileri silerek GB'larca alan açar" FontSize="11" Foreground="#94A3B8"/>
                                            </StackPanel>
                                        </CheckBox>
                                    </DockPanel>
                                </Border>

                                <!-- Geçersiz Kırık Kısayollar (Listeleme Özellikli) -->
                                <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="12,10" Margin="0,0,0,8">
                                    <StackPanel>
                                        <DockPanel LastChildFill="True">
                                            <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                                <Button x:Name="btnToggleShortcutsList" Style="{StaticResource PresetChip}" Content="Listeyi Göster" Height="24" Padding="8,0" Margin="0,0,8,0" Visibility="Collapsed"/>
                                                <Border Background="#1D2338" CornerRadius="6" Padding="10,3" VerticalAlignment="Center">
                                                    <TextBlock x:Name="lblBrokenShortcutsCount" Text="0 adet" FontSize="11" FontWeight="Bold" Foreground="#F59E0B"/>
                                                </Border>
                                            </StackPanel>
                                            <CheckBox x:Name="chkShortcuts" IsChecked="False" VerticalAlignment="Center">
                                                <StackPanel Margin="6,0,0,0">
                                                    <TextBlock Text="Hedefi Olmayan Kırık Kısayollar (.lnk)" FontWeight="SemiBold" Foreground="#FFFFFF"/>
                                                    <TextBlock Text="Masaüstü ve Başlat Menüsünde hedefi silinmiş olanları listeler ve temizler (Ağ ve USB atlanır)" FontSize="11" Foreground="#94A3B8"/>
                                                </StackPanel>
                                            </CheckBox>
                                        </DockPanel>
                                        <Border x:Name="pnlBrokenShortcutsDetails" Visibility="Collapsed" Background="#111420" BorderBrush="#20263C" BorderThickness="1" CornerRadius="6" Margin="0,10,0,0" Padding="8">
                                            <StackPanel>
                                                <TextBlock Text="Tespit Edilen Kırık Kısayollar:" FontSize="11" FontWeight="SemiBold" Foreground="#38BDF8" Margin="0,0,0,6"/>
                                                <ListBox x:Name="lstBrokenShortcuts" MaxHeight="130" Background="Transparent" BorderThickness="0" Foreground="#E2E8F0" FontSize="11" ScrollViewer.VerticalScrollBarVisibility="Auto"/>
                                            </StackPanel>
                                        </Border>
                                    </StackPanel>
                                </Border>

                            </StackPanel>
                        </ScrollViewer>
                    </Border>

                    <!-- Alt Bilgi ve İlerleme Çubuğu -->
                    <Grid Grid.Row="3" Margin="0,12,0,0">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>

                        <StackPanel Grid.Column="0" VerticalAlignment="Center">
                            <TextBlock x:Name="lblCleanStatus" Text="Temizlik boyutları canlı hesaplanıyor..." FontSize="12" Foreground="#94A3B8"/>
                            <ProgressBar x:Name="progClean" Height="4" Margin="0,6,14,0" Background="#1F2538" Foreground="#4F46E5" BorderThickness="0" Maximum="100" Value="0"/>
                        </StackPanel>

                        <Button x:Name="btnOpenLogFile" Grid.Column="1" Style="{StaticResource PresetChip}" Content="📄 Son Raporu Aç" Margin="14,0,0,0"/>
                    </Grid>
                </Grid>

                <!-- GÖRÜNÜM 3: SİSTEM SAĞLIK VE ONARIM MERKEZİ (ÖRTÜŞME / SIĞMAMA SORUNLARI TAMAMEN DÜZELTİLDİ) -->
                <Grid x:Name="viewHealth" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>

                    <!-- Üst Navigasyon -->
                    <DockPanel Grid.Row="0" Margin="0,0,0,14" LastChildFill="True">
                        <Button x:Name="btnBackFromHealth" Style="{StaticResource PresetChip}" Content="← Ana Ekrana Dön" Margin="0,0,14,0"/>
                        <TextBlock Text="🖥️  Sistem Sağlık, Onarım ve Donanım Merkezi" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                    </DockPanel>

                    <!-- 2 Sütunlu Sağlık Paneli: Sol Eylemler (510px), Sağ Canlı Konsol (*) -->
                    <Grid Grid.Row="1">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="510"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>

                        <!-- Sol Sütun: Araç Kartları -->
                        <Border Grid.Column="0" Background="#111420" BorderBrush="#1F2538" BorderThickness="1" CornerRadius="12" Padding="14" Margin="0,0,14,0">
                            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                                <StackPanel Margin="0,0,6,28">

                                    <!-- 1. SFC -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="SFC Sistem Dosyası Taraması" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Bozuk veya eksik Windows sistem dosyalarını doğrular ve onarır (sfc /scannow)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunSfc" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Tara ve Onar" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 2. DISM -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="DISM Windows İmaj Onarımı" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Windows bileşen deposunu Windows Update üzerinden onarır" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunDism" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Onarımı Başlat" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 3. DISM ScanHealth -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Bileşen Deposu Durum Kontrolü (ScanHealth)" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Windows bileşen deposunu salt okunur tarar, onarım gerekip gerekmediğini bildirir (dism /scanhealth)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunDismScan" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Durumu Tara" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 4. Chkdsk -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Chkdsk Disk Hata Taraması" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="C: sürücüsünü canlı tarar, yeniden başlatma gerektirmeden dosya sistemini inceler" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunChkdsk" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Diski Tara" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 5. Disk S.M.A.R.T. Sağlık ve Aşınma Bilgisi -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Disk S.M.A.R.T. Sağlık ve Aşınma Durumu" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="SSD/HDD yıpranma yüzdesi, sıcaklık, çalışma saati ve donanım sağlık durumunu listeler" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunSmartInfo" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="S.M.A.R.T. Oku" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 6. Windows Sistem Sağlık Raporu (perfmon /report) -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Windows Sistem Sağlık Raporu" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="60 saniyelik kapsamlı resmi Windows donanım, CPU, RAM ve sistem tanı raporunu başlatır (perfmon /report)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunPerfmonReport" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Rapor Başlat" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 7. Sürücü ve Donanım Aygıt Sağlık Denetimi -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Sürücü ve Donanım Aygıt Sağlık Denetimi" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Sarı ünlemli, eksik veya hatalı çalışan donanım sürücülerini denetler (Get-PnpDevice)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunDriverCheck" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Sürücüleri Tara" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 4. Ağ Sıfırlama -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Tam Ağ ve İnternet Sıfırlama" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Winsock, IP yığını ve DNS'i sıfırlar (Uyarı: Statik IP ayarları sıfırlanabilir)" FontSize="11" Foreground="#F59E0B" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnResetNetwork" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Ağı Sıfırla" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 4.1 Hızlı DNS Yöneticisi -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,12" Margin="0,0,0,8">
                                        <StackPanel>
                                            <!-- Başlık ve Canlı Durum Rozeti -->
                                            <DockPanel LastChildFill="True" Margin="0,0,0,4">
                                                <Border DockPanel.Dock="Right" Background="#111827" BorderBrush="#1F2937" BorderThickness="1" CornerRadius="6" Padding="8,3" VerticalAlignment="Center">
                                                    <TextBlock x:Name="lblCurrentDnsStatus" Text="Aktif: Okunuyor..." FontSize="11" FontWeight="SemiBold" Foreground="#38BDF8"/>
                                                </Border>
                                                <TextBlock Text="Hızlı DNS Yöneticisi" FontWeight="Bold" FontSize="13" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                                            </DockPanel>

                                            <!-- Açıklama Metni (Sıkışmadan, Geniş ve Ferah) -->
                                            <TextBlock Text="Düşük ping ve hızlı erişim için optimize DNS profili seçin veya modemin varsayılan (DHCP) ayarlarına dönün." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,0,0,10"/>

                                            <!-- Seçim ve Uygulama Alanı -->
                                            <Grid>
                                                <Grid.ColumnDefinitions>
                                                    <ColumnDefinition Width="*"/>
                                                    <ColumnDefinition Width="Auto"/>
                                                </Grid.ColumnDefinitions>
                                                <ComboBox x:Name="cmbDnsProfiles" Grid.Column="0" Style="{StaticResource DarkComboBox}" Height="30" Margin="0,0,10,0" VerticalAlignment="Center">
                                                    <ComboBoxItem Content="🔄 Otomatik (Varsayılan DHCP)" IsSelected="True"/>
                                                    <ComboBoxItem Content="⚡ Cloudflare DNS (1.1.1.1)"/>
                                                    <ComboBoxItem Content="🔍 Google DNS (8.8.8.8)"/>
                                                    <ComboBoxItem Content="🛡️ Quad9 Güvenli DNS (9.9.9.9)"/>
                                                </ComboBox>
                                                <Button x:Name="btnApplyDns" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="DNS Uygula" Width="105" Height="30" VerticalAlignment="Center"/>
                                            </Grid>
                                        </StackPanel>
                                    </Border>

                                    <!-- 5. Store Sıfırlama -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Microsoft Store Önbellek Sıfırlama" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Açılmayan veya indirme hatası veren Store önbelleğini temizler (wsreset.exe)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnWsReset" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Store Sıfırla" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 5.1 Windows Update Onarımı ve Sıfırlama -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Windows Update Onarımı ve Sıfırlama" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Takılan indirmeleri ve güncelleme hatalarını çözer; Update servislerini (wuauserv, bits, cryptsvc) ve önbelleği sıfırlar" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnResetWinUpdate" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Update Onar" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 6. Hazırda Bekletme -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <StackPanel Orientation="Horizontal" Margin="0,0,0,3">
                                                    <TextBlock Text="Hazırda Bekletme (Hibernate): " FontWeight="Bold" Foreground="#FFFFFF"/>
                                                    <TextBlock x:Name="lblHibernateStatus" Text="Kontrol ediliyor..." FontWeight="Bold" Foreground="#38BDF8"/>
                                                </StackPanel>
                                                <TextBlock Text="Kapatılırsa C: diskinde gigabaytlarca yer açılır (Hızlı başlatma kapanır)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap"/>
                                            </StackPanel>
                                            <Button x:Name="btnToggleHibernate" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Değiştir" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 7. RAM Testi -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="Windows Bellek Tanılama (RAM Testi)" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Donanımsal RAM arızalarını test eder (Yeniden başlatma gerektirir)" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnRunRamTest" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="RAM Testi" Width="105" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>

                                    <!-- 8. Disk Sağlığı Bilgisi -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,8">
                                        <StackPanel>
                                            <TextBlock Text="Disk Donanım Sağlığı (Get-PhysicalDisk)" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                            <TextBlock x:Name="lblDiskHealthInfo" Text="Taranıyor..." FontSize="12" Foreground="#34D399" Margin="0,4,0,0" TextWrapping="Wrap"/>
                                        </StackPanel>
                                    </Border>

                                    <!-- 9. Windows Lisans ve Etkinleştirme Durumu -->
                                    <Border Background="#171B2A" BorderBrush="#22273C" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,16">
                                        <Grid>
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="Auto"/>
                                            </Grid.ColumnDefinitions>
                                            <StackPanel Grid.Column="0" Margin="0,0,12,0" VerticalAlignment="Center">
                                                <TextBlock Text="🔑 Windows Lisans ve Etkinleştirme Durumu" FontWeight="Bold" Foreground="#FFFFFF" TextWrapping="Wrap"/>
                                                <TextBlock Text="Kurulu Windows sürümü, lisans türü (OEM/Retail) ve ürün anahtarı ayrıntılarını görüntüler" FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,0"/>
                                            </StackPanel>
                                            <Button x:Name="btnCheckLicense" Grid.Column="1" Style="{StaticResource ActionCardBtn}" Content="Lisansı Sorgula" Width="120" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Border>
                                </StackPanel>
                            </ScrollViewer>
                        </Border>

                        <!-- Sağ Sütun: Canlı Terminal & Log Çıktısı -->
                        <Border Grid.Column="1" Background="#0A0C12" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="12" Padding="14">
                            <DockPanel LastChildFill="True">
                                <Grid DockPanel.Dock="Top" Margin="0,0,0,10">
                                    <TextBlock Text="CANLI KONSOL ÇIKTISI" FontSize="11" FontWeight="Bold" Foreground="#64748B" VerticalAlignment="Center"/>
                                    <Button x:Name="btnClearTerminal" Style="{StaticResource PresetChip}" Content="Temizle" Height="26" Padding="10,0" HorizontalAlignment="Right"/>
                                </Grid>
                                <TextBox x:Name="txtTerminal" IsReadOnly="True" Background="Transparent" Foreground="#38BDF8" BorderThickness="0" FontFamily="Consolas" FontSize="11" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap"/>
                            </DockPanel>
                        </Border>
                    </Grid>
                </Grid>

                <!-- GÖRÜNÜM 4: GÜNCELLEME PENCERESİ / PANELİ (GÖRSELDEKİ BİREBİR TASARIM) -->
                <Grid x:Name="viewUpdate" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Üst Başlık -->
                    <Grid Grid.Row="0" Margin="0,0,0,14">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>

                        <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                            <Button x:Name="btnBackFromUpdate" Content="← Ana Menüye Dön" Background="#1D2338" Foreground="#38BDF8" BorderThickness="0" Padding="12,6" Margin="0,0,14,0" Cursor="Hand" FontWeight="SemiBold">
                                <Button.Resources>
                                    <Style TargetType="Border">
                                        <Setter Property="CornerRadius" Value="6"/>
                                    </Style>
                                </Button.Resources>
                            </Button>
                            <Border Background="#1E2338" Width="32" Height="32" CornerRadius="8" Margin="0,0,10,0">
                                <TextBlock Text="🔄" FontSize="16" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                            <TextBlock Text="Güncellemeler" FontSize="18" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                        </StackPanel>

                        <Border Grid.Column="2" Background="#1E2338" CornerRadius="8" Padding="12,4" VerticalAlignment="Center">
                            <TextBlock x:Name="lblUpdateSelectedBadge" Text="0 / 0 seçili" FontWeight="Bold" Foreground="#38BDF8" FontSize="12"/>
                        </Border>
                    </Grid>

                    <!-- Filtreler ve Hızlı Butonlar -->
                    <DockPanel Grid.Row="1" Margin="0,0,0,12" LastChildFill="True">
                        <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                            <Button x:Name="btnRescanUpdates" Style="{StaticResource PresetChip}" Content="🔄 Yeniden Tara" Margin="0,0,8,0"/>
                            <Button x:Name="btnOpenWinUpdate" Style="{StaticResource PresetChip}" Content="⚙ Windows Update Ayarları"/>
                        </StackPanel>

                        <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                            <CheckBox x:Name="chkSelectAllUpdates" IsChecked="False" Content="Tümünü seç" Margin="0,0,20,0"/>
                            <CheckBox x:Name="chkIncludeStore" IsChecked="False" Content="Store uygulamalarını da dahil et"/>
                        </StackPanel>
                    </DockPanel>

                    <!-- Güncelleme Listesi -->
                    <Border Grid.Row="2" Background="#111420" BorderBrush="#1F2538" BorderThickness="1" CornerRadius="10" Padding="14">
                        <Grid>
                            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                                <StackPanel x:Name="pnlUpdateList"/>
                            </ScrollViewer>
                            <TextBlock x:Name="lblUpdatePlaceholder" Text="Güncellemeler aranıyor..." HorizontalAlignment="Center" VerticalAlignment="Center" Foreground="#64748B" FontSize="14"/>
                        </Grid>
                    </Border>

                    <!-- Alt Çubuk (İlerleme & Başlat) -->
                    <Grid Grid.Row="3" Margin="0,14,0,0">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>

                        <StackPanel Grid.Column="0" VerticalAlignment="Center">
                            <TextBlock x:Name="lblUpdateProgressText" Text="Güncellemeleri yüklemek için listeden seçim yapın." FontSize="12" Foreground="#94A3B8"/>
                            <ProgressBar x:Name="progUpdate" Height="4" Margin="0,6,16,0" Background="#1F2538" Foreground="#4F46E5" BorderThickness="0" Maximum="100" Value="0"/>
                        </StackPanel>

                        <Button x:Name="btnCloseUpdate" Grid.Column="1" Style="{StaticResource PresetChip}" Content="Kapat" Margin="0,0,10,0"/>
                        <Button x:Name="btnExecuteUpdates" Grid.Column="2" Style="{StaticResource PrimaryBtn}" Content="⬇  Seçilenleri güncelle"/>
                    </Grid>
                </Grid>

                <!-- GÖRÜNÜM 5: BAŞLANGIÇ PROGRAMLARI YÖNETİCİSİ -->
                <Grid x:Name="viewStartup" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Üst Başlık ve Geri Dön Butonu -->
                    <Grid Grid.Row="0" Margin="0,0,0,14">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>

                        <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                            <Button x:Name="btnBackFromStartup" Content="← Geri" Background="#1D2338" Foreground="#94A3B8" BorderThickness="0" Padding="12,6" Margin="0,0,14,0" Cursor="Hand" FontWeight="SemiBold">
                                <Button.Resources>
                                    <Style TargetType="Border">
                                        <Setter Property="CornerRadius" Value="6"/>
                                    </Style>
                                </Button.Resources>
                            </Button>
                            <Border Background="#231734" Width="32" Height="32" CornerRadius="8" Margin="0,0,10,0">
                                <TextBlock Text="🚀" FontSize="16" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                            <TextBlock Text="Başlangıç Programları Yöneticisi" FontSize="18" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                        </StackPanel>

                        <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                            <Border Background="#1E1734" BorderBrush="#3B2664" BorderThickness="1" CornerRadius="8" Padding="12,4" Margin="0,0,8,0" VerticalAlignment="Center">
                                <TextBlock x:Name="lblBootTimeBadge" Text="⏱️ Son BIOS: Hesaplanıyor..." FontSize="12" FontWeight="Bold" Foreground="#A855F7"/>
                            </Border>
                            <Border Background="#1E2338" CornerRadius="8" Padding="12,4" VerticalAlignment="Center">
                                <TextBlock x:Name="lblStartupBadge" Text="Toplam: -- Program" FontSize="12" FontWeight="Bold" Foreground="#C084FC"/>
                            </Border>
                        </StackPanel>
                    </Grid>

                    <!-- Açıklama ve Yeniden Tara Araç Çubuğu -->
                    <Border Grid.Row="1" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,12">
                        <DockPanel LastChildFill="True">
                            <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                <Button x:Name="btnRescanStartup" Content="↻ Yeniden Tara" Background="#1E2338" Foreground="#C084FC" BorderThickness="0" Padding="12,6" Cursor="Hand" FontWeight="SemiBold">
                                    <Button.Resources>
                                        <Style TargetType="Border">
                                            <Setter Property="CornerRadius" Value="6"/>
                                        </Style>
                                    </Button.Resources>
                                </Button>
                            </StackPanel>
                            <StackPanel VerticalAlignment="Center" Margin="0,0,12,0">
                                <TextBlock Text="Windows açılışında arka planda otomatik başlayan uygulamalar." FontWeight="SemiBold" Foreground="#FFFFFF" FontSize="12"/>
                                <TextBlock Text="Gereksiz programları devre dışı bırakarak açılış süresini ve arka plan RAM kullanımını düşürebilirsiniz." FontSize="11" Foreground="#64748B" Margin="0,3,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>

                    <!-- Liste Alanı (ScrollViewer) -->
                    <Border Grid.Row="2" Background="#0F121C" BorderBrush="#1A1F30" BorderThickness="1" CornerRadius="10" Padding="12">
                        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                            <StackPanel x:Name="pnlStartupList">
                                <!-- Program kartları buraya dinamik eklenir -->
                            </StackPanel>
                        </ScrollViewer>
                    </Border>

                    <!-- Alt Bilgi Çubuğu -->
                    <Border Grid.Row="3" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,8" Margin="0,12,0,0">
                        <DockPanel LastChildFill="True">
                            <TextBlock Text="💡 Not: Programları devre dışı bırakmak dosyalarını silmez; yalnızca PC açılışında otomatik başlamalarını engeller. İstediğiniz zaman tekrar açabilirsiniz." FontSize="11" Foreground="#94A3B8" VerticalAlignment="Center"/>
                        </DockPanel>
                    </Border>
                </Grid>

                <!-- GÖRÜNÜM 6: BÜYÜK DOSYA AVCISI (DİSK ALAN ANALİZİ) -->
                <Grid x:Name="viewAnalyzer" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Üst Başlık ve Geri Dön Butonu -->
                    <Grid Grid.Row="0" Margin="0,0,0,14">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>

                        <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
                            <Button x:Name="btnBackFromAnalyzer" Content="← Geri" Background="#1D2338" Foreground="#94A3B8" BorderThickness="0" Padding="12,6" Margin="0,0,14,0" Cursor="Hand" FontWeight="SemiBold">
                                <Button.Resources>
                                    <Style TargetType="Border">
                                        <Setter Property="CornerRadius" Value="6"/>
                                    </Style>
                                </Button.Resources>
                            </Button>
                            <Border Background="#0C2538" Width="32" Height="32" CornerRadius="8" Margin="0,0,10,0">
                                <TextBlock Text="🔍" FontSize="16" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                            <TextBlock Text="Büyük Dosya Avcısı (Disk Analizi)" FontSize="18" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                        </StackPanel>

                        <Border Grid.Column="2" Background="#1E2338" CornerRadius="8" Padding="12,4" VerticalAlignment="Center">
                            <TextBlock x:Name="lblAnalyzerBadge" Text="Taranmadı" FontSize="12" FontWeight="Bold" Foreground="#38BDF8"/>
                        </Border>
                    </Grid>

                    <!-- Filtreler ve Tarama Araç Çubuğu -->
                    <Border Grid.Row="1" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,12">
                        <DockPanel LastChildFill="True">
                            <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                <Button x:Name="btnStartAnalyzerScan" Content="🔍 Taramayı Başlat" Background="#0284C7" Foreground="#FFFFFF" BorderThickness="0" Padding="14,6" Cursor="Hand" FontWeight="Bold">
                                    <Button.Resources>
                                        <Style TargetType="Border">
                                            <Setter Property="CornerRadius" Value="6"/>
                                        </Style>
                                    </Button.Resources>
                                </Button>
                            </StackPanel>

                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                <!-- Konum Filtresi -->
                                <TextBlock Text="Konum:" Foreground="#94A3B8" FontSize="11" FontWeight="SemiBold" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                <ComboBox x:Name="cmbAnalyzerLocation" Style="{StaticResource DarkComboBox}" Width="240" Height="30" VerticalAlignment="Center" Margin="0,0,16,0">
                                    <ComboBoxItem Content="📁 Kullanıcı Klasörleri (Hızlı)" IsSelected="True"/>
                                    <ComboBoxItem Content="💾 Tüm C: Sürücüsü (Kapsamlı)"/>
                                </ComboBox>

                                <!-- Minimum Boyut Filtresi -->
                                <TextBlock Text="Min. Boyut:" Foreground="#94A3B8" FontSize="11" FontWeight="SemiBold" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                <ComboBox x:Name="cmbAnalyzerMinSize" Style="{StaticResource DarkComboBox}" Width="120" Height="30" VerticalAlignment="Center">
                                    <ComboBoxItem Content="> 500 MB" IsSelected="True"/>
                                    <ComboBoxItem Content="> 1 GB"/>
                                    <ComboBoxItem Content="> 100 MB"/>
                                </ComboBox>
                            </StackPanel>
                        </DockPanel>
                    </Border>

                    <!-- Dosya Listesi (ScrollViewer) -->
                    <Border Grid.Row="2" Background="#0F121C" BorderBrush="#1A1F30" BorderThickness="1" CornerRadius="10" Padding="12">
                        <Grid>
                            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                                <StackPanel x:Name="pnlAnalyzerList">
                                    <TextBlock x:Name="lblAnalyzerPlaceholder" Text="Taramayı başlatmak için yukarıdaki '🔍 Taramayı Başlat' düğmesine tıklayın." Foreground="#64748B" FontSize="13" HorizontalAlignment="Center" Margin="0,60,0,0"/>
                                </StackPanel>
                            </ScrollViewer>
                            <ProgressBar x:Name="progAnalyzer" Height="3" VerticalAlignment="Top" IsIndeterminate="True" Visibility="Collapsed" Foreground="#38BDF8" Background="#161B2A" BorderThickness="0"/>
                        </Grid>
                    </Border>

                    <!-- Alt Bilgi Çubuğu -->
                    <Border Grid.Row="3" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,8" Margin="0,12,0,0">
                        <DockPanel LastChildFill="True">
                            <TextBlock x:Name="lblAnalyzerFooter" Text="💡 İpucu: 'Klasörde Göster' butonu dosyayı Windows Gezgini'nde açar. 'Sil' butonu kalıcı silmeden önce onay ister." FontSize="11" Foreground="#94A3B8" VerticalAlignment="Center"/>
                        </DockPanel>
                    </Border>
                </Grid>

                <!-- GÖRÜNÜM 7: WINDOWS BLOATWARE KALDIRICI -->
                <Grid x:Name="viewBloatware" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Satır 0: Üst Başlık, Rozet ve Toplu Kaldır Butonu -->
                    <DockPanel Grid.Row="0" Margin="0,0,0,12" LastChildFill="True">
                        <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                            <Border Background="#1E2338" CornerRadius="8" Padding="12,4" Margin="0,0,10,0" VerticalAlignment="Center">
                                <TextBlock x:Name="lblBloatwareCountBadge" Text="Taranıyor..." FontSize="12" FontWeight="Bold" Foreground="#FB7185"/>
                            </Border>
                            <Button x:Name="btnExecuteBloatwareRemoval" Content="🗑️  Seçilenleri Kaldır" Background="#E11D48" Foreground="#FFFFFF" BorderThickness="0" Padding="16,8" Cursor="Hand" FontWeight="Bold" FontSize="13">
                                <Button.Resources>
                                    <Style TargetType="Border">
                                        <Setter Property="CornerRadius" Value="8"/>
                                    </Style>
                                </Button.Resources>
                            </Button>
                        </StackPanel>

                        <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                            <Button x:Name="btnBackFromBloatware" Style="{StaticResource PresetChip}" Content="← Ana Ekrana Dön" Margin="0,0,14,0"/>
                            <Border Background="#4C0519" Width="32" Height="32" CornerRadius="8" Margin="0,0,10,0">
                                <TextBlock Text="🗑️" FontSize="16" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                            <TextBlock Text="Windows Bloatware &amp; Yerleşik Uygulama Kaldırıcı" FontSize="16" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                        </StackPanel>
                    </DockPanel>

                    <!-- Satır 1: Hızlı Seçim ve Filtre Önayarları -->
                    <Border Grid.Row="1" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,8" Margin="0,0,0,12">
                        <DockPanel LastChildFill="True">
                            <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                <Button x:Name="btnRescanBloatware" Style="{StaticResource PresetChip}" Content="🔄 Yeniden Tara"/>
                            </StackPanel>
                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                <TextBlock Text="Hızlı Seçim:" FontSize="11" FontWeight="SemiBold" Foreground="#64748B" VerticalAlignment="Center" Margin="0,0,10,0"/>
                                <Button x:Name="btnSelectSafeBloatware" Style="{StaticResource PresetChip}" Content="⚡ Önerilen Güvenli Bloatware'leri Seç" Margin="0,0,8,0"/>
                                <Button x:Name="btnSelectAllBloatware" Style="{StaticResource PresetChip}" Content="Tümünü Seç" Margin="0,0,8,0"/>
                                <Button x:Name="btnClearBloatwareSelection" Style="{StaticResource PresetChip}" Content="Seçimi Temizle" Margin="0,0,8,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>

                    <!-- Satır 2: Uygulama Listesi (ScrollViewer) -->
                    <Border Grid.Row="2" Background="#0F121C" BorderBrush="#1A1F30" BorderThickness="1" CornerRadius="10" Padding="12">
                        <Grid>
                            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                                <StackPanel x:Name="pnlBloatwareList">
                                    <TextBlock x:Name="lblBloatwarePlaceholder" Text="Yerleşik Windows uygulamaları taranıyor..." Foreground="#64748B" FontSize="13" HorizontalAlignment="Center" Margin="0,60,0,0"/>
                                </StackPanel>
                            </ScrollViewer>
                            <ProgressBar x:Name="progBloatware" Height="3" VerticalAlignment="Top" IsIndeterminate="True" Visibility="Collapsed" Foreground="#FB7185" Background="#161B2A" BorderThickness="0"/>
                        </Grid>
                    </Border>

                    <!-- Satır 3: Alt Güvenlik & İpucu Çubuğu -->
                    <Border Grid.Row="3" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,8" Margin="0,12,0,0">
                        <DockPanel LastChildFill="True">
                            <TextBlock x:Name="lblBloatwareStatus" Text="💡 Bilgi: Uygulamalar hem kullanıcı profilinden hem de Windows provisioned imajından kalıcı silinir; güncelleme gelse dahi kendi kendine geri yüklenmez." FontSize="11" Foreground="#94A3B8" VerticalAlignment="Center"/>
                        </DockPanel>
                    </Border>
                </Grid>

                <!-- GÖRÜNÜM 8: SİSTEM İNCE AYARLARI (TWEAKS) -->
                <Grid x:Name="viewTweaks" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Üst Başlık ve Hızlı Eylem Çubuğu -->
                    <Border Grid.Row="0" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="12" Padding="16,12" Margin="0,0,0,12">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                            </Grid.RowDefinitions>

                            <!-- Üst Satır: Geri Butonu + Başlık + Eylem Butonları -->
                            <DockPanel Grid.Row="0" LastChildFill="True">
                                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                    <StackPanel Orientation="Vertical" Margin="0,0,8,0" VerticalAlignment="Center">
                                        <Button x:Name="btnRestartExplorer" Style="{StaticResource PresetChip}" Content="🔄 Gezgini Yenile" Height="22" Padding="8,1" Margin="0,0,0,3" FontSize="10" ToolTip="Kibar yenileme: Değişiklikleri Windows kabuğuna bildirir (Ekran kapanmaz)."/>
                                        <Button x:Name="btnKillRestartExplorer" Style="{StaticResource PresetChip}" Content="⚡ Gezgini Yeniden Başlat" Height="22" Padding="8,1" FontSize="10" ToolTip="Tam yeniden başlatma: explorer.exe sürecini baştan başlatarak tüm görsel ayarları anında zorlar."/>
                                    </StackPanel>
                                    <Button x:Name="btnApplyRecommendedTweaks" Style="{StaticResource PrimaryBtn}" Content="⭐ Önerilenleri Uygula" Margin="0,0,8,0" VerticalAlignment="Center" ToolTip="En güvenli gizlilik ve performans ayarlarını tek tıkla uygular."/>
                                    <Button x:Name="btnResetAllTweaks" Style="{StaticResource PresetChip}" Content="↺ Sıfırla" VerticalAlignment="Center" ToolTip="Tüm ayarları orijinal Windows fabrika ayarlarına döndürür."/>
                                </StackPanel>
                                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                    <Button x:Name="btnBackFromTweaks" Style="{StaticResource PresetChip}" Content="← Ana Ekrana Dön" VerticalAlignment="Center" Margin="0,0,14,0"/>
                                    <TextBlock Text="🛡️ Sistem İnce Ayarları" FontSize="17" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                                    <Border Background="#312E81" CornerRadius="6" Padding="6,2" Margin="10,0,0,0" VerticalAlignment="Center">
                                        <TextBlock Text="Windows 11 Optimizasyonu" FontSize="10" FontWeight="Bold" Foreground="#A5B4FC"/>
                                    </Border>
                                </StackPanel>
                            </DockPanel>

                            <!-- Alt Satır: Durum / Açıklama + Arama Kutusu -->
                            <DockPanel Grid.Row="1" LastChildFill="True" Margin="0,10,0,0">
                                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                    <TextBlock Text="🔍" FontSize="12" Foreground="#64748B" VerticalAlignment="Center" Margin="0,0,6,0"/>
                                    <TextBox x:Name="txtSearchTweaks" Width="180" Height="28" Background="#161B2A" Foreground="#FFFFFF" BorderBrush="#2D374D" BorderThickness="1" VerticalContentAlignment="Center" Padding="8,0" Tag="Ayar ara..."/>
                                </StackPanel>
                                <TextBlock x:Name="lblTweaksStatus" Text="Gizlilik, telemetri, yapay zeka, arayüz ve performans ayarlarını tek tıkla açın veya kapatın." FontSize="11" Foreground="#64748B" VerticalAlignment="Center"/>
                            </DockPanel>
                        </Grid>
                    </Border>

                    <!-- Kaydırılabilir Ayar Kategorileri (12 Kategori Kartı) -->
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="0,0,8,0">
                        <StackPanel x:Name="pnlTweaksCategories">
                <!-- 🔒 Gizlilik ve Önerilen İçerikler -->
                <Border x:Name="grpTweaksPrivacy" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🔒 Gizlilik ve Önerilen İçerikler" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Telemetri, kullanıcı takibi, kilit ekranı ve sistem reklamlarını denetleyin." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Telemetri, Tanılama Verileri ve Hedefli Reklamları Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglTelemetry" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Telemetri, Tanılama Verileri ve Hedefli Reklamları Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Microsoft'a arka planda tanılama verisi (DiagTrack) gönderilmesini ve hedefli reklam takibini engeller." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- DiagTrack Telemetri Dinleyicisini Kapat (AutoLogger) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDiagtrackListener" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="DiagTrack Telemetri Dinleyicisini Kapat (AutoLogger)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows açılışında arka planda çalışan ETW telemetri oturumunu ve diske gizli .etl log yazımını engeller." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Telemetri Zamanlanmış Görevlerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglTelemetryTasks" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Telemetri Zamanlanmış Görevlerini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Application Experience, CEIP, Disk Tanılama, Geri Bildirim ve Hata Raporlama zamanlanmış görevlerini devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Windows İpuçları, Öneriler ve Tanıtımları Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglTips" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Windows İpuçları, Öneriler ve Tanıtımları Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows genelinde çıkan öneri, ipucu ve karşılama pencerelerini devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Windows Bildirimlerini Kapat (Uygulamalar ve Bildiriciler) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglNotifications" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Windows Bildirimlerini Kapat (Uygulamalar ve Bildiriciler)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Uygulamalardan ve arka plan servislerinden gelen masaüstü bildirim pencerelerini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Windows Konum Hizmetleri ve Uygulama Konum Erişimini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglLocation" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Windows Konum Hizmetleri ve Uygulama Konum Erişimini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Konum algılayıcılarını kapatır ve uygulamaların coğrafi konumunuza erişmesini engeller." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Cihazımı Bul (Find My Device) Konum Takibini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglFindMyDevice" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Cihazımı Bul (Find My Device) Konum Takibini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Arka planda cihaz konumunun periyodik olarak Microsoft hesabına kaydedilmesini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Kilit Ekranında İpuçları ve Önerileri Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglLockScreenTips" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Kilit Ekranında İpuçları ve Önerileri Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Kilit ekranında Microsoft tarafından gösterilen öneri, ipucu ve tanıtımları gizler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Microsoft Edge Reklamları ve Haber Akışını Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglEdgeAds" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Microsoft Edge Reklamları ve Haber Akışını Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Edge tarayıcısında kişiselleştirilmiş reklamları, haber akışını ve arama önerilerini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Ayarlar Ana Sayfasındaki Microsoft 365 Copilot Reklamlarını Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglCopilotSettings" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Ayarlar Ana Sayfasındaki Microsoft 365 Copilot Reklamlarını Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows Ayarlar uygulaması ana sayfasında çıkan Copilot tanıtım kartlarını gizler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- ✨ Yapay Zeka (AI) -->
                <Border x:Name="grpTweaksAI" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="✨ Yapay Zeka (AI)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Windows 11 yerleşik yapay zeka araçlarını ve arka plan modellerini yönetin." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Microsoft Copilot'ı Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglCopilot" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Microsoft Copilot'ı Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows genelindeki yerleşik Copilot yapay zeka asistanını tamamen devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Windows Recall (Ekran Geçmişi Kaydı) Özelliğini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglRecall" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Windows Recall (Ekran Geçmişi Kaydı) Özelliğini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Ekranın periyodik anlık görüntülerini alıp analiz eden Recall sistemini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gelişmiş Yapay Zeka ve Sistem AI Bileşenlerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglAdvancedAI" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Gelişmiş Yapay Zeka ve Sistem AI Araçlarını Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Copilot+ donanım efektleri (Studio Effects, AutoSR, Voice Clarity), klavye Copilot tuşu, Gezgin ve Fotoğraflar AI araçlarını kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Click To Do, Yapay Zeka Metin ve Görüntü Analizini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglClickToDo" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Click To Do, Yapay Zeka Metin ve Görüntü Analizini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Ekranda tıklanan metin ve görsellerin arka planda yapay zeka ile taranmasını engeller." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Yapay Zeka Hizmetinin Otomatik Başlamasını Engelle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglAIService" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Yapay Zeka Hizmetinin Otomatik Başlamasını Engelle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Arka planda çalışan yapay zeka modelleri sistem servisinin otomatik açılmasını önler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Microsoft Edge Yapay Zeka Özelliklerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglEdgeAI" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Microsoft Edge Yapay Zeka Özelliklerini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Edge içindeki Copilot yan çubuğu ve yapay zeka metin tamamlama özelliklerini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Google Chrome Yapay Zeka (AI & Gemini) Özelliklerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglChromeAI" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Google Chrome Yapay Zeka (AI &amp; Gemini) Özelliklerini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Chrome'daki Gemini entegrasyonunu, AI arama/yazma araçlarını ve yerel modellerin (Gemini Nano) RAM/disk tüketimini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Paint Yapay Zeka (Cocreator / Sihirli Silgi) Özelliklerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglPaintAI" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Paint Yapay Zeka (Cocreator / Sihirli Silgi) Özelliklerini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Paint uygulamasındaki yapay zeka araçlarını ve bulut model isteklerini devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Not Defteri Yapay Zeka (AI Yeniden Yazma) Özelliklerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglNotepadAI" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Not Defteri Yapay Zeka (AI Yeniden Yazma) Özelliklerini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Not Defteri uygulamasındaki Copilot metin dönüştürme ve analiz araçlarını kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 🖌️ Görünüm (Appearance) -->
                <Border x:Name="grpTweaksAppearance" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🖌️ Görünüm (Appearance)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Windows koyu tema, saydamlık, görsel efektler ve masaüstü duvar kağıdı ayarları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Sistem ve Uygulamalar İçin Koyu Temayı (Dark Mode) Etkinleştir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDarkMode" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Sistem ve Uygulamalar İçin Koyu Temayı (Dark Mode) Etkinleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows kabuğu ve desteklenen tüm uygulamalar için göz yormayan karanlık temayı açar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Saydamlık Efektlerini Kapat (Performans Artışı) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglTransparency" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Saydamlık Efektlerini Kapat (Performans Artışı)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Görev çubuğu ve pencerelerdeki akrilik saydamlığı kapatıp GPU yükünü hafifletir." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Pencere Animasyonlarını ve Görsel Efektleri Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglAnimations" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Pencere Animasyonlarını ve Görsel Efektleri Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Pencerelerin açılış-kapanış animasyonlarını kapatır. ⚡ ('Gezgini Yeniden Başlat' butonu ile anında devreye girer)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Masaüstünde Windows Öne Çıkanlar (Spotlight) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbSpotlight" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Simgesi Göster (Varsayılan)"/>
                                <ComboBoxItem Content="Simgesi Gizle"/>
                                <ComboBoxItem Content="Spotlight Arka Planını Kapat"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Masaüstünde Windows Öne Çıkanlar (Spotlight)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Masaüstü arka planında Spotlight önerilerini ve 'Bu resim hakkında bilgi edinin' simgesini yönetin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 🗗 Çoklu Görev (Multi-tasking) -->
                <Border x:Name="grpTweaksMultiTasking" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🗗 Çoklu Görev (Multi-tasking)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Pencere hizalama (Snap), yerleşim şablonları ve Alt+Tab sekme gösterimi." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Pencere Hizalamayı (Window Snapping) Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglSnap" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Pencere Hizalamayı (Window Snapping) Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Pencerelerin ekran kenarlarına sürüklendiğinde otomatik yapışmasını/bölünmesini kapatır. 💻 (Tam etki için oturumu kapatıp açmanız veya bilgisayarı yeniden başlatmanız gerekir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Hizalama Sırasında Uygulama Önerilerini Göstermeyi Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglSnapSuggestions" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Hizalama Sırasında Uygulama Önerilerini Göstermeyi Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Bir pencere yana yaslandığında boş kalan yarıda diğer pencerelerin önerilmesini kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Üst Ekran ve Büyüt Butonundaki Hizalama Menüsünü Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglSnapFlyout" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Üst Ekran ve Büyüt Butonundaki Hizalama Menüsünü Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Pencerelerin büyüt butonuna gelindiğinde açılan hizalama şablonları kutusunu gizler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Alt+Tab Basıldığında Tarayıcı Sekmelerini Gösterme -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbAltTabTabs" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Sekmeleri Gösterme (Yalnızca Pencereler)"/>
                                <ComboBoxItem Content="En Son 3 Sekmeyi Göster (Varsayılan)"/>
                                <ComboBoxItem Content="En Son 5 Sekmeyi Göster"/>
                                <ComboBoxItem Content="En Son 20 Sekmeyi Göster"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Alt+Tab Basıldığında Tarayıcı Sekmelerini Gösterme" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Alt+Tab tuşlarına basıldığında açık tarayıcı sekmelerinin gösterilip gösterilmeyeceğini belirleyin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 💻 Sistem (System) -->
                <Border x:Name="grpTweaksSystem" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="💻 Sistem (System)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Sağ tık menüsü, fare ivmesi, depolama ve başlangıç optimizasyonları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Dosya Taşırken ve Paylaşırken 'Sürükleme Tepsisi'ni Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDragTray" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Dosya Taşırken ve Paylaşırken 'Sürükleme Tepsisi'ni Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Dosya sürüklerken ekran üstünde açılan paylaşım tepsisini devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Klasik Windows 10 Sağ Tık Menüsünü Kullan -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglClassicContextMenu" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Klasik Windows 10 Sağ Tık Menüsünü Kullan" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows 11'in kısaltılmış menüsü yerine doğrudan eski tam sağ tık menüsünü açar. ⚡ ('Gezgini Yeniden Başlat' butonu ile anında devreye girer)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gelişmiş Sağ Tık (Bağlam Menüsü) Yöneticisi -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <Button x:Name="btnOpenContextMenuManager" Content="Menüyü Yönet ➔" Background="#0284C7" Foreground="#FFFFFF" BorderThickness="0" Padding="12,5" Cursor="Hand" FontWeight="SemiBold" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <Button.Resources>
                                    <Style TargetType="Border">
                                        <Setter Property="CornerRadius" Value="6"/>
                                    </Style>
                                </Button.Resources>
                            </Button>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="🛠️ Gelişmiş Sağ Tık (Bağlam Menüsü) Yöneticisi" FontSize="13" FontWeight="SemiBold" Foreground="#38BDF8"/>
                                <TextBlock Text="Sağ tık menüsünü temizleyin (WinRAR, 7-Zip, Notepad++, VLC vb. kaldırın) veya yeni pratik araçlar ve özel programlar (.exe) ekleyin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Fare İvmesini (İşaretçi Hassasiyetini Artır) Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglMouseAccel" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Fare İvmesini (İşaretçi Hassasiyetini Artır) Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Hıza göre değişen fare ivmesini kaldırır; oyuncular için 1:1 net kontrol sağlar. 💻 (Tam etki için bilgisayarı yeniden başlatmanız önerilir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Yapışkan Tuşlar Kısayolunu Kapat (5x Shift) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglStickyKeys" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Yapışkan Tuşlar Kısayolunu Kapat (5x Shift)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Shift tuşuna 5 kez üst üste basıldığında beliren 'Yapışkan Tuşlar' uyarısını engeller." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Akıllı Depolama (Storage Sense) Otomatik Temizliğini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglStorageSense" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Akıllı Depolama (Storage Sense) Otomatik Temizliğini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows'un geçici dosyaları arka planda otomatik olarak silmesini devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Hızlı Başlatmayı (Fast Startup / Hiberboot) Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglFastStartup" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Hızlı Başlatmayı (Fast Startup / Hiberboot) Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Kapanışta çekirdek durumunun diske kaydedilmesini kapatır; temiz ve kararlı açılış sağlar. 💻 (Bilgisayar yeniden başladığında devreye girer)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- BitLocker Otomatik Cihaz Şifrelemesini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglBitLockerAuto" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="BitLocker Otomatik Cihaz Şifrelemesini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Yeni kurulumlarda veya donanım değişikliklerinde disklerin otomatik kilitlenmesini engeller. 💻 (Tam etki için bilgisayarı yeniden başlatmanız önerilir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Modern Standby Ağ Bağlantısını Kapat (Pil Tasarrufu) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglModernStandby" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Modern Standby Ağ Bağlantısını Kapat (Pil Tasarrufu)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Cihaz uyku (Modern Standby) modundayken arka planda ağ bağlantısını keserek pil ömrünü korur. 💻 (Tam etki için bilgisayarı yeniden başlatmanız önerilir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 🔄 Windows Update -->
                <Border x:Name="grpTweaksWindowsUpdate" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🔄 Windows Update" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Windows Update teslim iyileştirme, yeniden başlatma ve otomatik sürücü kuralları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- 'En Son Güncellemeleri Hemen Al' Seçeneğini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglLatestUpdatesOptIn" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="'En Son Güncellemeleri Hemen Al' Seçeneğini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Deneysel özellik güncellemelerinin öncelikli sunulmasını engeller, kararlı sürümde tutar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Oturum Açıkken Otomatik Yeniden Başlatmayı Engelle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglPreventAutoRestart" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Oturum Açıkken Otomatik Yeniden Başlatmayı Engelle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows Update sonrasında bilgisayar başında çalışırken sistemin aniden yeniden başlamasını önler. 💻 (Yeniden başlatma ilkesi için bilgisayarı yeniden başlatmanız önerilir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Güncellemelerin Diğer PC'lerle Paylaşılmasını Kapat (P2P) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDeliveryOptimization" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Güncellemelerin Diğer PC'lerle Paylaşılmasını Kapat (P2P)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="İndirilen Windows güncellemelerinin yerel ağdaki veya internetteki PC'lere yüklenmesini durdurur." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Windows'un Otomatik Donanım Yardımcı Uygulamaları Yüklemesini Engelle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglCompanionApps" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Windows'un Otomatik Donanım Yardımcı Uygulamaları Yüklemesini Engelle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Yeni donanım takıldığında Microsoft Store'dan otomatik yardımcı yazılım indirilmesini önler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 📁 Dosya Gezgini (File Explorer) -->
                <Border x:Name="grpTweaksExplorer" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="📁 Dosya Gezgini (File Explorer)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Dosya uzantıları, gizli dosyalar, sürücü harfleri ve sol gezinti bölmesi." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Dosya Gezginini Şununla Aç -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbLaunchTo" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Başlangıç / Giriş (Varsayılan)"/>
                                <ComboBoxItem Content="Bu Bilgisayar (This PC)"/>
                                <ComboBoxItem Content="İndirilenler"/>
                                <ComboBoxItem Content="OneDrive"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Dosya Gezginini Şununla Aç" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Dosya Gezgini ilk açıldığında görüntülenecek başlangıç konumunu belirleyin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Bilinen Dosya Türleri İçin Dosya Uzantılarını Göster -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglFileExtensions" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Bilinen Dosya Türleri İçin Dosya Uzantılarını Göster" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Güvenlik için tüm dosyaların gerçek uzantılarını görünür hale getirir (.exe, .txt vb.)." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Dosya Gezgininde Kompakt Görünümü Etkinleştir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglCompactMode" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Dosya Gezgininde Kompakt Görünümü Etkinleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Dosya ve klasörler arasındaki boşlukları azaltarak ekranda daha fazla öğe listeler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gizli Dosya, Klasör ve Sürücüleri Göster -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHiddenFiles" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Gizli Dosya, Klasör ve Sürücüleri Göster" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Sistemdeki gizli dosyaları ve klasörleri görünür kılar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gezinti Bölmesindeki Yinelenen Taşınabilir Sürücü Simgelerini Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDuplicateDrives" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Gezinti Bölmesindeki Yinelenen Taşınabilir Sürücü Simgelerini Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="USB ve harici disklerin sol menüde iki kez listelenmesi hatasını düzeltir." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gezinti Bölmesinden 'Giriş / Başlangıç' Sekmesini Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideHome" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Gezinti Bölmesinden 'Giriş / Başlangıç' Sekmesini Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Dosya Gezgini sol kenar çubuğundaki Giriş (Home) kısayolunu kaldırır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gezinti Bölmesinden 'Galeri' Sekmesini Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideGallery" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Gezinti Bölmesinden 'Galeri' Sekmesini Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Dosya Gezgini sol kenar çubuğundaki Galeri simgesini gizler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Gezinti Bölmesinden 'OneDrive' Simgesini Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideOneDrive" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Gezinti Bölmesinden 'OneDrive' Simgesini Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Dosya Gezgini sol kenar çubuğundaki OneDrive kısayolunu gizler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- 'Bu Bilgisayar' Altına Klasörleri Geri Getir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglCommonFoldersThisPC" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="'Bu Bilgisayar' Altına Klasörleri Geri Getir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Belgeler, İndirilenler, Müzik, Resimler klasörlerini 'Bu Bilgisayar' altına geri ekler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Sürücü Harfi Konumu -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbDriveLetters" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Sürücü Harfini Etiketten Sonra Göster (Varsayılan)"/>
                                <ComboBoxItem Content="Sürücü Harfini Etiketten Önce Göster"/>
                                <ComboBoxItem Content="Ağ Sürücü Harflerini Önce Göster"/>
                                <ComboBoxItem Content="Sürücü Harflerini Gizle"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Sürücü Harfi Konumu" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Sürücü harflerinin etiketten önce veya sonra nasıl listeleneceğini ayarlayın." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- ⊞ İsteğe Bağlı Windows Özellikleri -->
                <Border x:Name="grpTweaksOptionalFeatures" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="⊞ İsteğe Bağlı Windows Özellikleri" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Gelişmiş Windows sanallaştırma ve alt sistem özellikleri." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Windows Sandbox (Güvenli Korumalı Alan) Özelliğini Etkinleştir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglSandbox" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Windows Sandbox (Güvenli Korumalı Alan) Özelliğini Etkinleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Şüpheli yazılımları güvenle test edebileceğiniz tek kullanımlık sanal Windows ortamı. 💻 (Değişiklik için bilgisayarı yeniden başlatmanız gerekir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Linux için Windows Alt Sistemi (WSL) Özelliğini Etkinleştir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglWSL" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Linux için Windows Alt Sistemi (WSL) Özelliğini Etkinleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows üzerinde yerel Linux dağıtımlarını (Ubuntu, Debian vb.) çalıştırmayı sağlar. 💻 (Değişiklik için bilgisayarı yeniden başlatmanız gerekir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 🗂️ Başlat Menüsü ve Arama -->
                <Border x:Name="grpTweaksStartSearch" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🗂️ Başlat Menüsü ve Arama" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Başlat menüsü düzeni, web araması, önerilenler ve arama kutusu ayarları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Başlat Menüsünden Sabitlenmiş Uygulamaları Kaldır -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbPinnedApps" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Sabitlenmiş Uygulamaları Temizle"/>
                                <ComboBoxItem Content="Varsayılan Düzen"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Başlat Menüsünden Sabitlenmiş Uygulamaları Kaldır" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Başlat menüsündeki tüm varsayılan sabitlenmiş simgeleri temizleyin veya koruyun." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Başlat Menüsü 'Tüm Uygulamalar' Görünümü -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbAllAppsView" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Tüm Uygulamaları Gizle (Hide)"/>
                                <ComboBoxItem Content="Kategori Görünümü - Varsayılan (Category)"/>
                                <ComboBoxItem Content="Izgara Görünümü (Grid)"/>
                                <ComboBoxItem Content="Liste Görünümü (List)"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Başlat Menüsü 'Tüm Uygulamalar' Görünümü" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Başlat menüsü 'Tüm Uygulamalar' düzenini seçin: Gizle, Kategori, Izgara veya Liste (Raphire 4 Mod)." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Başlat Menüsündeki 'Önerilenler' Bölümünü Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideRecommended" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Başlat Menüsündeki 'Önerilenler' Bölümünü Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Başlat menüsündeki son açılan dosyalar ve önerilen içerik kutusunu tamamen gizler." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Başlat Menüsünde Telefon Bağlantısı Entegrasyonunu Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDisablePhoneLink" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Başlat Menüsünde Telefon Bağlantısı Entegrasyonunu Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Başlat menüsü yanında beliren telefon durumu ve bildirim çubuğunu kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Başlat Menüsünde Bing Web Araması ve Copilot'ı Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDisableBingSearch" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Başlat Menüsünde Bing Web Araması ve Copilot'ı Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Arama çubuğuna yazınca internette arama yapılmasını engeller, sadece bilgisayarınızda arar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Aramada Microsoft Store Uygulama Önerilerini Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDisableStoreSearch" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Aramada Microsoft Store Uygulama Önerilerini Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Başlat arama sonuçlarında mağaza uygulamalarının ve reklamlarının önerilmesini engeller." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 🗔 Görev Çubuğu (Taskbar) -->
                <Border x:Name="grpTweaksTaskbar" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🗔 Görev Çubuğu (Taskbar)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Hizalama, arama stili, simge birleştirme, hava durumu ve geliştirici ayarları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Görev Çubuğunu Sola Hizala (Windows 10 Stili) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglAlignLeft" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Görev Çubuğunu Sola Hizala (Windows 10 Stili)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Başlat menüsü ve görev çubuğu simgelerini ortaya değil, sol köşeye hizalar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Görev Çubuğu Arama Stili -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbSearchStyle" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Arama Kutusunu Göster (Varsayılan)"/>
                                <ComboBoxItem Content="Arama Simgesi ve Etiketi Göster"/>
                                <ComboBoxItem Content="Yalnızca Arama Simgesini Göster"/>
                                <ComboBoxItem Content="Aramayı Gizle"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Görev Çubuğu Arama Stili" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Görev çubuğundaki arama alanının nasıl görüntüleneceğini seçin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Görev Çubuğundaki 'Görev Görünümü' Butonunu Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideTaskView" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Görev Çubuğundaki 'Görev Görünümü' Butonunu Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Sanal masaüstleri butonunu görev çubuğundan kaldırır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Görev Çubuğu ve Kilit Ekranında Widget'ları (Hava Durumu) Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglDisableWidgets" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Görev Çubuğu ve Kilit Ekranında Widget'ları (Hava Durumu) Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Sol alt köşedeki hava durumu ve haberler widget düğmesini tamamen kapatır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Görev Çubuğunda Sohbet (Chat / Meet Now) Simgesini Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideChat" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Görev Çubuğunda Sohbet (Chat / Meet Now) Simgesini Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Görev çubuğundaki Microsoft Teams Sohbet / Şimdi Toplan simgesini gizler. ⚡ ('Gezgini Yeniden Başlat' ile anında devreye girer)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Sağ Tık Menüsünde 'Görevi Sonlandır' Seçeneğini Göster -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglEndTask" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Sağ Tık Menüsünde 'Görevi Sonlandır' Seçeneğini Göster" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Görev çubuğunda yanıt vermeyen uygulamalara sağ tıklayıp doğrudan sonlandırma imkanı sunar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- 'Son Aktif Pencereye Geçiş' (Last Active Click) Modunu Aç -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglLastActiveClick" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="'Son Aktif Pencereye Geçiş' (Last Active Click) Modunu Aç" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Birden fazla penceresi olan simgeye tıklandığında önizleme yerine son aktif pencereye anında geçer." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Görev Çubuğu Uygulamalarını Şurada Göster (Çoklu Monitör) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbShowAppsOn" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Tüm Görev Çubuklarında (Varsayılan)"/>
                                <ComboBoxItem Content="Ana Görev Çubuğu ve Pencerenin Açık Olduğu Çubuk"/>
                                <ComboBoxItem Content="Yalnızca Pencerenin Açık Olduğu Çubuk"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Görev Çubuğu Uygulamalarını Şurada Göster (Çoklu Monitör)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Çoklu monitörlerde uygulama butonlarının nerede yer alacağını belirleyin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Ana Ekranda Görev Çubuğu Düğmelerini Birleştir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbCombineMain" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Her Zaman (Varsayılan)"/>
                                <ComboBoxItem Content="Görev Çubuğu Dolduğunda"/>
                                <ComboBoxItem Content="Hiçbir Zaman"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Ana Ekranda Görev Çubuğu Düğmelerini Birleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Ana ekranda uygulama etiketlerinin gösterilme ve birleştirilme mantığını seçin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- İkincil Ekranlarda Görev Çubuğu Düğmelerini Birleştir -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <ComboBox x:Name="cmbCombineSecondary" Style="{StaticResource DarkComboBox}" Width="230" Height="28" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0">
                                <ComboBoxItem Content="Değişiklik Yapma"/>
                                <ComboBoxItem Content="Her Zaman (Varsayılan)"/>
                                <ComboBoxItem Content="Görev Çubuğu Dolduğunda"/>
                                <ComboBoxItem Content="Hiçbir Zaman"/>
                            </ComboBox>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="İkincil Ekranlarda Görev Çubuğu Düğmelerini Birleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="İkinci ve diğer monitörlerde görev çubuğu düğmelerinin birleştirilme mantığını seçin." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Tüm Sistem Tepsisi Simgelerini Göster -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglShowAllTrayIcons" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Tüm Sistem Tepsisi Simgelerini Göster" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Arka plan uygulamalarını yukarı ok (^) menüsüne gizlemek yerine doğrudan görev çubuğunda gösterir." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- 🎮 Oyun (Gaming) -->
                <Border x:Name="grpTweaksGaming" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="🎮 Oyun (Gaming)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Xbox Game Bar ve arka plan ekran kaydı optimizasyonları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Xbox Oyun/Ekran Arka Plan Kaydını (Game DVR) Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglGameDVR" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Xbox Oyun/Ekran Arka Plan Kaydını (Game DVR) Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Oyun sırasında arka planda sürekli kayıt yapılmasını kapatarak FPS düşüşünü engeller. 💻 (Tam etki için bilgisayarı yeniden başlatmanız önerilir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Xbox Game Bar Entegrasyonunu Kapat -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglGameBar" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Xbox Game Bar ve Oyun Kayıt Entegrasyonunu Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Windows + G kısayolu ile açılan Game Bar arayüzünü ve kayıt servislerini devre dışı bırakır (Uygulama paketini silmez). 💻 (Tam etki için bilgisayarı yeniden başlatmanız önerilir)" FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                <!-- ⚙️ Diğer (Other) -->
                <Border x:Name="grpTweaksOther" Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                    <StackPanel>
                        <DockPanel LastChildFill="True" Margin="0,0,0,4">
                            <TextBlock Text="⚙️ Diğer (Other)" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                        </DockPanel>
                        <TextBlock Text="Windows Ayarlar uygulaması ve Brave tarayıcı optimizasyonları." FontSize="11" Foreground="#94A3B8" Margin="0,0,0,10"/>
                    <!-- Ayarlar Uygulamasındaki 'Giriş' (Home) Sayfasını Gizle -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglHideSettingsHome" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Ayarlar Uygulamasındaki 'Giriş' (Home) Sayfasını Gizle" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Ayarlar açıldığında tanıtım dolu Giriş sekmesi yerine doğrudan Sistem sekmesini açar." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <!-- Brave Tarayıcısındaki Gereksiz Özellikleri Kapat (AI, Kripto) -->
                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                        <DockPanel LastChildFill="True">
                            <CheckBox x:Name="tglBraveBloat" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="16,0,0,0"/>
                            <StackPanel VerticalAlignment="Center">
                                <TextBlock Text="Brave Tarayıcısındaki Gereksiz Özellikleri Kapat (AI, Kripto)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                <TextBlock Text="Brave tarayıcısındaki Kripto Cüzdanı, Brave Rewards ve AI sohbetini devre dışı bırakır." FontSize="11" Foreground="#64748B" TextWrapping="Wrap" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    </StackPanel>
                </Border>
                        </StackPanel>
                    </ScrollViewer>

                    <!-- Alt Eylem Çubuğu: Bekleyen Değişiklikler & Toplu Uygula Butonu -->
                    <Border Grid.Row="2" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="12" Padding="16,10" Margin="0,10,0,0">
                        <DockPanel LastChildFill="True">
                            <StackPanel Orientation="Horizontal" DockPanel.Dock="Right" VerticalAlignment="Center">
                                <Button x:Name="btnDiscardPendingTweaks" Style="{StaticResource PresetChip}" Content="↺ Değişiklikleri Geri Al" Margin="0,0,10,0" VerticalAlignment="Center" Visibility="Collapsed" ToolTip="Uygulanmamış tüm değişiklikleri iptal edip önceki haline döndürür."/>
                                <Button x:Name="btnApplyPendingTweaks" Content="✨ 0 değişikliği uygula" FontWeight="Bold" FontSize="13" Padding="18,8" Height="36" VerticalAlignment="Center" IsEnabled="False" Opacity="0.5" Cursor="Hand" Background="#1E293B" Foreground="#64748B" ToolTip="Seçilen tüm sistem ince ayarlarını sırayla uygular.">
                                    <Button.Resources>
                                        <Style TargetType="Border">
                                            <Setter Property="CornerRadius" Value="8"/>
                                        </Style>
                                    </Button.Resources>
                                </Button>
                            </StackPanel>
                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                <TextBlock Text="Bekleyen değişiklikler: " FontSize="13" Foreground="#94A3B8" VerticalAlignment="Center"/>
                                <TextBlock x:Name="lblPendingTweaksCount" Text="0 ayar" FontSize="13" FontWeight="Bold" Foreground="#64748B" VerticalAlignment="Center"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                </Grid>

                <!-- GÖRÜNÜM 9: SAĞ TIK (BAĞLAM MENÜSÜ) YÖNETİCİSİ -->
                <Grid x:Name="viewContextMenu" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Satır 0: Üst Başlık & Hızlı Eylem Çubuğu (2 Satırlı Geniş Düzen - Çakışma Kesinlikle Engellendi) -->
                    <Border Grid.Row="0" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="12" Padding="16,12" Margin="0,0,0,12">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                            </Grid.RowDefinitions>

                            <!-- Üst Satır: Geri Butonu + Başlık (Sol) ve Toplam Durum Rozeti (Sağ) -->
                            <DockPanel Grid.Row="0" LastChildFill="True">
                                <Border DockPanel.Dock="Right" Background="#1E2338" CornerRadius="8" Padding="12,5" VerticalAlignment="Center">
                                    <TextBlock x:Name="lblContextMenuBadge" Text="Toplam: -- Öğe" FontSize="11" FontWeight="Bold" Foreground="#38BDF8"/>
                                </Border>

                                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                    <Button x:Name="btnBackFromContextMenu" Style="{StaticResource PresetChip}" Content="← İnce Ayarlara Dön" Margin="0,0,14,0"/>
                                    <Border Background="#0C4A6E" Width="30" Height="30" CornerRadius="8" Margin="0,0,10,0">
                                        <TextBlock Text="🖱️" FontSize="15" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                    </Border>
                                    <TextBlock Text="Sağ Tık (Bağlam Menüsü) Yöneticisi" FontSize="17" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                                </StackPanel>
                            </DockPanel>

                            <!-- Alt Satır: Açıklama Metni (Sol) + Hızlı Eylem Butonları (Sağ) -->
                            <DockPanel Grid.Row="1" LastChildFill="True" Margin="0,10,0,0">
                                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                    <Button x:Name="btnToggleCtxTools" Style="{StaticResource PresetChip}" Content="➕ Program &amp; Kısayol Ekle ▼" Margin="0,0,8,0" Foreground="#38BDF8" ToolTip="Hazır pratik kısayolları ve özel program (.exe) ekleme panelini açıp kapatır."/>
                                    <Button x:Name="btnRestartExplorerFromCtx" Style="{StaticResource PresetChip}" Content="⚡ Gezgini Yeniden Başlat" Margin="0,0,8,0" FontWeight="Bold" Foreground="#38BDF8" ToolTip="explorer.exe sürecini baştan başlatarak sağ tık menüsündeki tüm gizleme, ekleme ve kaldırma değişikliklerini anında aktif eder."/>
                                    <Button x:Name="btnRescanContextMenu" Style="{StaticResource PresetChip}" Content="🔄 Yeniden Tara"/>
                                </StackPanel>

                                <TextBlock Text="Sağ tık menüsünü temizleyin, gereksiz eklentileri gizleyin veya özel programlar ekleyin." FontSize="11" Foreground="#64748B" VerticalAlignment="Center" TextWrapping="Wrap" Margin="0,0,12,0"/>
                            </DockPanel>
                        </Grid>
                    </Border>

                    <!-- Satır 1: Hazır Kısayollar ve Özel Program Ekleme Panelleri (Açılır/Kapanır Çekmece - Varsayılan: Gizli) -->
                    <Border x:Name="pnlCtxQuickTools" Grid.Row="1" Visibility="Collapsed" Margin="0,0,0,12">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="12"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>

                            <!-- Sol Kart: Hazır Süper Kısayollar -->
                            <Border Grid.Column="0" Background="#111420" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="10" Padding="14,12">
                                <StackPanel>
                                    <TextBlock Text="⚡ Hazır Pratik Kısayollar" FontSize="13" FontWeight="Bold" Foreground="#38BDF8" Margin="0,0,0,4"/>
                                    <TextBlock Text="Sağ tık menünüze tek tıkla güçlü Windows kısayolları ekleyin:" FontSize="11" Foreground="#64748B" Margin="0,0,0,10"/>

                                    <!-- Kısayol 1: Yönetici Terminali Aç -->
                                    <DockPanel Margin="0,0,0,8">
                                        <CheckBox x:Name="tglCtxTerminalAdmin" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                        <StackPanel VerticalAlignment="Center">
                                            <TextBlock Text="💻 Yönetici Olarak Terminal Aç" FontSize="12" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                            <TextBlock Text="Masaüstü ve klasör boşluğunda yönetici PowerShell açar" FontSize="10" Foreground="#64748B"/>
                                        </StackPanel>
                                    </DockPanel>

                                    <!-- Kısayol 2: Sahipliği Al -->
                                    <DockPanel Margin="0,0,0,8">
                                        <CheckBox x:Name="tglCtxTakeOwnership" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                        <StackPanel VerticalAlignment="Center">
                                            <TextBlock Text="🛡️ Sahipliği Al (Take Ownership)" FontSize="12" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                            <TextBlock Text="Erişilemeyen dosya ve klasörlerde tam sahiplik yetkisi alır" FontSize="10" Foreground="#64748B"/>
                                        </StackPanel>
                                    </DockPanel>

                                    <!-- Kısayol 3: Not Defteri ile Aç -->
                                    <DockPanel Margin="0,0,0,8">
                                        <CheckBox x:Name="tglCtxOpenNotepad" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                        <StackPanel VerticalAlignment="Center">
                                            <TextBlock Text="📝 Not Defteri ile Aç" FontSize="12" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                            <TextBlock Text="Tüm dosya türleri için hızlı Not Defteri seçeneği" FontSize="10" Foreground="#64748B"/>
                                        </StackPanel>
                                    </DockPanel>

                                    <!-- Kısayol 4: Yolu Kopyala -->
                                    <DockPanel Margin="0,0,0,8">
                                        <CheckBox x:Name="tglCtxCopyPath" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                        <StackPanel VerticalAlignment="Center">
                                            <TextBlock Text="📋 Dosya / Klasör Yolunu Kopyala" FontSize="12" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                            <TextBlock Text="Seçilen öğenin tam yolunu doğrudan panoya kopyalar" FontSize="10" Foreground="#64748B"/>
                                        </StackPanel>
                                    </DockPanel>

                                    <!-- Kısayol 5: VirusTotal ile Tara -->
                                    <DockPanel>
                                        <CheckBox x:Name="tglCtxVirusTotal" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                        <StackPanel VerticalAlignment="Center">
                                            <TextBlock Text="🛡️ VirusTotal ile Tara" FontSize="12" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                            <TextBlock Text="Dosya hash'i ile anında 70+ antivirüs raporunu tarayıcıda açar" FontSize="10" Foreground="#64748B"/>
                                        </StackPanel>
                                    </DockPanel>
                                </StackPanel>
                            </Border>

                            <!-- Sağ Kart: Özel Uygulama (.exe) Ekle -->
                            <Border Grid.Column="2" Background="#111420" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="10" Padding="14,12">
                                <StackPanel>
                                    <TextBlock Text="➕ Sağ Tık Menüsüne Program (.exe) Ekle" FontSize="13" FontWeight="Bold" Foreground="#10B981" Margin="0,0,0,4"/>
                                    <TextBlock Text="İstediğiniz programı sağ tık menüsüne ekleyerek doğrudan çalıştırın:" FontSize="11" Foreground="#64748B" Margin="0,0,0,8"/>

                                    <!-- Menü Başlığı -->
                                    <TextBlock Text="Menü Başlığı:" FontSize="11" Foreground="#94A3B8" Margin="0,0,0,2"/>
                                    <TextBox x:Name="txtCustomAppName" Height="26" Background="#181F30" Foreground="#FFFFFF" BorderBrush="#2A344A" BorderThickness="1" Padding="6,2" FontSize="11" Margin="0,0,0,6"/>

                                    <!-- Program Yolu + Gözat -->
                                    <TextBlock Text="Program (.exe) Dosya Yolu:" FontSize="11" Foreground="#94A3B8" Margin="0,0,0,2"/>
                                    <DockPanel Margin="0,0,0,6">
                                        <Button x:Name="btnBrowseCustomApp" Content="Gözat..." DockPanel.Dock="Right" Background="#1E293B" Foreground="#38BDF8" BorderThickness="0" Padding="10,2" Margin="6,0,0,0" Cursor="Hand" FontWeight="SemiBold" FontSize="11">
                                            <Button.Resources>
                                                <Style TargetType="Border">
                                                    <Setter Property="CornerRadius" Value="4"/>
                                                </Style>
                                            </Button.Resources>
                                        </Button>
                                        <TextBox x:Name="txtCustomAppPath" Height="26" Background="#181F30" Foreground="#FFFFFF" BorderBrush="#2A344A" BorderThickness="1" Padding="6,2" FontSize="11"/>
                                    </DockPanel>

                                    <!-- Kapsam ve Ekle Butonu -->
                                    <DockPanel>
                                        <Button x:Name="btnAddCustomApp" Content="➕ Menüye Ekle" DockPanel.Dock="Right" Background="#059669" Foreground="#FFFFFF" BorderThickness="0" Padding="14,4" Cursor="Hand" FontWeight="Bold" FontSize="11" Margin="8,0,0,0">
                                            <Button.Resources>
                                                <Style TargetType="Border">
                                                    <Setter Property="CornerRadius" Value="5"/>
                                                </Style>
                                            </Button.Resources>
                                        </Button>
                                        <ComboBox x:Name="cmbCustomAppTarget" Style="{StaticResource DarkComboBox}" Height="26" FontSize="11">
                                            <ComboBoxItem Content="Tüm Dosyalar (*)" IsSelected="True"/>
                                            <ComboBoxItem Content="Klasörler (Directory)"/>
                                            <ComboBoxItem Content="Masaüstü ve Arka Plan (Boşluk)"/>
                                        </ComboBox>
                                    </DockPanel>
                                </StackPanel>
                            </Border>
                        </Grid>
                    </Border>

                    <!-- Satır 2: Mevcut Sağ Tık Menü Öğeleri Listesi (Arama Çubuğu + Geniş ScrollViewer) -->
                    <Border Grid.Row="2" Background="#0F121C" BorderBrush="#1A1F30" BorderThickness="1" CornerRadius="10" Padding="12">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="*"/>
                            </Grid.RowDefinitions>

                            <!-- Arama ve Liste Başlığı Çubuğu -->
                            <DockPanel Grid.Row="0" Margin="0,0,0,10" LastChildFill="True">
                                <Border DockPanel.Dock="Right" Background="#161B2A" BorderBrush="#242E44" BorderThickness="1" CornerRadius="8" Padding="10,4" Width="260">
                                    <DockPanel LastChildFill="True">
                                        <TextBlock Text="🔍" FontSize="11" Foreground="#64748B" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                        <TextBox x:Name="txtSearchContextMenu" Background="Transparent" Foreground="#FFFFFF" BorderThickness="0" FontSize="11" VerticalAlignment="Center" CaretBrush="#38BDF8"/>
                                    </DockPanel>
                                </Border>
                                <TextBlock Text="Mevcut Sağ Tık Öğeleri" FontSize="13" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                            </DockPanel>

                            <Grid Grid.Row="1">
                                <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                                    <StackPanel x:Name="pnlContextMenuList">
                                        <TextBlock x:Name="lblContextMenuPlaceholder" Text="Sağ tık menü öğeleri taranıyor..." Foreground="#64748B" FontSize="13" HorizontalAlignment="Center" Margin="0,40,0,0"/>
                                    </StackPanel>
                                </ScrollViewer>
                                <ProgressBar x:Name="progContextMenu" Height="3" VerticalAlignment="Top" IsIndeterminate="True" Visibility="Collapsed" Foreground="#38BDF8" Background="#161B2A" BorderThickness="0"/>
                            </Grid>
                        </Grid>
                    </Border>

                    <!-- Satır 3: Alt Durum & Bilgilendirme Çubuğu -->
                    <Border Grid.Row="3" Background="#10131E" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="8" Padding="14,8" Margin="0,12,0,0">
                        <DockPanel LastChildFill="True">
                            <TextBlock x:Name="lblContextMenuStatus" Text="💡 İpucu: Kaldırdığınız veya devre dışı bıraktığınız sağ tık öğeleri istediğiniz an tekrar etkinleştirilebilir. Değişikliklerin anında görünmesi için '⚡ Gezgini Yenile' butonunu kullanabilirsiniz." FontSize="11" Foreground="#94A3B8" VerticalAlignment="Center"/>
                        </DockPanel>
                    </Border>
                </Grid>

                <!-- GÖRÜNÜM 9: PERFORMANS VE OYUN MODU MERKEZİ -->
                <Grid x:Name="viewPerformance" Visibility="Collapsed">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>

                    <!-- Satır 0: Üst Başlık ve Geri Dön Butonu -->
                    <Border Grid.Row="0" Background="#111420" BorderBrush="#1C2133" BorderThickness="1" CornerRadius="10" Padding="16,12" Margin="0,0,0,12">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                            </Grid.RowDefinitions>

                            <DockPanel Grid.Row="0" LastChildFill="True">
                                <Button x:Name="btnBackFromPerformance" Content="← Ana Menüye Dön" DockPanel.Dock="Left" Background="#1E293B" Foreground="#38BDF8" BorderThickness="0" Padding="12,5" Cursor="Hand" FontWeight="SemiBold" FontSize="12">
                                    <Button.Resources>
                                        <Style TargetType="Border">
                                            <Setter Property="CornerRadius" Value="6"/>
                                        </Style>
                                    </Button.Resources>
                                </Button>
                                <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="14,0,0,0">
                                    <TextBlock Text="⚡ Performans ve Oyun Modu" FontSize="16" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                                    <Border Background="#3B1E08" BorderBrush="#F59E0B" BorderThickness="1" CornerRadius="6" Padding="8,2" Margin="10,0,0,0" VerticalAlignment="Center">
                                        <TextBlock Text="🚀 FPS ve Düşük Gecikme" FontSize="11" FontWeight="Bold" Foreground="#FBBF24"/>
                                    </Border>
                                </StackPanel>
                            </DockPanel>

                            <DockPanel Grid.Row="1" LastChildFill="True" Margin="0,8,0,0">
                                <StackPanel Orientation="Horizontal" DockPanel.Dock="Right">
                                    <Button x:Name="btnRestartExplorerFromPerf" Content="🔄 Gezgini Yeniden Başlat" Background="#1E293B" Foreground="#38BDF8" BorderThickness="0" Padding="10,4" Cursor="Hand" FontWeight="SemiBold" FontSize="11" Margin="8,0,0,0">
                                        <Button.Resources>
                                            <Style TargetType="Border">
                                                <Setter Property="CornerRadius" Value="6"/>
                                            </Style>
                                        </Button.Resources>
                                    </Button>
                                    <Button x:Name="btnRefreshPerformance" Content="⟳ Durumu Yenile" Background="#1E293B" Foreground="#94A3B8" BorderThickness="0" Padding="10,4" Cursor="Hand" FontWeight="SemiBold" FontSize="11" Margin="8,0,0,0">
                                        <Button.Resources>
                                            <Style TargetType="Border">
                                                <Setter Property="CornerRadius" Value="6"/>
                                            </Style>
                                        </Button.Resources>
                                    </Button>
                                </StackPanel>
                                <TextBlock Text="Arka plan kaynak tüketimini azaltın, oyunlarda maksimum FPS ve en düşük giriş gecikmesini (input lag) sağlayın." FontSize="11" Foreground="#64748B" VerticalAlignment="Center"/>
                            </DockPanel>
                        </Grid>
                    </Border>

                    <!-- Satır 1: Performans Ayarları Kartları (Kaydırılabilir Liste) -->
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Margin="0,0,8,0">

                            <!-- Kart 1: Arka Plan ve Disk Kaynakları -->
                            <Border Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                                <StackPanel>
                                    <TextBlock Text="⚙️ Sistem &amp; Arka Plan Kaynakları" FontSize="15" FontWeight="Bold" Foreground="#38BDF8"/>
                                    <TextBlock Text="Sistemin arka planda harcadığı gereksiz RAM, CPU ve disk yükünü hafifletin:" FontSize="11" Foreground="#94A3B8" Margin="0,2,0,10"/>

                                    <!-- Ayar 1: Arka Plan Uygulamaları -->
                                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfBackgroundApps" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Arka Plan Uygulamalarını Kapat" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="Windows mağaza ve UWP uygulamalarının arka planda çalışıp RAM ve CPU tüketmesini engeller." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>

                                    <!-- Ayar 2: Diskten Hızlı Getirme (SysMain) -->
                                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfSysMain" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Diskten Hızlı Getirmeyi Kapat (SysMain / SuperFetch)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="Özellikle SSD'lerde gereksiz disk önbelleklemesini kapatır, %100 disk kullanımı takılmalarını önler." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>

                                    <!-- Ayar 3: Arama İndeksleme (WSearch) -->
                                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfSearchIndexing" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Arama İndekslemesini Kapat (Windows Search)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="Arka planda diski ve işlemciyi yoran arama dizini oluşturmayı durdurur (SSD/HDD ve pil tasarrufu sağlar)." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>

                                    <!-- Ayar 4: Görsel Efektler (En İyi Performans) -->
                                    <Border Padding="6,8">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfVisualEffects" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Görsel Efektleri En İyi Performansa Ayarla" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="Pencere animasyonlarını, saydamlık ve menü gölgelerini kapatır (yazı tipi netliği korunur)." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>
                                </StackPanel>
                            </Border>

                            <!-- Kart 2: Oyun Ayarları (Görseldeki Gibi Çekmece Kart) -->
                            <Border Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                                <StackPanel>
                                    <DockPanel LastChildFill="True">
                                        <Border Background="#3B1E08" CornerRadius="6" Padding="6,2" DockPanel.Dock="Right" VerticalAlignment="Center">
                                            <TextBlock Text="FPS &amp; Gecikme" FontSize="10" FontWeight="Bold" Foreground="#F59E0B"/>
                                        </Border>
                                        <StackPanel VerticalAlignment="Center">
                                            <TextBlock Text="🎮 Oyun Ayarları" FontSize="15" FontWeight="Bold" Foreground="#F59E0B"/>
                                            <TextBlock Text="Belirli oyunlarda kare hızını (FPS) ve akıcılığı artırabilecek ayarlar:" FontSize="11" Foreground="#94A3B8" Margin="0,2,0,0"/>
                                        </StackPanel>
                                    </DockPanel>

                                    <StackPanel Margin="0,10,0,0">
                                        <!-- Ayar 3: Oyun Modu -->
                                        <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfGameMode" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="Oyun Modu (Windows Game Mode)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Oyun oynarken CPU ve GPU kaynaklarını doğrudan oyuna tahsis eder, arka plan bildirimlerini duraklatır." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>

                                        <!-- Ayar 4: Pencereli Mod İyileştirme Seçenekleri -->
                                        <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfWindowedOptimizations" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="Pencereli Mod İyileştirme Seçenekleri" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Pencereli veya çerçevesiz oyunlarda modern sunum modeliyle giriş gecikmesini azaltır ve Auto HDR sunar." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>

                                        <!-- Ayar 5: Arka Planda Kayıt (Game DVR) -->
                                        <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfGameDVR" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="Arka Planda Kaydı Kapat (Xbox Game DVR)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Oyun sırasında sürekli gizli video kaydı almayı kapatarak ekran kartı ve disk üzerindeki yükü kaldırır (FPS artışı)." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>

                                        <!-- Ayar 6: Tam Ekran Optimizasyonlarını Devre Dışı Bırak (FSE) -->
                                        <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfFSE" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="Doğrudan Tam Ekran Modu (Tam Ekran İyileştirmelerini Kapat)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Oyunları gerçek özel tam ekran (Exclusive Fullscreen) modunda çalıştırarak DWM gecikmesini sıfırlar." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>

                                        <!-- Ayar 7: HAGS (Donanım Hızlandırmalı GPU Zamanlaması) -->
                                        <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfHAGS" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="HAGS (Donanım Hızlandırmalı GPU Zamanlaması)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Ekran kartının görevleri doğrudan yönetmesini sağlar (GTX 16xx/RTX veya RX 5000+ gerektirir, yeniden başlatma şart)." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>

                                        <!-- Ayar 8: VBS (Sanallaştırma Tabanlı Güvenlik) -->
                                        <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfVBS" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="VBS ve Bellek Bütünlüğünü Kapat (FPS Artışı)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Bellek bütünlüğünü (HVCI) kapatıp FPS artırır. Güvenliği azaltır; WSL2/Sandbox bozulmaz (Yeniden başlatma gerekir)." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>

                                        <!-- Ayar 9: Windows Dinamik Aydınlatma (RGB Kontrolü) -->
                                        <Border Padding="6,8">
                                            <DockPanel>
                                                <CheckBox x:Name="tglPerfDynamicLighting" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                                <StackPanel VerticalAlignment="Center">
                                                    <TextBlock Text="Dinamik Aydınlatmayı Kapat (Windows RGB Kontrolü)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                    <TextBlock Text="Windows'un klavye ve fare RGB ışıklarını denetlemesini engelleyerek donanım yazılımı çakışmalarını ve giriş gecikmelerini önler." FontSize="11" Foreground="#64748B"/>
                                                </StackPanel>
                                            </DockPanel>
                                        </Border>
                                    </StackPanel>
                                </StackPanel>
                            </Border>

                            <!-- Kart 3: Ağ & Güç İyileştirmeleri -->
                            <Border Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                                <StackPanel>
                                    <TextBlock Text="🚀 Ağ &amp; Donanım Güç Planı" FontSize="15" FontWeight="Bold" Foreground="#10B981"/>
                                    <TextBlock Text="Çevrimiçi oyunlarda ping süresini düşürün ve donanımınızın tam potansiyelini açığa çıkarın:" FontSize="11" Foreground="#94A3B8" Margin="0,2,0,10"/>

                                    <!-- Ayar 9: Nagle Algoritması -->
                                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfNagle" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Ağ Ping Düşürme (Nagle Algoritmasını Kapat)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="Çevrimiçi oyunlarda veri paketlerinin birikmeden anında gönderilmesini sağlar (TcpAckFrequency &amp; TCPNoDelay)." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>

                                    <!-- Ayar 10: Ağ Bağdaştırıcısı Donanım Yükü Aktarımı -->
                                    <Border Padding="6,8" BorderBrush="#1E2638" BorderThickness="0,0,0,1">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfNetOffload" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Ağ Bağdaştırıcısı Donanım Yükü Aktarımı (Offload &amp; RSS)" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="Ağ işlevlerini ve paket sağlama görevlerini işlemciden ağ kartının dahili çipine aktarır (CPU yükü azalır)." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>

                                    <!-- Ayar 11: Yüksek Performans Güç Planı -->
                                    <Border Padding="6,8">
                                        <DockPanel>
                                            <CheckBox x:Name="tglPerfPowerPlan" Style="{StaticResource ModernToggleSwitch}" DockPanel.Dock="Right" VerticalAlignment="Center"/>
                                            <StackPanel VerticalAlignment="Center">
                                                <TextBlock Text="Nihai / Yüksek Performans Güç Planını Etkinleştir" FontSize="13" FontWeight="SemiBold" Foreground="#F1F5F9"/>
                                                <TextBlock Text="İşlemcinin uyku ve frekans kısıtlamalarını kaldırarak sürekli maksimum güçte çalışmasını sağlar." FontSize="11" Foreground="#64748B"/>
                                            </StackPanel>
                                        </DockPanel>
                                    </Border>
                                </StackPanel>
                            </Border>

                            <!-- Kart 4: Windows Arka Plan Hizmetleri (Servis Optimizasyonu) -->
                            <Border Background="#161B2A" BorderBrush="#1F293D" BorderThickness="1" CornerRadius="10" Padding="16,14" Margin="0,0,0,12">
                                <StackPanel>
                                    <DockPanel LastChildFill="True">
                                        <Button x:Name="btnManageServices" Content="⚡ Hizmetleri Yönet" DockPanel.Dock="Right" VerticalAlignment="Center" Width="145" Height="34"
                                                Background="#7C3AED" Foreground="#FFFFFF" BorderThickness="0" FontWeight="Bold" FontSize="12" Cursor="Hand">
                                            <Button.Resources>
                                                <Style TargetType="Border">
                                                    <Setter Property="CornerRadius" Value="8"/>
                                                </Style>
                                            </Button.Resources>
                                        </Button>
                                        <StackPanel VerticalAlignment="Center" Margin="0,0,14,0">
                                            <StackPanel Orientation="Horizontal" Margin="0,0,0,3">
                                                <TextBlock Text="🛠️ Gereksiz Windows Hizmetleri (33 Servis)" FontSize="15" FontWeight="Bold" Foreground="#C084FC"/>
                                                <Border Background="#2E1065" BorderBrush="#7C3AED" BorderThickness="1" CornerRadius="6" Padding="6,2" Margin="10,0,0,0" VerticalAlignment="Center">
                                                    <TextBlock Text="RAM &amp; CPU Tasarrufu" FontSize="10" FontWeight="Bold" Foreground="#DDD6FE"/>
                                                </Border>
                                            </StackPanel>
                                            <TextBlock Text="Telemetri, karma gerçeklik, akıllı kart, hata raporlama ve kullanılmayan arka plan hizmetlerini devre dışı bırakın." FontSize="11" Foreground="#94A3B8" TextWrapping="Wrap"/>
                                        </StackPanel>
                                    </DockPanel>
                                </StackPanel>
                            </Border>

                        </StackPanel>
                    </ScrollViewer>

                    <!-- Satır 2: Alt Eylem Çubuğu: Bekleyen Değişiklikler & Toplu Uygula Butonu -->
                    <Border Grid.Row="2" Background="#111420" BorderBrush="#1C2234" BorderThickness="1" CornerRadius="12" Padding="16,10" Margin="0,10,0,0">
                        <DockPanel LastChildFill="True">
                            <StackPanel Orientation="Horizontal" DockPanel.Dock="Right" VerticalAlignment="Center">
                                <Button x:Name="btnDiscardPendingPerf" Style="{StaticResource PresetChip}" Content="↺ Değişiklikleri Geri Al" Margin="0,0,10,0" VerticalAlignment="Center" Visibility="Collapsed" ToolTip="Uygulanmamış tüm performans değişikliklerini iptal edip önceki haline döndürür."/>
                                <Button x:Name="btnApplyPendingPerf" Content="⚡ 0 değişikliği uygula" FontWeight="Bold" FontSize="13" Padding="18,8" Height="36" VerticalAlignment="Center" IsEnabled="False" Opacity="0.5" Cursor="Hand" Background="#1E293B" Foreground="#64748B" ToolTip="Seçilen tüm performans ve oyun ayarlarını sırayla uygular.">
                                    <Button.Resources>
                                        <Style TargetType="Border">
                                            <Setter Property="CornerRadius" Value="8"/>
                                        </Style>
                                    </Button.Resources>
                                </Button>
                            </StackPanel>
                            <StackPanel VerticalAlignment="Center">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="Bekleyen değişiklikler: " FontSize="13" Foreground="#94A3B8" VerticalAlignment="Center"/>
                                    <TextBlock x:Name="lblPendingPerfCount" Text="0 ayar" FontSize="13" FontWeight="Bold" Foreground="#64748B" VerticalAlignment="Center"/>
                                </StackPanel>
                                <TextBlock x:Name="lblPerformanceStatus" Text="✓ Performans ayarları senkronize edildi." FontSize="11" Foreground="#38BDF8" Margin="0,3,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                </Grid>

            </Grid>

            <!-- 4. HAKKINDA VE KISAYOL OVERLAY MODAL -->
            <Grid x:Name="pnlAboutOverlay" Grid.Row="0" Grid.RowSpan="3" Background="#CC080A10" Visibility="Collapsed">
                <Border Width="480" HorizontalAlignment="Center" VerticalAlignment="Center" Background="#111422" BorderBrush="#252F48" BorderThickness="1" CornerRadius="16" Padding="28,24">
                    <StackPanel>
                        <!-- Başlık & İkon & Kapat Butonu -->
                        <DockPanel LastChildFill="True" Margin="0,0,0,16">
                            <Button x:Name="btnCloseAbout" DockPanel.Dock="Right" Style="{StaticResource WinCloseBtn}" Content="✕" Width="28" Height="28" VerticalAlignment="Top"/>
                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                <Border Background="#4F46E5" Width="42" Height="42" CornerRadius="10" Margin="0,0,12,0">
                                    <TextBlock Text="🛡️" FontSize="22" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <StackPanel VerticalAlignment="Center">
                                    <TextBlock Text="TemizWin" FontSize="20" FontWeight="Bold" Foreground="#FFFFFF"/>
                                    <TextBlock Text="v1.0" FontSize="12" FontWeight="SemiBold" Foreground="#38BDF8"/>
                                </StackPanel>
                            </StackPanel>
                        </DockPanel>

                        <!-- Geliştirici ve Bilgi Rozetleri -->
                        <Border Background="#161B2E" BorderBrush="#1F2942" BorderThickness="1" CornerRadius="10" Padding="16,12" Margin="0,0,0,16">
                            <StackPanel>
                                <DockPanel LastChildFill="False" Margin="0,0,0,8">
                                    <TextBlock Text="Geliştirici:" FontSize="12" Foreground="#94A3B8" DockPanel.Dock="Left"/>
                                    <TextBlock Text="HK" FontSize="13" FontWeight="Bold" Foreground="#F8FAFC" DockPanel.Dock="Left" Margin="8,0,0,0"/>
                                    <Border Background="#0C2E24" BorderBrush="#10B981" BorderThickness="1" CornerRadius="6" Padding="8,2" DockPanel.Dock="Right">
                                        <TextBlock Text="✓ Kararlı Sürüm" FontSize="10" FontWeight="Bold" Foreground="#10B981"/>
                                    </Border>
                                </DockPanel>
                                <TextBlock Text="Windows 10 ve 11 için optimize edilmiş; harici dosya veya bağımlılık gerektirmeyen, hafif, hızlı ve açık kaynaklı sistem bakım aracı." FontSize="11" Foreground="#64748B" TextWrapping="Wrap"/>
