# ------------------------------------------------------------------------------
# 6. Yardımcı Fonksiyonlar (Boyut, Format, Güvenli Dosya İşlemleri)
# ------------------------------------------------------------------------------
function Format-Size([double]$bytes) {
    if ($bytes -ge 1GB) { return "{0:N2} GB" -f ($bytes / 1GB) }
    if ($bytes -ge 1MB) { return "{0:N1} MB" -f ($bytes / 1MB) }
    if ($bytes -ge 1KB) { return "{0:N0} KB" -f ($bytes / 1KB) }
    if ($bytes -gt 0) { return "{0:N0} B" -f $bytes }
    return "0 KB"
}

function Format-WmiDateTime([string]$rawDate) {
    if (-not $rawDate) { return (Get-Date).ToString("yyyy-MM-dd HH:mm:ss") }
    try {
        return [System.Management.ManagementDateTimeConverter]::ToDateTime($rawDate).ToString("yyyy-MM-dd HH:mm:ss")
    } catch {
        try {
            if ($rawDate -match '^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})') {
                $dt = [datetime]::new([int]$Matches[1], [int]$Matches[2], [int]$Matches[3], [int]$Matches[4], [int]$Matches[5], [int]$Matches[6])
                return $dt.ToString("yyyy-MM-dd HH:mm:ss")
            }
        } catch {}
        return $rawDate
    }
}

# Hızlı, güvenli, sembolik bağ / junction döngülerine girmeyen dosya boyutu hesaplayıcı
function Get-FolderSizeSafe([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return 0 }
    try {
        if (-not (Test-Path -LiteralPath $path -ErrorAction SilentlyContinue)) { return 0 }
        [double]$size = 0
        $queue = New-Object System.Collections.Generic.Queue[string]
        $queue.Enqueue($path)
        while ($queue.Count -gt 0) {
            $current = $queue.Dequeue()
            try {
                $di = New-Object System.IO.DirectoryInfo($current)
                foreach ($f in $di.EnumerateFiles()) {
                    $size += $f.Length
                }
                foreach ($d in $di.EnumerateDirectories()) {
                    if (($d.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0) {
                        $queue.Enqueue($d.FullName)
                    }
                }
            } catch {}
        }
        return $size
    } catch { return 0 }
}

function Get-BrowserTargetFilesSize([string]$targetType) {
    [double]$total = 0
    $userDataDirs = @(
        "$env:LOCALAPPDATA\Google\Chrome\User Data",
        "$env:LOCALAPPDATA\Microsoft\Edge\User Data",
        "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data",
        "$env:APPDATA\Opera Software\Opera Stable",
        "$env:APPDATA\Opera Software\Opera GX Stable",
        "$env:LOCALAPPDATA\Opera Software\Opera Stable",
        "$env:LOCALAPPDATA\Opera Software\Opera GX Stable"
    )

    $targetFiles = @()
    $targetDirs  = @()
    if ($targetType -eq "History") {
        $targetFiles = @(
            "History", "History-journal",
            "Visited Links",
            "Top Sites", "Top Sites-journal",
            "Network Action Predictor", "Network Action Predictor-journal",
            "Shortcuts", "Shortcuts-journal",
            "DownloadMetadata",
            "History Provider Cache"
        )
        $targetDirs = @("Sessions", "Sessions_Encrypted", "JumpListIconsMostVisited")
    }
    elseif ($targetType -eq "Cookies") {
        $targetFiles = @(
            "Cookies", "Cookies-journal",
            "Network\Cookies", "Network\Cookies-journal",
            "Network\Device Bound Sessions", "Network\Device Bound Sessions-journal",
            "Network\Trust Tokens", "Network\Trust Tokens-journal",
            "Extension Cookies", "Extension Cookies-journal",
            "DIPS", "DIPS-journal"
        )
    }
    elseif ($targetType -eq "Passwords") {
        $targetFiles = @(
            "Login Data", "Login Data-journal",
            "Login Data For Account", "Login Data For Account-journal",
            "Web Data", "Web Data-journal",
            "Account Web Data", "Account Web Data-journal",
            "Affiliation Database", "Affiliation Database-journal"
        )
    }

    foreach ($ud in $userDataDirs) {
        if (Test-Path -LiteralPath $ud -ErrorAction SilentlyContinue) {
            try {
                $profiles = Get-ChildItem -Path $ud -Directory -ErrorAction SilentlyContinue | Where-Object {
                    $_.Name -eq "Default" -or $_.Name -like "Profile *"
                }
                $allDirs = [System.Collections.Generic.List[string]]::new()
                foreach ($p in $profiles) { $allDirs.Add($p.FullName) }
                if (Test-Path (Join-Path $ud "Preferences") -ErrorAction SilentlyContinue) {
                    $allDirs.Add($ud)
                }

                foreach ($dir in $allDirs) {
                    foreach ($tf in $targetFiles) {
                        $filePath = Join-Path $dir $tf
                        if (Test-Path -LiteralPath $filePath -ErrorAction SilentlyContinue) {
                            try {
                                $total += (Get-Item -LiteralPath $filePath -Force -ErrorAction SilentlyContinue).Length
                            } catch {}
                        }
                    }

                    foreach ($td in $targetDirs) {
                        $subDir = Join-Path $dir $td
                        if (Test-Path -LiteralPath $subDir -ErrorAction SilentlyContinue) {
                            try {
                                $subFiles = Get-ChildItem -Path $subDir -File -Force -Recurse -ErrorAction SilentlyContinue
                                foreach ($sf in $subFiles) { $total += $sf.Length }
                            } catch {}
                        }
                    }
                }
            } catch {}
        }
    }

    # Firefox profilleri
    $firefoxDir = "$env:APPDATA\Mozilla\Firefox\Profiles"
    if (Test-Path -LiteralPath $firefoxDir -ErrorAction SilentlyContinue) {
        try {
            $ffProfiles = Get-ChildItem -Path $firefoxDir -Directory -ErrorAction SilentlyContinue
            foreach ($ffp in $ffProfiles) {
                $ffFiles = @()
                if ($targetType -eq "Cookies") {
                    $ffFiles = @("cookies.sqlite", "cookies.sqlite-wal", "cookies.sqlite-shm")
                }
                elseif ($targetType -eq "Passwords") {
                    $ffFiles = @("logins.json", "logins-backup.json", "key4.db", "formhistory.sqlite", "formhistory.sqlite-wal")
                }
                elseif ($targetType -eq "History") {
                    $ffFiles = @("formhistory.sqlite", "formhistory.sqlite-wal", "sessionstore.jsonlz4")
                    $sessBackupDir = Join-Path $ffp.FullName "sessionstore-backups"
                    if (Test-Path -LiteralPath $sessBackupDir -ErrorAction SilentlyContinue) {
                        try {
                            $sbFiles = Get-ChildItem -Path $sessBackupDir -File -Force -ErrorAction SilentlyContinue
                            foreach ($sbf in $sbFiles) { $total += $sbf.Length }
                        } catch {}
                    }
                }
                foreach ($fff in $ffFiles) {
                    $filePath = Join-Path $ffp.FullName $fff
                    if (Test-Path -LiteralPath $filePath -ErrorAction SilentlyContinue) {
                        try {
                            $total += (Get-Item -LiteralPath $filePath -Force -ErrorAction SilentlyContinue).Length
                        } catch {}
                    }
                }
            }
        } catch {}
    }

    return $total
}

function Get-ChromiumAllProfilesSize([string]$userDataPath) {
    if (-not (Test-Path $userDataPath -ErrorAction SilentlyContinue)) { return 0 }
    [double]$total = 0
    try {
        # 1. Kök User Data dizinindeki genel GPU ve bileşen önbellekleri
        $rootCacheFolders = @(
            "GrShaderCache", "old_GrShaderCache_000", "ShaderCache", 
            "component_crx_cache", "extensions_crx_cache", "GPUPersistentCache"
        )
        foreach ($rc in $rootCacheFolders) {
            $rcPath = Join-Path $userDataPath $rc
            if (Test-Path $rcPath) {
                $total += (Get-FolderSizeSafe $rcPath)
            }
        }

        # 2. Tüm profiller altındaki önbellekler (Default, Profile 1, Profile 2...)
        $profiles = Get-ChildItem -Path $userDataPath -Directory -ErrorAction SilentlyContinue | Where-Object {
            $_.Name -eq "Default" -or $_.Name -like "Profile *"
        }
        foreach ($p in $profiles) {
            $profileCacheFolders = @(
                "Cache", "GPUCache", "Code Cache",
                "DawnWebGPUCache", "DawnGraphiteCache", "AutofillAiModelCache",
                "Shared Dictionary\cache",
                "Service Worker\CacheStorage", "Service Worker\ScriptCache",
                "File System", "Application Cache", "Media Cache"
            )
            foreach ($sub in $profileCacheFolders) {
                $subPath = Join-Path $p.FullName $sub
                if (Test-Path $subPath) {
                    $total += (Get-FolderSizeSafe $subPath)
                }
            }
        }
    } catch {}
    return $total
}

function Write-Terminal([string]$msg, [string]$tag = "") {
    $timestamp = (Get-Date).ToString("HH:mm:ss")
    if ($txtTerminal) {
        $txtTerminal.AppendText("[$timestamp] $msg`r`n")
        $txtTerminal.ScrollToEnd()
    }
    try {
        if ($tag -eq "SUCCESS" -or ($msg -match "Başarıyla Tamamlandı|başarıyla temizlendi|başarıyla kaldırıldı|başarıyla uygulandı")) {
            Write-Host "[$timestamp] [BAŞARILI] $msg" -ForegroundColor Green
        } elseif ($tag -eq "STEP" -or ($msg -match "Başlatılıyor|Taranıyor|Temizleniyor|Analiz|>>>|===" -and $msg -notmatch "başarısız oldu")) {
            Write-Host "[$timestamp] [İŞLEM] $msg" -ForegroundColor Yellow
        } elseif ($tag -eq "ERROR" -or ($msg -match "^\[HATA\]|başarısız oldu|hata oluştu|erişim engellendi|ulaşılamadı")) {
            Write-Host "[$timestamp] [HATA] $msg" -ForegroundColor Red
        } else {
            Write-Host "[$timestamp] [BİLGİ] $msg" -ForegroundColor Gray
        }
    } catch {}
}

# ------------------------------------------------------------------------------
# 7. Görünüm Değiştirici (Navigation)
# ------------------------------------------------------------------------------
# ------------------------------------------------------------------------------
# Başlangıç Uygulamaları Yönetim Motoru (StartupApproved Registry API)
# ------------------------------------------------------------------------------
function Get-StartupTargetExe {
    param([string]$command)
    if ([string]::IsNullOrWhiteSpace($command)) { return $null }

    $targetExe = $null
    $expanded = [Environment]::ExpandEnvironmentVariables($command).Trim()
    if ($expanded -match '^"([^"]+)"') {
        $targetExe = $matches[1]
    } elseif ($expanded -match '^([^\s"]+\.exe)') {
        $targetExe = $matches[1]
    } elseif ($expanded -match '^(.+?\.exe)(\s.*)?$') {
        $targetExe = $matches[1]
    } elseif ($expanded -match '^"([^"]+\.lnk)"' -or $expanded -match '^([^\s"]+\.lnk)') {
        $targetExe = if ($matches[1]) { $matches[1] } else { $expanded }
    } elseif ($expanded -match '^([^\s]+)') {
        $targetExe = $matches[1]
    }

    # Kısayol (.lnk) dosyası ise asıl hedef dosyayı çözümle
    if ($targetExe -and $targetExe.EndsWith(".lnk", [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $targetExe -PathType Leaf -ErrorAction SilentlyContinue)) {
        try {
            $sh = New-Object -ComObject WScript.Shell
            $sc = $sh.CreateShortcut($targetExe)
            if ($sc.TargetPath -and (Test-Path -LiteralPath $sc.TargetPath -PathType Leaf -ErrorAction SilentlyContinue)) {
                $targetExe = $sc.TargetPath
            }
            [System.Runtime.InteropServices.Marshal]::ReleaseComObject($sh) | Out-Null
        } catch {}
    }

    if ($targetExe) {
        if (-not [System.IO.Path]::IsPathRooted($targetExe)) {
            $foundCmd = Get-Command $targetExe -ErrorAction SilentlyContinue
            if ($foundCmd -and $foundCmd.Source) {
                $targetExe = $foundCmd.Source
            }
        }
        if (Test-Path -LiteralPath $targetExe -PathType Leaf -ErrorAction SilentlyContinue) {
            return $targetExe
        }
    }
    return $null
}

function Get-StartupAppIconElement([string]$exePath, [string]$appName) {
    $iconBorder = New-Object System.Windows.Controls.Border
    $iconBorder.Width = 34
    $iconBorder.Height = 34
    $iconBorder.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $iconBorder.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#181D2D")
    $iconBorder.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#23293D")
    $iconBorder.BorderThickness = [System.Windows.Thickness]::new(1)
    $iconBorder.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
    $iconBorder.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $iconBorder.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center

    $iconImage = $null
    if ($exePath -and (Test-Path -LiteralPath $exePath -ErrorAction SilentlyContinue)) {
        try {
            $icon = [System.Drawing.Icon]::ExtractAssociatedIcon($exePath)
            if ($icon) {
                $hIcon = $icon.Handle
                $bmpSource = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
                    $hIcon,
                    [System.Windows.Int32Rect]::Empty,
                    [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
                )
                $bmpSource.Freeze()
                $img = New-Object System.Windows.Controls.Image
                $img.Source = $bmpSource
                $img.Width = 22
                $img.Height = 22
                $img.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
                $img.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                [System.Windows.Media.RenderOptions]::SetBitmapScalingMode($img, [System.Windows.Media.BitmapScalingMode]::HighQuality)
                $iconImage = $img
                $icon.Dispose()
            }
        } catch {
            $iconImage = $null
        }
    }

    if ($iconImage) {
        $iconBorder.Child = $iconImage
    } else {
        $txtFallback = New-Object System.Windows.Controls.TextBlock
        $txtFallback.Text = "🚀"
        $txtFallback.FontSize = 15
        $txtFallback.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $txtFallback.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $iconBorder.Child = $txtFallback
    }

    return $iconBorder
}

function Get-StartupFriendlyName {
    param(
        [string]$rawName,
        [string]$command
    )
    if ([string]::IsNullOrWhiteSpace($rawName) -and [string]::IsNullOrWhiteSpace($command)) {
        return "Bilinmeyen Program"
    }

    $friendlyName = $null
    $targetExe = Get-StartupTargetExe $command

    # Hedef exe varsa Windows dosya meta verisinden (FileVersionInfo) resmi ismi oku
    if ($targetExe) {
        try {
            $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($targetExe)
            if ($vi.FileDescription -and $vi.FileDescription.Trim().Length -gt 1) {
                $desc = $vi.FileDescription.Trim()
                if ($desc -eq "Windows Security notification icon") {
                    $friendlyName = "Windows Güvenliği"
                } else {
                    $friendlyName = $desc
                }
            } elseif ($vi.ProductName -and $vi.ProductName.Trim().Length -gt 1) {
                $friendlyName = $vi.ProductName.Trim()
            }
        } catch {}
    }

    if ($friendlyName) {
        return $friendlyName
    }

    # Dosyadan resmi isim okunamazsa arkasındaki hash, GUID veya sayı kodlarını temizle
    $clean = $rawName
    if ($clean -match '^(.+?)_[A-Fa-f0-9]{16,64}$') {
        $clean = $matches[1]
        if ($clean -match 'MicrosoftEdge') { return "Microsoft Edge" }
    }
    if ($clean -match '^\{?[A-Fa-f0-9-]{32,36}\}?$') {
        if ($targetExe) {
            return [System.IO.Path]::GetFileNameWithoutExtension($targetExe)
        }
    }

    return $clean
}

function Get-StartupAppsList {
    $list = [System.Collections.Generic.List[PSCustomObject]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    # 1. HKCU Run
    $hkcuRunPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run"
    $hkcuAppPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run"
    if (Test-Path $hkcuRunPath) {
        try {
            $props = (Get-ItemProperty $hkcuRunPath).PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' }
            foreach ($p in $props) {
                $name = $p.Name
                $cmd  = [string]$p.Value
                $seenKey = "HKCU:$name"
                if ($seen.Contains($seenKey)) { continue }
                $seen.Add($seenKey) | Out-Null
                $isEnabled = $true
                if (Test-Path $hkcuAppPath) {
                    $appBytes = (Get-ItemProperty $hkcuAppPath).$name
                    if ($appBytes -and $appBytes[0] -ne 2) { $isEnabled = $false }
                }
                $targetExe = Get-StartupTargetExe $cmd
                $friendlyName = Get-StartupFriendlyName $name $cmd
                $list.Add([PSCustomObject]@{
                    Name        = $friendlyName
                    Command     = $cmd
                    ExePath     = $targetExe
                    Type        = "Kullanıcı Kayıt Defteri (HKCU)"
                    TypeShort   = "HKCU"
                    AppKey      = $hkcuAppPath
                    ItemName    = $name
                    IsEnabled   = $isEnabled
                })
            }
        } catch {}
    }

    # 2. HKLM Run (64-bit Sistem)
    $hklmRunPath = "HKLM:\Software\Microsoft\Windows\CurrentVersion\Run"
    $hklmAppPath = "HKLM:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run"
    if (Test-Path $hklmRunPath) {
        try {
            $props = (Get-ItemProperty $hklmRunPath).PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' }
            foreach ($p in $props) {
                $name = $p.Name
                $cmd  = [string]$p.Value
                $seenKey = "HKLM:$name"
                if ($seen.Contains($seenKey)) { continue }
                $seen.Add($seenKey) | Out-Null
                $isEnabled = $true
                if (Test-Path $hklmAppPath) {
                    $appBytes = (Get-ItemProperty $hklmAppPath).$name
                    if ($appBytes -and $appBytes[0] -ne 2) { $isEnabled = $false }
                }
                $targetExe = Get-StartupTargetExe $cmd
                $friendlyName = Get-StartupFriendlyName $name $cmd
                $list.Add([PSCustomObject]@{
                    Name        = $friendlyName
                    Command     = $cmd
                    ExePath     = $targetExe
                    Type        = "Sistem Kayıt Defteri (HKLM)"
                    TypeShort   = "HKLM"
                    AppKey      = $hklmAppPath
                    ItemName    = $name
                    IsEnabled   = $isEnabled
                })
            }
        } catch {}
    }

    # 3. HKLM WOW6432Node Run (32-bit Uygulamalar)
    $hklm32RunPath = "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"
    $hklm32AppPath = "HKLM:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32"
    if (Test-Path $hklm32RunPath) {
        try {
            $props = (Get-ItemProperty $hklm32RunPath).PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' }
            foreach ($p in $props) {
                $name = $p.Name
                $cmd  = [string]$p.Value
                $seenKey = "HKLM32:$name"
                if ($seen.Contains($seenKey)) { continue }
                $seen.Add($seenKey) | Out-Null
                $isEnabled = $true
                if (Test-Path $hklm32AppPath) {
                    $appBytes = (Get-ItemProperty $hklm32AppPath).$name
                    if ($appBytes -and $appBytes[0] -ne 2) { $isEnabled = $false }
                }
                $targetExe = Get-StartupTargetExe $cmd
                $friendlyName = Get-StartupFriendlyName $name $cmd
                $list.Add([PSCustomObject]@{
                    Name        = $friendlyName
                    Command     = $cmd
                    ExePath     = $targetExe
                    Type        = "Sistem Kayıt Defteri (HKLM 32-bit)"
                    TypeShort   = "HKLM 32"
                    AppKey      = $hklm32AppPath
                    ItemName    = $name
                    IsEnabled   = $isEnabled
                })
            }
        } catch {}
    }

    # 4. Kullanıcı Başlangıç Klasörü (Startup Folder)
    $userStartup = [Environment]::GetFolderPath('Startup')
    $folderAppKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder"
    if (Test-Path $userStartup) {
        try {
            $files = Get-ChildItem $userStartup -File -ErrorAction SilentlyContinue
            foreach ($f in $files) {
                $name = $f.Name
                $seenKey = "FOLDER:$name"
                if ($seen.Contains($seenKey)) { continue }
                $seen.Add($seenKey) | Out-Null
                $isEnabled = $true
                if (Test-Path $folderAppKey) {
                    $appBytes = (Get-ItemProperty $folderAppKey).$name
                    if ($appBytes -and $appBytes[0] -ne 2) { $isEnabled = $false }
                }
                $targetExe = Get-StartupTargetExe $f.FullName
                $rawBase = [System.IO.Path]::GetFileNameWithoutExtension($f.Name)
                $friendlyName = Get-StartupFriendlyName $rawBase $f.FullName
                $list.Add([PSCustomObject]@{
                    Name        = $friendlyName
                    Command     = $f.FullName
                    ExePath     = $targetExe
                    Type        = "Kullanıcı Başlangıç Klasörü"
                    TypeShort   = "KLASÖR"
                    AppKey      = $folderAppKey
                    ItemName    = $f.Name
                    IsEnabled   = $isEnabled
                })
            }
        } catch {}
    }

    # 5. Ortak (Tüm Kullanıcılar) Başlangıç Klasörü (Common Startup Folder)
    $commonStartup = [Environment]::GetFolderPath('CommonStartup')
    $commonFolderAppKey = "HKLM:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder"
    if (Test-Path $commonStartup) {
        try {
            $files = Get-ChildItem $commonStartup -File -ErrorAction SilentlyContinue
            foreach ($f in $files) {
                $name = $f.Name
                $seenKey = "COMMONFOLDER:$name"
                if ($seen.Contains($seenKey)) { continue }
                $seen.Add($seenKey) | Out-Null
                $isEnabled = $true
                if (Test-Path $commonFolderAppKey) {
                    $appBytes = (Get-ItemProperty $commonFolderAppKey).$name
                    if ($appBytes -and $appBytes[0] -ne 2) { $isEnabled = $false }
                }
                $targetExe = Get-StartupTargetExe $f.FullName
                $rawBase = [System.IO.Path]::GetFileNameWithoutExtension($f.Name)
                $friendlyName = Get-StartupFriendlyName $rawBase $f.FullName
                $list.Add([PSCustomObject]@{
                    Name        = $friendlyName
                    Command     = $f.FullName
                    ExePath     = $targetExe
                    Type        = "Ortak Başlangıç Klasörü"
                    TypeShort   = "KLASÖR"
                    AppKey      = $commonFolderAppKey
                    ItemName    = $f.Name
                    IsEnabled   = $isEnabled
                })
            }
        } catch {}
    }

    return $list.ToArray()
}

function Toggle-StartupApp([PSCustomObject]$app) {
    if (-not $app.AppKey -or -not $app.ItemName) { return $false }
    try {
        if (-not (Test-Path $app.AppKey)) {
            New-Item -Path $app.AppKey -Force | Out-Null
        }
        if ($app.IsEnabled) {
            # Devre dışı bırak: 0x03
            [byte[]]$bytes = @(0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
            Set-ItemProperty -Path $app.AppKey -Name $app.ItemName -Value $bytes -Type Binary
            $app.IsEnabled = $false
        } else {
            # Etkinleştir: 0x02
            [byte[]]$bytes = @(0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
            Set-ItemProperty -Path $app.AppKey -Name $app.ItemName -Value $bytes -Type Binary
            $app.IsEnabled = $true
        }
        $statusStr = if ($app.IsEnabled) { "Etkinleştirildi" } else { "Devre Dışı Bırakıldı" }
        try {
            Write-CmdLog "BAŞLANGIÇ" "$($app.Name) -> $statusStr (Set-ItemProperty '$($app.AppKey)' '$($app.ItemName)')" "Cyan"
        } catch {}
        return $true
    } catch {
        return $false
    }
}

$script:allStartupApps = [System.Collections.Generic.List[PSCustomObject]]::new()

function Update-StartupBadgeCounts {
    if (-not $script:allStartupApps) { return }
    $totalCount = $script:allStartupApps.Count
    $activeCount = 0
    foreach ($a in $script:allStartupApps) {
        if ($a.IsEnabled) { $activeCount++ }
    }
    $disabledCount = $totalCount - $activeCount

    if ($lblStartupBadge) {
        $lblStartupBadge.Text = "Toplam: $totalCount Program ($activeCount Etkin, $disabledCount Devre Dışı)"
    }
    if ($lblStartupCount) {
        $lblStartupCount.Text = "$activeCount program"
    }
}

function Get-SystemBootTimeInfo {
    $biosTimeSec = $null
    $bootDurationSec = $null
    try {
        $powerReg = Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" -ErrorAction SilentlyContinue
        if ($powerReg -and $powerReg.FwPOSTTime -and [int64]$powerReg.FwPOSTTime -gt 0) {
            $biosTimeSec = [Math]::Round(([int64]$powerReg.FwPOSTTime) / 1000, 1)
        }
    } catch {}
    try {
        $evt = Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-Diagnostics-Performance/Operational'; Id=100} -MaxEvents 1 -ErrorAction SilentlyContinue
        if ($evt) {
            $xml = [xml]$evt.ToXml()
            $bootMs = [int64]$xml.Event.EventData.Data[0].'#text'
            if ($bootMs -gt 0) {
                $bootDurationSec = [Math]::Round($bootMs / 1000, 1)
            }
        }
    } catch {}
    $lastBootTime = $null
    $uptimeStr = ""
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
        if ($os -and $os.LastBootUpTime) {
            $lastBootTime = $os.LastBootUpTime
            $diff = (Get-Date) - $lastBootTime
            if ($diff.Days -gt 0) {
                $uptimeStr = "$($diff.Days) gün $($diff.Hours) saat"
            } elseif ($diff.Hours -gt 0) {
                $uptimeStr = "$($diff.Hours) saat $($diff.Minutes) dk"
            } else {
                $uptimeStr = "$($diff.Minutes) dakika"
            }
        }
    } catch {}
    return @{
        BiosTimeSec     = $biosTimeSec
        BootDurationSec = $bootDurationSec
        LastBootTime    = $lastBootTime
        UptimeStr       = $uptimeStr
    }
}

function Refresh-StartupAppsList {
    if (-not $pnlStartupList) { return }
    $pnlStartupList.Children.Clear()
    $script:allStartupApps.Clear()

    $apps = @(Get-StartupAppsList)
    $totalCount = $apps.Count
    $activeCount = @($apps | Where-Object { $_.IsEnabled }).Count
    $disabledCount = $totalCount - $activeCount

    if ($lblStartupBadge) {
        $lblStartupBadge.Text = "Toplam: $totalCount Program ($activeCount Etkin, $disabledCount Devre Dışı)"
    }
    if ($lblStartupCount) {
        $lblStartupCount.Text = "$activeCount program"
    }

    # Açılış Süresi Bilgisi (Boot Time)
    if ($lblBootTimeBadge) {
        $bootInfo = Get-SystemBootTimeInfo
        $badgeText = ""

        if ($bootInfo.BootDurationSec) {
            $badgeText = "⏱️ Açılış: $($bootInfo.BootDurationSec)s"
            if ($bootInfo.BiosTimeSec) {
                $badgeText += " (BIOS: $($bootInfo.BiosTimeSec)s)"
            }
        } elseif ($bootInfo.BiosTimeSec) {
            $badgeText = "⏱️ BIOS Zamanı: $($bootInfo.BiosTimeSec)s"
        } else {
            $badgeText = "⏱️ Sistem Aktif"
        }

        $lblBootTimeBadge.Text = $badgeText
    }

    if ($totalCount -eq 0) {
        $emptyTb = New-Object System.Windows.Controls.TextBlock
        $emptyTb.Text = "Başlangıçta çalışan herhangi bir program bulunamadı."
        $emptyTb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        $emptyTb.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $emptyTb.Margin = [System.Windows.Thickness]::new(0, 30, 0, 30)
        $pnlStartupList.Children.Add($emptyTb) | Out-Null
        return
    }

    foreach ($app in $apps) {
        $script:allStartupApps.Add($app)

        $card = New-Object System.Windows.Controls.Border
        $card.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#131724")
        $card.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2438")
        $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $card.Padding = [System.Windows.Thickness]::new(12, 10, 12, 10)
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 0, 8)

        $dock = New-Object System.Windows.Controls.DockPanel
        $dock.LastChildFill = $true

        # Sağ Alan: Durum Metni ve Modern Toggle Switch
        $rightSp = New-Object System.Windows.Controls.StackPanel
        $rightSp.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $rightSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [System.Windows.Controls.DockPanel]::SetDock($rightSp, [System.Windows.Controls.Dock]::Right)

        # Durum Metni (Açık / Devre Dışı)
        $lblState = New-Object System.Windows.Controls.TextBlock
        $lblState.FontSize = 11
        $lblState.FontWeight = [System.Windows.FontWeights]::SemiBold
        $lblState.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $lblState.Margin = [System.Windows.Thickness]::new(0, 0, 10, 0)
        $lblState.Text = if ($app.IsEnabled) { "Açık" } else { "Devre Dışı" }
        $lblState.Foreground = if ($app.IsEnabled) {
            [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
        } else {
            [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        }
        $rightSp.Children.Add($lblState) | Out-Null

        # Modern Toggle Switch (CheckBox)
        $tglStartup = New-Object System.Windows.Controls.CheckBox
        $tglStartup.Style = $window.FindResource("ModernToggleSwitch")
        $tglStartup.IsChecked = [bool]$app.IsEnabled
        $tglStartup.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $tglStartup.Margin = [System.Windows.Thickness]::new(0, 0, 4, 0)
        $tglStartup.Cursor = [System.Windows.Input.Cursors]::Hand

        $currentApp = $app
        $currentLblState = $lblState
        $isInternalToggle = $false

        $tglStartup.Add_Click({
            param($s, $e)
            if ($isInternalToggle) { return }
            $res = Toggle-StartupApp $currentApp
            if ($res) {
                $currentLblState.Text = if ($currentApp.IsEnabled) { "Açık" } else { "Devre Dışı" }
                $currentLblState.Foreground = if ($currentApp.IsEnabled) {
                    [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
                } else {
                    [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
                }
                Update-StartupBadgeCounts
            } else {
                $isInternalToggle = $true
                $s.IsChecked = [bool]$currentApp.IsEnabled
                $isInternalToggle = $false
            }
        }.GetNewClosure())

        $rightSp.Children.Add($tglStartup) | Out-Null
        $dock.Children.Add($rightSp) | Out-Null

        # Sol Alan: Program İkonu, İsmi, Konum Türü ve Komut
        $leftOuterSp = New-Object System.Windows.Controls.StackPanel
        $leftOuterSp.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $leftOuterSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        # Program İkon Kutucuğu
        $iconElem = Get-StartupAppIconElement $app.ExePath $app.Name
        $leftOuterSp.Children.Add($iconElem) | Out-Null

        # Metin Alanı (İsim, Tür, Komut)
        $leftSp = New-Object System.Windows.Controls.StackPanel
        $leftSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $headerSp = New-Object System.Windows.Controls.StackPanel
        $headerSp.Orientation = [System.Windows.Controls.Orientation]::Horizontal

        $txtName = New-Object System.Windows.Controls.TextBlock
        $txtName.Text = $app.Name
        $txtName.FontWeight = [System.Windows.FontWeights]::Bold
        $txtName.FontSize = 13
        $txtName.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
        $headerSp.Children.Add($txtName) | Out-Null

        $typeBadge = New-Object System.Windows.Controls.Border
        $typeBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2438")
        $typeBadge.CornerRadius = [System.Windows.CornerRadius]::new(4)
        $typeBadge.Padding = [System.Windows.Thickness]::new(6, 1, 6, 1)
        $typeBadge.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
        $typeBadge.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $txtType = New-Object System.Windows.Controls.TextBlock
        $txtType.Text = $app.TypeShort
        $txtType.FontSize = 10
        $txtType.FontWeight = [System.Windows.FontWeights]::Bold
        $txtType.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
        $typeBadge.Child = $txtType
        $headerSp.Children.Add($typeBadge) | Out-Null

        $leftSp.Children.Add($headerSp) | Out-Null

        $txtCmd = New-Object System.Windows.Controls.TextBlock
        $txtCmd.Text = $app.Command
        $txtCmd.FontSize = 11
        $txtCmd.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        $txtCmd.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
        $txtCmd.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
        $txtCmd.MaxWidth = 480
        $leftSp.Children.Add($txtCmd) | Out-Null

        $leftOuterSp.Children.Add($leftSp) | Out-Null

        $dock.Children.Add($leftOuterSp) | Out-Null
        $card.Child = $dock

        if ($app.ItemName -and $app.ItemName -ne $app.Name) {
            $card.ToolTip = "Kayıt Adı: $($app.ItemName)`nKomut: $($app.Command)"
        } else {
            $card.ToolTip = "Komut: $($app.Command)"
        }

        $pnlStartupList.Children.Add($card) | Out-Null
    }
}

# ------------------------------------------------------------------------------
# Büyük Dosya Avcısı Motoru (Çoklu Sürücü C:, D:, E:... & Asenkron Arka Plan Motoru)
# ------------------------------------------------------------------------------
$script:availableDrives      = @()
$script:selectedDriveIndex   = 0
$script:analyzerPowerShell   = $null
$script:analyzerRunspaceHost = $null
$script:analyzerAsyncHandle  = $null
$script:analyzerStopwatch    = $null
$script:isAnalyzerScanning   = $false
$script:analyzerTimer        = New-Object System.Windows.Threading.DispatcherTimer
$script:analyzerTimer.Interval = [TimeSpan]::FromMilliseconds(100)

function Get-ReadyDrivesList {
    return @([System.IO.DriveInfo]::GetDrives() | Where-Object {
        $_.IsReady -and ($_.DriveType -eq [System.IO.DriveType]::Fixed -or $_.DriveType -eq [System.IO.DriveType]::Removable)
    })
}

function Refresh-HeaderDrives {
    $script:availableDrives = Get-ReadyDrivesList
    if ($script:availableDrives.Count -eq 0) { return }

    if ($script:selectedDriveIndex -ge $script:availableDrives.Count) {
        $script:selectedDriveIndex = 0
    }

    $curDrv = $script:availableDrives[$script:selectedDriveIndex]
    $let = $curDrv.Name.TrimEnd('\')

    if ($lblSelectedDriveName) {
        if ($script:availableDrives.Count -gt 1) {
            $lblSelectedDriveName.Text = "$let ▾"
            if ($btnHeaderDriveBadge) {
                $btnHeaderDriveBadge.ToolTip = "Sıradaki sürücüye geçmek için tıklayın ($($script:availableDrives.Count) sürücü algılandı: $(($script:availableDrives | ForEach-Object { $_.Name.TrimEnd('\') }) -join ', '))"
            }
        } else {
            $lblSelectedDriveName.Text = "$let"
            if ($btnHeaderDriveBadge) {
                $btnHeaderDriveBadge.ToolTip = "Sistem sürücüsü ($let)"
            }
        }
    }

    if ($lblFreeSpaceC) {
        $freeFmt = if ($curDrv.AvailableFreeSpace -ge 1GB) { "{0:N1} GB" -f ($curDrv.AvailableFreeSpace / 1GB) } else { "{0:N0} MB" -f ($curDrv.AvailableFreeSpace / 1MB) }
        $lblFreeSpaceC.Text = $freeFmt
    }
}

function Cycle-HeaderDrive {
    if ($script:availableDrives.Count -le 1) {
        Refresh-HeaderDrives
        return
    }
    $script:selectedDriveIndex = ($script:selectedDriveIndex + 1) % $script:availableDrives.Count
    Refresh-HeaderDrives
}

function Update-AnalyzerLocationOptions {
    if (-not $cmbAnalyzerLocation) { return }

    $allDrives = Get-ReadyDrivesList
    $curSelectedTag = if ($cmbAnalyzerLocation.SelectedItem -and $cmbAnalyzerLocation.SelectedItem.Tag) { [string]$cmbAnalyzerLocation.SelectedItem.Tag } else { "UserFolders" }

    $cmbAnalyzerLocation.Items.Clear()

    # 1. Kullanıcı Klasörleri
    $itemUser = New-Object System.Windows.Controls.ComboBoxItem
    $itemUser.Content = "📁 Kullanıcı Klasörleri (Hızlı)"
    $itemUser.Tag = "UserFolders"
    $cmbAnalyzerLocation.Items.Add($itemUser) | Out-Null
    if ($curSelectedTag -eq "UserFolders") { $itemUser.IsSelected = $true }

    # 2. Algılanan Her Sürücü (C:, D:, E:...)
    foreach ($drv in $allDrives) {
        $let = $drv.Name.TrimEnd('\')
        $freeFmt = if ($drv.AvailableFreeSpace -ge 1GB) { "{0:N0} GB" -f ($drv.AvailableFreeSpace / 1GB) } else { "{0:N0} MB" -f ($drv.AvailableFreeSpace / 1MB) }
        $label = if ($drv.VolumeLabel) { $drv.VolumeLabel } else { "Sürücü" }

        $itemDrv = New-Object System.Windows.Controls.ComboBoxItem
        $itemDrv.Content = "💾 $label ($let) [$freeFmt Boş]"
        $itemDrv.Tag = "Drive_" + $let.TrimEnd(':')
        $cmbAnalyzerLocation.Items.Add($itemDrv) | Out-Null
        if ($curSelectedTag -eq $itemDrv.Tag) { $itemDrv.IsSelected = $true }
    }

    # 3. Birden Fazla Sürücü Varsa "Tüm Sürücüler"
    if ($allDrives.Count -gt 1) {
        $itemAll = New-Object System.Windows.Controls.ComboBoxItem
        $itemAll.Content = "🌐 Tüm Diskleri Tara (Kapsamlı)"
        $itemAll.Tag = "AllDrives"
        $cmbAnalyzerLocation.Items.Add($itemAll) | Out-Null
        if ($curSelectedTag -eq "AllDrives") { $itemAll.IsSelected = $true }
    }

    if ($cmbAnalyzerLocation.SelectedIndex -eq -1) {
        $cmbAnalyzerLocation.SelectedIndex = 0
    }
}

function Render-AnalyzerResults($files, [double]$elapsedSec) {
    if (-not $pnlAnalyzerList) { return }
    $pnlAnalyzerList.Children.Clear()

    $script:analyzerTotalFound = @($files).Count
    [double]$script:analyzerSumBytes = 0
    foreach ($f in $files) { $script:analyzerSumBytes += $f.Length }
    $sumFmt = if ($script:analyzerSumBytes -ge 1GB) { "{0:N1} GB" -f ($script:analyzerSumBytes / 1GB) } else { "{0:N0} MB" -f ($script:analyzerSumBytes / 1MB) }

    $lblAnalyzerBadge.Text = "Bulunan: $($script:analyzerTotalFound) Dosya ($sumFmt)"
    $lblAnalyzerFooter.Text = "⏱️ Tarama tamamlandı: $elapsedSec sn | Toplam $sumFmt alan kaplayan $($script:analyzerTotalFound) büyük dosya listelendi."

    if ($script:analyzerTotalFound -eq 0) {
        $emptyTb = New-Object System.Windows.Controls.TextBlock
        $emptyTb.Text = "Seçilen filtre kriterlerine uygun büyük dosya bulunamadı."
        $emptyTb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        $emptyTb.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $emptyTb.Margin = [System.Windows.Thickness]::new(0, 40, 0, 40)
        $pnlAnalyzerList.Children.Add($emptyTb) | Out-Null
        return
    }

    foreach ($file in $files) {
        $card = New-Object System.Windows.Controls.Border
        $card.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#131724")
        $card.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2438")
        $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $card.Padding = [System.Windows.Thickness]::new(12, 10, 12, 10)
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 0, 8)

        $dock = New-Object System.Windows.Controls.DockPanel
        $dock.LastChildFill = $true

        # Sağ Alan: Boyut Rozeti, Klasörde Göster ve Sil Butonları
        $rightSp = New-Object System.Windows.Controls.StackPanel
        $rightSp.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $rightSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [System.Windows.Controls.DockPanel]::SetDock($rightSp, [System.Windows.Controls.Dock]::Right)

        # Boyut Rozeti
        $szBadge = New-Object System.Windows.Controls.Border
        $szBadge.CornerRadius = [System.Windows.CornerRadius]::new(6)
        $szBadge.Padding = [System.Windows.Thickness]::new(10, 4, 10, 4)
        $szBadge.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
        $badgeBg = if ($file.Length -ge 5GB) { "#2E151B" } elseif ($file.Length -ge 1GB) { "#2A1B12" } else { "#16293A" }
        $szBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString($badgeBg)

        $txtSz = New-Object System.Windows.Controls.TextBlock
        $txtSz.Text = $file.SizeFormatted
        $txtSz.FontSize = 12
        $txtSz.FontWeight = [System.Windows.FontWeights]::Bold
        $badgeFg = if ($file.Length -ge 5GB) { "#EF4444" } elseif ($file.Length -ge 1GB) { "#F59E0B" } else { "#38BDF8" }
        $txtSz.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($badgeFg)
        $szBadge.Child = $txtSz
        $rightSp.Children.Add($szBadge) | Out-Null

        # Klasörde Göster Butonu
        $btnOpen = New-Object System.Windows.Controls.Button
        $btnOpen.Content = "📂 Klasörde Göster"
        $btnOpen.Padding = [System.Windows.Thickness]::new(10, 4, 10, 4)
        $btnOpen.Cursor = [System.Windows.Input.Cursors]::Hand
        $btnOpen.FontWeight = [System.Windows.FontWeights]::SemiBold
        $btnOpen.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
        $btnOpen.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1D2338")
        $btnOpen.BorderThickness = [System.Windows.Thickness]::new(0)
        $btnOpen.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)

        $styleBorder1 = New-Object System.Windows.Style([System.Windows.Controls.Border])
        $styleBorder1.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Border]::CornerRadiusProperty, [System.Windows.CornerRadius]::new(6))))
        $btnOpen.Resources.Add([System.Windows.Controls.Border], $styleBorder1)

        $curFile = $file
        $btnOpen.Add_Click({
            param($s, $e)
            if (Test-Path -LiteralPath $curFile.FullName) {
                [System.Diagnostics.Process]::Start("explorer.exe", "/select,`"$($curFile.FullName)`"") | Out-Null
            }
        }.GetNewClosure())
        $rightSp.Children.Add($btnOpen) | Out-Null

        # Sil Butonu
        $btnDelete = New-Object System.Windows.Controls.Button
        $btnDelete.Content = "🗑️ Sil"
        $btnDelete.Padding = [System.Windows.Thickness]::new(10, 4, 10, 4)
        $btnDelete.Cursor = [System.Windows.Input.Cursors]::Hand
        $btnDelete.FontWeight = [System.Windows.FontWeights]::SemiBold
        $btnDelete.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
        $btnDelete.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#2E151B")
        $btnDelete.BorderThickness = [System.Windows.Thickness]::new(0)

        $styleBorder2 = New-Object System.Windows.Style([System.Windows.Controls.Border])
        $styleBorder2.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Border]::CornerRadiusProperty, [System.Windows.CornerRadius]::new(6))))
        $btnDelete.Resources.Add([System.Windows.Controls.Border], $styleBorder2)

        $curCard = $card
        $btnDelete.Add_Click({
            param($s, $e)
            $confirmMsg = "Bu büyük dosyayı kalıcı olarak silmek istediğinizden emin misiniz?`n`n" +
                          "Dosya: $($curFile.Name)`n" +
                          "Boyut: $($curFile.SizeFormatted)`n" +
                          "Konum: $($curFile.FullName)"
            $ans = [System.Windows.MessageBox]::Show($window, $confirmMsg, "TemizWin - Dosya Silme Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
            if ($ans -eq [System.Windows.MessageBoxResult]::Yes) {
                try {
                    [System.IO.File]::Delete($curFile.FullName)
                    $pnlAnalyzerList.Children.Remove($curCard)
                    $script:analyzerTotalFound--
                    $script:analyzerSumBytes -= $curFile.Length
                    if ($script:analyzerTotalFound -lt 0) { $script:analyzerTotalFound = 0 }
                    if ($script:analyzerSumBytes -lt 0) { $script:analyzerSumBytes = 0 }
                    $newSumFmt = if ($script:analyzerSumBytes -ge 1GB) { "{0:N1} GB" -f ($script:analyzerSumBytes / 1GB) } else { "{0:N0} MB" -f ($script:analyzerSumBytes / 1MB) }
                    if ($lblAnalyzerBadge) { $lblAnalyzerBadge.Text = "Bulunan: $($script:analyzerTotalFound) Dosya ($newSumFmt)" }
                    if ($lblAnalyzerFooter) { $lblAnalyzerFooter.Text = "✓ Dosya silindi: $($curFile.Name) | Kalan: $($script:analyzerTotalFound) dosya ($newSumFmt)" }
                    if ($script:analyzerTotalFound -eq 0) {
                        $emptyTb = New-Object System.Windows.Controls.TextBlock
                        $emptyTb.Text = "Tüm büyük dosyalar silindi veya temizlendi."
                        $emptyTb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
                        $emptyTb.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
                        $emptyTb.Margin = [System.Windows.Thickness]::new(0, 40, 0, 40)
                        $pnlAnalyzerList.Children.Add($emptyTb) | Out-Null
                    }
                    # Sürücü boş alanını canlı güncelle
                    try {
                        Refresh-HeaderDrives
                        Update-AnalyzerLocationOptions
                    } catch {}
                    [System.Windows.MessageBox]::Show($window, "Dosya başarıyla silindi ve alan açıldı.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                } catch {
                    [System.Windows.MessageBox]::Show($window, "Dosya silinemedi: $($_.Exception.Message)", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
                }
            }
        }.GetNewClosure())
        $rightSp.Children.Add($btnDelete) | Out-Null

        $dock.Children.Add($rightSp) | Out-Null

        # Sol Alan: Simge, İsim ve Tam Yol
        $leftSp = New-Object System.Windows.Controls.StackPanel
        $leftSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $headerSp = New-Object System.Windows.Controls.StackPanel
        $headerSp.Orientation = [System.Windows.Controls.Orientation]::Horizontal

        $txtIcon = New-Object System.Windows.Controls.TextBlock
        $txtIcon.Text = $file.Icon
        $txtIcon.FontSize = 14
        $txtIcon.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)
        $txtIcon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $headerSp.Children.Add($txtIcon) | Out-Null

        $txtName = New-Object System.Windows.Controls.TextBlock
        $txtName.Text = $file.Name
        $txtName.FontWeight = [System.Windows.FontWeights]::Bold
        $txtName.FontSize = 13
        $txtName.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
        $txtName.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $headerSp.Children.Add($txtName) | Out-Null

        $catBadge = New-Object System.Windows.Controls.Border
        $catBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2438")
        $catBadge.CornerRadius = [System.Windows.CornerRadius]::new(4)
        $catBadge.Padding = [System.Windows.Thickness]::new(6, 1, 6, 1)
        $catBadge.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
        $catBadge.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $txtCat = New-Object System.Windows.Controls.TextBlock
        $txtCat.Text = $file.Category
        $txtCat.FontSize = 10
        $txtCat.FontWeight = [System.Windows.FontWeights]::Bold
        $txtCat.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
        $catBadge.Child = $txtCat
        $headerSp.Children.Add($catBadge) | Out-Null

        $leftSp.Children.Add($headerSp) | Out-Null

        $txtPath = New-Object System.Windows.Controls.TextBlock
        $txtPath.Text = $file.FullName
        $txtPath.FontSize = 11
        $txtPath.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        $txtPath.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
        $txtPath.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
        $txtPath.MaxWidth = 480
        $leftSp.Children.Add($txtPath) | Out-Null

        $dock.Children.Add($leftSp) | Out-Null
        $card.Child = $dock
        $pnlAnalyzerList.Children.Add($card) | Out-Null
    }
}

function Stop-AnalyzerScanExecution {
    if (-not $script:isAnalyzerScanning) { return }
    $script:isAnalyzerScanning = $false
    $script:analyzerTimer.Stop()
    try { $script:analyzerPowerShell.Stop() } catch {}
    try { $script:analyzerPowerShell.Dispose() } catch {}
    try { $script:analyzerRunspaceHost.Close(); $script:analyzerRunspaceHost.Dispose() } catch {}
    $script:analyzerPowerShell = $null
    $script:analyzerRunspaceHost = $null
    $script:analyzerAsyncHandle = $null

    $progAnalyzer.Visibility = [System.Windows.Visibility]::Collapsed
    $btnStartAnalyzerScan.Content = "🔍 Taramayı Başlat"
    $btnStartAnalyzerScan.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#0284C7")
    $lblAnalyzerBadge.Text = "İptal Edildi"
    $lblAnalyzerFooter.Text = "⚠️ Tarama kullanıcı tarafından durduruldu."
}

function Start-AnalyzerScanExecution {
    if (-not $pnlAnalyzerList) { return }

    if ($script:isAnalyzerScanning) {
        Stop-AnalyzerScanExecution
        return
    }

    $script:isAnalyzerScanning = $true
    Write-CmdLog "ANALİZ" ">>> Büyük dosya ve disk analizi başlatıldı..." "Cyan"
    $btnStartAnalyzerScan.Content = "⏹️ İptal Et"
    $btnStartAnalyzerScan.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#991B1B")
    $progAnalyzer.Visibility = [System.Windows.Visibility]::Visible
    $lblAnalyzerBadge.Text = "Taranıyor..."
    $pnlAnalyzerList.Children.Clear()

    $selectedItem = if ($cmbAnalyzerLocation) { $cmbAnalyzerLocation.SelectedItem } else { $null }
    $locTag = if ($selectedItem -and $selectedItem.Tag) { [string]$selectedItem.Tag } else { "UserFolders" }

    $szIdx = if ($cmbAnalyzerMinSize) { $cmbAnalyzerMinSize.SelectedIndex } else { 0 }
    $minBytes = switch ($szIdx) {
        0 { 500MB }
        1 { 1GB }
        2 { 100MB }
        default { 500MB }
    }

    $script:analyzerStopwatch = [System.Diagnostics.Stopwatch]::StartNew()

    $iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
    $script:analyzerRunspaceHost = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($iss)
    $script:analyzerRunspaceHost.ApartmentState = [System.Threading.ApartmentState]::STA
    $script:analyzerRunspaceHost.ThreadOptions  = [System.Management.Automation.Runspaces.PSThreadOptions]::UseNewThread
    $script:analyzerRunspaceHost.Open()

    $script:analyzerPowerShell = [powershell]::Create()
    $script:analyzerPowerShell.Runspace = $script:analyzerRunspaceHost

    $scannerScript = {
        param([string]$targetLocTag, [long]$minSz, [string]$userProf)

        $results = [System.Collections.Generic.List[PSCustomObject]]::new()
        $seenPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $videoExt = @(".mp4", ".mkv", ".avi", ".mov", ".wmv", ".flv", ".webm", ".m4v")
        $archExt  = @(".zip", ".rar", ".7z", ".tar", ".gz", ".iso", ".img", ".vmdk", ".vhd")
        $appExt   = @(".exe", ".msi", ".apk", ".dll")

        function Process-ItemSafe($f) {
            $ext = $f.Extension.ToLowerInvariant()
            $icon = "📄"
            $cat = "Belge / Dosya"
            if ($videoExt -contains $ext) { $icon = "🎬"; $cat = "Video" }
            elseif ($archExt -contains $ext) {
                if ($ext -eq ".iso" -or $ext -eq ".img") { $icon = "💿"; $cat = "Disk İmajı" }
                else { $icon = "📦"; $cat = "Arşiv" }
            }
            elseif ($appExt -contains $ext) { $icon = "⚙️"; $cat = "Uygulama" }

            $szFmt = if ($f.Length -ge 1GB) { "{0:N2} GB" -f ($f.Length / 1GB) } else { "{0:N0} MB" -f ($f.Length / 1MB) }

            return [PSCustomObject]@{
                Name          = $f.Name
                FullName      = $f.FullName
                Directory     = $f.DirectoryName
                Length        = $f.Length
                SizeFormatted = $szFmt
                Icon          = $icon
                Category      = $cat
            }
        }

        function Scan-SingleDriveInternal([string]$drvRoot, [bool]$isSystemDrive) {
            $skipDirs = @("`$Recycle.Bin", "`$RECYCLE.BIN", "System Volume Information", "Recovery")
            if ($isSystemDrive) {
                $skipDirs += @("Windows", "ProgramData", "PerfLogs")
            }

            $dirsToScan = @()
            try {
                foreach ($d in [System.IO.Directory]::GetDirectories($drvRoot)) {
                    $bName = [System.IO.Path]::GetFileName($d)
                    if ($skipDirs -contains $bName) { continue }
                    try {
                        $di = [System.IO.DirectoryInfo]::new($d)
                        if ($di.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { continue }
                        $dirsToScan += $d
                    } catch {}
                }
            } catch {}

            try {
                foreach ($rf in [System.IO.Directory]::GetFiles($drvRoot)) {
                    try {
                        $fi = [System.IO.FileInfo]::new($rf)
                        if ($isSystemDrive -and $fi.Name -match '^(pagefile\.sys|hiberfil\.sys|swapfile\.sys|dumpstack\.log)$') { continue }
                        if ($fi.Length -ge $minSz) {
                            if ($seenPaths.Add($fi.FullName)) {
                                $results.Add((Process-ItemSafe $fi))
                            }
                        }
                    } catch {}
                }
            } catch {}

            foreach ($dir in $dirsToScan) {
                try {
                    $files = Get-ChildItem -LiteralPath $dir -File -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
                        if ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
                        return ($_.Length -ge $minSz)
                    }
                    foreach ($f in $files) {
                        if ($seenPaths.Add($f.FullName)) {
                            $results.Add((Process-ItemSafe $f))
                        }
                    }
                } catch {}
            }
        }

        if ($targetLocTag -eq "UserFolders") {
            $rawFolders = @(
                "$userProf\Downloads",
                "$userProf\Desktop",
                "$userProf\Documents",
                "$userProf\Pictures",
                "$userProf\Videos",
                "$userProf\Music",
                "$userProf\OneDrive\Desktop",
                "$userProf\OneDrive\Documents",
                "$userProf\OneDrive\Pictures",
                "$userProf\OneDrive\Videos"
            )
            $targetFolders = [System.Collections.Generic.List[string]]::new()
            foreach ($fld in $rawFolders) {
                if ((Test-Path -LiteralPath $fld -ErrorAction SilentlyContinue) -and -not $targetFolders.Contains($fld)) {
                    $targetFolders.Add($fld)
                }
            }
            foreach ($folder in $targetFolders) {
                try {
                    $files = Get-ChildItem -LiteralPath $folder -File -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
                        if ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
                        return ($_.Length -ge $minSz)
                    }
                    foreach ($f in $files) {
                        if ($seenPaths.Add($f.FullName)) {
                            $results.Add((Process-ItemSafe $f))
                        }
                    }
                } catch {}
            }
        }
        elseif ($targetLocTag.StartsWith("Drive_")) {
            $letter = $targetLocTag.Substring(6)
            $root = "$letter`:\"
            if (Test-Path -LiteralPath $root) {
                Scan-SingleDriveInternal $root ($letter.ToUpper() -eq "C")
            }
        }
        elseif ($targetLocTag -eq "AllDrives") {
            $allDrives = [System.IO.DriveInfo]::GetDrives() | Where-Object {
                $_.IsReady -and ($_.DriveType -eq [System.IO.DriveType]::Fixed -or $_.DriveType -eq [System.IO.DriveType]::Removable)
            }
            foreach ($ad in $allDrives) {
                $isSys = ($ad.Name.StartsWith("C:", [System.StringComparison]::OrdinalIgnoreCase))
                Scan-SingleDriveInternal $ad.RootDirectory.FullName $isSys
            }
        }

        return @($results | Sort-Object -Property Length -Descending | Select-Object -First 50)
    }

    $null = $script:analyzerPowerShell.AddScript($scannerScript).AddArgument($locTag).AddArgument($minBytes).AddArgument($env:USERPROFILE)
    $script:analyzerAsyncHandle = $script:analyzerPowerShell.BeginInvoke()
    $script:analyzerTimer.Start()
}

$script:analyzerTimer.Add_Tick({
    if (-not $script:analyzerAsyncHandle -or -not $script:isAnalyzerScanning) {
        $script:analyzerTimer.Stop()
        return
    }

    $elapsedSec = [Math]::Round($script:analyzerStopwatch.ElapsedMilliseconds / 1000, 1)
    $lblAnalyzerBadge.Text = "Taranıyor... ($elapsedSec sn)"
    $lblAnalyzerFooter.Text = "⏳ Disk arka planda inceleniyor... ($elapsedSec saniye geçti, arayüz kesintisiz çalışıyor)"

    if ($script:analyzerAsyncHandle.IsCompleted) {
        $script:analyzerTimer.Stop()
        $script:isAnalyzerScanning = $false
        $script:analyzerStopwatch.Stop()
        $finalSec = [Math]::Round($script:analyzerStopwatch.ElapsedMilliseconds / 1000, 2)

        $progAnalyzer.Visibility = [System.Windows.Visibility]::Collapsed
        $btnStartAnalyzerScan.Content = "🔍 Taramayı Başlat"
        $btnStartAnalyzerScan.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#0284C7")

        $files = @()
        $scanError = $null
        try {
            $files = @($script:analyzerPowerShell.EndInvoke($script:analyzerAsyncHandle))
        } catch {
            $scanError = $_.Exception.Message
        }

        try { $script:analyzerPowerShell.Dispose() } catch {}
        try { $script:analyzerRunspaceHost.Close(); $script:analyzerRunspaceHost.Dispose() } catch {}
        $script:analyzerPowerShell = $null
        $script:analyzerRunspaceHost = $null
        $script:analyzerAsyncHandle = $null

        if ($scanError) {
            if ($lblAnalyzerBadge) { $lblAnalyzerBadge.Text = "Hata Oluştu" }
            if ($lblAnalyzerFooter) { $lblAnalyzerFooter.Text = "⚠️ Tarama sırasında hata oluştu: $scanError" }
        } else {
            Render-AnalyzerResults $files $finalSec
        }
    }
})

# Fonksiyon: Get-LargeFilesList (Test uyumluluğu için senkron çağrı)
function Get-LargeFilesList([string]$locationType, [long]$minBytes) {
    $locTag = if ($locationType -eq "SystemDrive") { "Drive_C" } else { $locationType }
    $allDrives = Get-ReadyDrivesList

    $results = [System.Collections.Generic.List[PSCustomObject]]::new()
    $videoExt = @(".mp4", ".mkv", ".avi", ".mov", ".wmv", ".flv", ".webm", ".m4v")
    $archExt  = @(".zip", ".rar", ".7z", ".tar", ".gz", ".iso", ".img", ".vmdk", ".vhd")
    $appExt   = @(".exe", ".msi", ".apk", ".dll")

    function Process-ItemSafe2($f) {
        $ext = $f.Extension.ToLowerInvariant()
        $icon = "📄"
        $cat = "Belge / Dosya"
        if ($videoExt -contains $ext) { $icon = "🎬"; $cat = "Video" }
        elseif ($archExt -contains $ext) {
            if ($ext -eq ".iso" -or $ext -eq ".img") { $icon = "💿"; $cat = "Disk İmajı" }
            else { $icon = "📦"; $cat = "Arşiv" }
        }
        elseif ($appExt -contains $ext) { $icon = "⚙️"; $cat = "Uygulama" }

        $szFmt = if ($f.Length -ge 1GB) { "{0:N2} GB" -f ($f.Length / 1GB) } else { "{0:N0} MB" -f ($f.Length / 1MB) }

        return [PSCustomObject]@{
            Name          = $f.Name
            FullName      = $f.FullName
            Directory     = $f.DirectoryName
            Length        = $f.Length
            SizeFormatted = $szFmt
            Icon          = $icon
            Category      = $cat
        }
    }

    if ($locTag -eq "UserFolders") {
        $targetFolders = @(
            "$env:USERPROFILE\Downloads",
            "$env:USERPROFILE\Desktop",
            "$env:USERPROFILE\Documents",
            "$env:USERPROFILE\Videos",
            "$env:USERPROFILE\Music"
        )
        foreach ($folder in $targetFolders) {
            if (-not (Test-Path -LiteralPath $folder -ErrorAction SilentlyContinue)) { continue }
            try {
                $files = Get-ChildItem -LiteralPath $folder -File -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
                    if ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
                    return ($_.Length -ge $minBytes)
                }
                foreach ($f in $files) {
                    $results.Add((Process-ItemSafe2 $f))
                }
            } catch {}
        }
    } else {
        $skipDirs = @("Windows", "`$Recycle.Bin", "`$RECYCLE.BIN", "System Volume Information", "Recovery", "PerfLogs", "ProgramData")
        $dirsToScan = @()
        try {
            foreach ($d in [System.IO.Directory]::GetDirectories("C:\")) {
                $bName = [System.IO.Path]::GetFileName($d)
                if ($skipDirs -contains $bName) { continue }
                try {
                    $di = [System.IO.DirectoryInfo]::new($d)
                    if ($di.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { continue }
                    $dirsToScan += $d
                } catch {}
            }
        } catch {}

        try {
            foreach ($rf in [System.IO.Directory]::GetFiles("C:\")) {
                try {
                    $fi = [System.IO.FileInfo]::new($rf)
                    if ($fi.Length -ge $minBytes) {
                        $results.Add((Process-ItemSafe2 $fi))
                    }
                } catch {}
            }
        } catch {}

        foreach ($dir in $dirsToScan) {
            try {
                $files = Get-ChildItem -LiteralPath $dir -File -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
                    if ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
                    return ($_.Length -ge $minBytes)
                }
                foreach ($f in $files) {
                    $results.Add((Process-ItemSafe2 $f))
                }
            } catch {}
        }
    }

    return @($results | Sort-Object -Property Length -Descending | Select-Object -First 50)
}

# ------------------------------------------------------------------------------
# 7.5. Bellek (RAM) Yönetimi ve Canlı Optimizasyon (EmptyWorkingSet API)
# ------------------------------------------------------------------------------
function Update-MainRamDisplay {
    try {
        if (-not ("Microsoft.VisualBasic.Devices.ComputerInfo" -as [type])) {
            Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction SilentlyContinue
        }
        $ci = New-Object Microsoft.VisualBasic.Devices.ComputerInfo
        $totGB = [math]::Round($ci.TotalPhysicalMemory / 1GB, 1)
        $availGB = [math]::Round($ci.AvailablePhysicalMemory / 1GB, 1)
        $usedGB = [math]::Round($totGB - $availGB, 1)
        $pct = [math]::Round(($usedGB / $totGB) * 100)
        
        if ($lblMainRamUsage) {
            $lblMainRamUsage.Text = "$usedGB GB (%$pct)"
            if ($pct -ge 85) {
                $lblMainRamUsage.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
            } elseif ($pct -ge 70) {
                $lblMainRamUsage.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
            } else {
                $lblMainRamUsage.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
            }
        }
    } catch {}
}

$script:ramResetTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:ramResetTimer.Interval = [TimeSpan]::FromSeconds(3)
$script:ramResetTimer.Add_Tick({
    $script:ramResetTimer.Stop()
    if ($btnOptimizeRam) {
        $btnOptimizeRam.Content = "⚡ Boşalt"
        $btnOptimizeRam.IsEnabled = $true
    }
})

function Optimize-SystemMemory {
    if (-not $btnOptimizeRam) { return }
    
    try {
        $btnOptimizeRam.IsEnabled = $false
        $btnOptimizeRam.Content = "⏳..."
        
        # 1. Standby List (Bekleyen Bellek Önbelleği) Temizliği - Saf ISLC / RAMMap Yöntemi
        # Aktif çalışan programların (Oyun, Discord, Chrome vb.) belleğini diske kovmaz;
        # çalışma kümelerine (Working Set) dokunmaz, takılma ve page fault üretmez!
        $standbyPurged = $false
        try {
            $standbyPurged = [Win32Mem]::PurgeStandbyList()
        } catch {}

        # 2. TemizWin kendi yönetilen belleğini optimize eder
        [System.GC]::Collect()
        [System.GC]::WaitForPendingFinalizers()
        
        Update-MainRamDisplay
        
        if ($btnOptimizeRam) {
            $btnOptimizeRam.Content = if ($standbyPurged) { "✓ Temizlendi" } else { "✓ Temiz" }
        }
        if ($lblMainStatus) {
            $lblMainStatus.Text = "⚡ Standby bellek önbelleği temizlendi."
            $lblMainStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
        }
        try {
            Write-CmdLog "RAM" "Optimize-SystemMemory (ISLC Standby Purge): Standby bellek önbelleği temizlendi." "Green"
        } catch {}
        
        $script:ramResetTimer.Start()
    } catch {
        if ($btnOptimizeRam) {
            $btnOptimizeRam.Content = "⚡ Boşalt"
            $btnOptimizeRam.IsEnabled = $true
        }
    }
}

# ------------------------------------------------------------------------------
# 7.8. Windows Bloatware Veritabanı ve Kaldırma Motoru
# ------------------------------------------------------------------------------
