    # --- YÜKSEK ÖNCELİKLİ GEREKSİZLER (SAFE BLOATWARE) ---
    @{ Id = "Clipchamp.Clipchamp"; Name = "Microsoft Clipchamp (Video Düzenleyici)"; Icon = "🎞️"; Safe = $true; Desc = "Yerleşik çevrimiçi video düzenleyici" },
