    @{ Id = "Microsoft.BingWeather"; Name = "MSN Hava Durumu"; Icon = "☀️"; Safe = $true; Desc = "Hava durumu önbelleği ve arka plan verisi" },
    @{ Id = "Microsoft.GetHelp"; Name = "Yardım Alın (Get Help)"; Icon = "❓"; Safe = $true; Desc = "Microsoft çevrimiçi destek yardımcısı" },
    @{ Id = "Microsoft.Getstarted"; Name = "İpuçları (Tips)"; Icon = "💡"; Safe = $true; Desc = "Windows tanıtım ve başlangıç ipuçları" },
    @{ Id = "Microsoft.MicrosoftOfficeHub"; Name = "Microsoft 365 (Office Uygulaması)"; Icon = "📑"; Safe = $true; Desc = "Office reklam ve web kısayol paneli" },
    @{ Id = "Microsoft.MicrosoftSolitaireCollection"; Name = "Solitaire Koleksiyonu"; Icon = "🃏"; Safe = $true; Desc = "Yerleşik kart oyunları paketi" },
    @{ Id = "Microsoft.People"; Name = "Kişiler (People)"; Icon = "👥"; Safe = $true; Desc = "Kişiler ve adres defteri senkronizasyonu" },
    @{ Id = "Microsoft.PowerAutomateDesktop"; Name = "Power Automate"; Icon = "🤖"; Safe = $true; Desc = "Masaüstü otomasyon arka plan servisi" },
    @{ Id = "Microsoft.Todos"; Name = "Microsoft To Do"; Icon = "📝"; Safe = $true; Desc = "Görev ve yapılacaklar listesi" },
