function Remove-MicrosoftEdgeClean {
    try {
        Write-CmdLog "EDGE" "Microsoft Edge zorla ve kalıcı kaldırma işlemi başlatılıyor..." "Yellow"
        
        # 1. Arka planda çalışan tüm Edge ve Updater süreçlerini sonlandır
        Write-CmdLog "EDGE" "Stop-Process -Name 'msedge', 'MicrosoftEdgeUpdate' -Force" "Yellow"
        Get-Process -Name "msedge", "MicrosoftEdgeUpdate", "identity_helper" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 600

        # 2. AppX paket ve provisioned kayıtlarını temizle (DevToolsClient korunur)
        Write-CmdLog "EDGE" "Get-AppxPackage '*MicrosoftEdge*' | Remove-AppxPackage" "Yellow"
        Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*MicrosoftEdge*" -and $_.Name -notlike "*DevToolsClient*" } | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
        Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like "*MicrosoftEdge*" -and $_.DisplayName -notlike "*DevToolsClient*" } | Remove-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue

        # 3. Registry AllowUninstall kilidini aç (Windows kaldırma blokajını aşar)
        try {
            $regView = [Microsoft.Win32.RegistryView]::Registry32
            $hklm = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, $regView)
            $edgeUpdateKey = $hklm.CreateSubKey('SOFTWARE\Microsoft\EdgeUpdateDev')
            if ($edgeUpdateKey) {
                $edgeUpdateKey.SetValue('AllowUninstall', '')
                $edgeUpdateKey.Dispose()
            }
            $hklm.Dispose()
        } catch {}

        # 4. Edge Stub oluştur (Windows dahili kaldırıcı kontrolünü tetikler)
        $edgeStub = "$env:SystemRoot\SystemApps\Microsoft.MicrosoftEdge_8wekyb3d8bbwe"
        try {
            New-Item $edgeStub -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
            New-Item "$edgeStub\MicrosoftEdge.exe" -ItemType File -Force -ErrorAction SilentlyContinue | Out-Null
        } catch {}

        # 5. Resmi Uninstaller komutunu tespit et ve çalıştır
        $uninstallCmd = $null
        try {
            $regView = [Microsoft.Win32.RegistryView]::Registry32
            $hklm = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, $regView)
            $uninstallRegKey = $hklm.OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Microsoft Edge')
            if ($uninstallRegKey) {
                $rawUninstall = $uninstallRegKey.GetValue('UninstallString')
                if ($rawUninstall) {
                    $uninstallCmd = "$rawUninstall --force-uninstall"
                }
                $uninstallRegKey.Dispose()
            }
            $hklm.Dispose()
        } catch {}

        $setupExe = $null
        if ($uninstallCmd) {
            Write-CmdLog "EDGE" "Start-Process cmd.exe /c $uninstallCmd" "Yellow"
            Start-Process cmd.exe -ArgumentList "/c `"$uninstallCmd`"" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 2
        } else {
            $setupExe = Get-ChildItem -Path "${env:ProgramFiles(x86)}\Microsoft\Edge\Application" -Filter "setup.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($setupExe) {
                Write-CmdLog "EDGE" "Start-Process $($setupExe.FullName) --uninstall --msedge --channel=stable --system-level --verbose-logging --force-uninstall" "Yellow"
                Start-Process -FilePath $setupExe.FullName -ArgumentList "--uninstall --msedge --channel=stable --system-level --verbose-logging --force-uninstall" -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue
                Start-Sleep -Seconds 2
            }
        }

        # Kaldırıcı hiç bulunamazsa sahte başarı dönme
        if (-not $uninstallCmd -and -not $setupExe) {
            Write-CmdLog "EDGE" "✗ Microsoft Edge kaldırıcı dosyası (setup.exe) bulunamadı." "Red"
            return $false
        }

        # 6. Kalan artık kısayolları ve stub dizinini temizle
        $edgePaths = @(
            "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\Microsoft Edge.lnk",
            "$env:APPDATA\Microsoft\Internet Explorer\Quick Launch\Microsoft Edge.lnk",
            "$env:APPDATA\Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar\Microsoft Edge.lnk",
            "$env:APPDATA\Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar\Tombstones\Microsoft Edge.lnk",
            "$env:PUBLIC\Desktop\Microsoft Edge.lnk",
            "$env:USERPROFILE\Desktop\Microsoft Edge.lnk",
            "$edgeStub"
        )
        foreach ($p in $edgePaths) {
            if (Test-Path -Path $p) {
                Remove-Item -Path $p -Force -Recurse -ErrorAction SilentlyContinue
            }
        }

        # 7. Başlangıç (Autostart) kayıtlarını temizle
        $autostartPaths = @(
            'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
            'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
        )
        foreach ($asp in $autostartPaths) {
            if (Test-Path $asp) {
                Remove-ItemProperty -Path $asp -Name "MicrosoftEdgeAutoLaunch_A9F6DCE4ABADF4F51CF45CD7129E3C6C" -ErrorAction SilentlyContinue
                Remove-ItemProperty -Path $asp -Name "Microsoft Edge Update" -ErrorAction SilentlyContinue
            }
        }

        # 8. AppData paket artıklarını temizle
        $pkgDir = "$env:LOCALAPPDATA\Packages"
        if (Test-Path $pkgDir) {
            Get-ChildItem -Path $pkgDir -Directory -Filter "*MicrosoftEdge*" -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        }

        # 9. Kaldırma doğrulaması (msedge.exe hala mevcut mu?)
        $edgeCheckPaths = @(
            "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
            "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
        )
        foreach ($cp in $edgeCheckPaths) {
            if (Test-Path -LiteralPath $cp -ErrorAction SilentlyContinue) {
                Write-CmdLog "EDGE" "✗ Microsoft Edge kaldırılamadı (msedge.exe hala mevcut)." "Red"
                return $false
            }
        }

        Write-CmdLog "EDGE" "✓ Microsoft Edge başarıyla ve tüm bileşenleriyle kaldırıldı." "Green"
        if ($script:pendingRebootTweaks) { $script:pendingRebootTweaks.Add("Microsoft Edge Kaldırıldı") | Out-Null }
        return $true
    } catch {
        Write-CmdLog "EDGE" "✗ Microsoft Edge kaldırılamadı: $($_.Exception.Message)" "Red"
        return $false
    }
}

function Remove-SingleAppxPackageClean([string]$packageId, [string]$displayName) {
    if ($packageId -like "*Edge*") {
        return (Remove-MicrosoftEdgeClean)
    }
    try {
        Write-CmdLog "UYGULAMA" "Get-AppxPackage '*$packageId*' | Remove-AppxPackage ($displayName)" "Yellow"
        
        # 1. Kilitli dosya veya kalıntı kalmaması için ilgili arka plan süreçlerini sonlandır
        if ($packageId -like "*Teams*") {
            Get-Process -Name "ms-teams", "msteams", "Teams" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        } elseif ($packageId -like "*CrossDevice*") {
            Get-Process -Name "CrossDeviceService", "PhoneExperienceHost" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        } elseif ($packageId -like "*Widgets*" -or $packageId -like "*StartExperiencesApp*" -or $packageId -like "*WebExperience*") {
            Get-Process -Name "Widgets", "WidgetService" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        } elseif ($packageId -like "*DevHome*") {
            Get-Process -Name "DevHome" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        }

        # 2. Mevcut kullanıcı profilinden kaldır
        Get-AppxPackage -Name "*$packageId*" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue
        
        # 3. Tüm kullanıcı profillerinden temizle (Yönetici yetkisi ile)
        if ($script:isAdmin) {
            Get-AppxPackage -AllUsers -Name "*$packageId*" -ErrorAction SilentlyContinue | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
        }

        # 4. Windows imaj deposundan (Provisioned) kaldır (Güncelleme sonrası geri gelmeyi önler)
        Write-CmdLog "UYGULAMA" "Get-AppxProvisionedPackage -Online | Remove-AppxProvisionedPackage ($displayName)" "Yellow"
        Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like "*$packageId*" -or $_.PackageName -like "*$packageId*" } | Remove-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue
        
        # 5. AppData altındaki paket artıklarını süpür
        $pkgDir = "$env:LOCALAPPDATA\Packages"
        if (Test-Path $pkgDir) {
            Write-CmdLog "UYGULAMA" "Remove-Item '$pkgDir\*$packageId*' -Recurse -Force" "Yellow"
            Get-ChildItem -Path $pkgDir -Directory -Filter "*$packageId*" -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        }

        # 6. Uygulamaya özel harici veri ve önbellek artıklarını süpür
        if ($packageId -like "*Teams*") {
            @(
                "$env:APPDATA\Microsoft\Teams",
                "$env:LOCALAPPDATA\Microsoft\Teams"
            ) | Where-Object { Test-Path $_ -ErrorAction SilentlyContinue } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        }

        # 7. Başlat menüsü ve masaüstünde kalabilecek artık kısayolları temizle
        $shortcutDirs = @(
            "$env:ProgramData\Microsoft\Windows\Start Menu\Programs",
            "$env:APPDATA\Microsoft\Windows\Start Menu\Programs",
            "$env:USERPROFILE\Desktop",
            "$env:PUBLIC\Desktop"
        )
        foreach ($sDir in $shortcutDirs) {
            if (Test-Path $sDir) {
                Get-ChildItem -Path $sDir -Filter "*.lnk" -Recurse -ErrorAction SilentlyContinue | Where-Object {
                    $_.BaseName -like "*$displayName*" -or $_.BaseName -like "*$packageId*"
                } | Remove-Item -Force -ErrorAction SilentlyContinue
            }
        }

        # 8. Gerçek kaldırma doğrulaması (Paket gerçekten silindi mi?)
        $stillInstalled = Get-AppxPackage -Name "*$packageId*" -ErrorAction SilentlyContinue
        if ($stillInstalled) {
            Write-CmdLog "UYGULAMA" "✗ $displayName sistemden kaldırılamadı (paket hala mevcut)." "Red"
            return $false
        }

        Write-CmdLog "UYGULAMA" "✓ $displayName başarıyla ve sıfır artıkla kaldırıldı." "Green"
        return $true
    } catch {
        Write-CmdLog "UYGULAMA" "✗ $displayName kaldırılamadı: $($_.Exception.Message)" "Red"
        return $false
    }
}

function Remove-OneDriveClean {
    try {
        Write-CmdLog "ONEDRIVE" "OneDrive kaldırma işlemi başlatılıyor..." "Yellow"
        # 1. Arka planda calisan OneDrive sureclerini zorla sonlandir
        Get-Process -Name "OneDrive", "OneDriveStandaloneUpdater" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 300

        # 2. Sessiz kaldiriciyi (Uninstaller) tespit et ve calistir
        $uninstallerPaths = @(
            "$env:LOCALAPPDATA\Microsoft\OneDrive\Update\OneDriveSetup.exe",
            "$env:LOCALAPPDATA\Microsoft\OneDrive\OneDriveSetup.exe",
            "$env:ProgramFiles\Microsoft OneDrive\OneDriveSetup.exe",
            "${env:ProgramFiles(x86)}\Microsoft OneDrive\OneDriveSetup.exe",
            "$env:SystemRoot\SysWOW64\OneDriveSetup.exe",
            "$env:SystemRoot\System32\OneDriveSetup.exe"
        )

        foreach ($uninst in $uninstallerPaths) {
            if ($uninst -and (Test-Path -LiteralPath $uninst -ErrorAction SilentlyContinue)) {
                Start-Process -FilePath $uninst -ArgumentList "/uninstall" -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue
                break
            }
        }

        # 3. Otomatik Baslangic (Run) kayitlarini temizle
        Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run" -Name "OneDrive" -ErrorAction SilentlyContinue
        Remove-ItemProperty -Path "HKLM:\Software\Microsoft\Windows\CurrentVersion\Run" -Name "OneDrive" -ErrorAction SilentlyContinue

        # 4. Dosya Gezgini sol menusundeki kalinti OneDrive simgesini (Namespace PIN) sok
        $clsids = @(
            "HKCR:\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}",
            "HKCR:\Wow6432Node\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}",
            "HKCU:\Software\Classes\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}",
            "HKCU:\Software\Classes\Wow6432Node\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}"
        )
        foreach ($c in $clsids) {
            if (Test-Path $c -ErrorAction SilentlyContinue) {
                Set-ItemProperty -Path $c -Name "System.IsPinnedToNameSpace" -Value 0 -Type DWord -ErrorAction SilentlyContinue
            }
        }

        # 5. Artik program ve log dizinlerini supur (Kullanicinin kendi kisisel dosyalarina dokunmadan)
        $residualPaths = @(
            "$env:LOCALAPPDATA\Microsoft\OneDrive",
            "$env:PROGRAMDATA\Microsoft OneDrive",
            "$env:SYSTEMDRIVE\OneDriveTemp"
        )
        foreach ($rp in $residualPaths) {
            if (Test-Path -LiteralPath $rp -ErrorAction SilentlyContinue) {
                Remove-Item -LiteralPath $rp -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        # 6. Kullanici ana dizinindeki bos veya artik OneDrive klasorunu temizle
        $userOd = "$env:USERPROFILE\OneDrive"
        if (Test-Path -LiteralPath $userOd -ErrorAction SilentlyContinue) {
            $userFiles = Get-ChildItem -LiteralPath $userOd -File -Force -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch 'desktop\.ini' }
            if (-not $userFiles -or $userFiles.Count -eq 0) {
                Remove-Item -LiteralPath $userOd -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        Write-Host "[$((Get-Date).ToString('HH:mm:ss'))] [BAŞARILI] OneDrive başarıyla kaldırıldı ve temizlendi." -ForegroundColor Green
        return $true
    } catch {
        Write-Host "[$((Get-Date).ToString('HH:mm:ss'))] [HATA] OneDrive kaldırılırken hata: $($_.Exception.Message)" -ForegroundColor Red
        return $false
    }
}

function Get-AppxLogoPath([string]$installLocation) {
    if (-not $installLocation -or -not (Test-Path $installLocation -ErrorAction SilentlyContinue)) { return $null }
    
    $searchDir = $null
    $assetsDir = Join-Path $installLocation "Assets"
    $imagesDir = Join-Path $installLocation "Images"

    if (Test-Path $assetsDir -ErrorAction SilentlyContinue) {
        $searchDir = $assetsDir
    } elseif (Test-Path $imagesDir -ErrorAction SilentlyContinue) {
        $searchDir = $imagesDir
    } else {
        $searchDir = $installLocation
    }

    $pngs = Get-ChildItem -Path $searchDir -Filter "*.png" -File -Recurse -ErrorAction SilentlyContinue
    if (-not $pngs -or $pngs.Count -eq 0) { return $null }

    $patterns = @(
        "*AppList*scale-200.png",
        "*AppList*scale-150.png",
        "*AppList*scale-100.png",
        "*AppList*.png",
        "*Square44x44Logo*targetsize-48*.png",
        "*Square44x44Logo*targetsize-32*.png",
        "*Square44x44Logo*scale-200*.png",
        "*Square44x44Logo*.png",
        "*MedTile*scale-200*.png",
        "*Square150x150Logo*scale-200*.png",
        "*Square150x150Logo*.png",
        "*StoreLogo*scale-200*.png",
        "*StoreLogo*.png"
    )

    foreach ($pat in $patterns) {
        $c = $pngs | Where-Object { $_.Name -like $pat -and $_.Name -notlike "*contrast-white*" -and $_.Name -notlike "*contrast-black*" } | Select-Object -First 1
        if ($c) { return $c.FullName }
    }

    $fallback = $pngs | Where-Object { $_.Name -notlike "*contrast*" -and $_.Length -gt 500 } | Select-Object -First 1
    if ($fallback) { return $fallback.FullName }
    return $pngs[0].FullName
}

function Refresh-BloatwareList {
    if (-not $pnlBloatwareList) { return }
    $pnlBloatwareList.Children.Clear()
    
    if ($progBloatware) { $progBloatware.Visibility = [System.Windows.Visibility]::Visible }
    if ($lblBloatwareCountBadge) { $lblBloatwareCountBadge.Text = "Taranıyor..." }

    $installedPackages = Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object { -not $_.IsFramework -and -not $_.NonRemovable }
    $foundList = [System.Collections.Generic.List[PSCustomObject]]::new()

    foreach ($entry in $script:knownBloatware) {
        $match = $installedPackages | Where-Object { $_.Name -like "*$($entry.Id)*" } | Select-Object -First 1
        $isEdge = ($entry.Id -like "*MicrosoftEdge*")
        $edgeExePath = $null
        if ($isEdge) {
            $edgeCandidates = @(
                "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
                "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
            )
            foreach ($ec in $edgeCandidates) {
                if (Test-Path -LiteralPath $ec -ErrorAction SilentlyContinue) {
                    $edgeExePath = $ec
                    break
                }
            }
        }
        $edgeOnDisk = ($isEdge -and $null -ne $edgeExePath)

        if ($match -or $edgeOnDisk) {
            $logoPath = if ($match) { Get-AppxLogoPath $match.InstallLocation } else { $null }
            $lvl = if ($entry.Level) { $entry.Level } elseif ($entry.Safe) { "Safe" } else { "Warning" }
            $ver = if ($match -and $match.Version) {
                $match.Version
            } elseif ($edgeOnDisk) {
                (Get-Item -LiteralPath $edgeExePath -ErrorAction SilentlyContinue).VersionInfo.ProductVersion
            } else { "" }

            $foundList.Add([PSCustomObject]@{
                Id          = $entry.Id
                FullName    = if ($match) { $match.PackageFullName } else { $entry.Id }
                Name        = $entry.Name
                Icon        = $entry.Icon
                LogoPath    = $logoPath
                ExePath     = if ($edgeOnDisk) { $edgeExePath } else { $null }
                Safe        = $entry.Safe
                Level       = $lvl
                Description = $entry.Desc
                Version     = $ver
                IsOneDrive  = $false
            })
        }
    }

    # Microsoft OneDrive Algılama (Yalnızca bilgisayarda fiziksel olarak kuruluysa listeye dahil edilir!)
    $oneDriveExe = @(
        "$env:LOCALAPPDATA\Microsoft\OneDrive\OneDrive.exe",
        "$env:ProgramFiles\Microsoft OneDrive\OneDrive.exe",
        "${env:ProgramFiles(x86)}\Microsoft OneDrive\OneDrive.exe"
    ) | Where-Object { Test-Path -LiteralPath $_ -ErrorAction SilentlyContinue } | Select-Object -First 1

    if (-not $oneDriveExe) {
        $odProc = Get-Process OneDrive -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($odProc -and $odProc.Path -and (Test-Path -LiteralPath $odProc.Path -ErrorAction SilentlyContinue)) {
            $oneDriveExe = $odProc.Path
        }
    }

    if ($oneDriveExe) {
        $odVer = (Get-Item -LiteralPath $oneDriveExe -ErrorAction SilentlyContinue).VersionInfo.FileVersion
        if (-not $odVer) { $odVer = "Yerleşik" }
        $foundList.Add([PSCustomObject]@{
            Id          = "Microsoft.OneDrive"
            FullName    = $oneDriveExe
            Name        = "Microsoft OneDrive"
            Icon        = "☁️"
            LogoPath    = $null
            ExePath     = $oneDriveExe
            Safe        = $true
            Description = "Bulut depolama ve arka plan senkronizasyonu"
            Version     = $odVer
            IsOneDrive  = $true
        })
    }

    if ($progBloatware) { $progBloatware.Visibility = [System.Windows.Visibility]::Collapsed }
    if ($lblBloatwareCountBadge) { $lblBloatwareCountBadge.Text = "$($foundList.Count) Uygulama Bulundu" }

    if ($foundList.Count -eq 0) {
        $emptyTxt = New-Object System.Windows.Controls.TextBlock
        $emptyTxt.Text = "✨ Tebrikler! Sisteminizde kurulu herhangi bir gereksiz yerleşik bloatware uygulaması bulunamadı."
        $emptyTxt.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
        $emptyTxt.FontSize = 13
        $emptyTxt.FontWeight = [System.Windows.FontWeights]::SemiBold
        $emptyTxt.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $emptyTxt.Margin = [System.Windows.Thickness]::new(0, 60, 0, 0)
        $pnlBloatwareList.Children.Add($emptyTxt) | Out-Null
        return
    }

    foreach ($app in $foundList) {
        $card = New-Object System.Windows.Controls.Border
        $card.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#131724")
        $card.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2438")
        $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $card.Padding = [System.Windows.Thickness]::new(14, 10, 14, 10)
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 0, 8)

        $dock = New-Object System.Windows.Controls.DockPanel
        $dock.LastChildFill = $true

        # Sağ Panel: Rozet ve Kaldır Butonu
        $pnlRight = New-Object System.Windows.Controls.StackPanel
        $pnlRight.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $pnlRight.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [System.Windows.Controls.DockPanel]::SetDock($pnlRight, [System.Windows.Controls.Dock]::Right)

        # Kategori Rozeti
        $bdrBadge = New-Object System.Windows.Controls.Border
        $bdrBadge.CornerRadius = [System.Windows.CornerRadius]::new(6)
        $bdrBadge.Padding = [System.Windows.Thickness]::new(8, 3, 8, 3)
        $bdrBadge.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
        $bdrBadge.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $txtBadge = New-Object System.Windows.Controls.TextBlock
        $txtBadge.FontSize = 10
        $txtBadge.FontWeight = [System.Windows.FontWeights]::Bold

        if ($app.Level -eq "Critical") {
            $bdrBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#450A0A")
            $txtBadge.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
            $txtBadge.Text = "🛑 Kritik Bileşen"
        } elseif ($app.Safe) {
            $bdrBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#062E25")
            $txtBadge.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            $txtBadge.Text = "✓ %100 Güvenli"
        } else {
            $bdrBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#352410")
            $txtBadge.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
            $txtBadge.Text = "⚠️ Sistem Aracı"
        }
        $bdrBadge.Child = $txtBadge
        $pnlRight.Children.Add($bdrBadge) | Out-Null

        # Tekli Kaldır Butonu
        $btnDel = New-Object System.Windows.Controls.Button
        $btnDel.Content = "🗑️ Kaldır"
        $btnDel.Style = $window.FindResource("ActionCardBtn")
        $btnDel.Width = 85
        $btnDel.Height = 28
        $btnDel.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $btnDel.Tag = $app

        $capturedApp = $app
        $capturedCard = $card
        $capturedBtn = $btnDel
        $btnDel.Add_Click({
            param($sender, $e)
            $thisBtn = if ($this) { $this } else { $capturedBtn }
            $targetApp = $capturedApp
            $targetCard = $capturedCard

            if ($targetApp.Level -eq "Critical") {
                $ans = [System.Windows.MessageBox]::Show($window, "'$($targetApp.Name)' kritik bir Windows sistem bileşenidir.`n`nKaldırılması durumunda sistem özellikleri veya mağaza bağımlılıkları etkilenebilir.`n`nYine de bu bileşeni kaldırmak istediğinizden emin misiniz?", "Kritik Sistem Bileşeni Uyarısı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
                if ($ans -ne [System.Windows.MessageBoxResult]::Yes) { return }
            }
            if (-not $targetApp) { return }

            $warnMsg = if ($targetApp.IsOneDrive) {
                "'Microsoft OneDrive' uygulamasını, arka plan servislerini ve Dosya Gezgini sol menü simgesini kalıcı olarak kaldırmak istiyor musunuz?`n`n(Kişisel dosyalarınız silinmez, yalnızca program ve sistem kalıntıları temizlenir.)"
            } elseif (-not $targetApp.Safe) {
                "DİKKAT: '$($targetApp.Name)' temel bir Windows sistem aracıdır.`n`nBu uygulamayı yine de tamamen kaldırmak istiyor musunuz?`n(İleride Microsoft Store üzerinden dilediğiniz zaman tekrar yükleyebilirsiniz.)"
            } else {
                "'$($targetApp.Name)' uygulamasını ve tüm önbellek kalıntılarını sistemden kalıcı olarak kaldırmak istiyor musunuz?"
            }
            $ans = [System.Windows.MessageBox]::Show($window, $warnMsg, "Uygulama Kaldırma Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
            if ($ans -eq [System.Windows.MessageBoxResult]::Yes) {
                if ($thisBtn) {
                    $thisBtn.IsEnabled = $false
                    $thisBtn.Content = "Siliniyor..."
                }
                $ok = if ($targetApp.IsOneDrive) {
                    Remove-OneDriveClean
                } elseif ($targetApp.Id -like "*Edge*") {
                    Remove-MicrosoftEdgeClean
                } else {
                    Remove-SingleAppxPackageClean $targetApp.Id $targetApp.Name
                }
                if ($ok) {
                    if ($pnlBloatwareList -and $targetCard) {
                        $pnlBloatwareList.Children.Remove($targetCard)
                    }
                    $remCount = if ($pnlBloatwareList) { $pnlBloatwareList.Children.Count } else { 0 }
                    if ($lblBloatwareCountBadge) { $lblBloatwareCountBadge.Text = "$remCount Uygulama Bulundu" }
                    if ($lblBloatwareStatus) { $lblBloatwareStatus.Text = "✓ '$($targetApp.Name)' başarıyla ve kalıntı bırakmadan kaldırıldı." }
                } else {
                    if ($thisBtn) {
                        $thisBtn.IsEnabled = $true
                        $thisBtn.Content = "🗑️ Kaldır"
                    }
                    [System.Windows.MessageBox]::Show($window, "Uygulama kaldırılırken bir hata oluştu.", "Hata", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
                }
            }
        }.GetNewClosure())

        $pnlRight.Children.Add($btnDel) | Out-Null
        $dock.Children.Add($pnlRight) | Out-Null

        # Sol Panel: CheckBox + İkon + İsim + Açıklama
        $pnlLeft = New-Object System.Windows.Controls.StackPanel
        $pnlLeft.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $pnlLeft.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $chk = New-Object System.Windows.Controls.CheckBox
        $chk.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $chk.Margin = [System.Windows.Thickness]::new(0, 0, 14, 0)
        $chk.Tag = $app
        $chk.IsChecked = $false
        $pnlLeft.Children.Add($chk) | Out-Null

        # İkon Kutusu (Orijinal Fluent PNG Simgesi veya Yedek Glif)
        $bdrIcon = New-Object System.Windows.Controls.Border
        $bdrIcon.Width = 36
        $bdrIcon.Height = 36
        $bdrIcon.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $bdrIcon.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1C2337")
        $bdrIcon.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
        $bdrIcon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $iconElement = $null
        if ($app.LogoPath -and (Test-Path $app.LogoPath -ErrorAction SilentlyContinue)) {
            try {
                $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
                $bmp.BeginInit()
                $bmp.UriSource = [System.Uri]::new($app.LogoPath)
                $bmp.DecodePixelWidth = 28
                $bmp.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $bmp.EndInit()
                $bmp.Freeze()

                $img = New-Object System.Windows.Controls.Image
                $img.Source = $bmp
                $img.Width = 26
                $img.Height = 26
                $img.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
                $img.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                $iconElement = $img
            } catch {
                $iconElement = $null
            }
        } elseif ($app.IsOneDrive -and $app.ExePath -and (Test-Path -LiteralPath $app.ExePath -ErrorAction SilentlyContinue)) {
            try {
                $icon = [System.Drawing.Icon]::ExtractAssociatedIcon($app.ExePath)
                if ($icon) {
                    $hIcon = $icon.Handle
                    $bmpSource = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
                        $hIcon,
                        [System.Windows.Int32Rect]::Empty,
                        [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
                    )
                    $bmpSource.Freeze()
                    $img = New-Object System.Windows.Controls.Image
                    $img.Source = $bmpSource
                    $img.Width = 26
                    $img.Height = 26
                    $img.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
                    $img.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                    $iconElement = $img
                }
            } catch {
                $iconElement = $null
            }
        }

        if (-not $iconElement) {
            $txtIcon = New-Object System.Windows.Controls.TextBlock
            $txtIcon.Text = $app.Icon
            $txtIcon.FontSize = 18
            $txtIcon.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
            $txtIcon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
            $iconElement = $txtIcon
        }

        $bdrIcon.Child = $iconElement
        $pnlLeft.Children.Add($bdrIcon) | Out-Null

        # Yazı Alanı
        $infoStack = New-Object System.Windows.Controls.StackPanel
        $infoStack.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $txtName = New-Object System.Windows.Controls.TextBlock
        $txtName.Text = $app.Name
        $txtName.FontSize = 13
        $txtName.FontWeight = [System.Windows.FontWeights]::Bold
        $txtName.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
        $infoStack.Children.Add($txtName) | Out-Null

        $txtDesc = New-Object System.Windows.Controls.TextBlock
        $txtDesc.Text = "$($app.Description) • $($app.Id) (v$($app.Version))"
        $txtDesc.FontSize = 11
        $txtDesc.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
        $txtDesc.Margin = [System.Windows.Thickness]::new(0, 2, 0, 0)
        $infoStack.Children.Add($txtDesc) | Out-Null

        $pnlLeft.Children.Add($infoStack) | Out-Null
        $dock.Children.Add($pnlLeft) | Out-Null
        $card.Child = $dock

        $pnlBloatwareList.Children.Add($card) | Out-Null
    }
}

$script:isUpdatingCtxUI = $false

# ------------------------------------------------------------------------------
# Sağ Tık (Bağlam Menüsü) Yöneticisi Mantığı
# ------------------------------------------------------------------------------
function Set-ContextMenuShortcut([string]$key, [bool]$turnOn) {
    try {
        switch ($key) {
            "TerminalAdmin" {
                $paths = @("Software\Classes\Directory\Background\shell\TemizWinTerminalAdmin", "Software\Classes\Directory\shell\TemizWinTerminalAdmin")
                if ($turnOn) {
                    foreach ($p in $paths) {
                        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($p)
                        $k.SetValue("", "Terminali Yönetici Olarak Aç")
                        $k.SetValue("Icon", "powershell.exe")
                        $k.SetValue("HasLUAShield", "")
                        $c = $k.CreateSubKey("command")
                        $c.SetValue("", 'powershell.exe -NoExit -Command "Set-Location ''%V''"')
                        $c.Close()
                        $k.Close()
                    }
                    Write-CmdLog "SAĞ TIK" "Terminali Yönetici Olarak Aç kısayolu eklendi" "Green"
                } else {
                    foreach ($p in $paths) {
                        [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($p, $false)
                    }
                    Write-CmdLog "SAĞ TIK" "Terminali Yönetici Olarak Aç kısayolu kaldırıldı" "Yellow"
                }
            }
            "TakeOwnership" {
                $paths = @("Software\Classes\*\shell\TemizWinTakeOwnership", "Software\Classes\Directory\shell\TemizWinTakeOwnership")
                if ($turnOn) {
                    foreach ($p in $paths) {
                        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($p)
                        $k.SetValue("", "Sahipliği Al (Take Ownership)")
                        $k.SetValue("Icon", "imageres.dll,-78")
                        $k.SetValue("HasLUAShield", "")
                        $c = $k.CreateSubKey("command")
                        $c.SetValue("", 'powershell.exe -WindowStyle Hidden -Command "Start-Process cmd -ArgumentList ''/c takeown /f """"%1"""" /r /d y & icacls """"%1"""" /grant administrators:F /t /c /l /q'' -Verb RunAs"')
                        $c.Close()
                        $k.Close()
                    }
                    Write-CmdLog "SAĞ TIK" "Sahipliği Al kısayolu eklendi" "Green"
                } else {
                    foreach ($p in $paths) {
                        [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($p, $false)
                    }
                    Write-CmdLog "SAĞ TIK" "Sahipliği Al kısayolu kaldırıldı" "Yellow"
                }
            }
            "OpenNotepad" {
                $p = "Software\Classes\*\shell\TemizWinOpenNotepad"
                if ($turnOn) {
                    $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($p)
                    $k.SetValue("", "Not Defteri ile Aç")
                    $k.SetValue("Icon", "notepad.exe")
                    $c = $k.CreateSubKey("command")
                    $c.SetValue("", 'notepad.exe "%1"')
                    $c.Close()
                    $k.Close()
                    Write-CmdLog "SAĞ TIK" "Not Defteri ile Aç kısayolu eklendi" "Green"
                } else {
                    [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($p, $false)
                    Write-CmdLog "SAĞ TIK" "Not Defteri ile Aç kısayolu kaldırıldı" "Yellow"
                }
            }
            "CopyPath" {
                $paths = @("Software\Classes\*\shell\TemizWinCopyPath", "Software\Classes\Directory\shell\TemizWinCopyPath")
                if ($turnOn) {
                    foreach ($p in $paths) {
                        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($p)
                        $k.SetValue("", "Dosya / Klasör Yolunu Kopyala")
                        $k.SetValue("Icon", "imageres.dll,-5302")
                        $c = $k.CreateSubKey("command")
                        $c.SetValue("", 'cmd.exe /c echo|set /p="%1"|clip')
                        $c.Close()
                        $k.Close()
                    }
                    Write-CmdLog "SAĞ TIK" "Yolu Kopyala kısayolu eklendi" "Green"
                } else {
                    foreach ($p in $paths) {
                        [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($p, $false)
                    }
                    Write-CmdLog "SAĞ TIK" "Yolu Kopyala kısayolu kaldırıldı" "Yellow"
                }
            }
            "VirusTotal" {
                $p = "Software\Classes\*\shell\TemizWinVirusTotal"
                if ($turnOn) {
                    $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($p)
                    $k.SetValue("", "VirusTotal ile Tara")
                    $k.SetValue("Icon", "imageres.dll,-102")
                    $c = $k.CreateSubKey("command")
                    $c.SetValue("", 'powershell.exe -WindowStyle Hidden -NoProfile -Command "try { $h = (Get-FileHash -Algorithm SHA256 -LiteralPath ''%1'' -ErrorAction Stop).Hash; Start-Process (''https://www.virustotal.com/gui/file/'' + $h) } catch {}"')
                    $c.Close()
                    $k.Close()
                    Write-CmdLog "SAĞ TIK" "VirusTotal ile Tara kısayolu eklendi" "Green"
                } else {
                    [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($p, $false)
                    Write-CmdLog "SAĞ TIK" "VirusTotal ile Tara kısayolu kaldırıldı" "Yellow"
                }
            }
        }
        Broadcast-ShellRefresh
        if ($lblContextMenuStatus) {
            $lblContextMenuStatus.Text = "✓ Sağ tık menüsü güncellendi ve masaüstü kabuğu yenilendi."
        }
    } catch {
        if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "Hata: $($_.Exception.Message)" }
    }
}

function Add-CustomContextMenuItem([string]$name, [string]$exePath, [int]$targetIndex) {
    try {
        $targetPath = switch ($targetIndex) {
            0 { "Software\Classes\*\shell" }
            1 { "Software\Classes\Directory\shell" }
            2 { "Software\Classes\Directory\Background\shell" }
            default { "Software\Classes\*\shell" }
        }
        $safeName = [System.Text.RegularExpressions.Regex]::Replace($name, '[^a-zA-Z0-9_]', '')
        if (-not $safeName) { $safeName = "App" }
        $keyPath = "$targetPath\TemizWin_App_$safeName"

        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($keyPath)
        $k.SetValue("", $name)
        $k.SetValue("Icon", $exePath)
        $k.SetValue("TemizWinManaged", 1, [Microsoft.Win32.RegistryValueKind]::DWord)
        $cmd = $k.CreateSubKey("command")
        if ($targetIndex -eq 2) {
            $cmd.SetValue("", "`"$exePath`"")
        } else {
            $cmd.SetValue("", "`"$exePath`" `"%1`"")
        }
        $cmd.Close()
        $k.Close()

        Broadcast-ShellRefresh
        Write-CmdLog "SAĞ TIK" "'$name' uygulaması sağ tık menüsüne eklendi ($exePath)" "Green"
        if ($lblContextMenuStatus) {
            $lblContextMenuStatus.Text = "✓ '$name' sağ tık menüsüne başarıyla eklendi!"
        }
        return $true
    } catch {
        if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "Hata: $($_.Exception.Message)" }
        return $false
    }
}

function Remove-CustomContextMenuItem([string]$regSubKey) {
    try {
        [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($regSubKey, $false)
        Broadcast-ShellRefresh
        Write-CmdLog "SAĞ TIK" "'$regSubKey' sağ tık menüsünden tamamen silindi" "Yellow"
        if ($lblContextMenuStatus) {
            $lblContextMenuStatus.Text = "✓ Seçilen uygulama sağ tık menüsünden kaldırıldı."
        }
        Refresh-ContextMenuList
    } catch {
        if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "Hata: $($_.Exception.Message)" }
    }
}

function Toggle-ContextMenuItem([PSCustomObject]$item) {
    try {
        $parentPath = $item.ParentPath
        $curKey = $item.KeyName
        $isCurrentlyEnabled = $item.IsEnabled

        if ($item.IsCustom) {
            # 1. TemizWin Özel Eklenen Öğe (HKCU:\Software\Classes\{Target}\shell\{Key})
            $fullSubKey = "$($item.ParentSubKey)\$curKey"
            if ($isCurrentlyEnabled) {
                # Devre Dışı Bırak: LegacyDisable + ProgrammaticAccessOnly + command.disabled
                $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($fullSubKey)
                if ($k) {
                    $k.SetValue("LegacyDisable", "")
                    $k.SetValue("ProgrammaticAccessOnly", "")
                    $k.Close()
                }
                if (Test-Path -LiteralPath "HKCU:\$fullSubKey\command") {
                    Rename-Item -LiteralPath "HKCU:\$fullSubKey\command" -NewName "command.disabled" -ErrorAction SilentlyContinue
                }
                $item.IsEnabled = $false
            } else {
                # Etkinleştir:
                $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($fullSubKey, $true)
                if ($k) {
                    $k.DeleteValue("LegacyDisable", $false)
                    $k.DeleteValue("ProgrammaticAccessOnly", $false)
                    $k.Close()
                }
                if (Test-Path -LiteralPath "HKCU:\$fullSubKey\command.disabled") {
                    Rename-Item -LiteralPath "HKCU:\$fullSubKey\command.disabled" -NewName "command" -ErrorAction SilentlyContinue
                }
                $item.IsEnabled = $true
            }
        } elseif ($item.Type -eq "Kabuk Menü Öğesi") {
            # 2. Standart Shell Verbleri (*\shell, Directory\shell, Background\shell, AllFilesystemObjects\shell, Folder\shell)
            $hive = $item.Hive
            $relSubKey = $item.SubKey
            $targetPath = "$parentPath\$curKey"
            $targetVerb = if ($item.BaseKeyName) { $item.BaseKeyName } else { ($item.KeyName -replace '\.disabled$', '') }
            $relScope = $item.RelScope

            if ($isCurrentlyEnabled) {
                # Devre Dışı Bırak: Asla .disabled adlı anahtar üretme! Yalnızca orijinal verbe LegacyDisable / ProgrammaticAccessOnly koy.
                if ($hive -eq "HKLM") {
                    try {
                        $kLM = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey("SOFTWARE\Classes\$relScope\shell\$targetVerb")
                        if ($kLM) {
                            $kLM.SetValue("LegacyDisable", "")
                            $kLM.SetValue("ProgrammaticAccessOnly", "")
                            $kLM.Close()
                        }
                    } catch {}
                    $hklmCmd = "HKLM:\SOFTWARE\Classes\$relScope\shell\$targetVerb\command"
                    if (Test-Path -LiteralPath $hklmCmd) {
                        Rename-Item -LiteralPath $hklmCmd -NewName "command.disabled" -ErrorAction SilentlyContinue
                    }
                    try { [Microsoft.Win32.Registry]::LocalMachine.DeleteSubKeyTree("SOFTWARE\Classes\$relScope\shell\$targetVerb.disabled", $false) } catch {}
                }

                # HKCU override oluştur (Windows Explorer HKCU'yu öncelikli okur)
                try {
                    $kCU = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey("Software\Classes\$relScope\shell\$targetVerb")
                    if ($kCU) {
                        $kCU.SetValue("LegacyDisable", "")
                        $kCU.SetValue("ProgrammaticAccessOnly", "")
                        $kCU.Close()
                    }
                } catch {}
                $hkcuCmd = "HKCU:\Software\Classes\$relScope\shell\$targetVerb\command"
                if (Test-Path -LiteralPath $hkcuCmd) {
                    Rename-Item -LiteralPath $hkcuCmd -NewName "command.disabled" -ErrorAction SilentlyContinue
                }
                try { [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree("Software\Classes\$relScope\shell\$targetVerb.disabled", $false) } catch {}

                if (Test-Path -LiteralPath "$targetPath\command") {
                    Rename-Item -LiteralPath "$targetPath\command" -NewName "command.disabled" -ErrorAction SilentlyContinue
                }

                $item.IsEnabled = $false
            } else {
                # Etkinleştir:
                if ($hive -eq "HKLM") {
                    try {
                        $kLM = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SOFTWARE\Classes\$relScope\shell\$targetVerb", $true)
                        if ($kLM) {
                            $kLM.DeleteValue("LegacyDisable", $false)
                            $kLM.DeleteValue("ProgrammaticAccessOnly", $false)
                            $kLM.Close()
                        }
                    } catch {}
                    $hklmDisCmd = "HKLM:\SOFTWARE\Classes\$relScope\shell\$targetVerb\command.disabled"
                    if (Test-Path -LiteralPath $hklmDisCmd) {
                        Rename-Item -LiteralPath $hklmDisCmd -NewName "command" -ErrorAction SilentlyContinue
                    }
                    try { [Microsoft.Win32.Registry]::LocalMachine.DeleteSubKeyTree("SOFTWARE\Classes\$relScope\shell\$targetVerb.disabled", $false) } catch {}
                }

                # HKCU override'ları temizle
                try {
                    [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree("Software\Classes\$relScope\shell\$targetVerb", $false)
                } catch {}
                try {
                    [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree("Software\Classes\$relScope\shell\$targetVerb.disabled", $false)
                } catch {}

                if (Test-Path -LiteralPath "$targetPath\command.disabled") {
                    Rename-Item -LiteralPath "$targetPath\command.disabled" -NewName "command" -ErrorAction SilentlyContinue
                }

                $item.IsEnabled = $true
            }
        } else {
            # 3. Shellex ContextMenuHandlers (COM Uzantıları)
            $clsid = $item.CLSID
            if ($isCurrentlyEnabled) {
                # Devre Dışı Bırak:
                $disKey = "$curKey.disabled"
                if (-not ($curKey -like "*.disabled")) {
                    if (Test-Path -LiteralPath "$parentPath\$disKey") {
                        Remove-Item -LiteralPath "$parentPath\$disKey" -Recurse -Force -ErrorAction SilentlyContinue
                    }
                    Rename-Item -LiteralPath "$parentPath\$curKey" -NewName $disKey -ErrorAction SilentlyContinue
                    $item.KeyName = $disKey
                }
                if ($clsid) {
                    try {
                        $blkCU = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey("Software\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked")
                        if ($blkCU) { $blkCU.SetValue($clsid, ""); $blkCU.Close() }
                    } catch {}
                    try {
                        $blkLM = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey("SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked")
                        if ($blkLM) { $blkLM.SetValue($clsid, ""); $blkLM.Close() }
                    } catch {}
                }
                $item.IsEnabled = $false
            } else {
                # Etkinleştir:
                $origName = $curKey -replace '\.disabled$', ''
                if ($curKey -like "*.disabled") {
                    if (Test-Path -LiteralPath "$parentPath\$origName") {
                        Remove-Item -LiteralPath "$parentPath\$curKey" -Recurse -Force -ErrorAction SilentlyContinue
                    } else {
                        Rename-Item -LiteralPath "$parentPath\$curKey" -NewName $origName -ErrorAction SilentlyContinue
                    }
                    $item.KeyName = $origName
                }
                if ($clsid) {
                    try {
                        $blkCU = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked", $true)
                        if ($blkCU) { $blkCU.DeleteValue($clsid, $false); $blkCU.Close() }
                    } catch {}
                    try {
                        $blkLM = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked", $true)
                        if ($blkLM) { $blkLM.DeleteValue($clsid, $false); $blkLM.Close() }
                    } catch {}
                }
                $item.IsEnabled = $true
            }
        }

        Broadcast-ShellRefresh
        $statusStr = if ($item.IsEnabled) { "etkinleştirildi" } else { "devre dışı bırakıldı" }
        Write-CmdLog "SAĞ TIK" "'$($item.DisplayName)' $statusStr" "Cyan"
        if ($lblContextMenuStatus) {
            $lblContextMenuStatus.Text = "✓ '$($item.DisplayName)' $statusStr. Sağ tık menüsünde anında görmek için '⚡ Gezgini Yeniden Başlat' butonuna tıklayın."
        }
        return $true
    } catch {
        Write-CmdLog "HATA" "Sağ tık ayarı değiştirilemedi: $($_.Exception.Message)" "Red"
        if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "Hata: $($_.Exception.Message)" }
        return $false
    }
}

function Get-FriendlyContextMenuName([string]$rawName, [string]$clsid) {
    # Bilinen Windows ve 3. parti bileşenler için temiz Türkçe sözlük
    $dict = @{
        "{90AA3A4E-1CBA-4233-B8BB-535773D48449}" = "Görev Çubuğuna Sabitle (Taskband Pin)"
        "{a2a9545d-a0c2-42b4-9708-a0b2badd77c8}" = "Başlat Menüsüne Sabitle (Start Menu Pin)"
        "{596AB062-B4D2-4215-9F74-E9109B0A8153}" = "Önceki Sürümler (Previous Versions)"
        "{474C98EE-CF3D-41f5-80E3-4AAB0AB04301}" = "Çevrimdışı Dosyalar (Offline Files)"
        "{3D1975AF-48C6-4f8e-A182-BE0E08FA86A9}" = "NVIDIA Denetim Masası"
        "{D969A300-E7FF-11d0-A93B-00A0C90F2719}" = "Yeni Menüsü (New Menu Handler)"
        "{09A47860-11B0-4DA5-AFA5-26D86198A780}" = "Microsoft Defender ile Tara"
        "{09799AFB-AD67-11d1-ABCD-00C04FC30936}" = "Birlikte Aç (Open With)"
        "{A470F8CF-A1E8-4f65-8335-227475AA5C46}" = "Dosya Şifreleme Menüsü"
        "{f81e9010-6ea4-11ce-a7ff-00aa003ca9f6}" = "Windows Paylaşımı (Sharing)"
        "{E61BF828-5E63-4287-BEF1-60B1A4FDE0E3}" = "Çalışma Klasörleri (WorkFolders)"
        "{D6791A63-E7E2-4fee-BF52-5DED8E86E9B8}" = "BitLocker Sürücü Şifreleme"
        "{fbeb8a05-beee-4442-804e-409d6c4515e9}" = "Sürücü Araçları"
        "EPP"                                     = "Microsoft Defender ile Tara"
        "Sharing"                                 = "Windows Paylaşımı (Sharing)"
        "ModernSharing"                           = "Modern Paylaşım Menüsü"
        "New"                                     = "Yeni Menüsü"
        "NvCplDesktopContext"                     = "NVIDIA Denetim Masası"
        "WorkFolders"                             = "Çalışma Klasörleri"
        "Open With"                               = "Birlikte Aç"
        "Open With EncryptionMenu"                = "Dosya Şifreleme Menüsü"
        "EncryptionMenu"                          = "Dosya Şifreleme Menüsü"
        "Library Location"                        = "Kitaplık Konumu"
        "RUShellExt"                              = "Remote Utilities Uzantısı"
        "CopyAsPathMenu"                          = "Yol Olarak Kopyala"
        "SendTo"                                  = "Gönder Menüsü (Send To)"
        "shred.bleachbit"                         = "BleachBit ile Güvenli Sil"
        "pintohomefile"                           = "Hızlı Erişime Sabitle (Dosya)"
        "pintohome"                               = "Hızlı Erişime Sabitle (Klasör)"
        "removeproperties"                        = "Özellikleri Kaldır"
        "AddToPlaylistVLC"                        = "VLC Oynatma Listesine Ekle"
        "PlayWithVLC"                             = "VLC ile Oynat"
        "git_gui"                                 = "Open Git GUI here"
        "git_shell"                               = "Open Git Bash here"
        "ShareX"                                  = "ShareX ile Yükle"
        "ModernProperties"                        = "Windows Modern Özellikler"
        "Offline Files"                           = "Çevrimdışı Dosyalar"
        "OfflineFilesLaunchSyncCenter"            = "Eşitleme Merkezi (Offline Files)"
        "LaunchWorkfoldersControl"                = "Çalışma Klasörleri Denetimi"
        "UpdateEncryptionSettingsWork"            = "Şifreleme Ayarlarını Güncelle"
        "UpdateEncryptionSettings"                = "Şifreleme Ayarlarını Güncelle"
    }

    $clean = $rawName -replace '\.disabled$', ''
    if ($dict.ContainsKey($clean)) { return $dict[$clean] }
    if ($clsid -and $dict.ContainsKey($clsid)) { return $dict[$clsid] }

    # Eğer GUID ise kayıt defterinden açıklamasını sorgula
    if ($clean -match '^\{[0-9a-fA-F\-]+\}$') {
        try {
            $regClsid = [Microsoft.Win32.Registry]::ClassesRoot.OpenSubKey("CLSID\$clean")
            if ($regClsid) {
                $desc = $regClsid.GetValue("")
                $regClsid.Close()
                if ($desc) { return "$desc ($clean)" }
            }
        } catch {}
    }

    return $clean
}

function Get-ContextMenuItems {
    $list = [System.Collections.Generic.List[PSCustomObject]]::new()

    # 1. TemizWin ile Eklenen Özel Uygulamalar
    $customScopes = @(
        @{ Scope = "Tüm Dosyalar (*)"; SubKey = "Software\Classes\*\shell" },
        @{ Scope = "Klasörler (Directory)"; SubKey = "Software\Classes\Directory\shell" },
        @{ Scope = "Masaüstü & Arka Plan"; SubKey = "Software\Classes\Directory\Background\shell" }
    )
    foreach ($cs in $customScopes) {
        $regKey = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($cs.SubKey)
        if ($regKey) {
            foreach ($subName in $regKey.GetSubKeyNames()) {
                if ($subName -like "TemizWin_App_*") {
                    $sub = $regKey.OpenSubKey($subName)
                    if ($sub) {
                        $title = $sub.GetValue("")
                        if (-not $title) { $title = $subName }
                        $cmdK = $sub.OpenSubKey("command")
                        $cmd = if ($cmdK) { $cmdK.GetValue("") } else { "" }
                        if ($cmdK) { $cmdK.Close() }
                        $isDis = ($sub.GetValue("LegacyDisable") -ne $null) -or ($sub.GetValue("ProgrammaticAccessOnly") -ne $null) -or (Test-Path -LiteralPath "HKCU:\$($cs.SubKey)\$subName\command.disabled")
                        $sub.Close()

                        $list.Add([PSCustomObject]@{
                            KeyName      = $subName
                            DisplayName  = $title
                            Command      = $cmd
                            Scope        = $cs.Scope
                            Type         = "TemizWin Özel"
                            IsCustom     = $true
                            CanDelete    = $true
                            ParentSubKey = $cs.SubKey
                            SubKeyPath   = "$($cs.SubKey)\$subName"
                            IsEnabled    = (-not $isDis)
                        })
                    }
                }
            }
            $regKey.Close()
        }
    }

    # 2. Sistem & 3. Parti Shell Komutları (*\shell, Directory\shell, Background\shell, AllFilesystemObjects\shell, Folder\shell)
    $shellTargets = @(
        @{ Scope = "Tüm Dosyalar"; Hive = "HKCU"; Path = "HKCU:\Software\Classes\*\shell"; SubKey = "Software\Classes\*\shell"; RelScope = "*" },
        @{ Scope = "Tüm Dosyalar"; Hive = "HKLM"; Path = "HKLM:\SOFTWARE\Classes\*\shell"; SubKey = "SOFTWARE\Classes\*\shell"; RelScope = "*" },
        @{ Scope = "Tüm Dosyalar (Genel)"; Hive = "HKLM"; Path = "HKLM:\SOFTWARE\Classes\AllFilesystemObjects\shell"; SubKey = "SOFTWARE\Classes\AllFilesystemObjects\shell"; RelScope = "AllFilesystemObjects" },
        @{ Scope = "Klasörler"; Hive = "HKCU"; Path = "HKCU:\Software\Classes\Directory\shell"; SubKey = "Software\Classes\Directory\shell"; RelScope = "Directory" },
        @{ Scope = "Klasörler"; Hive = "HKLM"; Path = "HKLM:\SOFTWARE\Classes\Directory\shell"; SubKey = "SOFTWARE\Classes\Directory\shell"; RelScope = "Directory" },
        @{ Scope = "Klasörler (Folder)"; Hive = "HKLM"; Path = "HKLM:\SOFTWARE\Classes\Folder\shell"; SubKey = "SOFTWARE\Classes\Folder\shell"; RelScope = "Folder" },
        @{ Scope = "Masaüstü & Arka Plan"; Hive = "HKCU"; Path = "HKCU:\Software\Classes\Directory\Background\shell"; SubKey = "Software\Classes\Directory\Background\shell"; RelScope = "Directory\Background" },
        @{ Scope = "Masaüstü & Arka Plan"; Hive = "HKLM"; Path = "HKLM:\SOFTWARE\Classes\Directory\Background\shell"; SubKey = "SOFTWARE\Classes\Directory\Background\shell"; RelScope = "Directory\Background" }
    )
    $ignoreKeys = @("find", "Open", "print", "runas", "Explore", "opennewwindow", "opennewprocess", "opennewtab", "cmd", "Powershell", "TemizWinTerminalAdmin", "TemizWinTakeOwnership", "TemizWinOpenNotepad", "TemizWinCopyPath", "TemizWinVirusTotal")

    foreach ($st in $shellTargets) {
        $root = if ($st.Hive -eq "HKCU") { [Microsoft.Win32.Registry]::CurrentUser } else { [Microsoft.Win32.Registry]::LocalMachine }
        $k = $root.OpenSubKey($st.SubKey)
        if ($k) {
            foreach ($subName in $k.GetSubKeyNames()) {
                if ($subName -like "TemizWin_*") { continue }
                $cleanSubName = $subName -replace '\.disabled$', ''
                if ($ignoreKeys -contains $cleanSubName) { continue }

                $existing = $list | Where-Object { ($_.KeyName -eq $subName -or $_.BaseKeyName -eq $cleanSubName) -and $_.Scope -eq $st.Scope }
                if ($existing) { continue }

                $sub = $k.OpenSubKey($subName)
                $title = ""
                $cmd = ""
                $hasCmdDisabled = $false
                $isDis = $false
                if ($sub) {
                    $title = $sub.GetValue("MUIVerb")
                    if (-not $title) { $title = $sub.GetValue("") }
                    if ($sub.GetValue("LegacyDisable") -ne $null -or $sub.GetValue("ProgrammaticAccessOnly") -ne $null) { $isDis = $true }
                    $c = $sub.OpenSubKey("command")
                    if ($c) { $cmd = $c.GetValue(""); $c.Close() }
                    $cDis = $sub.OpenSubKey("command.disabled")
                    if ($cDis) { $hasCmdDisabled = $true; if (-not $cmd) { $cmd = $cDis.GetValue("") }; $cDis.Close() }
                    $sub.Close()
                }

                # HKCU override durumunu da kontrol et
                $cuKey = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\$($st.RelScope)\shell\$cleanSubName")
                if (-not $cuKey) {
                    $cuKey = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\$($st.RelScope)\shell\$subName")
                }
                if ($cuKey) {
                    if ($cuKey.GetValue("LegacyDisable") -ne $null -or $cuKey.GetValue("ProgrammaticAccessOnly") -ne $null) {
                        $isDis = $true
                    }
                    $cuKey.Close()
                }

                if ($hasCmdDisabled -or ($subName -like "*.disabled")) { $isDis = $true }
                if (-not $title -or $title -like "@*") {
                    $title = Get-FriendlyContextMenuName $cleanSubName ""
                }
                $title = $title -replace '&', ''

                $list.Add([PSCustomObject]@{
                    KeyName      = $subName
                    BaseKeyName  = $cleanSubName
                    DisplayName  = $title
                    Command      = if ($cmd) { $cmd } else { "Komut: $cleanSubName" }
                    Scope        = $st.Scope
                    RelScope     = $st.RelScope
                    Hive         = $st.Hive
                    SubKey       = "$($st.SubKey)\$subName"
                    Type         = "Kabuk Menü Öğesi"
                    IsCustom     = $false
                    CanDelete    = $false
                    ParentPath   = $st.Path
                    IsEnabled    = (-not $isDis)
                })
            }
            $k.Close()
        }
    }

    # 3. ContextMenuHandlers (Shellex) Taraması
    $shellexTargets = @(
        @{ Scope = "Tüm Dosyalar"; Path = "HKLM:\SOFTWARE\Classes\*\shellex\ContextMenuHandlers"; SubKey = "SOFTWARE\Classes\*\shellex\ContextMenuHandlers" },
        @{ Scope = "Tüm Dosyalar (Genel)"; Path = "HKLM:\SOFTWARE\Classes\AllFilesystemObjects\shellex\ContextMenuHandlers"; SubKey = "SOFTWARE\Classes\AllFilesystemObjects\shellex\ContextMenuHandlers" },
        @{ Scope = "Klasörler"; Path = "HKLM:\SOFTWARE\Classes\Directory\shellex\ContextMenuHandlers"; SubKey = "SOFTWARE\Classes\Directory\shellex\ContextMenuHandlers" },
        @{ Scope = "Klasörler (Folder)"; Path = "HKLM:\SOFTWARE\Classes\Folder\shellex\ContextMenuHandlers"; SubKey = "SOFTWARE\Classes\Folder\shellex\ContextMenuHandlers" },
        @{ Scope = "Masaüstü & Arka Plan"; Path = "HKLM:\SOFTWARE\Classes\Directory\Background\shellex\ContextMenuHandlers"; SubKey = "SOFTWARE\Classes\Directory\Background\shellex\ContextMenuHandlers" }
    )
    $blockedKeyCU = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked")
    $blockedListCU = if ($blockedKeyCU) { $blockedKeyCU.GetValueNames(); $blockedKeyCU.Close() } else { @() }
    $blockedKeyLM = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked")
    $blockedListLM = if ($blockedKeyLM) { $blockedKeyLM.GetValueNames(); $blockedKeyLM.Close() } else { @() }
    $blockedList = @($blockedListCU + $blockedListLM) | Select-Object -Unique

    foreach ($sxt in $shellexTargets) {
        $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($sxt.SubKey)
        if ($k) {
            foreach ($subName in $k.GetSubKeyNames()) {
                $cleanSubName = $subName -replace '\.disabled$', ''
                $existing = $list | Where-Object { ($_.KeyName -eq $subName -or $_.KeyName -eq $cleanSubName) -and $_.Scope -eq $sxt.Scope }
                if ($existing) { continue }

                $sub = $k.OpenSubKey($subName)
                $clsid = ""
                if ($sub) {
                    $clsid = $sub.GetValue("")
                    $sub.Close()
                }
                if (-not $clsid -and $cleanSubName -match '^\{[0-9a-fA-F\-]+\}$') { $clsid = $cleanSubName }

                $isDis = ($subName -like "*.disabled") -or ($clsid -and $blockedList -contains $clsid)
                $friendly = Get-FriendlyContextMenuName $cleanSubName $clsid

                $list.Add([PSCustomObject]@{
                    KeyName      = $subName
                    DisplayName  = $friendly
                    Command      = if ($clsid) { "CLSID: $clsid" } else { "Shell Extension Handler" }
                    Scope        = $sxt.Scope
                    Type         = "Kabuk Uzantısı (Shellex)"
                    IsCustom     = $false
                    CanDelete    = $false
                    ParentPath   = $sxt.Path
                    IsEnabled    = (-not $isDis)
                    CLSID        = $clsid
                })
            }
            $k.Close()
        }
    }

    return $list
}

function Refresh-ContextMenuShortcutsState {
    $script:isUpdatingCtxUI = $true
    try {
        $termAdmin = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\Directory\Background\shell\TemizWinTerminalAdmin")
        if ($tglCtxTerminalAdmin) { $tglCtxTerminalAdmin.IsChecked = ($termAdmin -ne $null) }
        if ($termAdmin) { $termAdmin.Close() }

        $takeOwn = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\*\shell\TemizWinTakeOwnership")
        if ($tglCtxTakeOwnership) { $tglCtxTakeOwnership.IsChecked = ($takeOwn -ne $null) }
        if ($takeOwn) { $takeOwn.Close() }

        $openNote = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\*\shell\TemizWinOpenNotepad")
        if ($tglCtxOpenNotepad) { $tglCtxOpenNotepad.IsChecked = ($openNote -ne $null) }
        if ($openNote) { $openNote.Close() }

        $copyPath = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\*\shell\TemizWinCopyPath")
        if ($tglCtxCopyPath) { $tglCtxCopyPath.IsChecked = ($copyPath -ne $null) }
        if ($copyPath) { $copyPath.Close() }

        $vtScan = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\*\shell\TemizWinVirusTotal")
        if ($tglCtxVirusTotal) { $tglCtxVirusTotal.IsChecked = ($vtScan -ne $null) }
        if ($vtScan) { $vtScan.Close() }
    } finally {
        $script:isUpdatingCtxUI = $false
    }
}

$script:allContextMenuCards = [System.Collections.Generic.List[PSCustomObject]]::new()

function Update-ContextMenuBadgeCounts {
    if (-not $lblContextMenuBadge) { return }
    $totalCount = $script:allContextMenuCards.Count
    $activeCount = 0
    foreach ($c in $script:allContextMenuCards) {
        if ($c.Item.IsEnabled) { $activeCount++ }
    }
    $disabledCount = $totalCount - $activeCount
    $lblContextMenuBadge.Text = "Toplam: $totalCount Öğe ($activeCount Açık, $disabledCount Devre Dışı)"
}

function Filter-ContextMenuItems {
    $q = if ($txtSearchContextMenu) { $txtSearchContextMenu.Text.Trim().ToLowerInvariant() } else { "" }
    foreach ($entry in $script:allContextMenuCards) {
        $match = [string]::IsNullOrEmpty($q) -or 
                 $entry.Name.ToLowerInvariant().Contains($q) -or 
                 $entry.Scope.ToLowerInvariant().Contains($q) -or 
                 $entry.Command.ToLowerInvariant().Contains($q)
        $entry.Card.Visibility = if ($match) { 
            [System.Windows.Visibility]::Visible 
        } else { 
            [System.Windows.Visibility]::Collapsed 
        }
    }
}

function Refresh-ContextMenuList {
    if (-not $pnlContextMenuList) { return }
    $pnlContextMenuList.Children.Clear()
    $script:allContextMenuCards.Clear()

    $items = Get-ContextMenuItems
    $totalCount = $items.Count
    $activeCount = ($items | Where-Object { $_.IsEnabled }).Count
    $disabledCount = $totalCount - $activeCount

    if ($lblContextMenuBadge) {
        $lblContextMenuBadge.Text = "Toplam: $totalCount Öğe ($activeCount Açık, $disabledCount Devre Dışı)"
    }

    if ($totalCount -eq 0) {
        $emptyTb = New-Object System.Windows.Controls.TextBlock
        $emptyTb.Text = "Sistemde herhangi bir ek sağ tık menü öğesi bulunamadı."
        $emptyTb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        $emptyTb.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $emptyTb.Margin = [System.Windows.Thickness]::new(0, 30, 0, 30)
        $pnlContextMenuList.Children.Add($emptyTb) | Out-Null
        return
    }

    $styleBorder = New-Object System.Windows.Style([System.Windows.Controls.Border])
    $styleBorder.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Border]::CornerRadiusProperty, [System.Windows.CornerRadius]::new(6))))

    foreach ($item in $items) {
        $card = New-Object System.Windows.Controls.Border
        $card.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#131724")
        $card.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2438")
        $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $card.Padding = [System.Windows.Thickness]::new(12, 10, 12, 10)
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 0, 8)

        $dock = New-Object System.Windows.Controls.DockPanel
        $dock.LastChildFill = $true

        # Sağ Alan: Modern Toggle Switch, Durum Metni ve Varsa Sil Butonu
        $rightSp = New-Object System.Windows.Controls.StackPanel
        $rightSp.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $rightSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        [System.Windows.Controls.DockPanel]::SetDock($rightSp, [System.Windows.Controls.Dock]::Right)

        # Durum Metni (Açık / Devre Dışı)
        $lblState = New-Object System.Windows.Controls.TextBlock
        $lblState.FontSize = 11
        $lblState.FontWeight = [System.Windows.FontWeights]::SemiBold
        $lblState.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $lblState.Margin = [System.Windows.Thickness]::new(0, 0, 10, 0)
        $lblState.Text = if ($item.IsEnabled) { "Açık" } else { "Devre Dışı" }
        $lblState.Foreground = if ($item.IsEnabled) {
            [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
        } else {
            [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        }
        $rightSp.Children.Add($lblState) | Out-Null

        # Modern Toggle Switch (CheckBox)
        $tglItem = New-Object System.Windows.Controls.CheckBox
        $tglItem.Style = $window.FindResource("ModernToggleSwitch")
        $tglItem.IsChecked = [bool]$item.IsEnabled
        $tglItem.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $tglItem.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)
        $tglItem.Cursor = [System.Windows.Input.Cursors]::Hand

        $currentItem = $item
        $currentLblState = $lblState
        $isInternalToggle = $false

        $tglItem.Add_Click({
            param($s, $e)
            if ($isInternalToggle) { return }
            $res = Toggle-ContextMenuItem $currentItem
            if ($res) {
                $currentLblState.Text = if ($currentItem.IsEnabled) { "Açık" } else { "Devre Dışı" }
                $currentLblState.Foreground = if ($currentItem.IsEnabled) {
                    [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
                } else {
                    [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
                }
                Update-ContextMenuBadgeCounts
            } else {
                $isInternalToggle = $true
                $s.IsChecked = [bool]$currentItem.IsEnabled
                $isInternalToggle = $false
            }
        }.GetNewClosure())
        $rightSp.Children.Add($tglItem) | Out-Null

        # Eğer TemizWin ile eklenmişse "Kaldır/Sil" Butonu
        if ($item.CanDelete) {
            $btnDelete = New-Object System.Windows.Controls.Button
            $btnDelete.Content = "🗑️ Sil"
            $btnDelete.Padding = [System.Windows.Thickness]::new(10, 3, 10, 3)
            $btnDelete.Cursor = [System.Windows.Input.Cursors]::Hand
            $btnDelete.FontWeight = [System.Windows.FontWeights]::SemiBold
            $btnDelete.BorderThickness = [System.Windows.Thickness]::new(0)
            $btnDelete.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F87171")
            $btnDelete.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#3B1824")
            $btnDelete.Margin = [System.Windows.Thickness]::new(4, 0, 0, 0)
            $btnDelete.Resources.Add([System.Windows.Controls.Border], $styleBorder)

            $delKeyPath = $item.SubKeyPath
            $btnDelete.Add_Click({
                param($s, $e)
                $ans = [System.Windows.MessageBox]::Show("Bu özel sağ tık menü öğesini kalıcı olarak silmek istiyor musunuz?", "Öğeyi Sil", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
                if ($ans -eq [System.Windows.MessageBoxResult]::Yes) {
                    Remove-CustomContextMenuItem $delKeyPath
                }
            }.GetNewClosure())
            $rightSp.Children.Add($btnDelete) | Out-Null
        }

        $dock.Children.Add($rightSp) | Out-Null

        # Sol Alan: Başlık, Kapsam Rozeti, Tür ve Komut
        $leftSp = New-Object System.Windows.Controls.StackPanel
        $leftSp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        # Üst Satır: Başlık + Rozetler
        $titleWrap = New-Object System.Windows.Controls.StackPanel
        $titleWrap.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $titleWrap.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $titleTb = New-Object System.Windows.Controls.TextBlock
        $titleTb.Text = $item.DisplayName
        $titleTb.FontSize = 13
        $titleTb.FontWeight = [System.Windows.FontWeights]::Bold
        $titleTb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
        $titleTb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $titleWrap.Children.Add($titleTb) | Out-Null

        # Kapsam Rozeti
        $scopeBadge = New-Object System.Windows.Controls.Border
        $scopeBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E293B")
        $scopeBadge.CornerRadius = [System.Windows.CornerRadius]::new(4)
        $scopeBadge.Padding = [System.Windows.Thickness]::new(6, 2, 6, 2)
        $scopeBadge.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
        $scopeBadge.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $scopeText = New-Object System.Windows.Controls.TextBlock
        $scopeText.Text = $item.Scope
        $scopeText.FontSize = 10
        $scopeText.FontWeight = [System.Windows.FontWeights]::SemiBold
        $scopeText.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
        $scopeBadge.Child = $scopeText
        $titleWrap.Children.Add($scopeBadge) | Out-Null

        if ($item.IsCustom) {
            $customBadge = New-Object System.Windows.Controls.Border
            $customBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#064E3B")
            $customBadge.CornerRadius = [System.Windows.CornerRadius]::new(4)
            $customBadge.Padding = [System.Windows.Thickness]::new(6, 2, 6, 2)
            $customBadge.Margin = [System.Windows.Thickness]::new(6, 0, 0, 0)
            $customBadge.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

            $customText = New-Object System.Windows.Controls.TextBlock
            $customText.Text = "★ Özel Eklendi"
            $customText.FontSize = 10
            $customText.FontWeight = [System.Windows.FontWeights]::Bold
            $customText.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
            $customBadge.Child = $customText
            $titleWrap.Children.Add($customBadge) | Out-Null
        }

        $leftSp.Children.Add($titleWrap) | Out-Null

        # Alt Satır: Komut veya Açıklama
        $cmdTb = New-Object System.Windows.Controls.TextBlock
        $cmdTb.Text = "$($item.Type): $($item.Command)"
        $cmdTb.FontSize = 11
        $cmdTb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        $cmdTb.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
        $cmdTb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
        $leftSp.Children.Add($cmdTb) | Out-Null

        $dock.Children.Add($leftSp) | Out-Null
        $card.Child = $dock
        $pnlContextMenuList.Children.Add($card) | Out-Null

        $script:allContextMenuCards.Add([PSCustomObject]@{
            Card    = $card
            Item    = $item
            Name    = $item.DisplayName
            Scope   = $item.Scope
            Command = $item.Command
        })
    }

    Filter-ContextMenuItems
}

function Refresh-ContextMenuState {
    Refresh-ContextMenuShortcutsState
    Refresh-ContextMenuList
}

function Switch-View([string]$viewName) {
    $viewMain.Visibility    = [System.Windows.Visibility]::Collapsed
    $viewClean.Visibility   = [System.Windows.Visibility]::Collapsed
    $viewHealth.Visibility  = [System.Windows.Visibility]::Collapsed
    $viewUpdate.Visibility  = [System.Windows.Visibility]::Collapsed
    if ($viewStartup)     { $viewStartup.Visibility     = [System.Windows.Visibility]::Collapsed }
    if ($viewAnalyzer)    { $viewAnalyzer.Visibility    = [System.Windows.Visibility]::Collapsed }
    if ($viewBloatware)   { $viewBloatware.Visibility   = [System.Windows.Visibility]::Collapsed }
    if ($viewTweaks)      { $viewTweaks.Visibility      = [System.Windows.Visibility]::Collapsed }
    if ($viewContextMenu) { $viewContextMenu.Visibility = [System.Windows.Visibility]::Collapsed }
    if ($viewPerformance) { $viewPerformance.Visibility = [System.Windows.Visibility]::Collapsed }

    switch ($viewName) {
        "Main"     { $viewMain.Visibility     = [System.Windows.Visibility]::Visible }
        "Clean"    { $viewClean.Visibility    = [System.Windows.Visibility]::Visible }
        "Health"   {
            $viewHealth.Visibility   = [System.Windows.Visibility]::Visible
            Update-DnsDisplay
        }
        "Update"   { $viewUpdate.Visibility   = [System.Windows.Visibility]::Visible }
        "Startup"  {
            if ($viewStartup) {
                $viewStartup.Visibility = [System.Windows.Visibility]::Visible
                Refresh-StartupAppsList
            }
        }
        "Analyzer" {
            if ($viewAnalyzer) {
                $viewAnalyzer.Visibility = [System.Windows.Visibility]::Visible
                Update-AnalyzerLocationOptions
            }
        }
        "Bloatware" {
            if ($viewBloatware) {
                $viewBloatware.Visibility = [System.Windows.Visibility]::Visible
                Refresh-BloatwareList
            }
        }
        "Tweaks" {
            if ($viewTweaks) {
                $viewTweaks.Visibility = [System.Windows.Visibility]::Visible
                Refresh-TweaksState
            }
        }
        "ContextMenu" {
            if ($viewContextMenu) {
                $viewContextMenu.Visibility = [System.Windows.Visibility]::Visible
                Refresh-ContextMenuState
            }
        }
        "Performance" {
            if ($viewPerformance) {
                $viewPerformance.Visibility = [System.Windows.Visibility]::Visible
                Refresh-PerformanceState
            }
        }
    }
}

# ------------------------------------------------------------------------------
# 8. C: Sürücüsü, Açılış ve Hazırda Bekletme Bilgilerini Güncelleme
# ------------------------------------------------------------------------------
function Refresh-SystemStats {
    try {
        # C: Disk Alanı
        $driveC = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.Name -like "C:*" }
        if ($driveC) {
            $freeGB = [Math]::Round($driveC.AvailableFreeSpace / 1GB, 1)
            $lblFreeSpaceC.Text = "$freeGB GB"
        }

        # Açılış Programı Sayısı
        $startupCount = 0
        $regPaths = @("HKCU:\Software\Microsoft\Windows\CurrentVersion\Run", "HKLM:\Software\Microsoft\Windows\CurrentVersion\Run")
        foreach ($rp in $regPaths) {
            if (Test-Path $rp -ErrorAction SilentlyContinue) {
                $props = (Get-ItemProperty $rp -ErrorAction SilentlyContinue).PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' }
                if ($props) { $startupCount += $props.Count }
            }
        }
        $startupFolder = [Environment]::GetFolderPath('Startup')
        if (Test-Path $startupFolder -ErrorAction SilentlyContinue) {
            $startupCount += @(Get-ChildItem $startupFolder -File -ErrorAction SilentlyContinue).Count
        }
        $initialApps = Get-StartupAppsList
        $activeStartupCount = @($initialApps | Where-Object { $_.IsEnabled }).Count
        $lblStartupCount.Text = "$activeStartupCount program"

        # Hazırda Bekletme (Hibernate) Durumu (File::Exists & Registry)
        $isHib = [System.IO.File]::Exists("C:\hiberfil.sys")
        if (-not $isHib) {
            $regHib = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Power" -Name "HibernateEnabled" -ErrorAction SilentlyContinue).HibernateEnabled
            if ($regHib -eq 1) { $isHib = $true }
        }
        if ($isHib) {
            $lblHibernateStatus.Text = "AÇIK"
            $lblHibernateStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
        } else {
            $lblHibernateStatus.Text = "KAPALI"
            $lblHibernateStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
        }

        # Disk Sağlığı - Tüm bağlı fiziksel sürücülerin (SSD / HDD / NVMe) taranması ve listelenmesi
        $disks = @(Get-PhysicalDisk -ErrorAction SilentlyContinue)
        if ($disks.Count -gt 0) {
            $diskLines = foreach ($d in $disks) {
                "$($d.DeviceId): $($d.FriendlyName) ($($d.MediaType)) - Durum: $($d.HealthStatus) (İşletim: $($d.OperationalStatus))"
            }
            $lblDiskHealthInfo.Text = $diskLines -join "`r`n"
        } else {
            $wdisks = @(Get-CimInstance Win32_DiskDrive -ErrorAction SilentlyContinue)
            if ($wdisks.Count -gt 0) {
                $diskLines = foreach ($d in $wdisks) {
                    "$($d.Index): $($d.Model) - Durum: $($d.Status)"
                }
                $lblDiskHealthInfo.Text = $diskLines -join "`r`n"
            } else {
                $lblDiskHealthInfo.Text = "Disk donanım sağlığı: Normal (OK)"
            }
        }
        Update-DnsDisplay
    } catch {}
}

function Update-DnsDisplay {
    if (-not $lblCurrentDnsStatus) { return }
    try {
        $activeAdapter = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | Select-Object -First 1
        if (-not $activeAdapter) {
            $activeAdapter = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notlike '*Virtual*' -and $_.InterfaceDescription -notlike '*Loopback*' } | Select-Object -First 1
        }
        if (-not $activeAdapter) {
            $lblCurrentDnsStatus.Text = " [Aktif Ağ Yok]"
            $lblCurrentDnsStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
            return
        }

        $dnsObj = Get-DnsClientServerAddress -InterfaceIndex $activeAdapter.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue
        $dnsAddrs = if ($dnsObj) { [string[]]$dnsObj.ServerAddresses } else { @() }

        $isDhcpDns = $true
        try {
            $netshOut = (netsh interface ipv4 show dnsservers name="$($activeAdapter.Name)" 2>&1) -join " "
            if ($netshOut -match "Statically Configured|statik") {
                $isDhcpDns = $false
            }
        } catch {}

        if ($isDhcpDns -or $dnsAddrs.Count -eq 0) {
            $lblCurrentDnsStatus.Text = "Aktif: Otomatik DHCP ($($activeAdapter.Name))"
            $lblCurrentDnsStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#34D399")
            if ($cmbDnsProfiles) { $cmbDnsProfiles.SelectedIndex = 0 }
        } elseif ($dnsAddrs -contains "1.1.1.1") {
            $lblCurrentDnsStatus.Text = "Aktif: Cloudflare (1.1.1.1)"
            $lblCurrentDnsStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
            if ($cmbDnsProfiles) { $cmbDnsProfiles.SelectedIndex = 1 }
        } elseif ($dnsAddrs -contains "8.8.8.8") {
            $lblCurrentDnsStatus.Text = "Aktif: Google (8.8.8.8)"
            $lblCurrentDnsStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#818CF8")
            if ($cmbDnsProfiles) { $cmbDnsProfiles.SelectedIndex = 2 }
        } elseif ($dnsAddrs -contains "9.9.9.9") {
            $lblCurrentDnsStatus.Text = "Aktif: Quad9 (9.9.9.9)"
            $lblCurrentDnsStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#C084FC")
            if ($cmbDnsProfiles) { $cmbDnsProfiles.SelectedIndex = 3 }
        } else {
            $lblCurrentDnsStatus.Text = "Özel: $($dnsAddrs -join ', ')"
            $lblCurrentDnsStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
        }
    } catch {}
}

$script:cachedLicenseInfo = $null

function Get-WindowsLicenseInfo {
    try {
        $rawDli = cscript.exe //NoLogo "$env:windir\system32\slmgr.vbs" /dli 2>&1
        $rawXpr = (cscript.exe //NoLogo "$env:windir\system32\slmgr.vbs" /xpr 2>&1) -join " "

        $name = "Windows"
        $channel = "Bilinmiyor"
        $partialKey = ""
        $status = "Bilinmiyor"
        $isPermanent = $false
        $expireText = ""

        foreach ($line in $rawDli) {
            if ($line -match "(?:Ad|Name)\s*:\s*(.+)") { $name = $matches[1].Trim() }
            if ($line -match "(?:A.*klama|Description)\s*:\s*(.+)" -or ($line -match ":\s*(.+)" -and ($line -match "RETAIL|OEM|VOLUME|KMS|MAK"))) { 
                $desc = $matches[1].Trim()
                if ($desc -match "RETAIL") { $channel = "Retail (Dijital / Perakende)" }
                elseif ($desc -match "OEM") { $channel = "OEM (Anakarta Gömülü Lisans)" }
                elseif ($desc -match "VOLUME_KMS|KMS") { $channel = "Volume / KMS (Şirket / Geçici)" }
                elseif ($desc -match "VOLUME_MAK|MAK") { $channel = "Volume / MAK (Toplu Lisans)" }
                else { $channel = $desc }
            }
            if ($line -match "(?:K.*smi|Partial)\s*.*:\s*(.+)") { $partialKey = $matches[1].Trim() }
            if ($line -match "(?:Lisans\s+Durumu|License\s+Status)\s*:\s*(.+)") { $status = $matches[1].Trim() }
        }

        if ($rawXpr -match "kal.*c|permanently") {
            $isPermanent = $true
            $expireText = "Kalıcı Olarak Etkin"
        } elseif ($rawXpr -match "(\d{1,2}[\./]\d{1,2}[\./]\d{2,4})") {
            $expireText = "Bitiş: " + $matches[1]
        } else {
            $expireText = $rawXpr.Trim()
        }

        $badgeText = ""
        $badgeColor = "#10B981"
        if ($status -match "Lisansl|Licensed") {
            if ($isPermanent) {
                $badgeText = "✅ Lisanslı (Kalıcı)"
                $badgeColor = "#10B981"
            } else {
                $badgeText = "⚠️ Süreli Lisans"
                $badgeColor = "#F59E0B"
            }
        } else {
            $badgeText = "❌ Etkin Değil"
            $badgeColor = "#EF4444"
        }

        $osName = (Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue).Caption
        if (-not $osName) {
            $osName = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion" -ErrorAction SilentlyContinue).ProductName
        }
        if (-not $osName) { $osName = $name }
        $osName = ($osName -replace 'Microsoft\s*', '').Trim()

        return [PSCustomObject]@{
            OsName      = $osName
            Name        = $name
            Channel     = $channel
            PartialKey  = $partialKey
            Status      = $status
            IsPermanent = $isPermanent
            ExpireText  = $expireText
            BadgeText   = $badgeText
            BadgeColor  = $badgeColor
            Summary     = "Sürüm: $osName  •  Kanal: $channel  •  Durum: $expireText" + $(if ($partialKey) { "  •  Anahtar: *****-$partialKey" } else { "" })
        }
    } catch {
        return [PSCustomObject]@{
            OsName      = "Windows"
            Channel     = "Bilinmiyor"
            PartialKey  = ""
            BadgeText   = "Okunamadı"
            BadgeColor  = "#94A3B8"
            Summary     = "Lisans bilgisi alınamadı."
        }
    }
}

function Show-ModernLicenseDialog([System.Windows.Window]$ownerWin) {
    try {
        $info = Get-WindowsLicenseInfo

        $dialogXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="TemizWin - Windows Lisans Bilgileri"
        Width="500" SizeToContent="Height"
        WindowStartupLocation="CenterOwner"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        Topmost="True" ShowInTaskbar="False">
    <Border Background="#0F131F" BorderBrush="#1E2638" BorderThickness="1.5" CornerRadius="14" Padding="24">
        <Border.Effect>
            <DropShadowEffect Color="#000000" BlurRadius="25" ShadowDepth="6" Opacity="0.6"/>
        </Border.Effect>
        <StackPanel>
            <!-- Başlık Satırı -->
            <DockPanel Margin="0,0,0,16">
                <Border Background="#1E293B" Width="42" Height="42" CornerRadius="10" Margin="0,0,14,0" DockPanel.Dock="Left">
                    <TextBlock Text="🔑" FontSize="20" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <StackPanel VerticalAlignment="Center">
                    <TextBlock Text="Windows Lisans ve Etkinleştirme" FontSize="16" FontWeight="Bold" Foreground="#FFFFFF"/>
                    <TextBlock Text="Sistem lisans ayrıntıları ve ürün anahtarı bilgisi" FontSize="11" Foreground="#94A3B8"/>
                </StackPanel>
            </DockPanel>

            <!-- Lisans Detayları Tablosu -->
            <Border Background="#161B2B" BorderBrush="#1E2638" BorderThickness="1" CornerRadius="8" Padding="16,14" Margin="0,0,0,20">
                <StackPanel>
                    <!-- Satır 1: Sürüm -->
                    <DockPanel Margin="0,0,0,8">
                        <TextBlock Text="İşletim Sistemi" FontSize="12" Foreground="#94A3B8" Width="130"/>
                        <TextBlock x:Name="lblDlgOs" FontSize="12" FontWeight="SemiBold" Foreground="#FFFFFF" TextAlignment="Right"/>
                    </DockPanel>
                    <Separator Background="#1E2638" Margin="0,0,0,8"/>

                    <!-- Satır 2: Lisans Kanalı -->
                    <DockPanel Margin="0,0,0,8">
                        <TextBlock Text="Lisans Türü" FontSize="12" Foreground="#94A3B8" Width="130"/>
                        <TextBlock x:Name="lblDlgChannel" FontSize="12" FontWeight="SemiBold" Foreground="#38BDF8" TextAlignment="Right"/>
                    </DockPanel>
                    <Separator Background="#1E2638" Margin="0,0,0,8"/>

                    <!-- Satır 3: Durum -->
                    <DockPanel Margin="0,0,0,8">
                        <TextBlock Text="Etkinleştirme" FontSize="12" Foreground="#94A3B8" Width="130"/>
                        <TextBlock x:Name="lblDlgStatus" FontSize="12" FontWeight="Bold" TextAlignment="Right"/>
                    </DockPanel>
                    <Separator Background="#1E2638" Margin="0,0,0,8"/>

                    <!-- Satır 4: Ürün Anahtarı -->
                    <DockPanel>
                        <TextBlock Text="Kısmi Anahtar" FontSize="12" Foreground="#94A3B8" Width="130"/>
                        <TextBlock x:Name="lblDlgKey" FontSize="12" FontWeight="SemiBold" Foreground="#E2E8F0" TextAlignment="Right"/>
                    </DockPanel>
                </StackPanel>
            </Border>

            <!-- Kapat Butonu -->
            <Button x:Name="btnDlgClose" Content="Tamam" Height="38"
                    Background="#2563EB" Foreground="#FFFFFF" BorderThickness="0"
                    FontWeight="Bold" FontSize="13" Cursor="Hand" HorizontalAlignment="Right" Width="120">
                <Button.Resources>
                    <Style TargetType="Border">
                        <Setter Property="CornerRadius" Value="8"/>
                    </Style>
                </Button.Resources>
            </Button>
        </StackPanel>
    </Border>
</Window>
"@

        $reader = [System.Xml.XmlReader]::Create([System.IO.StringReader]::new($dialogXaml))
        $dlg = [System.Windows.Markup.XamlReader]::Load($reader)
        if ($ownerWin) { $dlg.Owner = $ownerWin }

        $lblDlgOs      = $dlg.FindName("lblDlgOs")
        $lblDlgChannel = $dlg.FindName("lblDlgChannel")
        $lblDlgStatus  = $dlg.FindName("lblDlgStatus")
        $lblDlgKey     = $dlg.FindName("lblDlgKey")
        $btnDlgClose   = $dlg.FindName("btnDlgClose")

        if ($lblDlgOs)      { $lblDlgOs.Text = $info.OsName }
        if ($lblDlgChannel) { $lblDlgChannel.Text = $info.Channel }
        if ($lblDlgStatus)  {
            $lblDlgStatus.Text = $info.BadgeText
            $lblDlgStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($info.BadgeColor)
        }
        if ($lblDlgKey) {
            $lblDlgKey.Text = if ($info.PartialKey) { "*****-" + $info.PartialKey } else { "Bulunamadı" }
        }

        if ($btnDlgClose) {
            $btnDlgClose.Add_Click({ $dlg.Close() })
        }

        $dlg.Add_MouseLeftButtonDown({
            if ($_.LeftButton -eq [System.Windows.Input.MouseButtonState]::Pressed) { $dlg.DragMove() }
        })

        $dlg.ShowDialog() | Out-Null
    } catch {
        $msg = "Windows Lisans Bilgileri:`n`n" +
               "İşletim Sistemi: $($info.OsName)`n" +
               "Lisans Türü: $($info.Channel)`n" +
               "Durum: $($info.BadgeText)`n" +
               "Anahtar: *****-$($info.PartialKey)"
        [System.Windows.MessageBox]::Show($ownerWin, $msg, "TemizWin - Lisans Bilgisi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
    }
}

# ------------------------------------------------------------------------------
# 9. Canlı Seçilen Temizlik Boyutunu Hesaplama (Event Driven)
# ------------------------------------------------------------------------------
function Update-LiveSelectedSize {
    [double]$selectedTotal = 0

    $map = @(
        @{ C = $chkTemp;        K = "Temp" },
        @{ C = $chkWinUpdate;   K = "WinUpdate" },
        @{ C = $chkRecycle;     K = "Recycle" },
        @{ C = $chkEventLogs;   K = "EventLogs" },
        @{ C = $chkDeliveryOpt; K = "DeliveryOpt" },
        @{ C = $chkWinOld;      K = "WinOld" },
        @{ C = $chkDriverStore; K = "DriverStore" },
        @{ C = $chkCrash;       K = "Crash" },
        @{ C = $chkThumbs;      K = "Thumbs" },
        @{ C = $chkPrefetch;    K = "Prefetch" },
        @{ C = $chkFont;        K = "Font" },
        @{ C = $chkDefender;    K = "Defender" },
        @{ C = $chkINetCache;   K = "INetCache" },
        @{ C = $chkChrome;      K = "Chrome" },
        @{ C = $chkEdge;        K = "Edge" },
        @{ C = $chkFirefox;     K = "Firefox" },
        @{ C = $chkOpera;       K = "Opera" },
        @{ C = $chkBrave;       K = "Brave" },
        @{ C = $chkApps;        K = "Apps" },
        @{ C = $chkAppNotion;   K = "AppNotion" },
        @{ C = $chkAppVSCode;   K = "AppVSCode" },
        @{ C = $chkAppPython;   K = "AppPython" },
        @{ C = $chkAppVlc;      K = "AppVlc" },
        @{ C = $chkTraceSystem; K = "TraceSystem" },
        @{ C = $chkTraceChrome; K = "TraceChrome" },
        @{ C = $chkTraceEdge;   K = "TraceEdge" },
        @{ C = $chkTraceBrave;  K = "TraceBrave" },
        @{ C = $chkBrowserHistory;   K = "BrowserHistory" },
        @{ C = $chkBrowserCookies;   K = "BrowserCookies" },
        @{ C = $chkBrowserPasswords; K = "BrowserPasswords" },
        @{ C = $chkShader;      K = "Shader" },
        @{ C = $chkGameClients; K = "GameClients" }
    )

    foreach ($item in $map) {
        if ($item.C -and $item.C.IsChecked -and $script:itemSizes.ContainsKey($item.K)) {
            $selectedTotal += $script:itemSizes[$item.K]
        }
    }

    $formatted = Format-Size $selectedTotal
    $lblLiveSelectedSize.Text = $formatted
    $lblCleanBadge.Text       = "Seçilen: $formatted"

    # Diğer Uygulama Öğeleri Grubu Rozeti
    [double]$totOtherApps = 0
    foreach ($k in @("AppNotion", "AppVSCode", "AppPython", "AppVlc", "Apps")) {
        if ($script:itemSizes.ContainsKey($k)) { $totOtherApps += $script:itemSizes[$k] }
    }
    if ($lblSizeGroupOtherApps) { $lblSizeGroupOtherApps.Text = Format-Size $totOtherApps }

    # Bilgisayar Kullanım İzlemeleri Grubu Rozeti
    [double]$totTraces = 0
    foreach ($k in @("TraceSystem", "TraceChrome", "TraceEdge", "TraceBrave")) {
        if ($script:itemSizes.ContainsKey($k)) { $totTraces += $script:itemSizes[$k] }
    }
    $cntTraces = ($script:traceSystemCount + $script:traceChromeCount + $script:traceEdgeCount + $script:traceBraveCount)
    if ($lblSizeGroupTraces) {
        if ($cntTraces -gt 0) {
            $lblSizeGroupTraces.Text = "$cntTraces Öğe (" + (Format-Size $totTraces) + ")"
        } else {
            $lblSizeGroupTraces.Text = Format-Size $totTraces
        }
    }
}

# Akordiyon & Grup Koordinasyon Bayrağı (Olay Döngüsü Koruması)
$script:isSyncingGroups = $false

# Diğer Uygulamalar Grubu Açılır / Kapanır Düğmesi & Başlık Tıklama
if ($btnToggleOtherApps) {
    $btnToggleOtherApps.Add_Click({
        if ($pnlOtherAppsChildren.Visibility -eq [System.Windows.Visibility]::Visible) {
            $pnlOtherAppsChildren.Visibility = [System.Windows.Visibility]::Collapsed
            $btnToggleOtherApps.Content = "⌄"
        } else {
            $pnlOtherAppsChildren.Visibility = [System.Windows.Visibility]::Visible
            $btnToggleOtherApps.Content = "⌃"
        }
    })
}

if ($bdrHeaderOtherApps) {
    $bdrHeaderOtherApps.Add_MouseLeftButtonUp({
        if ($btnToggleOtherApps) {
            $btnToggleOtherApps.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent))
        }
    })
}

if ($chkGroupOtherApps) {
    $chkGroupOtherApps.Add_Checked({
        if ($script:isSyncingGroups) { return }
        $script:isSyncingGroups = $true
        try {
            if ($bdrAppNotion -and $bdrAppNotion.Visibility -eq [System.Windows.Visibility]::Visible) { $chkAppNotion.IsChecked = $true }
            if ($bdrAppVSCode -and $bdrAppVSCode.Visibility -eq [System.Windows.Visibility]::Visible) { $chkAppVSCode.IsChecked = $true }
            if ($bdrAppPython -and $bdrAppPython.Visibility -eq [System.Windows.Visibility]::Visible) { $chkAppPython.IsChecked = $true }
            if ($bdrAppVlc -and $bdrAppVlc.Visibility -eq [System.Windows.Visibility]::Visible)       { $chkAppVlc.IsChecked = $true }
            if ($chkApps) { $chkApps.IsChecked = $true }
        } finally {
            $script:isSyncingGroups = $false
        }
        Update-LiveSelectedSize
    })

    $chkGroupOtherApps.Add_Unchecked({
        if ($script:isSyncingGroups) { return }
        $script:isSyncingGroups = $true
        try {
            if ($chkAppNotion) { $chkAppNotion.IsChecked = $false }
            if ($chkAppVSCode) { $chkAppVSCode.IsChecked = $false }
            if ($chkAppPython) { $chkAppPython.IsChecked = $false }
            if ($chkAppVlc)    { $chkAppVlc.IsChecked = $false }
            if ($chkApps)      { $chkApps.IsChecked = $false }
        } finally {
            $script:isSyncingGroups = $false
        }
        Update-LiveSelectedSize
    })
}

# Bilgisayar Kullanım İzlemeleri Grubu Açılır / Kapanır Düğmesi & Başlık Tıklama
if ($btnToggleTraces) {
    $btnToggleTraces.Add_Click({
        if ($pnlTracesChildren.Visibility -eq [System.Windows.Visibility]::Visible) {
            $pnlTracesChildren.Visibility = [System.Windows.Visibility]::Collapsed
            $btnToggleTraces.Content = "⌄"
        } else {
            $pnlTracesChildren.Visibility = [System.Windows.Visibility]::Visible
            $btnToggleTraces.Content = "⌃"
        }
    })
}

if ($bdrHeaderTraces) {
    $bdrHeaderTraces.Add_MouseLeftButtonUp({
        if ($btnToggleTraces) {
            $btnToggleTraces.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent))
        }
    })
}

if ($chkGroupTraces) {
    $chkGroupTraces.Add_Checked({
        if ($script:isSyncingGroups) { return }
        $script:isSyncingGroups = $true
        try {
            if ($chkTraceSystem) { $chkTraceSystem.IsChecked = $true }
            if ($chkTraceChrome) { $chkTraceChrome.IsChecked = $true }
            if ($chkTraceEdge)   { $chkTraceEdge.IsChecked = $true }
            if ($chkTraceBrave)  { $chkTraceBrave.IsChecked = $true }
        } finally {
            $script:isSyncingGroups = $false
        }
        Update-LiveSelectedSize
    })

    $chkGroupTraces.Add_Unchecked({
        if ($script:isSyncingGroups) { return }
        $script:isSyncingGroups = $true
        try {
            if ($chkTraceSystem) { $chkTraceSystem.IsChecked = $false }
            if ($chkTraceChrome) { $chkTraceChrome.IsChecked = $false }
            if ($chkTraceEdge)   { $chkTraceEdge.IsChecked = $false }
            if ($chkTraceBrave)  { $chkTraceBrave.IsChecked = $false }
        } finally {
            $script:isSyncingGroups = $false
        }
        Update-LiveSelectedSize
    })
}

# Checkbox değişikliklerini dinle
$allCheckboxes = @(
    $chkTemp, $chkWinUpdate, $chkRecycle, $chkEventLogs, $chkWsxx, $chkDeliveryOpt, $chkWinOld,
    $chkDriverStore,
    $chkCrash, $chkThumbs, $chkPrefetch, $chkFont, $chkDefender, $chkINetCache, $chkChrome, $chkEdge,
    $chkFirefox, $chkOpera, $chkBrave, $chkApps,
    $chkAppNotion, $chkAppVSCode, $chkAppPython, $chkAppVlc,
    $chkTraceSystem, $chkTraceChrome, $chkTraceEdge, $chkTraceBrave,
    $chkBrowserHistory, $chkBrowserCookies, $chkBrowserPasswords,
    $chkShader, $chkGameClients,
    $chkDns, $chkOldRestore, $chkShortcuts
)
foreach ($cb in $allCheckboxes) {
    if ($cb) {
        $cb.Add_Checked({ Update-LiveSelectedSize })
        $cb.Add_Unchecked({ Update-LiveSelectedSize })
    }
}

# ------------------------------------------------------------------------------
# 10. Temizlik Boyutlarını Sıralı & Canlı Hesaplama (DispatcherTimer ile Kesintisiz)
# ------------------------------------------------------------------------------
$script:sizingItems = @(
    @{ Key = "Temp"; Label = $lblSizeTemp; Calc = { (Get-FolderSizeSafe $env:TEMP) + (Get-FolderSizeSafe "C:\Windows\Temp") } },
    @{ Key = "WinUpdate"; Label = $lblSizeWinUpdate; Calc = { Get-FolderSizeSafe "C:\Windows\SoftwareDistribution\Download" } },
    @{ Key = "Recycle"; Label = $lblSizeRecycle; Calc = { if (Test-Path "C:\`$Recycle.Bin" -ErrorAction SilentlyContinue) { Get-FolderSizeSafe "C:\`$Recycle.Bin" } else { 0 } } },
    @{ Key = "EventLogs"; Label = $lblSizeEventLogs; Calc = { (Get-FolderSizeSafe "C:\Windows\System32\winevt\Logs") + (Get-FolderSizeSafe "C:\Windows\Logs") + (Get-FolderSizeSafe "C:\Windows\System32\LogFiles") + (Get-FolderSizeSafe "C:\Windows\Panther") } },
    @{ Key = "DeliveryOpt"; Label = $lblSizeDeliveryOpt; Calc = {
        (Get-FolderSizeSafe "C:\Windows\SoftwareDistribution\DeliveryOptimization") +
        (Get-FolderSizeSafe "C:\Windows\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization") +
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Network\Downloader")
    } },
    @{ Key = "WinOld"; Label = $lblSizeWinOld; Calc = {
        (Get-FolderSizeSafe "C:\Windows.old") +
        (Get-FolderSizeSafe "C:\`$WINDOWS.~BT")
    } },
    @{ Key = "DriverStore"; Label = $lblSizeDriverStore; Calc = {
        try {
            $rawPnp = pnputil /enum-drivers
            $drList = [System.Collections.Generic.List[psobject]]::new()
            $cHash = [System.Collections.Hashtable]::new()
            foreach ($line in ($rawPnp -split '\r?\n')) {
                $line = $line.Trim()
                if (-not $line) {
                    if ($cHash.ContainsKey('PublishedName') -and $cHash.ContainsKey('OriginalName')) {
                        $drList.Add([PSCustomObject]@{
                            PublishedName = $cHash['PublishedName']
                            OriginalName  = $cHash['OriginalName']
                            DriverVersion = if ($cHash.ContainsKey('DriverVersion')) { $cHash['DriverVersion'] } else { "" }
                        })
                    }
                    $cHash.Clear()
                } elseif ($line -match '^([^:]+):\s*(.*)$') {
                    $k = $matches[1].Trim()
                    $v = $matches[2].Trim()
                    if ($k -match '^(Published Name|Yay[ıi]mlanan Ad[ıi]?)$') {
                        $cHash['PublishedName'] = $v
                    } elseif ($k -match '^(Original Name|Özgün Ad[ıi]?|Ozgun Ad[ıi]?|Orijinal Ad[ıi]?)$') {
                        $cHash['OriginalName'] = $v
                    } elseif ($k -match '^(Driver Version|Sürücü Sürümü|Surucu Surumu|Sürüm|Driver Date|Sürücü Tarihi)$') {
                        $cHash['DriverVersion'] = $v
                    }
                }
            }
            if ($cHash.ContainsKey('PublishedName') -and $cHash.ContainsKey('OriginalName')) {
                $drList.Add([PSCustomObject]@{
                    PublishedName = $cHash['PublishedName']
                    OriginalName  = $cHash['OriginalName']
                    DriverVersion = if ($cHash.ContainsKey('DriverVersion')) { $cHash['DriverVersion'] } else { "" }
                })
            }
            $byOrig = $drList | Group-Object { $_.OriginalName.ToLower() }
            [double]$candBytes = 0
            $drPath = 'C:\Windows\System32\DriverStore\FileRepository'
            [string[]]$dateFormats = @('MM/dd/yyyy', 'M/d/yyyy', 'dd.MM.yyyy', 'd.M.yyyy', 'yyyy-MM-dd', 'dd/MM/yyyy')
            foreach ($g in $byOrig) {
                if ($g.Count -gt 1) {
                    $validItems = [System.Collections.Generic.List[psobject]]::new()
                    $hasInvalidDate = $false
                    foreach ($dr in $g.Group) {
                        $parsedDate = [datetime]::MinValue
                        $parsedVer = [version]'0.0'
                        try {
                            $parts = $dr.DriverVersion -split '\s+'
                            $dPart = $parts[0]
                            if (-not [datetime]::TryParseExact($dPart, $dateFormats, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$parsedDate)) {
                                [datetime]::TryParse($dPart, [ref]$parsedDate) | Out-Null
                            }
                            if ($parts.Count -ge 2) {
                                $clean = $parts[1] -replace '[^\d\.]', ''
                                if ($clean -match '^\d+(\.\d+)+$') {
                                    $vParts = $clean -split '\.'
                                    if ($vParts.Count -gt 4) { $clean = ($vParts[0..3] -join '.') }
                                    $parsedVer = [version]$clean
                                } elseif ($clean -match '^\d+$') {
                                    $parsedVer = [version]"$clean.0"
                                }
                            }
                        } catch {}
                        if ($parsedDate -eq [datetime]::MinValue) {
                            $hasInvalidDate = $true
                            break
                        }
                        $validItems.Add([PSCustomObject]@{
                            Item    = $dr
                            Date    = $parsedDate
                            Version = $parsedVer
                        })
                    }
                    if ($hasInvalidDate -or $validItems.Count -lt 2) { continue }

                    # 1. Öncelik Tarih (artan), 2. Öncelik Sürüm Numarası (artan)
                    $sorted = $validItems | Sort-Object -Property Date, Version
                    if ($sorted[0].Date -eq $sorted[-1].Date -and $sorted[0].Version -eq $sorted[-1].Version) { continue }

                    for ($i = 0; $i -lt ($sorted.Count - 1); $i++) {
                        $cand = $sorted[$i].Item
                        $baseName = ($cand.OriginalName -split '\.')[0]
                        $matchFolders = Get-ChildItem -LiteralPath $drPath -Directory -Filter "$baseName*" -ErrorAction SilentlyContinue
                        if ($matchFolders) {
                            $fSize = (Get-ChildItem -LiteralPath $matchFolders[0].FullName -File -Recurse -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
                            if ($fSize) { $candBytes += $fSize }
                        }
                    }
                }
            }
            $candBytes
        } catch { 0 }
    } },
    @{ Key = "Crash"; Label = $lblSizeCrash; Calc = {
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\CrashDumps") +
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Windows\WER") +
        (Get-FolderSizeSafe "C:\Windows\Minidump") +
        (Get-FolderSizeSafe "C:\Windows\System32\config\systemprofile\AppData\Local\CrashDumps") +
        (Get-FolderSizeSafe "C:\Windows\LiveKernelReports") +
        (if (Test-Path "C:\Windows\MEMORY.DMP") { (Get-Item "C:\Windows\MEMORY.DMP" -Force -ErrorAction SilentlyContinue).Length } else { 0 })
    } },
    @{ Key = "Thumbs"; Label = $lblSizeThumbs; Calc = {
        [double]$sz = 0
        $explDir = "$env:LOCALAPPDATA\Microsoft\Windows\Explorer"
        if (Test-Path $explDir) {
            Get-ChildItem -Path $explDir -Filter "*cache_*.db" -File -Force -ErrorAction SilentlyContinue | ForEach-Object { $sz += $_.Length }
        }
        $mainIcon = "$env:LOCALAPPDATA\IconCache.db"
        if (Test-Path $mainIcon) {
            try { $sz += (New-Object System.IO.FileInfo($mainIcon)).Length } catch {}
        }
        return $sz
    } },
    @{ Key = "Prefetch"; Label = $lblSizePrefetch; Calc = { Get-FolderSizeSafe "C:\Windows\Prefetch" } },
    @{ Key = "Font"; Label = $lblSizeFont; Calc = { Get-FolderSizeSafe "C:\Windows\ServiceProfiles\LocalService\AppData\Local\FontCache" } },
    @{ Key = "Defender"; Label = $lblSizeDefender; Calc = {
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Windows Defender\Support") +
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Store") +
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Results\Quick") +
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Results\Resource") +
        (Get-FolderSizeSafe "C:\ProgramData\Microsoft\Windows Defender\Definition Updates\Backup")
    } },
    @{ Key = "INetCache"; Label = $lblSizeINetCache; Calc = {
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Windows\INetCache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Windows\WebCache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Windows\IEDownloadHistory")
    } },
    @{ Key = "Chrome"; Label = $lblSizeChrome; Calc = { Get-ChromiumAllProfilesSize "$env:LOCALAPPDATA\Google\Chrome\User Data" } },
    @{ Key = "Edge"; Label = $lblSizeEdge; Calc = { Get-ChromiumAllProfilesSize "$env:LOCALAPPDATA\Microsoft\Edge\User Data" } },
    @{ Key = "Firefox"; Label = $lblSizeFirefox; Calc = {
        [double]$ffTot = (Get-FolderSizeSafe "$env:LOCALAPPDATA\Mozilla\Firefox\Profiles") +
                         (Get-FolderSizeSafe "$env:APPDATA\Mozilla\Firefox\Background Tasks Profiles") +
                         (Get-FolderSizeSafe "$env:APPDATA\Mozilla\Firefox\Crash Reports") +
                         (Get-FolderSizeSafe "$env:APPDATA\Mozilla\Firefox\Pending Pings")
        $ffProf = Get-ChildItem -Path "$env:APPDATA\Mozilla\Firefox\Profiles" -Directory -ErrorAction SilentlyContinue
        foreach ($p in $ffProf) {
            $ffTot += (Get-FolderSizeSafe (Join-Path $p.FullName "storage\default"))
        }
        return $ffTot
    } },
    @{ Key = "Opera"; Label = $lblSizeOpera; Calc = { (Get-FolderSizeSafe "$env:LOCALAPPDATA\Opera Software\Opera Stable\Cache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\Opera Software\Opera Stable\GPUCache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\Opera Software\Opera GX Stable\Cache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\Opera Software\Opera GX Stable\GPUCache") } },
    @{ Key = "Brave"; Label = $lblSizeBrave; Calc = { Get-ChromiumAllProfilesSize "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data" } },
        @{ Key = "Apps"; Label = $lblSizeApps; Calc = {
        (Get-FolderSizeSafe "$env:APPDATA\discord\Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\discord\Code Cache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Spotify\Storage") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Spotify\Data") +
        (Get-FolderSizeSafe "$env:APPDATA\Microsoft\Teams\Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Slack\Cache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Office\16.0\OfficeFileCache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Office\15.0\OfficeFileCache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Office\16.0\WebServiceCache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\Office\OTele") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\OneDrive\cache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\OneDrive\logs") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\Microsoft\OneDrive\setup\logs") +
        (Get-FolderSizeSafe "C:\ProgramData\NVIDIA Corporation\NvProfileUpdaterPlugin") +
        (Get-FolderSizeSafe "C:\ProgramData\NVIDIA Corporation\NVIDIA App\MessageBus")
    } },
    @{ Key = "AppNotion"; Label = $lblSizeAppNotion; Container = $bdrAppNotion; Calc = {
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\notion-updater") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\logs") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\GPUCache") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Code Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Partitions\notion\Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Partitions\notion\GPUCache") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Code Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Partitions\notion\Service Worker\CacheStorage") +
        (Get-FolderSizeSafe "$env:APPDATA\Notion\Partitions\notion\Service Worker\ScriptCache")
    } },
    @{ Key = "AppVSCode"; Label = $lblSizeAppVSCode; Container = $bdrAppVSCode; Calc = {
        (Get-FolderSizeSafe "$env:APPDATA\Code\CachedData") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\Code Cache") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\GPUCache") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\DawnWebGPUCache") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\DawnGraphiteCache") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\CachedExtensionVSIXs") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\logs") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\Service Worker\ScriptCache") +
        (Get-FolderSizeSafe "$env:APPDATA\Code\Service Worker\CacheStorage")
    } },
    @{ Key = "AppPython"; Label = $lblSizeAppPython; Container = $bdrAppPython; Calc = {
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\pip\cache") +
        (Get-FolderSizeSafe "$env:LOCALAPPDATA\pip\Cache")
    } },
    @{ Key = "AppVlc"; Label = $lblSizeAppVlc; Container = $bdrAppVlc; Calc = {
        (Get-FolderSizeSafe "$env:APPDATA\vlc\art") +
        (Get-FolderSizeSafe "$env:APPDATA\vlc\crashdump")
    } },
    @{ Key = "TraceSystem"; Label = $lblSizeTraceSystem; Calc = {
        $traceLogs = @(Get-ChildItem -Path "C:\ProgramData\USOShared\Logs", "C:\Windows\System32\WDI", "C:\Windows\System32\SleepStudy", "C:\Windows\Logs\waasmedic", "C:\ProgramData\Microsoft\Diagnosis\DownloadedSettings" -Recurse -File -Force -ErrorAction SilentlyContinue)
        $recentFiles = @(Get-ChildItem -Path "$env:APPDATA\Microsoft\Windows\Recent" -Recurse -File -Force -ErrorAction SilentlyContinue)
        $cnt = $traceLogs.Count + $recentFiles.Count
        $sz = [double](($traceLogs | Measure-Object -Property Length -Sum).Sum + ($recentFiles | Measure-Object -Property Length -Sum).Sum)
        $script:traceSystemCount = $cnt
        if ($lblSizeTraceSystem) { $lblSizeTraceSystem.Text = "$cnt Öğe (" + (Format-Size $sz) + ")" }
        return $sz
    } },
    @{ Key = "TraceChrome"; Label = $lblSizeTraceChrome; Calc = {
        $files = @(Get-ChildItem -Path "$env:LOCALAPPDATA\Google\Chrome\User Data" -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { 
            $_.FullName -match 'History|Visited Links|Top Sites|Network Action Predictor|Shortcuts|DownloadMetadata' 
        })
        $cnt = $files.Count
        $sz = [double](($files | Measure-Object -Property Length -Sum).Sum)
        $script:traceChromeCount = $cnt
        if ($lblSizeTraceChrome) { $lblSizeTraceChrome.Text = "$cnt Öğe (" + (Format-Size $sz) + ")" }
        return $sz
    } },
    @{ Key = "TraceEdge"; Label = $lblSizeTraceEdge; Calc = {
        $files = @(Get-ChildItem -Path "$env:LOCALAPPDATA\Microsoft\Edge\User Data" -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { 
            $_.FullName -match 'History|Visited Links|Top Sites|Network Action Predictor|Shortcuts|DownloadMetadata' 
        })
        $cnt = $files.Count
        $sz = [double](($files | Measure-Object -Property Length -Sum).Sum)
        $script:traceEdgeCount = $cnt
        if ($lblSizeTraceEdge) { $lblSizeTraceEdge.Text = "$cnt Öğe (" + (Format-Size $sz) + ")" }
        return $sz
    } },
    @{ Key = "TraceBrave"; Label = $lblSizeTraceBrave; Calc = {
        $files = @(Get-ChildItem -Path "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data" -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { 
            $_.FullName -match 'History|Visited Links|Top Sites|Network Action Predictor|Shortcuts|DownloadMetadata' 
        })
        $cnt = $files.Count
        $sz = [double](($files | Measure-Object -Property Length -Sum).Sum)
        $script:traceBraveCount = $cnt
        if ($lblSizeTraceBrave) { $lblSizeTraceBrave.Text = "$cnt Öğe (" + (Format-Size $sz) + ")" }
        return $sz
    } },
    @{ Key = "BrowserHistory";   Label = $lblSizeBrowserHistory;   Calc = { Get-BrowserTargetFilesSize "History" } },
    @{ Key = "BrowserCookies";   Label = $lblSizeBrowserCookies;   Calc = { Get-BrowserTargetFilesSize "Cookies" } },
    @{ Key = "BrowserPasswords"; Label = $lblSizeBrowserPasswords; Calc = { Get-BrowserTargetFilesSize "Passwords" } },
    @{ Key = "Shader"; Label = $lblSizeShader; Calc = { (Get-FolderSizeSafe "$env:LOCALAPPDATA\D3DSCache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\NVIDIA\DXCache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\NVIDIA\GLCache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\AMD\DxCache") } },
    @{ Key = "GameClients"; Label = $lblSizeGameClients; Calc = { (Get-FolderSizeSafe "$env:LOCALAPPDATA\Steam\htmlcache") + (Get-FolderSizeSafe "${env:ProgramFiles(x86)}\Steam\htmlcache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\EpicGamesLauncher\Saved\webcache") + (Get-FolderSizeSafe "$env:LOCALAPPDATA\Electronic Arts\EA Desktop\Logs") } }
)

$script:sizingIndex = 0
$script:sizingTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:sizingTimer.Interval = [TimeSpan]::FromMilliseconds(20)
$script:sizingTimer.Add_Tick({
    if ($script:sizingIndex -lt $script:sizingItems.Count) {
        $cur = $script:sizingItems[$script:sizingIndex]
        $script:sizingIndex++
        try {
            $sz = & $cur.Calc
            $script:itemSizes[$cur.Key] = $sz
            if ($cur.Label) { $cur.Label.Text = Format-Size $sz }
            if ($cur.Container) {
                $isAppInstalled = $false
                if ($cur.Key -eq "AppNotion") { $isAppInstalled = (Test-Path "$env:APPDATA\Notion") -or (Test-Path "$env:LOCALAPPDATA\Programs\Notion") }
                elseif ($cur.Key -eq "AppVSCode") { $isAppInstalled = (Test-Path "$env:APPDATA\Code") -or (Test-Path "$env:LOCALAPPDATA\Programs\Microsoft VS Code") }
                elseif ($cur.Key -eq "AppPython") { $isAppInstalled = (Test-Path "$env:LOCALAPPDATA\pip") -or (Test-Path "$env:LOCALAPPDATA\Programs\Python") }
                elseif ($cur.Key -eq "AppVlc")    { $isAppInstalled = (Test-Path "$env:APPDATA\vlc") -or (Test-Path "C:\Program Files\VideoLAN\VLC") -or (Test-Path "C:\Program Files (x86)\VideoLAN\VLC") }

                if ($sz -gt 0 -or $isAppInstalled) {
                    $cur.Container.Visibility = [System.Windows.Visibility]::Visible
                } else {
                    $cur.Container.Visibility = [System.Windows.Visibility]::Collapsed
                    if ($cur.Key -eq "AppNotion" -and $chkAppNotion) { $chkAppNotion.IsChecked = $false }
                    if ($cur.Key -eq "AppVSCode" -and $chkAppVSCode) { $chkAppVSCode.IsChecked = $false }
                    if ($cur.Key -eq "AppPython" -and $chkAppPython) { $chkAppPython.IsChecked = $false }
                    if ($cur.Key -eq "AppVlc" -and $chkAppVlc) { $chkAppVlc.IsChecked = $false }
                }
            }
            Update-LiveSelectedSize
        } catch {
            if ($cur.Label) { $cur.Label.Text = "0 KB" }
            if ($cur.Container) {
                $cur.Container.Visibility = [System.Windows.Visibility]::Collapsed
            }
        }
    } else {
        $script:sizingTimer.Stop()
        if (-not $script:isCleaningRunning) {
            $lblCleanStatus.Text = "Boyutlar güncellendi. Temizlemek istediğiniz öğeleri seçin."
        }
    }
})

function Scan-AllCleanupSizes {
    Write-CmdLog "TARAMA" "Disk temizlik kategorileri taranıyor ve boyutlar hesaplanıyor..." "DarkCyan"
    $script:sizingIndex = 0
    $lblCleanStatus.Text = "Temizlik boyutları canlı hesaplanıyor..."
    $script:sizingTimer.Start()
}

# ------------------------------------------------------------------------------
# 11. Kırık Kısayolları Tarama
# ------------------------------------------------------------------------------
function Scan-BrokenShortcuts {
    $wsh = New-Object -ComObject WScript.Shell
    $dirs = @(
        [Environment]::GetFolderPath('Desktop'),
        [Environment]::GetFolderPath('CommonDesktopDirectory'),
        [Environment]::GetFolderPath('StartMenu'),
        [Environment]::GetFolderPath('CommonStartMenu')
    )
    $broken = @()
    $brokenDetails = @()
    foreach ($d in $dirs) {
        if (Test-Path $d -ErrorAction SilentlyContinue) {
            $files = Get-ChildItem -Path $d -Filter "*.lnk" -Recurse -ErrorAction SilentlyContinue
            foreach ($f in $files) {
                try {
                    $sc = $wsh.CreateShortcut($f.FullName)
                    $target = $sc.TargetPath
                    if ([string]::IsNullOrWhiteSpace($target)) { continue }
                    if ($target.StartsWith("\\")) { continue } # Ağ yollarını atla
                    if ($target -cmatch '^[A-Za-z]:\\') {
                        $drive = $target.Substring(0, 3)
                        if (-not (Test-Path $drive -ErrorAction SilentlyContinue)) { continue } # Takılı olmayan USB/sürücü atla
                        if (-not (Test-Path $target -ErrorAction SilentlyContinue)) {
                            $broken += $f.FullName
                            $brokenDetails += [PSCustomObject]@{
                                File   = $f.FullName
                                Name   = $f.Name
                                Target = $target
                            }
                        }
                    }
                } catch {}
            }
        }
    }
    $script:brokenShortcutFiles = $broken
    $lblBrokenShortcutsCount.Text = "$($broken.Count) adet"
    if ($broken.Count -gt 0) {
        Write-CmdLog "KISAYOL" "Kırık kısayol taraması tamamlandı: $($broken.Count) adet geçersiz kısayol tespit edildi." "Yellow"
    } else {
        Write-CmdLog "KISAYOL" "Kırık kısayol taraması tamamlandı: Geçersiz kısayol bulunamadı." "DarkGray"
    }

    # Madde 8: Kırık kısayolları tek tek seçilebilir CheckBox nesneleri olarak ListBox'a ekle
    if ($lstBrokenShortcuts) {
        $lstBrokenShortcuts.Items.Clear()
        foreach ($bd in $brokenDetails) {
            $cb = New-Object System.Windows.Controls.CheckBox
            $cb.IsChecked = $true
            $cb.Tag = $bd.File
            $cb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#E2E8F0")
            $cb.Content = "$($bd.Name)  →  [Hedef Yok: $($bd.Target)]"
            $cb.Margin = New-Object System.Windows.Thickness(0, 2, 0, 2)
            $cb.Add_Checked({ Update-LiveSelectedSize })
            $cb.Add_Unchecked({ Update-LiveSelectedSize })
            [void]$lstBrokenShortcuts.Items.Add($cb)
        }
    }
    if ($btnToggleShortcutsList) {
        if ($broken.Count -gt 0) {
            $btnToggleShortcutsList.Visibility = [System.Windows.Visibility]::Visible
        } else {
            $btnToggleShortcutsList.Visibility = [System.Windows.Visibility]::Collapsed
            if ($pnlBrokenShortcutsDetails) { $pnlBrokenShortcutsDetails.Visibility = [System.Windows.Visibility]::Collapsed }
        }
    }}

# ------------------------------------------------------------------------------
# 12. Winget Güncellemelerini Tarama ve Listeleme (Dosya Yönlendirmeli Deadlock-Free)
# ------------------------------------------------------------------------------
$script:wingetTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:wingetTimer.Interval = [TimeSpan]::FromMilliseconds(250)
$script:wingetProc = $null
$script:wingetLog = "$env:TEMP\temizwin_winget_scan.txt"

function Update-SelectedWingetCount {
    $selCount = 0
    $totalCount = $script:wingetPackages.Count
    foreach ($item in $pnlUpdateList.Children) {
        if ($item -is [System.Windows.Controls.Border]) {
            $grid = $item.Child
            if ($grid -and $grid.Children.Count -gt 0) {
                $cb = $grid.Children[0]
                if ($cb -is [System.Windows.Controls.CheckBox] -and $cb.IsChecked) {
                    $selCount++
                }
            }
        }
    }
    $lblUpdateSelectedBadge.Text = "$selCount / $totalCount seçili"
}

$script:wingetTimer.Add_Tick({
    if ($script:wingetProc -and $script:wingetProc.HasExited) {
        $script:wingetTimer.Stop()
        $out = ""
        if (Test-Path $script:wingetLog) {
            try {
                $out = [System.IO.File]::ReadAllText($script:wingetLog, [System.Text.Encoding]::UTF8)
                Remove-Item $script:wingetLog -Force -ErrorAction SilentlyContinue
            } catch {}
        }
        $script:wingetProc.Dispose()
        $script:wingetProc = $null

        $incStore = if ($chkIncludeStore) { $chkIncludeStore.IsChecked -eq $true } else { $false }
        $packages = @()
        $start = $false
        foreach ($line in ($out -split "`r?`n")) {
            if ($line -match '^-{5,}') { $start = $true; continue }
            if (-not $start -or [string]::IsNullOrWhiteSpace($line)) { continue }

            $tokens = ($line.Trim() -split '\s+')
            if ($tokens.Count -ge 4) {
                # Ayrık karşılaştırma simgelerini temizle (<, >, ->, vb.)
                $cleanTokens = @($tokens | Where-Object { $_ -ne '<' -and $_ -ne '>' -and $_ -ne '->' -and $_ -ne '→' })
                if ($cleanTokens.Count -ge 4) {
                    $source = $cleanTokens[-1].ToLower()
                    if ($source -ne 'winget' -and $source -ne 'msstore') {
                        # Bazı winget çıktılarında Source sütunu boş olabilir
                        if ($cleanTokens.Count -ge 4 -and ($cleanTokens[-2] -match '^\d' -or $cleanTokens[-1] -match '^\d')) {
                            $source = 'winget'
                            $available = $cleanTokens[-1]
                            $version   = $cleanTokens[-2]
                            $id        = $cleanTokens[-3]
                            $nameTokens = $cleanTokens[0..($cleanTokens.Count - 4)]
                        } else {
                            continue
                        }
                    } else {
                        if ($cleanTokens.Count -lt 5) { continue }
                        if (-not $incStore -and $source -eq 'msstore') { continue }
                        $available = $cleanTokens[-2]
                        $version   = $cleanTokens[-3]
                        $id        = $cleanTokens[-4]
                        $nameTokens = $cleanTokens[0..($cleanTokens.Count - 5)]
                    }

                    $idIdx = $line.IndexOf($id)
                    $name = if ($idIdx -gt 0) { $line.Substring(0, $idIdx).Trim() } else { $nameTokens -join ' ' }

                    $packages += [PSCustomObject]@{
                        Name      = $name
                        Id        = $id
                        Version   = $version
                        Available = $available
                        Source    = $source
                    }
                }
            }
        }

        $script:wingetPackages = $packages
        $count = $packages.Count
        $lblAvailableUpdates.Text = "$count program"
        $lblUpdateSelectedBadge.Text = "0 / $count seçili"
        $lblUpdateProgressText.Text = "Tarama tamamlandı: $count adet güncellenebilir program bulundu."
        $scanColor = "DarkGray"
        if ($count -gt 0) { $scanColor = "Green" }
        Write-CmdLog "GÜNCELLEME" "Tarama tamamlandı: $count adet güncellenebilir program bulundu." $scanColor
        if ($count -gt 0) {
            foreach ($pkg in $packages) {
                Write-CmdLog "PAKET" "-> $($pkg.Name) [$($pkg.Id)] ($($pkg.Version) -> $($pkg.Available)) [$($pkg.Source)]" "Gray"
            }
        }

        if ($count -eq 0) {
            $lblUpdatePlaceholder.Text = "Tüm programlarınız güncel! Yeni güncelleme bulunamadı."
            $lblUpdatePlaceholder.Visibility = [System.Windows.Visibility]::Visible
        } else {
            $lblUpdatePlaceholder.Visibility = [System.Windows.Visibility]::Collapsed
            $pnlUpdateList.Children.Clear()

            foreach ($pkg in $packages) {
                $itemBorder = New-Object System.Windows.Controls.Border
                $itemBorder.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#171B2A")
                $itemBorder.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#22273C")
                $itemBorder.BorderThickness = New-Object System.Windows.Thickness(1)
                $itemBorder.CornerRadius = New-Object System.Windows.CornerRadius(8)
                $itemBorder.Padding = New-Object System.Windows.Thickness(12, 10, 12, 10)
                $itemBorder.Margin = New-Object System.Windows.Thickness(0, 0, 0, 6)
                $itemBorder.Tag = $pkg.Id
                $itemBorder.DataContext = $pkg

                $grid = New-Object System.Windows.Controls.Grid
                $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = [System.Windows.GridLength]::Auto
                $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
                $c2 = New-Object System.Windows.Controls.ColumnDefinition; $c2.Width = [System.Windows.GridLength]::Auto
                $c3 = New-Object System.Windows.Controls.ColumnDefinition; $c3.Width = [System.Windows.GridLength]::Auto
                [void]$grid.ColumnDefinitions.Add($c0)
                [void]$grid.ColumnDefinitions.Add($c1)
                [void]$grid.ColumnDefinitions.Add($c2)
                [void]$grid.ColumnDefinitions.Add($c3)

                $cb = New-Object System.Windows.Controls.CheckBox
                $cb.IsChecked = $false
                $cb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                $cb.Margin = New-Object System.Windows.Thickness(0, 0, 12, 0)
                $cb.Add_Checked({ Update-SelectedWingetCount })
                $cb.Add_Unchecked({ Update-SelectedWingetCount })
                [System.Windows.Controls.Grid]::SetColumn($cb, 0)
                [void]$grid.Children.Add($cb)

                $sp = New-Object System.Windows.Controls.StackPanel
                $sp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                $tName = New-Object System.Windows.Controls.TextBlock
                $tName.Text = $pkg.Name
                $tName.FontWeight = [System.Windows.FontWeights]::SemiBold
                $tName.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
                $tId = New-Object System.Windows.Controls.TextBlock
                $tId.Text = "$($pkg.Id) ($($pkg.Source))"
                $tId.FontSize = 11
                $tId.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
                [void]$sp.Children.Add($tName)
                [void]$sp.Children.Add($tId)
                [System.Windows.Controls.Grid]::SetColumn($sp, 1)
                [void]$grid.Children.Add($sp)

                $tVer = New-Object System.Windows.Controls.TextBlock
                $tVer.Text = "$($pkg.Version) → $($pkg.Available)"
                $tVer.FontWeight = [System.Windows.FontWeights]::Bold
                $tVer.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
                $tVer.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                $tVer.Margin = New-Object System.Windows.Thickness(12, 0, 16, 0)
                [System.Windows.Controls.Grid]::SetColumn($tVer, 2)
                [void]$grid.Children.Add($tVer)

                $statusBdr = New-Object System.Windows.Controls.Border
                $statusBdr.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E2538")
                $statusBdr.CornerRadius = New-Object System.Windows.CornerRadius(6)
                $statusBdr.Padding = New-Object System.Windows.Thickness(10, 4, 10, 4)
                $statusBdr.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                $tStatus = New-Object System.Windows.Controls.TextBlock
                $tStatus.Text = "Bekliyor"
                $tStatus.FontSize = 11
                $tStatus.FontWeight = [System.Windows.FontWeights]::SemiBold
                $tStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
                $statusBdr.Child = $tStatus
                [System.Windows.Controls.Grid]::SetColumn($statusBdr, 3)
                [void]$grid.Children.Add($statusBdr)

                $itemBorder.Child = $grid
                [void]$pnlUpdateList.Children.Add($itemBorder)
            }
        }
    }
})

function Scan-WingetUpdates {
    $lblAvailableUpdates.Text = "Taranıyor..."
    $lblUpdateProgressText.Text = "Güncellemeler taranıyor, lütfen bekleyin..."
    $pnlUpdateList.Children.Clear()
    $lblUpdatePlaceholder.Text = "Kurulu programlar taranıyor..."
    $lblUpdatePlaceholder.Visibility = [System.Windows.Visibility]::Visible

    $wingetCmd = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $wingetCmd) {
        $lblAvailableUpdates.Text = "0 program"
        $lblUpdatePlaceholder.Text = "Sistemde winget (Windows Paket Yöneticisi) bulunamadı."
        $lblUpdateProgressText.Text = "Winget bulunamadı."
        Write-CmdLog "GÜNCELLEME" "winget.exe sistemde bulunamadı." "Red"
        return
    }

    # Tehlikeli ve körlemesine sürüm güncellemesi yapan --include-unknown kaldırıldı.
    # msstore filtrelemesi ayrıştırma aşamasında Store checkbox durumuna göre yapılır.
    $wArgs = "upgrade --disable-interactivity --accept-source-agreements"
    Write-CmdLog "GÜNCELLEME" "winget $wArgs (Kurulu program güncellemeleri taranıyor...)" "Cyan"

    if (Test-Path $script:wingetLog) { Remove-Item $script:wingetLog -Force -ErrorAction SilentlyContinue }

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = "cmd.exe"
    $psi.Arguments = "/c chcp 65001 >nul & winget $wArgs > `"$($script:wingetLog)`" 2>&1"
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true

    try {
        $script:wingetProc = [System.Diagnostics.Process]::Start($psi)
        $script:wingetTimer.Start()
    } catch {
        $lblAvailableUpdates.Text = "Hata"
        $lblUpdateProgressText.Text = "Tarama başlatılamadı: $($_.Exception.Message)"
    }
}

# ------------------------------------------------------------------------------
# 14. Temizlik Motoru (STA Runspace, Arka Planda Sıfır Donma, Hacim Korumalı)
# ------------------------------------------------------------------------------
$script:cleanProgressQueue = [System.Collections.Concurrent.ConcurrentQueue[psobject]]::new()
$script:cleanRunspaceHost  = $null
$script:cleanRunspace      = $null
$script:cleanAsyncResult   = $null
[double]$script:cleanTotalFreed  = 0
$script:cleanLogEntries          = @()
[double]$script:initialFreeSpace = 0

$script:cleanUiTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:cleanUiTimer.Interval = [TimeSpan]::FromMilliseconds(50)

$script:cleanUiTimer.Add_Tick({
    $item = $null
    while ($script:cleanProgressQueue.TryDequeue([ref]$item)) {
        if ($item.Type -eq "Progress") {
            $lblCleanStatus.Text = $item.Msg
            $progClean.Value = $item.Prog
            Write-CmdLog "İŞLEM" $item.Msg "Yellow"
        }
        elseif ($item.Type -eq "Log") {
            if ($item.LogText) {
                $script:cleanLogEntries += $item.LogText
                Write-CmdLog "TEMİZLİK" $item.LogText "Green"
            }
            if ($item.Freed) { $script:cleanTotalFreed += $item.Freed }
        }
        elseif ($item.Type -eq "RpFailedPrompt") {
            Write-CmdLog "UYARI" "Geri yükleme noktası oluşturulamadı. Kullanıcı onayı bekleniyor..." "Yellow"
            $detail = if ($item.ErrorMsg) { "`n`nDetay / Hata: $($item.ErrorMsg)" } else { "" }
            $promptMsg = "Geri yükleme noktası oluşturulamadı (Sistem koruması kapalı veya hata oluştu).$detail`n`nNoktasız devam edilsin mi?"
            $ans = [System.Windows.MessageBox]::Show($window, $promptMsg, "TemizWin - Geri Yükleme Uyarısı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
            if ($script:cleanSyncState) {
                $script:cleanSyncState['UserChoice'] = ($ans -eq [System.Windows.MessageBoxResult]::Yes)
                $script:cleanSyncState['DecisionMade'] = $true
            }
        }
        elseif ($item.Type -eq "Aborted") {
            Write-CmdLog "TEMİZLİK" "Temizlik iptal edildi: $($item.Msg)" "Red"
            $script:cleanUiTimer.Stop()
            $script:isCleaningRunning = $false
            $script:isTamBakimMode = $false
            $progClean.Value = 0
            $lblCleanStatus.Text = "Temizlik İptal Edildi: $($item.Msg)"
            if ($lblMainStatus) { $lblMainStatus.Text = "Temizlik İptal Edildi." }
            $btnExecuteClean.IsEnabled = $true
            if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }

            if ($chkRestorePointClean) { $chkRestorePointClean.IsChecked = $false }
            if ($chkRestorePointMain) { $chkRestorePointMain.IsChecked = $false }

            if ($script:cleanRunspace) {
                try {
                    $script:cleanRunspace.EndInvoke($script:cleanAsyncResult) | Out-Null
                    $script:cleanRunspace.Dispose()
                } catch {}
                $script:cleanRunspace = $null
                $script:cleanAsyncResult = $null
            }
            if ($script:cleanRunspaceHost) {
                try { $script:cleanRunspaceHost.Dispose() } catch {}
                $script:cleanRunspaceHost = $null
            }

            [System.Windows.MessageBox]::Show($window, "Temizlik işlemi iptal edildi.`n`nGeri yükleme noktası oluşturulamadığı için hiçbir dosya veya ayar silinmedi.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
        }
        elseif ($item.Type -eq "Done") {
            $script:cleanUiTimer.Stop()
            $script:isCleaningRunning = $false
            $progClean.Value = 100
            $btnExecuteClean.IsEnabled = $true
            if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }

            # UI Thread üzerinde de pano kesin olarak sıfırlanır (Çift Güvence)
            try { [System.Windows.Clipboard]::Clear() } catch {}

            # Tek seferlik geri yükleme noktası kutuları temizlik tamamlanınca otomatik sıfırlanır
            if ($chkRestorePointClean) { $chkRestorePointClean.IsChecked = $false }
            if ($chkRestorePointMain) { $chkRestorePointMain.IsChecked = $false }

            if ($script:cleanRunspace) {
                try {
                    $script:cleanRunspace.EndInvoke($script:cleanAsyncResult) | Out-Null
                    $script:cleanRunspace.Dispose()
                } catch {}
                $script:cleanRunspace = $null
                $script:cleanAsyncResult = $null
            }
            if ($script:cleanRunspaceHost) {
                try { $script:cleanRunspaceHost.Dispose() } catch {}
                $script:cleanRunspaceHost = $null
            }

            [double]$finalFree = 0
            $driveC2 = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.Name -like "C:*" }
            if ($driveC2) { $finalFree = [double]$driveC2.AvailableFreeSpace }
            [double]$initFree = [double]$script:initialFreeSpace
            [double]$realFreed = if ($finalFree -gt $initFree) { $finalFree - $initFree } else { [double]0 }
            [int]$skippedTotal = if ($item.SkippedCount) { [int]$item.SkippedCount } else { 0 }

            $script:cleanLogEntries += "------------------------------------------------------------------------------"
            $script:cleanLogEntries += "SONUÇ:"
            $script:cleanLogEntries += "Silinen Çöp Veri       : $(Format-Size $script:cleanTotalFreed)"
            if ($realFreed -gt 0) {
                $script:cleanLogEntries += "Diskte Net Açılan Alan : $(Format-Size $realFreed)"
                $script:cleanLogEntries += "Açıklama Notu          : (Fark; temizlik öncesi alınan Sistem Geri Yükleme güvenlik yedeği ve sıkıştırılmış dosyalardan kaynaklanır.)"
            }
            $script:cleanLogEntries += "Eski Boş Alan (C:)     : $(Format-Size $script:initialFreeSpace)"
            $script:cleanLogEntries += "Yeni Boş Alan (C:)     : $(Format-Size $finalFree)"
            if ($skippedTotal -gt 0) {
                $script:cleanLogEntries += "Kilitli/Atlanan Dosya  : $skippedTotal adet (kullanımda olduğu için güvenle korundu)"
            }
            $script:cleanLogEntries += "Kilitli dosyalar güvenle atlandı, şifrelere ve oyunlara dokunulmadı."
            $script:cleanLogEntries += "=============================================================================="

            $desktopPath = [Environment]::GetFolderPath('Desktop')
            $reportFile = "$desktopPath\TemizWin_Rapor_$((Get-Date).ToString('yyyyMMdd_HHmmss')).txt"
            try {
                [System.IO.File]::WriteAllLines($reportFile, $script:cleanLogEntries, [System.Text.Encoding]::UTF8)
                $script:lastReportPath = $reportFile
            } catch {}

            $bestFreed = if ($realFreed -gt 0) { $realFreed } else { $script:cleanTotalFreed }
            $lblCleanStatus.Text = "Temizlik Tamamlandı! $(Format-Size $bestFreed) alan açıldı 🚀"
            Refresh-SystemStats
            Scan-AllCleanupSizes
            $skipMsg = if ($skippedTotal -gt 0) { " | Kilitli/Atlanan: $skippedTotal dosya" } else { "" }
            $logFreedFmt = if ($realFreed -gt 0) { "Silinen Çöp: $(Format-Size $script:cleanTotalFreed) (Net Açılan: $(Format-Size $realFreed))" } else { "Silinen Çöp: $(Format-Size $script:cleanTotalFreed)" }
            Write-CmdLog "SONUÇ" "Temizlik tamamlandı! $logFreedFmt$skipMsg" "Green"
            Write-CmdLog "RAPOR" "Masaüstü raporu kaydedildi: $reportFile" "Cyan"

            $freedLines = if ($realFreed -gt 0) {
                "• Silinen Çöp Veri : $(Format-Size $script:cleanTotalFreed)`n" +
                "• Diskte Net Açılan Alan : $(Format-Size $realFreed)`n" +
                "  Açıklama Notu: (Fark; temizlik öncesi alınan Sistem Geri Yükleme güvenlik yedeği ve sıkıştırılmış dosyalardan kaynaklanır.)`n"
            } else {
                "• Silinen Çöp Veri : $(Format-Size $script:cleanTotalFreed)`n"
            }
            $currentFreeLine = if ($finalFree -gt 0) { "• C: Güncel Boş Alan : $(Format-Size $finalFree)`n" } else { "" }
            $skipLine = if ($skippedTotal -gt 0) { "• Kilitli/Atlanan Dosya : $skippedTotal adet (korundu)`n" } else { "" }

            if ($lblMainStatus) { $lblMainStatus.Text = "Bakım Tamamlandı! $(Format-Size $bestFreed) alan açıldı 🚀" }
            $msgNormal = "Temizlik başarıyla tamamlandı!`n`n" +
                $freedLines +
                $currentFreeLine +
                $skipLine + "`n" +
                "Rapor masaüstünüze kaydedildi.`n`n" +
                "Dosya: $reportFile"
            [System.Windows.MessageBox]::Show($window, $msgNormal, "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
        }
    }
})

function Execute-CleanEngine([bool]$createRestorePoint = $false) {
    if ($script:isCleaningRunning) { return }
    if ($script:isHealthRunning) {
        if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
        $btnExecuteClean.IsEnabled = $true
        $script:isTamBakimMode = $false
        $script:isCleaningRunning = $false
        if ($lblMainStatus) { $lblMainStatus.Text = "Hazır" }
        [System.Windows.MessageBox]::Show($window, "Şu anda arka planda bir sistem sağlığı/onarım işlemi devam ediyor.`nLütfen mevcut işlemin bitmesini bekleyin.", "TemizWin - Sağlık İşlemi Sürüyor", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }

    # Hangi kategorilerin seçildiğini belirle
    $selectedMap = [System.Collections.Generic.Dictionary[string, bool]]::new()
    $hasAny = $false
    foreach ($item in @(
        @{ K = "Temp";        C = $chkTemp },
        @{ K = "WinUpdate";   C = $chkWinUpdate },
        @{ K = "Recycle";     C = $chkRecycle },
        @{ K = "EventLogs";   C = $chkEventLogs },
        @{ K = "Wsxx";        C = $chkWsxx },
        @{ K = "DeliveryOpt"; C = $chkDeliveryOpt },
        @{ K = "WinOld";      C = $chkWinOld },
        @{ K = "DriverStore"; C = $chkDriverStore },
        @{ K = "Crash";       C = $chkCrash },
        @{ K = "Thumbs";      C = $chkThumbs },
        @{ K = "Prefetch";    C = $chkPrefetch },
        @{ K = "Font";        C = $chkFont },
        @{ K = "Defender";    C = $chkDefender },
        @{ K = "INetCache";   C = $chkINetCache },
        @{ K = "Chrome";      C = $chkChrome },
        @{ K = "Edge";        C = $chkEdge },
        @{ K = "Firefox";     C = $chkFirefox },
        @{ K = "Opera";       C = $chkOpera },
        @{ K = "Brave";       C = $chkBrave },
        @{ K = "Apps";        C = $chkApps },
        @{ K = "AppNotion";   C = $chkAppNotion },
        @{ K = "AppVSCode";   C = $chkAppVSCode },
        @{ K = "AppPython";   C = $chkAppPython },
        @{ K = "AppVlc";      C = $chkAppVlc },
        @{ K = "TraceSystem"; C = $chkTraceSystem },
        @{ K = "TraceChrome"; C = $chkTraceChrome },
        @{ K = "TraceEdge";   C = $chkTraceEdge },
        @{ K = "TraceBrave";  C = $chkTraceBrave },
        @{ K = "BrowserHistory";   C = $chkBrowserHistory },
        @{ K = "BrowserCookies";   C = $chkBrowserCookies },
        @{ K = "BrowserPasswords"; C = $chkBrowserPasswords },
        @{ K = "Shader";      C = $chkShader },
        @{ K = "GameClients"; C = $chkGameClients },
        @{ K = "Dns";         C = $chkDns },
        @{ K = "OldRestore";  C = $chkOldRestore },
        @{ K = "Shortcuts";   C = $chkShortcuts }
    )) {
        $chk = ($item.C -and $item.C.IsChecked -eq $true)
        $selectedMap[$item.K] = $chk
        if ($chk) { $hasAny = $true }
    }

    if (-not $hasAny -and -not $createRestorePoint) {
        $script:isCleaningRunning = $false
        $btnExecuteClean.IsEnabled = $true
        if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
        [System.Windows.MessageBox]::Show($window, "Lütfen temizlemek istediğiniz en az bir kategori seçin.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }

    # Güvenlik Onayı: Windows.old seçildiyse geri dönüşün kapanacağı uyarısını ver
    if ($selectedMap["WinOld"]) {
        $winOldMsg = "⚠️ DİKKAT: Eski Windows Kurulum Dosyaları (Windows.old) Silinecek!`n`n" +
            "Windows.old klasörü silindiğinde, önceki Windows sürümünüze geri dönme (Geri Al / Rollback) imkanınız kalıcı olarak ortadan kalkacaktır.`n`n" +
            "Eğer mevcut sisteminizden memnunsanız ve diskte gigabaytlarca yer açmak istiyorsanız devam edebilirsiniz.`n`n" +
            "Windows.old klasörünü kalıcı olarak silmek istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $winOldMsg, "TemizWin - Windows.old Silme Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            if ($chkWinOld) { $chkWinOld.IsChecked = $false }
            $selectedMap["WinOld"] = $false
            
            $hasRemaining = $false
            foreach ($v in $selectedMap.Values) { if ($v) { $hasRemaining = $true; break } }
            if (-not $hasRemaining -and -not $createRestorePoint) {
                Write-CmdLog "TEMİZLİK" "[i] Windows.old dışında seçili kategori kalmadığı için işlem iptal edildi." "Yellow"
                if ($lblCleanStatus) { $lblCleanStatus.Text = "İptal Edildi: Windows.old dışında seçili kategori yok." }
                $script:isCleaningRunning = $false
                $btnExecuteClean.IsEnabled = $true
                if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
                if ($script:isTamBakimMode) {
                    $script:isTamBakimMode = $false
                    if ($lblMainStatus) { $lblMainStatus.Text = "Hazır" }
                }
                return
            } else {
                Write-CmdLog "TEMİZLİK" "[i] Windows.old silme onayı verilmedi; bu adım atlanarak diğer temizliklere devam ediliyor." "Yellow"
            }
        }
    }

    # Güvenlik Onayı: Olay Günlükleri seçildiyse kullanıcıdan açık onay al
    if ($selectedMap["EventLogs"]) {
        $evtMsg = "⚠️ DİKKAT: Windows Olay Günlükleri (Event Logs) Temizlenecek!`n`n" +
            "Sistem, uygulama ve hata günlükleri silinecektir. (Güvenlik / Security denetim günlüğü KORUNACAKTIR.)`n`n" +
            "Geçmiş sorun giderme ve hata analiz kayıtları sıfırlanacaktır.`n`n" +
            "Olay günlüklerini silmek istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $evtMsg, "TemizWin - Olay Günlükleri Silme Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            if ($chkEventLogs) { $chkEventLogs.IsChecked = $false }
            $selectedMap["EventLogs"] = $false
            
            $hasRemaining = $false
            foreach ($v in $selectedMap.Values) { if ($v) { $hasRemaining = $true; break } }
            if (-not $hasRemaining -and -not $createRestorePoint) {
                Write-CmdLog "TEMİZLİK" "[i] Olay günlükleri dışında seçili kategori kalmadığı için işlem iptal edildi." "Yellow"
                if ($lblCleanStatus) { $lblCleanStatus.Text = "İptal Edildi: Olay günlükleri dışında seçili kategori yok." }
                $script:isCleaningRunning = $false
                $btnExecuteClean.IsEnabled = $true
                if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
                if ($script:isTamBakimMode) {
                    $script:isTamBakimMode = $false
                    if ($lblMainStatus) { $lblMainStatus.Text = "Hazır" }
                }
                return
            } else {
                Write-CmdLog "TEMİZLİK" "[i] Olay günlükleri silme onayı verilmedi; bu adım atlanarak diğer temizliklere devam ediliyor." "Yellow"
            }
        }
    }

    # Güvenlik Onayı: Eski Geri Yükleme Noktaları seçildiyse kullanıcıdan açık onay al
    if ($selectedMap["OldRestore"]) {
        $rpMsg = "⚠️ DİKKAT: Eski Sistem Geri Yükleme Noktaları Temizlenecek!`n`n" +
            "En güncel (en son alınan) geri yükleme noktası KESİNLİKLE KORUNACAK, yalnızca daha eski noktalar temizlenecektir.`n`n" +
            "Eski geri yükleme noktalarını temizlemek istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $rpMsg, "TemizWin - Geri Yükleme Noktaları Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            if ($chkOldRestore) { $chkOldRestore.IsChecked = $false }
            $selectedMap["OldRestore"] = $false
            
            $hasRemaining = $false
            foreach ($v in $selectedMap.Values) { if ($v) { $hasRemaining = $true; break } }
            if (-not $hasRemaining -and -not $createRestorePoint) {
                Write-CmdLog "TEMİZLİK" "[i] Geri yükleme noktaları dışında seçili kategori kalmadığı için işlem iptal edildi." "Yellow"
                if ($lblCleanStatus) { $lblCleanStatus.Text = "İptal Edildi: Geri yükleme noktaları dışında seçili kategori yok." }
                $script:isCleaningRunning = $false
                $btnExecuteClean.IsEnabled = $true
                if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
                if ($script:isTamBakimMode) {
                    $script:isTamBakimMode = $false
                    if ($lblMainStatus) { $lblMainStatus.Text = "Hazır" }
                }
                return
            } else {
                Write-CmdLog "TEMİZLİK" "[i] Geri yükleme noktaları silme onayı verilmedi; bu adım atlanarak diğer temizliklere devam ediliyor." "Yellow"
            }
        }
    }

    # Güvenlik Onayı: WinSxS Derin Bileşen Temizliği (/ResetBase) seçildiyse kullanıcıdan açık onay al
    if ($selectedMap["Wsxx"]) {
        $wsxxMsg = "⚠️ Eski Windows Güncelleme Yedekleri Silinecek`n`n" +
            "Diskte yüksek alan açılacaktır. Gelecekte gelecek yeni güncellemeleri kesinlikle etkilemez, yalnızca geçmiş yedekleri temizler.`n`n" +
            "Devam etmek istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $wsxxMsg, "TemizWin - WinSxS Bileşen Temizliği Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            if ($chkWsxx) { $chkWsxx.IsChecked = $false }
            $selectedMap["Wsxx"] = $false
            
            $hasRemaining = $false
            foreach ($v in $selectedMap.Values) { if ($v) { $hasRemaining = $true; break } }
            if (-not $hasRemaining -and -not $createRestorePoint) {
                Write-CmdLog "TEMİZLİK" "[i] WinSxS dışında seçili kategori kalmadığı için işlem iptal edildi." "Yellow"
                if ($lblCleanStatus) { $lblCleanStatus.Text = "İptal Edildi: WinSxS dışında seçili kategori yok." }
                $script:isCleaningRunning = $false
                $btnExecuteClean.IsEnabled = $true
                if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
                if ($script:isTamBakimMode) {
                    $script:isTamBakimMode = $false
                    if ($lblMainStatus) { $lblMainStatus.Text = "Hazır" }
                }
                return
            } else {
                Write-CmdLog "TEMİZLİK" "[i] WinSxS derin temizlik onayı verilmedi; bu adım atlanarak diğer temizliklere devam ediliyor." "Yellow"
            }
        }
    }

    # Güvenlik Onayı: Şifreler veya Çerezler seçildiyse kullanıcıdan açık onay al
    if ($selectedMap["BrowserPasswords"]) {
        $warnMsg = "⚠️ DİKKAT: Kayıtlı Şifreler ve Otomatik Doldurma Verileri Silinecek!`n`n" +
            "Seçtiğiniz tarayıcılarda kayıtlı TÜM hesap şifreleri, kullanıcı adları, form ve adres otomatik tamamlama verileri kalıcı olarak silinecektir.`n`n"
        if ($selectedMap["BrowserCookies"]) {
            $warnMsg += "Ayrıca çerezler seçildiği için tüm açık web oturumlarınız da kapatılacaktır.`n`n"
        }
        $warnMsg += "Şifrelerinizi hatırlamıyorsanız hesaplarınıza tekrar giriş yapamayabilirsiniz.`n`nBu işlemi onaylıyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $warnMsg, "TemizWin - Kritik Veri Silme Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            $script:isCleaningRunning = $false
            $btnExecuteClean.IsEnabled = $true
            if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
            return
        }
    }
    elseif ($selectedMap["BrowserCookies"]) {
        $cookieMsg = "Tarayıcı çerezleri silinecektir.`n`n" +
            "Tüm web sitelerindeki açık oturumlarınız (Google, YouTube, e-posta, sosyal medya vb.) kapatılacaktır ve tekrar giriş yapmanız gerekecektir.`n`n" +
            "(Not: Kayıtlı şifreleriniz silinmez, yalnızca oturumlar kapatılır.)`n`n" +
            "Devam etmek istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $cookieMsg, "TemizWin - Açık Oturumları Kapatma Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) {
            $script:isCleaningRunning = $false
            $btnExecuteClean.IsEnabled = $true
            if ($btnFullMaintenance) { $btnFullMaintenance.IsEnabled = $true }
            return
        }
    }

    # Madde 8: ListBox'ta kullanıcının tek tek işaretlediği kırık kısayolları topla
    $shortcutsToDelete = @()
    if ($selectedMap["Shortcuts"] -and $lstBrokenShortcuts) {
        foreach ($item in $lstBrokenShortcuts.Items) {
            if ($item -is [System.Windows.Controls.CheckBox] -and $item.IsChecked -eq $true) {
                $shortcutsToDelete += [string]$item.Tag
            }
        }
    }

    $script:isCleaningRunning = $true
    $btnExecuteClean.IsEnabled = $false
    $progClean.Value = 0
    $lblCleanStatus.Text = "Temizlik motoru başlatılıyor (Arka Plan STA Runspace)..."

    $selectedCount = ($selectedMap.Values | Where-Object { $_ -eq $true }).Count
    Write-CmdLog "TEMİZLİK" ">>> Sistem temizliği başlatıldı ($selectedCount kategori seçildi)..." "Green"
    if ($createRestorePoint) {
        Write-CmdLog "GÜVENLİK" "Checkpoint-Computer -Description 'TemizWin_Sistem_Bakimi' (Geri yükleme noktası alınıyor...)" "Yellow"
    }

    $script:cleanProgressQueue = [System.Collections.Concurrent.ConcurrentQueue[psobject]]::new()
    $script:cleanTotalFreed = 0
    $script:cleanLogEntries = @()
    $script:cleanLogEntries += "=============================================================================="
    $script:cleanLogEntries += "                   TEMIZWIN SISTEM TEMIZLIK RAPORU                            "
    $script:cleanLogEntries += "Tarih: $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))"
    $script:cleanLogEntries += "Yönetici Modu: $($script:isAdmin)"
    $script:cleanLogEntries += "=============================================================================="

    $driveC1 = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.Name -like "C:*" }
    [double]$script:initialFreeSpace = if ($driveC1) { [double]$driveC1.AvailableFreeSpace } else { [double]0 }

    # Parametreleri Runspace'e aktar
    $runspaceScript = {
        param($q, $sel, $doRestorePoint, $shortcutsList, $envMap, $syncState)

        $script:cleanSkippedCount = 0

        function Format-SizeLocal([double]$bytes) {
            if ($bytes -ge 1GB) { return "{0:N2} GB" -f ($bytes / 1GB) }
            if ($bytes -ge 1MB) { return "{0:N1} MB" -f ($bytes / 1MB) }
            if ($bytes -ge 1KB) { return "{0:N0} KB" -f ($bytes / 1KB) }
            if ($bytes -gt 0) { return "{0:N0} B" -f $bytes }
            return "0 KB"
        }

        function Format-WmiDateTimeLocal([string]$rawDate) {
            if (-not $rawDate) { return (Get-Date).ToString("yyyy-MM-dd HH:mm:ss") }
            try {
                return [System.Management.ManagementDateTimeConverter]::ToDateTime($rawDate).ToString("yyyy-MM-dd HH:mm:ss")
            } catch {
                try {
                    if ($rawDate -match '^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})') {
                        $dt = [datetime]::new([int]$Matches[1], [int]$Matches[2], [int]$Matches[3], [int]$Matches[4], [int]$Matches[5], [int]$Matches[6])
                        return $dt.ToString("yyyy-MM-dd HH:mm:ss")
                    }
                } catch {}
                return $rawDate
            }
        }

        # JUNCTION KORUMALI GÜVENLİ DOSYA TEMİZLEME MOTORU
        function Clean-PathSafe([string]$targetDir) {
            if (-not (Test-Path -LiteralPath $targetDir -ErrorAction SilentlyContinue)) { return 0 }
            [double]$freed = 0
            try {
                $dirQueue = New-Object System.Collections.Generic.Queue[string]
                $dirQueue.Enqueue($targetDir)
                $dirsToDelete = New-Object System.Collections.Generic.List[string]

                while ($dirQueue.Count -gt 0) {
                    $curr = $dirQueue.Dequeue()
                    try {
                        $di = New-Object System.IO.DirectoryInfo($curr)
                        foreach ($f in $di.EnumerateFiles()) {
                            $origAttr = $f.Attributes
                            $isReadOnly = (($origAttr -band [System.IO.FileAttributes]::ReadOnly) -ne 0)
                            try {
                                $len = $f.Length
                                if ($isReadOnly) {
                                    $f.Attributes = [System.IO.FileAttributes]::Normal
                                }
                                [System.IO.File]::Delete($f.FullName)
                                $freed += $len
                            } catch {
                                if ($isReadOnly) {
                                    try { $f.Attributes = $origAttr } catch {}
                                }
                                $script:cleanSkippedCount++
                            }
                        }
                        foreach ($d in $di.EnumerateDirectories()) {
                            # MADDE 4: JUNCTION / SYMBOLIC LINK KORUMASI (ASLA İÇİNE GİRİLMEZ)
                            if (($d.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0) {
                                $dirQueue.Enqueue($d.FullName)
                                $dirsToDelete.Add($d.FullName)
                            }
                        }
                    } catch {}
                }

                # Boş kalan alt klasörleri tersten güvenle sil (hedef ana klasör korunur)
                $dirsToDelete.Reverse()
                foreach ($dPath in $dirsToDelete) {
                    try {
                        if ((Get-ChildItem -LiteralPath $dPath -Force -ErrorAction SilentlyContinue).Count -eq 0) {
                            $dInfo = New-Object System.IO.DirectoryInfo($dPath)
                            $origDAttr = $dInfo.Attributes
                            $isDirReadOnly = (($origDAttr -band [System.IO.FileAttributes]::ReadOnly) -ne 0)
                            try {
                                if ($isDirReadOnly) {
                                    $dInfo.Attributes = [System.IO.FileAttributes]::Normal
                                }
                                [System.IO.Directory]::Delete($dPath, $false)
                            } catch {
                                if ($isDirReadOnly) {
                                    try { $dInfo.Attributes = $origDAttr } catch {}
                                }
                            }
                        }
                    } catch {}
                }
            } catch {}
            return $freed
        }

        # Chromium Tabanlı Tarayıcılarda Tüm Profilleri Temizleme
        function Clean-BrowserTargetFiles([string]$targetType) {
            [double]$freed = 0
            $userDataDirs = @(
                "$($envMap['LOCALAPPDATA'])\Google\Chrome\User Data",
                "$($envMap['LOCALAPPDATA'])\Microsoft\Edge\User Data",
                "$($envMap['LOCALAPPDATA'])\BraveSoftware\Brave-Browser\User Data",
                "$($envMap['APPDATA'])\Opera Software\Opera Stable",
                "$($envMap['APPDATA'])\Opera Software\Opera GX Stable",
                "$($envMap['LOCALAPPDATA'])\Opera Software\Opera Stable",
                "$($envMap['LOCALAPPDATA'])\Opera Software\Opera GX Stable"
            )

            $targetFiles = @()
            $targetDirs  = @()
            if ($targetType -eq "History") {
                $targetFiles = @(
                    "History", "History-journal",
                    "Visited Links",
                    "Top Sites", "Top Sites-journal",
                    "Network Action Predictor", "Network Action Predictor-journal",
                    "Shortcuts", "Shortcuts-journal",
                    "DownloadMetadata",
                    "History Provider Cache"
                )
                $targetDirs = @("Sessions", "Sessions_Encrypted", "JumpListIconsMostVisited")
            }
            elseif ($targetType -eq "Cookies") {
                $targetFiles = @(
                    "Cookies", "Cookies-journal",
                    "Network\Cookies", "Network\Cookies-journal",
                    "Network\Device Bound Sessions", "Network\Device Bound Sessions-journal",
                    "Network\Trust Tokens", "Network\Trust Tokens-journal",
                    "Extension Cookies", "Extension Cookies-journal",
                    "DIPS", "DIPS-journal"
                )
            }
            elseif ($targetType -eq "Passwords") {
                $targetFiles = @(
                    "Login Data", "Login Data-journal",
                    "Login Data For Account", "Login Data For Account-journal",
                    "Web Data", "Web Data-journal",
                    "Account Web Data", "Account Web Data-journal",
                    "Affiliation Database", "Affiliation Database-journal"
                )
            }

            foreach ($ud in $userDataDirs) {
                if (Test-Path -LiteralPath $ud -ErrorAction SilentlyContinue) {
                    try {
                        $profiles = Get-ChildItem -Path $ud -Directory -ErrorAction SilentlyContinue | Where-Object {
                            $_.Name -eq "Default" -or $_.Name -like "Profile *"
                        }
                        $allDirs = [System.Collections.Generic.List[string]]::new()
                        foreach ($p in $profiles) { $allDirs.Add($p.FullName) }
                        if (Test-Path (Join-Path $ud "Preferences") -ErrorAction SilentlyContinue) {
                            $allDirs.Add($ud)
                        }

                        foreach ($dir in $allDirs) {
                            # 1. Hedef dosyaları temizle
                            foreach ($tf in $targetFiles) {
                                $filePath = Join-Path $dir $tf
                                if (Test-Path -LiteralPath $filePath -ErrorAction SilentlyContinue) {
                                    try {
                                        $len = (Get-Item -LiteralPath $filePath -Force -ErrorAction SilentlyContinue).Length
                                        [System.IO.File]::Delete($filePath)
                                        $freed += $len
                                    } catch {
                                        try {
                                            Start-Sleep -Milliseconds 150
                                            [System.IO.File]::Delete($filePath)
                                            $freed += $len
                                        } catch {}
                                    }
                                }
                            }

                            # 2. Oturum ve sekme klasörlerini temizle
                            foreach ($td in $targetDirs) {
                                $subDir = Join-Path $dir $td
                                if (Test-Path -LiteralPath $subDir -ErrorAction SilentlyContinue) {
                                    try {
                                        $subFiles = Get-ChildItem -Path $subDir -File -Force -Recurse -ErrorAction SilentlyContinue
                                        foreach ($sf in $subFiles) {
                                            try {
                                                $sLen = $sf.Length
                                                [System.IO.File]::Delete($sf.FullName)
                                                $freed += $sLen
                                            } catch {
                                                try {
                                                    Start-Sleep -Milliseconds 150
                                                    [System.IO.File]::Delete($sf.FullName)
                                                    $freed += $sLen
                                                } catch {}
                                            }
                                        }
                                    } catch {}
                                }
                            }
                        }
                    } catch {}
                }
            }

            # Firefox profilleri
            $firefoxDir = "$($envMap['APPDATA'])\Mozilla\Firefox\Profiles"
            if (Test-Path -LiteralPath $firefoxDir -ErrorAction SilentlyContinue) {
                try {
                    $ffProfiles = Get-ChildItem -Path $firefoxDir -Directory -ErrorAction SilentlyContinue
                    foreach ($ffp in $ffProfiles) {
                        $ffFiles = @()
                        if ($targetType -eq "Cookies") {
                            $ffFiles = @("cookies.sqlite", "cookies.sqlite-wal", "cookies.sqlite-shm")
                        }
                        elseif ($targetType -eq "Passwords") {
                            $ffFiles = @("logins.json", "logins-backup.json", "key4.db", "formhistory.sqlite", "formhistory.sqlite-wal")
                        }
                        elseif ($targetType -eq "History") {
                            $ffFiles = @("formhistory.sqlite", "formhistory.sqlite-wal", "sessionstore.jsonlz4")
                            $sessBackupDir = Join-Path $ffp.FullName "sessionstore-backups"
                            if (Test-Path -LiteralPath $sessBackupDir -ErrorAction SilentlyContinue) {
                                try {
                                    $sbFiles = Get-ChildItem -Path $sessBackupDir -File -Force -ErrorAction SilentlyContinue
                                    foreach ($sbf in $sbFiles) {
                                        try {
                                            $len = $sbf.Length
                                            [System.IO.File]::Delete($sbf.FullName)
                                            $freed += $len
                                        } catch {}
                                    }
                                } catch {}
                            }
                        }
                        foreach ($fff in $ffFiles) {
                            $filePath = Join-Path $ffp.FullName $fff
                            if (Test-Path -LiteralPath $filePath -ErrorAction SilentlyContinue) {
                                try {
                                    $len = (Get-Item -LiteralPath $filePath -Force -ErrorAction SilentlyContinue).Length
                                    [System.IO.File]::Delete($filePath)
                                    $freed += $len
                                } catch {
                                    try {
                                        Start-Sleep -Milliseconds 150
                                        [System.IO.File]::Delete($filePath)
                                        $freed += $len
                                    } catch {}
                                }
                            }
                        }
                    }
                } catch {}
            }

            return $freed
        }

        function Clean-ChromiumAllProfiles([string]$userDataDir) {
            if (-not (Test-Path $userDataDir -ErrorAction SilentlyContinue)) { return 0 }
            [double]$tot = 0
            try {
                # 1. Kök User Data dizinindeki genel GPU ve bileşen önbellekleri
                $rootCacheFolders = @(
                    "GrShaderCache", "old_GrShaderCache_000", "ShaderCache", 
                    "component_crx_cache", "extensions_crx_cache", "GPUPersistentCache"
                )
                foreach ($rc in $rootCacheFolders) {
                    $rcPath = Join-Path $userDataDir $rc
                    if (Test-Path $rcPath) {
                        $tot += (Clean-PathSafe $rcPath)
                    }
                }

                # 2. Tüm profiller altındaki önbellekler (Default, Profile 1, Profile 2...)
                $profiles = Get-ChildItem -Path $userDataDir -Directory -ErrorAction SilentlyContinue | Where-Object {
                    $_.Name -eq "Default" -or $_.Name -like "Profile *"
                }
                foreach ($p in $profiles) {
                    $profileCacheFolders = @(
                        "Cache", "GPUCache", "Code Cache",
                        "DawnWebGPUCache", "DawnGraphiteCache", "AutofillAiModelCache",
                        "Shared Dictionary\cache",
                        "Service Worker\CacheStorage", "Service Worker\ScriptCache",
                        "File System", "Application Cache", "Media Cache"
                    )
                    foreach ($sub in $profileCacheFolders) {
                        $subPath = Join-Path $p.FullName $sub
                        if (Test-Path $subPath) {
                            $tot += (Clean-PathSafe $subPath)
                        }
                    }
                }
            } catch {}
            return $tot
        }

        # 0. AŞAMA: GERİ YÜKLEME NOKTASI (Madde 3 & 7 & Güvenlik Doğrulaması)
        if ($doRestorePoint) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 5; Msg = "1/3: Geri yükleme noktası oluşturuluyor (VSS snapshot)..." })
            $regPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore"
            $origFreq = $null
            $hasOrig = $false
            try {
                $prop = Get-ItemProperty -Path $regPath -Name "SystemRestorePointCreationFrequency" -ErrorAction SilentlyContinue
                if ($prop -and $prop.PSObject.Properties['SystemRestorePointCreationFrequency']) {
                    $origFreq = $prop.SystemRestorePointCreationFrequency
                    $hasOrig = $true
                }
                Set-ItemProperty -Path $regPath -Name "SystemRestorePointCreationFrequency" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            } catch {}

            $rpSuccess = $false
            $failReason = ""
            $resMsg = ""
            try {
                Checkpoint-Computer -Description "TemizWin_Sistem_Bakimi" -RestorePointType "MODIFY_SETTINGS" -ErrorAction Stop | Out-Null
                $latest = Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Select-Object -Last 1
                if ($latest -and $latest.Description -like "*TemizWin*") {
                    $rpSuccess = $true
                    $dtStr = Format-WmiDateTimeLocal $latest.CreationTime
                    $resMsg = "[+] Geri Yükleme Noktası: Başarıyla oluşturuldu ve doğrulandı ($dtStr)."
                } else {
                    Start-Sleep -Milliseconds 500
                    $latest = Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Select-Object -Last 1
                    if ($latest -and $latest.Description -like "*TemizWin*") {
                        $rpSuccess = $true
                        $dtStr = Format-WmiDateTimeLocal $latest.CreationTime
                        $resMsg = "[+] Geri Yükleme Noktası: Başarıyla oluşturuldu ve doğrulandı ($dtStr)."
                    } else {
                        $rpSuccess = $false
                        $failReason = "Geri yükleme noktası sistem kayıtlarında doğrulanamadı (Sistem koruması kapalı olabilir)."
                        $resMsg = "[-] Geri Yükleme Noktası: Oluşturulamadı ($failReason)"
                    }
                }
            } catch {
                $rpSuccess = $false
                $failReason = $_.Exception.Message
                $resMsg = "[-] Geri Yükleme Noktası: $failReason"
            } finally {
                # Madde 3: Kayıt defteri ayarı kesinlikle eski haline getirilir
                try {
                    if ($hasOrig) {
                        Set-ItemProperty -Path $regPath -Name "SystemRestorePointCreationFrequency" -Value $origFreq -Type DWord -Force -ErrorAction SilentlyContinue
                    } else {
                        Remove-ItemProperty -Path $regPath -Name "SystemRestorePointCreationFrequency" -Force -ErrorAction SilentlyContinue
                    }
                } catch {}
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = $resMsg; Freed = 0 })

            if (-not $rpSuccess) {
                if ($syncState) {
                    $syncState['DecisionMade'] = $false
                    $syncState['UserChoice'] = $false
                    $q.Enqueue([PSCustomObject]@{
                        Type = "RpFailedPrompt"
                        ErrorMsg = $failReason
                    })

                    while (-not $syncState['DecisionMade']) {
                        Start-Sleep -Milliseconds 100
                    }

                    if (-not $syncState['UserChoice']) {
                        $q.Enqueue([PSCustomObject]@{
                            Type = "Aborted"
                            Msg = "Geri yükleme noktası oluşturulamadığı için kullanıcı tarafından iptal edildi."
                        })
                        return
                    } else {
                        $q.Enqueue([PSCustomObject]@{
                            Type = "Log"
                            LogText = "[!] Kullanıcı onayı: Geri yükleme noktası olmadan temizliğe devam ediliyor."
                            Freed = 0
                        })
                    }
                }
            }
        }

        # 1. Temp
        if ($sel["Temp"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 12; Msg = "Sistem geçici dosyaları (%TEMP% ve Windows Temp) temizleniyor..." })
            $f = (Clean-PathSafe $envMap["TEMP"]) + (Clean-PathSafe "C:\Windows\Temp")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Sistem Geçici Dosyaları: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 2. Windows Update
        if ($sel["WinUpdate"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 20; Msg = "Windows Update indirme önbelleği temizleniyor..." })
            $f = 0
            try {
                try { Stop-Service -Name wuauserv -Force -ErrorAction SilentlyContinue; Stop-Service -Name bits -Force -ErrorAction SilentlyContinue } catch {}
                $f = Clean-PathSafe "C:\Windows\SoftwareDistribution\Download"
            } finally {
                try { Start-Service -Name bits -ErrorAction SilentlyContinue; Start-Service -Name wuauserv -ErrorAction SilentlyContinue } catch {}
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Windows Update Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 3. Geri Dönüşüm
        if ($sel["Recycle"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 28; Msg = "Geri Dönüşüm Kutusu boşaltılıyor..." })
            $f = 0
            try {
                $drives = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq "Fixed" }
                foreach ($d in $drives) {
                    $rbPath = Join-Path $d.Name '$Recycle.Bin'
                    $f += (Clean-PathSafe $rbPath)
                }
                Clear-RecycleBin -Force -ErrorAction SilentlyContinue | Out-Null
            } catch {}
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Geri Dönüşüm Kutusu: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 4. Olay ve Sistem Günlükleri (Event Logs / CBS / DISM)
        if ($sel["EventLogs"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 36; Msg = "Windows olay ve sistem güncelleme günlükleri temizleniyor..." })
            [double]$evtFreed = 0
            try {
                if (Test-Path "C:\Windows\Logs\waasmedic") {
                    Start-Process -FilePath "takeown.exe" -ArgumentList "/F ""C:\Windows\Logs\waasmedic"" /A /R /D Y" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                    Start-Process -FilePath "icacls.exe" -ArgumentList """C:\Windows\Logs\waasmedic"" /grant *S-1-5-32-544:F /T /C /Q" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                }
            } catch {}
            $evtFreed += (Clean-PathSafe "C:\Windows\Logs")
            $evtFreed += (Clean-PathSafe "C:\Windows\System32\LogFiles")
            $evtFreed += (Clean-PathSafe "C:\Windows\Panther")

            $evtDir = "C:\Windows\System32\winevt\Logs"
            [double]$beforeEvt = 0
            try {
                if (Test-Path $evtDir) {
                    $di = New-Object System.IO.DirectoryInfo($evtDir)
                    foreach ($f in $di.EnumerateFiles()) { $beforeEvt += $f.Length }
                }
            } catch {}

            try {
                wevtutil el | Where-Object { $_.Trim().ToLower() -ne "security" } | ForEach-Object { wevtutil cl "$_" 2>$null }
            } catch {}

            [double]$afterEvt = 0
            try {
                if (Test-Path $evtDir) {
                    $di = New-Object System.IO.DirectoryInfo($evtDir)
                    foreach ($f in $di.EnumerateFiles()) { $afterEvt += $f.Length }
                }
            } catch {}

            if ($beforeEvt -gt $afterEvt) { $evtFreed += ($beforeEvt - $afterEvt) }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Windows Olay ve Sistem Günlükleri: $(Format-SizeLocal $evtFreed) temizlendi (Güvenlik / Security denetim günlüğü korundu)."; Freed = $evtFreed })
        }

        # 5. WinSxS DISM (/ResetBase Derin Temizlik)
        if ($sel["Wsxx"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 44; Msg = "WinSxS bileşen deposu derin temizleniyor (DISM /ResetBase)..." })
            try {
                $p = Start-Process -FilePath "dism.exe" -ArgumentList "/online /cleanup-image /startcomponentcleanup /resetbase" -WindowStyle Hidden -Wait -PassThru -ErrorAction SilentlyContinue
            } catch {}
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] WinSxS Bileşen Deposu (DISM /ResetBase Derin Temizlik) tamamlandı."; Freed = 0 })
        }

        # 5.1 Teslim İyileştirme Dosyaları (Delivery Optimization)
        if ($sel["DeliveryOpt"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 48; Msg = "Teslim İyileştirme (Delivery Optimization) dosyaları temizleniyor..." })
            [double]$doFreed = 0
            $doFreed += (Clean-PathSafe "C:\Windows\SoftwareDistribution\DeliveryOptimization")
            $doFreed += (Clean-PathSafe "C:\Windows\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache")
            $doFreed += (Clean-PathSafe "C:\Windows\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Logs")
            $doFreed += (Clean-PathSafe "C:\ProgramData\Microsoft\Network\Downloader")
            try { Delete-DeliveryOptimizationCache -Force -ErrorAction SilentlyContinue } catch {}
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Teslim İyileştirme Dosyaları: $(Format-SizeLocal $doFreed) temizlendi."; Freed = $doFreed })
        }

        # 6. Eski Windows Kurulumları (Windows.old, $WINDOWS.~BT)
        if ($sel["WinOld"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 52; Msg = "Eski Windows kurulum kalıntıları (Windows.old, `$WINDOWS.~BT) temizleniyor..." })
            $f1 = 0; $f2 = 0
            if (Test-Path "C:\Windows.old") {
                try {
                    Start-Process -FilePath "takeown.exe" -ArgumentList "/F ""C:\Windows.old"" /A /R /D Y" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                    Start-Process -FilePath "icacls.exe" -ArgumentList """C:\Windows.old"" /grant *S-1-5-32-544:F /T /C /Q" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                } catch {}
                $f1 = Clean-PathSafe "C:\Windows.old"
                try { cmd.exe /c "rd /s /q C:\Windows.old 2>nul" } catch {}
            }
            if (Test-Path "C:\`$WINDOWS.~BT") {
                try {
                    Start-Process -FilePath "takeown.exe" -ArgumentList "/F ""C:\`$WINDOWS.~BT"" /A /R /D Y" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                    Start-Process -FilePath "icacls.exe" -ArgumentList """C:\`$WINDOWS.~BT"" /grant *S-1-5-32-544:F /T /C /Q" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                } catch {}
                $f2 = Clean-PathSafe "C:\`$WINDOWS.~BT"
                try { cmd.exe /c "rd /s /q ""C:\`$WINDOWS.~BT"" 2>nul" } catch {}
            }
            $tot = $f1 + $f2
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Eski Windows Kurulumları (Windows.old): $(Format-SizeLocal $tot) temizlendi."; Freed = $tot })
        }

        # 7. Crash Dumps & WER
        if ($sel["Crash"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 58; Msg = "Çökme dökümleri ve WER hata raporları temizleniyor..." })
            $f = (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\CrashDumps") +
                 (Clean-PathSafe "C:\ProgramData\Microsoft\Windows\WER") +
                 (Clean-PathSafe "C:\Windows\Minidump") +
                 (Clean-PathSafe "C:\Windows\System32\config\systemprofile\AppData\Local\CrashDumps") +
                 (Clean-PathSafe "C:\Windows\LiveKernelReports")
            if (Test-Path "C:\Windows\MEMORY.DMP") {
                try {
                    $memSize = (Get-Item "C:\Windows\MEMORY.DMP" -Force -ErrorAction SilentlyContinue).Length
                    Remove-Item "C:\Windows\MEMORY.DMP" -Force -ErrorAction SilentlyContinue
                    $f += $memSize
                } catch {}
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Çökme Dökümleri ve WER: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 8. Thumbs & İkon (Madde 5: SADECE thumbcache_*.db ve iconcache_*.db silinir, klasör korunur)
        if ($sel["Thumbs"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 64; Msg = "Küçük resim ve simge önbelleği (thumbcache / iconcache db) temizleniyor..." })
            $f = 0
            $explDir = "$($envMap['LOCALAPPDATA'])\Microsoft\Windows\Explorer"
            if (Test-Path $explDir) {
                Get-ChildItem -Path $explDir -Filter "*cache_*.db" -File -Force -ErrorAction SilentlyContinue | ForEach-Object {
                    try {
                        $f += $_.Length
                        [System.IO.File]::Delete($_.FullName)
                    } catch {}
                }
            }
            $mainIcon = "$($envMap['LOCALAPPDATA'])\IconCache.db"
            if (Test-Path $mainIcon) {
                try {
                    $fi = New-Object System.IO.FileInfo($mainIcon)
                    $f += $fi.Length
                    [System.IO.File]::Delete($mainIcon)
                } catch {}
            }
            # Windows dahili küçük resim temizleyicisini tetikle (kilitli dosyalara COM sinyali)
            try {
                Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VolumeCaches\Thumbnail Cache" -Name "StateFlags6109" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue
                Start-Process -FilePath "cleanmgr.exe" -ArgumentList "/sagerun:6109" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
                Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VolumeCaches\Thumbnail Cache" -Name "StateFlags6109" -Force -ErrorAction SilentlyContinue
            } catch {}
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Küçük Resim ve Simge Önbelleği (cache_*.db): $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 9. Prefetch
        if ($sel["Prefetch"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 70; Msg = "Prefetch önbelleği temizleniyor..." })
            $f = Clean-PathSafe "C:\Windows\Prefetch"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Prefetch: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 10. Font Cache
        if ($sel["Font"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 75; Msg = "Windows yazı tipi (Font) önbelleği temizleniyor..." })
            try { Stop-Service -Name "FontCache" -Force -ErrorAction SilentlyContinue } catch {}
            $f = Clean-PathSafe "C:\Windows\ServiceProfiles\LocalService\AppData\Local\FontCache"
            try { Start-Service -Name "FontCache" -ErrorAction SilentlyContinue } catch {}
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Yazı Tipi (Font) Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 10.1 Microsoft Defender Virüsten Koruma Önbelleği
        if ($sel["Defender"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 76; Msg = "Microsoft Defender tarama günlükleri ve tanım önbelleği temizleniyor..." })
            $f = (Clean-PathSafe "C:\ProgramData\Microsoft\Windows Defender\Support") +
                 (Clean-PathSafe "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Store") +
                 (Clean-PathSafe "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Results\Quick") +
                 (Clean-PathSafe "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Results\Resource") +
                 (Clean-PathSafe "C:\ProgramData\Microsoft\Windows Defender\Definition Updates\Backup")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Microsoft Defender Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 10.2 Geçici İnternet Dosyaları (INetCache & WebCache)
        if ($sel["INetCache"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 78; Msg = "Geçici internet dosyaları (INetCache & WebCache) temizleniyor..." })
            try {
                Start-Process -FilePath "rundll32.exe" -ArgumentList "inetcpl.cpl,ClearMyTracksByProcess 8" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue
            } catch {}
            $f = (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Windows\INetCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Windows\WebCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Windows\IEDownloadHistory")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Geçici İnternet Dosyaları (INetCache): $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # Açık Tarayıcıları Otomatik Kapatma (Kilitli Dosyaları Çözmek ve Eksiksiz Temizlik İçin)
        $browsersToClose = [System.Collections.Generic.List[string]]::new()
        if ($sel["Chrome"]  -or $sel["BrowserHistory"] -or $sel["BrowserCookies"] -or $sel["BrowserPasswords"]) { $browsersToClose.Add("chrome") }
        if ($sel["Edge"]    -or $sel["BrowserHistory"] -or $sel["BrowserCookies"] -or $sel["BrowserPasswords"]) { $browsersToClose.Add("msedge") }
        if ($sel["Brave"]   -or $sel["BrowserHistory"] -or $sel["BrowserCookies"] -or $sel["BrowserPasswords"]) { $browsersToClose.Add("brave") }
        if ($sel["Opera"]   -or $sel["BrowserHistory"] -or $sel["BrowserCookies"] -or $sel["BrowserPasswords"]) { $browsersToClose.Add("opera"); $browsersToClose.Add("opera_gx") }
        if ($sel["Firefox"] -or $sel["BrowserHistory"] -or $sel["BrowserCookies"] -or $sel["BrowserPasswords"]) { $browsersToClose.Add("firefox") }

        $closedBrowsers = [System.Collections.Generic.List[string]]::new()
        foreach ($bName in ($browsersToClose | Select-Object -Unique)) {
            $runningProcs = Get-Process -Name $bName -ErrorAction SilentlyContinue
            if ($runningProcs) {
                $closedBrowsers.Add($bName)
                $runningProcs | Stop-Process -Force -ErrorAction SilentlyContinue
            }
        }

        if ($closedBrowsers.Count -gt 0) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 79; Msg = "Açık tarayıcılar kapatılıyor ($($closedBrowsers -join ', '))..." })
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[*] Kilitli dosyaların silinebilmesi için açık tarayıcılar kapatıldı: $($closedBrowsers -join ', ')" })
            $swCloseWait = [System.Diagnostics.Stopwatch]::StartNew()
            while ($swCloseWait.ElapsedMilliseconds -lt 1200) {
                $anyLeft = $false
                foreach ($bName in $closedBrowsers) {
                    if (Get-Process -Name $bName -ErrorAction SilentlyContinue) { $anyLeft = $true; break }
                }
                if (-not $anyLeft) { break }
                Start-Sleep -Milliseconds 100
            }
            Start-Sleep -Milliseconds 300
        }

        # 11. Tarayıcılar (Tüm Profiller)
        if ($sel["Chrome"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 80; Msg = "Google Chrome (Tüm Profiller) önbelleği temizleniyor..." })
            $f = Clean-ChromiumAllProfiles "$($envMap['LOCALAPPDATA'])\Google\Chrome\User Data"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Google Chrome (Tüm Profiller): $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        if ($sel["Edge"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 83; Msg = "Microsoft Edge (Tüm Profiller) önbelleği temizleniyor..." })
            $f = Clean-ChromiumAllProfiles "$($envMap['LOCALAPPDATA'])\Microsoft\Edge\User Data"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Microsoft Edge (Tüm Profiller): $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        if ($sel["Firefox"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 85; Msg = "Mozilla Firefox önbelleği ve site verileri temizleniyor..." })
            [double]$f = (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Mozilla\Firefox\Profiles") +
                         (Clean-PathSafe "$($envMap['APPDATA'])\Mozilla\Firefox\Background Tasks Profiles") +
                         (Clean-PathSafe "$($envMap['APPDATA'])\Mozilla\Firefox\Crash Reports") +
                         (Clean-PathSafe "$($envMap['APPDATA'])\Mozilla\Firefox\Pending Pings")
            $ffProf = Get-ChildItem -Path "$($envMap['APPDATA'])\Mozilla\Firefox\Profiles" -Directory -ErrorAction SilentlyContinue
            foreach ($p in $ffProf) {
                $f += (Clean-PathSafe (Join-Path $p.FullName "storage\default"))
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Mozilla Firefox: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        if ($sel["Opera"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 87; Msg = "Opera ve Opera GX önbelleği temizleniyor..." })
            $f = (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Opera Software\Opera Stable\Cache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Opera Software\Opera Stable\GPUCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Opera Software\Opera GX Stable\Cache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Opera Software\Opera GX Stable\GPUCache")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Opera & Opera GX: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        if ($sel["Brave"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 89; Msg = "Brave Browser (Tüm Profiller) önbelleği temizleniyor..." })
            $f = Clean-ChromiumAllProfiles "$($envMap['LOCALAPPDATA'])\BraveSoftware\Brave-Browser\User Data"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Brave Browser (Tüm Profiller): $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 12. Uygulamalar (Office & OneDrive Dahil)
        if ($sel["Apps"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 91; Msg = "Uygulama önbellekleri (Discord, Spotify, Teams, Slack, Office, OneDrive) temizleniyor..." })
            $f = (Clean-PathSafe "$($envMap['APPDATA'])\discord\Cache") +
                 (Clean-PathSafe "$($envMap['APPDATA'])\discord\Code Cache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Spotify\Storage") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Spotify\Data") +
                 (Clean-PathSafe "$($envMap['APPDATA'])\Microsoft\Teams\Cache") +
                 (Clean-PathSafe "$($envMap['APPDATA'])\Slack\Cache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Office\16.0\OfficeFileCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Office\15.0\OfficeFileCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Office\16.0\WebServiceCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\Office\OTele") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\OneDrive\cache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\OneDrive\logs") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Microsoft\OneDrive\setup\logs") +
                  (Clean-PathSafe "C:\ProgramData\NVIDIA Corporation\NvProfileUpdaterPlugin") +
                 (Clean-PathSafe "C:\ProgramData\NVIDIA Corporation\NVIDIA App\MessageBus")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Uygulama Önbellekleri: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
