        # 12.1 Notion Önbelleği
        if ($sel["AppNotion"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 92; Msg = "Notion uygulama önbelleği ve güncelleme kalıntıları temizleniyor..." })
            $nDirs = @(
                "$($envMap['LOCALAPPDATA'])\notion-updater",
                "$($envMap['APPDATA'])\Notion\logs",
                "$($envMap['APPDATA'])\Notion\Cache",
                "$($envMap['APPDATA'])\Notion\GPUCache",
                "$($envMap['APPDATA'])\Notion\Code Cache",
                "$($envMap['APPDATA'])\Notion\Partitions\notion\Cache",
                "$($envMap['APPDATA'])\Notion\Partitions\notion\GPUCache",
                "$($envMap['APPDATA'])\Notion\Partitions\notion\Code Cache",
                "$($envMap['APPDATA'])\Notion\Partitions\notion\Service Worker\CacheStorage",
                "$($envMap['APPDATA'])\Notion\Partitions\notion\Service Worker\ScriptCache"
            )
            [double]$f = 0
            foreach ($nd in $nDirs) { $f += (Clean-PathSafe $nd) }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Notion Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 12.2 Visual Studio Code Önbelleği
        if ($sel["AppVSCode"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 93; Msg = "Visual Studio Code önbelleği temizleniyor..." })
            $vDirs = @(
                "$($envMap['APPDATA'])\Code\CachedData",
                "$($envMap['APPDATA'])\Code\Cache",
                "$($envMap['APPDATA'])\Code\Code Cache",
                "$($envMap['APPDATA'])\Code\GPUCache",
                "$($envMap['APPDATA'])\Code\DawnWebGPUCache",
                "$($envMap['APPDATA'])\Code\DawnGraphiteCache",
                "$($envMap['APPDATA'])\Code\CachedExtensionVSIXs",
                "$($envMap['APPDATA'])\Code\logs",
                "$($envMap['APPDATA'])\Code\Service Worker\ScriptCache",
                "$($envMap['APPDATA'])\Code\Service Worker\CacheStorage"
            )
            [double]$f = 0
            foreach ($vd in $vDirs) { $f += (Clean-PathSafe $vd) }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Visual Studio Code: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 12.3 Python Pip Paket Önbelleği
        if ($sel["AppPython"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 94; Msg = "Python pip paket önbelleği temizleniyor..." })
            $pDirs = @(
                "$($envMap['LOCALAPPDATA'])\pip\cache",
                "$($envMap['LOCALAPPDATA'])\pip\Cache"
            )
            [double]$f = 0
            foreach ($pd in $pDirs) { $f += (Clean-PathSafe $pd) }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Python Pip Paket Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 12.4 VLC Medya Oynatıcı Önbelleği
        if ($sel["AppVlc"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 94; Msg = "VLC medya oynatıcı önbelleği temizleniyor..." })
            $vlcDirs = @(
                "$($envMap['APPDATA'])\vlc\art",
                "$($envMap['APPDATA'])\vlc\crashdump"
            )
            [double]$f = 0
            foreach ($vlcd in $vlcDirs) { $f += (Clean-PathSafe $vlcd) }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] VLC Medya Oynatıcı Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 13. Shader Önbelleği
        # Tarayıcı Ziyaret ve İndirme Geçmişi
        if ($sel["BrowserHistory"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 84; Msg = "Tarayıcı ziyaret ve indirme geçmişi temizleniyor..." })
            $f = Clean-BrowserTargetFiles "History"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Tarayıcı Geçmişi ve İndirmeler: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # Tarayıcı Çerezleri ve Açık Oturumlar
        if ($sel["BrowserCookies"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 86; Msg = "Tarayıcı çerezleri ve oturumları temizleniyor..." })
            $f = Clean-BrowserTargetFiles "Cookies"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Tarayıcı Çerezleri (Oturumlar): $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # Kayıtlı Şifreler ve Otomatik Doldurma Verileri
        if ($sel["BrowserPasswords"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 88; Msg = "Tarayıcı kayıtlı şifreleri ve form verileri temizleniyor..." })
            $f = Clean-BrowserTargetFiles "Passwords"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[!] Kayıtlı Şifreler ve Form Verileri: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        if ($sel["Shader"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 93; Msg = "Grafik shader önbelleği (NVIDIA, AMD, DirectX) temizleniyor..." })
            $f = (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\D3DSCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\NVIDIA\DXCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\NVIDIA\GLCache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\AMD\DxCache")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Grafik Shader Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 14. Oyun İstemcileri Arayüz Önbelleği
        if ($sel["GameClients"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 95; Msg = "Oyun istemcileri arayüz web önbelleği temizleniyor..." })
            $f = (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Steam\htmlcache") +
                 (Clean-PathSafe "${env:ProgramFiles(x86)}\Steam\htmlcache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\EpicGamesLauncher\Saved\webcache") +
                 (Clean-PathSafe "$($envMap['LOCALAPPDATA'])\Electronic Arts\EA Desktop\Logs")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Oyun İstemcileri Web Arayüz Önbelleği: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        function Clean-BrowserSpecificHistory([string]$userDataDir) {
            if (-not (Test-Path -LiteralPath $userDataDir -ErrorAction SilentlyContinue)) { return 0 }
            [double]$freed = 0
            $targetFiles = @(
                "History", "History-journal",
                "Visited Links",
                "Top Sites", "Top Sites-journal",
                "Network Action Predictor", "Network Action Predictor-journal",
                "Shortcuts", "Shortcuts-journal",
                "DownloadMetadata",
                "History Provider Cache"
            )
            try {
                $profiles = Get-ChildItem -Path $userDataDir -Directory -ErrorAction SilentlyContinue | Where-Object {
                    $_.Name -eq "Default" -or $_.Name -like "Profile *"
                }
                foreach ($p in $profiles) {
                    foreach ($tf in $targetFiles) {
                        $fp = Join-Path $p.FullName $tf
                        if (Test-Path -LiteralPath $fp -ErrorAction SilentlyContinue) {
                            try {
                                $len = (Get-Item -LiteralPath $fp -Force -ErrorAction SilentlyContinue).Length
                                [System.IO.File]::Delete($fp)
                                $freed += $len
                            } catch {
                                try {
                                    Start-Sleep -Milliseconds 100
                                    [System.IO.File]::Delete($fp)
                                    $freed += $len
                                } catch {}
                            }
                        }
                    }
                }
            } catch {}
            return $freed
        }

        # 15.1 Sistem Kullanım İzleri ve Windows Olay İzleme Günlükleri
        if ($sel["TraceSystem"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 96; Msg = "Sistem kullanım izleri ve olay izleme günlükleri temizleniyor..." })
            [double]$f = 0
            try {
                $etlFiles = Get-ChildItem -Path "C:\Windows\System32\WDI" -Filter "*.etl" -Recurse -File -Force -ErrorAction SilentlyContinue
                foreach ($ef in $etlFiles) {
                    try {
                        $len = $ef.Length
                        [System.IO.File]::Delete($ef.FullName)
                        $f += $len
                    } catch {}
                }
                $subDirs = Get-ChildItem -Path "C:\Windows\System32\WDI" -Directory -Force -ErrorAction SilentlyContinue
                foreach ($d in $subDirs) {
                    if ($d.Name -match '^{[0-9a-fA-F-]+}$') {
                        try {
                            $inner = Get-ChildItem -Path $d.FullName -Recurse -File -Force -ErrorAction SilentlyContinue
                            if (-not $inner -or $inner.Count -eq 0) { [System.IO.Directory]::Delete($d.FullName, $true) }
                        } catch {}
                    }
                }
            } catch {}
            $f += (Clean-PathSafe "C:\ProgramData\USOShared\Logs")
            $f += (Clean-PathSafe "C:\Windows\System32\WDI\LogFiles")
            $f += (Clean-PathSafe "C:\Windows\System32\SleepStudy")
            $f += (Clean-PathSafe "C:\Windows\Logs\waasmedic")
            $f += (Clean-PathSafe "C:\ProgramData\Microsoft\Diagnosis\DownloadedSettings")
            $f += (Clean-PathSafe "$($envMap['APPDATA'])\Microsoft\Windows\Recent")
            $f += (Clean-PathSafe "$($envMap['APPDATA'])\Microsoft\Windows\Recent\AutomaticDestinations")
            $f += (Clean-PathSafe "$($envMap['APPDATA'])\Microsoft\Windows\Recent\CustomDestinations")
            try { Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RunMRU" -Name * -ErrorAction SilentlyContinue } catch {}
            try { Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\TypedPaths" -Name * -ErrorAction SilentlyContinue } catch {}
            try { Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery" -Name * -ErrorAction SilentlyContinue } catch {}

            try { [System.Windows.Clipboard]::Clear() } catch {}
            try {
                Add-Type -AssemblyName System.Runtime.WindowsRuntime -ErrorAction SilentlyContinue
                $asType = [System.Type]::GetType("Windows.ApplicationModel.DataTransfer.Clipboard, Windows, ContentType=WindowsRuntime")
                if ($asType) {
                    $clearM = $asType.GetMethod("ClearHistory", [System.Type]::EmptyTypes)
                    if ($clearM) { $null = $clearM.Invoke($null, $null) }
                }
            } catch {}

            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Sistem Kullanım İzleri: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 15.2 Chrome Kullanım İzleri
        if ($sel["TraceChrome"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 96; Msg = "Google Chrome kullanım izleri temizleniyor..." })
            $f = Clean-BrowserSpecificHistory "$($envMap['LOCALAPPDATA'])\Google\Chrome\User Data"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Google Chrome Kullanım İzleri: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 15.3 Edge Kullanım İzleri
        if ($sel["TraceEdge"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 97; Msg = "Microsoft Edge kullanım izleri temizleniyor..." })
            $f = (Clean-BrowserSpecificHistory "$($envMap['LOCALAPPDATA'])\Microsoft\Edge\User Data") +
                 (Clean-PathSafe "C:\ProgramData\Microsoft\EdgeUpdate\Log")
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Microsoft Edge Kullanım İzleri: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 15.4 Brave Kullanım İzleri
        if ($sel["TraceBrave"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 97; Msg = "Brave kullanım izleri temizleniyor..." })
            $f = Clean-BrowserSpecificHistory "$($envMap['LOCALAPPDATA'])\BraveSoftware\Brave-Browser\User Data"
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Brave Kullanım İzleri: $(Format-SizeLocal $f) temizlendi."; Freed = $f })
        }

        # 16. DNS
        if ($sel["Dns"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 97; Msg = "DNS çözümleyici önbelleği temizleniyor..." })
            Clear-DnsClientCache -ErrorAction SilentlyContinue
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] DNS Çözümleyici Önbelleği temizlendi."; Freed = 0 })
        }

        # 17. Eski Geri Yükleme Noktaları (srclient.dll API ile, 3. parti VSS kopyaları korunur, en yenisi kesin korunur)
        if ($sel["OldRestore"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 98; Msg = "Eski geri yükleme noktaları taranıyor (en yenisi korunuyor)..." })
            $delCount = 0
            $failCount = 0
            $totalFound = 0
            try {
                $rps = @(Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Sort-Object SequenceNumber)
                $totalFound = $rps.Count
                if ($totalFound -gt 1) {
                    for ($i = 0; $i -lt ($totalFound - 1); $i++) {
                        $seq = [int]$rps[$i].SequenceNumber
                        $rc = -1
                        try {
                            if ("SRClient" -as [type]) {
                                $rc = [SRClient]::SRRemoveRestorePoint($seq)
                            }
                        } catch {}
                        if ($rc -eq 0) { $delCount++ } else { $failCount++ }
                    }
                }
            } catch {}
            
            $logMsg = if ($totalFound -eq 0) {
                "[i] Eski Geri Yükleme Noktaları: Sistemde kayıtlı geri yükleme noktası bulunamadı (veya Sistem Koruması kapalı)."
            } elseif ($totalFound -eq 1) {
                "[i] Eski Geri Yükleme Noktaları (srclient.dll): 0 adet eski nokta silindi (yalnızca 1 adet güncel nokta mevcut ve korundu)."
            } elseif ($failCount -gt 0) {
                "[+] Eski Geri Yükleme Noktaları (srclient.dll): $delCount adet eski nokta silindi (en güncel nokta korundu, $failCount adet silinemedi)."
            } else {
                "[+] Eski Geri Yükleme Noktaları (srclient.dll): $delCount adet eski nokta silindi (en güncel nokta korundu)."
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = $logMsg; Freed = 0 })
        }

        # 18. Kırık Kısayollar (Madde 8: Yalnızca kullanıcının işaretlediği kırık kısayollar silinir)
        if ($sel["Shortcuts"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 99; Msg = "Seçilen kırık kısayollar temizleniyor..." })
            $delCount = 0
            if ($shortcutsList -and $shortcutsList.Count -gt 0) {
                foreach ($targetLnk in $shortcutsList) {
                    try {
                        if (Test-Path -LiteralPath $targetLnk -ErrorAction SilentlyContinue) {
                            Remove-Item -LiteralPath $targetLnk -Force -ErrorAction SilentlyContinue
                            $delCount++
                        }
                    } catch {}
                }
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = "[+] Kırık Kısayollar: $delCount adet seçili kısayol temizlendi."; Freed = 0 })
        }

        # 19. Eski Donanım Sürücü Paketleri (Driver Store)
        if ($sel["DriverStore"]) {
            $q.Enqueue([PSCustomObject]@{ Type = "Progress"; Prog = 99; Msg = "Eski donanım sürücü paketleri (Driver Store) temizleniyor..." })
            $delCount = 0
            [double]$freedDrivers = 0
            try {
                $rawPnp = pnputil /enum-drivers
                $drList = [System.Collections.Generic.List[psobject]]::new()
                $cHash = [System.Collections.Hashtable]::new()
                foreach ($line in ($rawPnp -split '\r?\n')) {
                    $line = $line.Trim()
                    if (-not $line) {
                        if ($cHash.ContainsKey('PublishedName') -and $cHash.ContainsKey('OriginalName')) {
                            $drList.Add([PSCustomObject]@{
                                PublishedName = $cHash['PublishedName']
                                OriginalName  = $cHash['OriginalName']
                                DriverVersion = if ($cHash.ContainsKey('DriverVersion')) { $cHash['DriverVersion'] } else { "" }
                            })
                        }
                        $cHash.Clear()
                    } elseif ($line -match '^([^:]+):\s*(.*)$') {
                        $k = $matches[1].Trim()
                        $v = $matches[2].Trim()
                        if ($k -match '^(Published Name|Yay[ıi]mlanan Ad[ıi]?)$') {
                            $cHash['PublishedName'] = $v
                        } elseif ($k -match '^(Original Name|Özgün Ad[ıi]?|Ozgun Ad[ıi]?|Orijinal Ad[ıi]?)$') {
                            $cHash['OriginalName'] = $v
                        } elseif ($k -match '^(Driver Version|Sürücü Sürümü|Surucu Surumu|Sürüm|Driver Date|Sürücü Tarihi)$') {
                            $cHash['DriverVersion'] = $v
                        }
                    }
                }
                if ($cHash.ContainsKey('PublishedName') -and $cHash.ContainsKey('OriginalName')) {
                    $drList.Add([PSCustomObject]@{
                        PublishedName = $cHash['PublishedName']
                        OriginalName  = $cHash['OriginalName']
                        DriverVersion = if ($cHash.ContainsKey('DriverVersion')) { $cHash['DriverVersion'] } else { "" }
                    })
                }
                $byOrig = $drList | Group-Object { $_.OriginalName.ToLower() }
                $drPath = 'C:\Windows\System32\DriverStore\FileRepository'
                [string[]]$dateFormats = @('MM/dd/yyyy', 'M/d/yyyy', 'dd.MM.yyyy', 'd.M.yyyy', 'yyyy-MM-dd', 'dd/MM/yyyy')
                foreach ($g in $byOrig) {
                    if ($g.Count -gt 1) {
                        $validItems = [System.Collections.Generic.List[psobject]]::new()
                        $hasInvalidDate = $false
                        foreach ($dr in $g.Group) {
                            $parsedDate = [datetime]::MinValue
                            $parsedVer = [version]'0.0'
                            try {
                                $parts = $dr.DriverVersion -split '\s+'
                                $dPart = $parts[0]
                                if (-not [datetime]::TryParseExact($dPart, $dateFormats, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$parsedDate)) {
                                    [datetime]::TryParse($dPart, [ref]$parsedDate) | Out-Null
                                }
                                if ($parts.Count -ge 2) {
                                    $clean = $parts[1] -replace '[^\d\.]', ''
                                    if ($clean -match '^\d+(\.\d+)+$') {
                                        $vParts = $clean -split '\.'
                                        if ($vParts.Count -gt 4) { $clean = ($vParts[0..3] -join '.') }
                                        $parsedVer = [version]$clean
                                    } elseif ($clean -match '^\d+$') {
                                        $parsedVer = [version]"$clean.0"
                                    }
                                }
                            } catch {}
                            if ($parsedDate -eq [datetime]::MinValue) {
                                $hasInvalidDate = $true
                                break
                            }
                            $validItems.Add([PSCustomObject]@{
                                Item    = $dr
                                Date    = $parsedDate
                                Version = $parsedVer
                            })
                        }
                        if ($hasInvalidDate -or $validItems.Count -lt 2) { continue }

                        # 1. Öncelik Tarih (artan), 2. Öncelik Sürüm Numarası (artan)
                        $sorted = $validItems | Sort-Object -Property Date, Version
                        if ($sorted[0].Date -eq $sorted[-1].Date -and $sorted[0].Version -eq $sorted[-1].Version) { continue }

                        for ($i = 0; $i -lt ($sorted.Count - 1); $i++) {
                            $cand = $sorted[$i].Item
                            $oemInf = $cand.PublishedName
                            $baseName = ($cand.OriginalName -split '\.')[0]
                            $matchFolders = Get-ChildItem -LiteralPath $drPath -Directory -Filter "$baseName*" -ErrorAction SilentlyContinue
                            [double]$fSize = 0
                            if ($matchFolders) {
                                $fSize = (Get-ChildItem -LiteralPath $matchFolders[0].FullName -File -Recurse -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
                            }
                            $pOut = & pnputil.exe /delete-driver $oemInf 2>&1
                            $pStr = $pOut -join " "
                            if ($LASTEXITCODE -eq 0 -or $pStr -match "deleted|başarıyla|silindi") {
                                $delCount++
                                if ($fSize -gt 0) { $freedDrivers += $fSize }
                            }
                        }
                    }
                }
            } catch {}
            $logMsg = if ($delCount -gt 0) {
                "[+] Driver Store (pnputil): $delCount adet eski donanım sürücüsü silindi ($(Format-SizeLocal $freedDrivers))."
            } else {
                "[i] Driver Store: Silinecek kullanılmayan eski sürücü paketi bulunamadı."
            }
            $q.Enqueue([PSCustomObject]@{ Type = "Log"; LogText = $logMsg; Freed = $freedDrivers })
        }

        # Tamamlandı Bildirimi
        $q.Enqueue([PSCustomObject]@{ Type = "Done"; SkippedCount = [int]$script:cleanSkippedCount })
    }

    $envMap = @{
        TEMP          = $env:TEMP
        APPDATA       = $env:APPDATA
        LOCALAPPDATA  = $env:LOCALAPPDATA
    }

    # Madde 4: STA modunda çalışan InitialSessionState ve Runspace ile OLE / Clipboard / WinRT uyumluluğu
    $iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
    $script:cleanRunspaceHost = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($iss)
    $script:cleanRunspaceHost.ApartmentState = [System.Threading.ApartmentState]::STA
    $script:cleanRunspaceHost.ThreadOptions  = [System.Management.Automation.Runspaces.PSThreadOptions]::UseNewThread
    $script:cleanRunspaceHost.Open()

    $script:cleanSyncState = [System.Collections.Hashtable]::Synchronized(@{
        'DecisionMade' = $false
        'UserChoice'   = $false
    })

    $script:cleanRunspace = [powershell]::Create()
    $script:cleanRunspace.Runspace = $script:cleanRunspaceHost
    $null = $script:cleanRunspace.AddScript($runspaceScript).AddArgument($script:cleanProgressQueue).AddArgument($selectedMap).AddArgument($createRestorePoint).AddArgument($shortcutsToDelete).AddArgument($envMap).AddArgument($script:cleanSyncState)
    $script:cleanAsyncResult = $script:cleanRunspace.BeginInvoke()
    $script:cleanUiTimer.Start()
}
# ------------------------------------------------------------------------------
# 15. Canlı Sağlık ve Onarım Konsolu Yürütücüsü (Kesintisiz Dosya Akışı ile %100 Non-Blocking)
# ------------------------------------------------------------------------------
$script:activeHealthProc = $null
$script:activeHealthTitle = ""
$script:healthLogFile = "$env:TEMP\temizwin_health_run.log"
$script:healthLogOffset = 0
$script:healthLastLoggedPct = -1
$script:healthLastConsoleProgress = ""
$script:healthDownloadAnnounced = $false
$script:healthStreamTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:healthStreamTimer.Interval = [TimeSpan]::FromMilliseconds(150)

$script:healthStreamTimer.Add_Tick({
    # Yeni yazılan log satırlarını bloke olmadan ve kodlama (UTF-16LE / UTF-8) otomatik tespitli oku
    if (Test-Path $script:healthLogFile) {
        try {
            $fs = [System.IO.FileStream]::new($script:healthLogFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $len = $fs.Length
            if ($len -gt $script:healthLogOffset) {
                [int64]$diff = $len - $script:healthLogOffset
                $count = if ($diff -gt 65536) { 65536 } else { [int]$diff }
                $fs.Seek($script:healthLogOffset, [System.IO.SeekOrigin]::Begin) | Out-Null
                $buf = New-Object byte[] $count
                $bytesRead = $fs.Read($buf, 0, $count)
                $script:healthLogOffset += $bytesRead

                if ($bytesRead -gt 0) {
                    # SFC.exe gibi araçlar UTF-16LE çıktısı verir (BOM veya her harften sonra null bayt)
                    $isUtf16 = ($bytesRead -ge 2 -and (($buf[0] -eq 0xFF -and $buf[1] -eq 0xFE) -or ($buf[0] -eq 0xFE -and $buf[1] -eq 0xFF) -or ($buf[1] -eq 0 -and $buf[0] -ne 0)))
                    $chunk = if ($isUtf16) {
                        [System.Text.Encoding]::Unicode.GetString($buf, 0, $bytesRead)
                    } else {
                        [System.Text.Encoding]::UTF8.GetString($buf, 0, $bytesRead)
                    }
                    if (-not [string]::IsNullOrEmpty($chunk)) {
                        # Kalan olası tekil null karakterleri temizle
                        $cleanChunk = $chunk.Replace("`0", "")

                        # 1. Arayüz içi terminale ekle
                        $txtTerminal.AppendText($cleanChunk)
                        $txtTerminal.ScrollToEnd()

                        # 2. Arka plandaki canlı PowerShell konsoluna anlık aktar
                        $streamLines = $cleanChunk -split "[\r\n]+"
                        foreach ($rawLine in $streamLines) {
                            $trimmed = $rawLine.Trim()
                            if ([string]::IsNullOrWhiteSpace($trimmed)) { continue }

                            # İlerleme çubuğu tespiti (DISM: [====== 67.5% ======] veya SFC: %67)
                            if ($trimmed -match '\[(=+)\s*(\d+(?:\.\d+)?%)\s*(=*)\]' -or $trimmed -match '(\d+(?:\.\d+)?)\s*%') {
                                $currentProg = $matches[0]
                                if ($currentProg -ne $script:healthLastConsoleProgress) {
                                    $script:healthLastConsoleProgress = $currentProg
                                    $timeNow = (Get-Date).ToString("HH:mm:ss")
                                    Write-Host "[$timeNow] [SAĞLIK] İlerleme: $currentProg" -ForegroundColor Cyan
                                }

                                if ($trimmed -match '(\d+(?:\.\d+)?)\s*%') {
                                    $pctVal = [double]$matches[1]
                                    if ($script:activeHealthTitle -match "DISM" -and $pctVal -ge 50 -and $pctVal -le 70 -and -not $script:healthDownloadAnnounced) {
                                        $script:healthDownloadAnnounced = $true
                                        Write-Host "[$((Get-Date).ToString('HH:mm:ss'))] [SAĞLIK] [İNDİRİLİYOR] Windows Update üzerinden onarım paketleri indiriliyor ve doğrulanıyor..." -ForegroundColor Yellow
                                    }
                                }
                            } else {
                                # Başlıklar, araç bilgisi ve sonuç metinleri konsola canlı basılır
                                $timeNow = (Get-Date).ToString("HH:mm:ss")
                                Write-Host "[$timeNow] [SAĞLIK] $trimmed" -ForegroundColor Gray
                            }
                        }
                    }
                }
            }
            $fs.Dispose()
        } catch {}
    }

    if ($script:activeHealthProc -and $script:activeHealthProc.HasExited) {
        $script:healthStreamTimer.Stop()

        # Son kalan veriyi oku
        if (Test-Path $script:healthLogFile) {
            try {
                $fs = [System.IO.FileStream]::new($script:healthLogFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
                $len = $fs.Length
                if ($len -gt $script:healthLogOffset) {
                    [int64]$diff = $len - $script:healthLogOffset
                    $count = if ($diff -gt 65536) { 65536 } else { [int]$diff }
                    $fs.Seek($script:healthLogOffset, [System.IO.SeekOrigin]::Begin) | Out-Null
                    $buf = New-Object byte[] $count
                    $bytesRead = $fs.Read($buf, 0, $count)
                    if ($bytesRead -gt 0) {
                        $isUtf16 = ($bytesRead -ge 2 -and (($buf[0] -eq 0xFF -and $buf[1] -eq 0xFE) -or ($buf[0] -eq 0xFE -and $buf[1] -eq 0xFF) -or ($buf[1] -eq 0 -and $buf[0] -ne 0)))
                        $chunk = if ($isUtf16) {
                            [System.Text.Encoding]::Unicode.GetString($buf, 0, $bytesRead)
                        } else {
                            [System.Text.Encoding]::UTF8.GetString($buf, 0, $bytesRead)
                        }
                        if (-not [string]::IsNullOrEmpty($chunk)) {
                            $cleanChunk = $chunk.Replace("`0", "")
                            $txtTerminal.AppendText($cleanChunk)
                            $txtTerminal.ScrollToEnd()
                        }
                    }
                }
                $fs.Dispose()
                Remove-Item $script:healthLogFile -Force -ErrorAction SilentlyContinue
            } catch {}
        }

        $exitCode = $script:activeHealthProc.ExitCode
        if ($exitCode -eq 0) {
            Write-Terminal "=== $($script:activeHealthTitle) Başarıyla Tamamlandı (Çıkış Kodu: 0) ===`r`n"
            Write-CmdLog "SAĞLIK" "=== $($script:activeHealthTitle) Başarıyla Tamamlandı ===" "Green"
            if ($script:activeHealthTitle -like "*SFC*" -or $script:activeHealthTitle -like "*DISM*") {
                if ($script:pendingRebootTweaks) { $script:pendingRebootTweaks.Add("Sistem Onarımı ($($script:activeHealthTitle))") | Out-Null }
            }
        } else {
            Write-Terminal "[HATA] $($script:activeHealthTitle) Başarısız Oldu / Hata Oluştu (Çıkış Kodu: $exitCode)!`r`n"
            Write-CmdLog "SAĞLIK" "[HATA] $($script:activeHealthTitle) Başarısız Oldu (Çıkış Kodu: $exitCode)" "Red"
        }
        $script:activeHealthProc.Dispose()
        $script:activeHealthProc = $null
        $script:isHealthRunning = $false

        $btnRunSfc.IsEnabled = $true
        $btnRunDism.IsEnabled = $true
        if ($btnRunDismScan) { $btnRunDismScan.IsEnabled = $true }
        $btnRunChkdsk.IsEnabled = $true
        if ($btnRunSmartInfo) { $btnRunSmartInfo.IsEnabled = $true }
        if ($btnRunPerfmonReport) { $btnRunPerfmonReport.IsEnabled = $true }
        if ($btnRunDriverCheck) { $btnRunDriverCheck.IsEnabled = $true }
        $btnResetNetwork.IsEnabled = $true
        $btnWsReset.IsEnabled = $true
    }
})

function Run-HealthCommand([string]$cmd, [string]$cmdArgs, [string]$title) {
    if ($script:isHealthRunning) {
        [System.Windows.MessageBox]::Show($window, "Şu anda bir onarım veya tarama işlemi devam ediyor.`nLütfen mevcut işlemin bitmesini bekleyin.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }
    if ($script:isCleaningRunning) {
        [System.Windows.MessageBox]::Show($window, "Şu anda bir sistem temizleme işlemi devam ediyor.`nLütfen temizliğin bitmesini bekleyin.", "TemizWin - Temizlik Sürüyor", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }

    # Windows üzerinde zaten çalışan çakışan servis kontrolü
    if ($cmd -match "dism") {
        $runningDism = Get-Process -Name "dism" -ErrorAction SilentlyContinue
        if ($runningDism) {
            [System.Windows.MessageBox]::Show($window, "Arka planda şu anda çalışan bir DISM işlemi var (PID: $(($runningDism | Select-Object -First 1).Id))!`n`nWindows aynı anda yalnızca tek bir DISM servisine izin verir. Lütfen mevcut onarımın bitmesini bekleyin.", "TemizWin - Servis Meşgul", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            Write-Terminal "[UYARI] Arka planda zaten çalışan bir DISM işlemi tespit edildi (PID: $(($runningDism | Select-Object -First 1).Id)). Yeni işlem başlatılmadı."
            Write-CmdLog "SAĞLIK" "[UYARI] Arka planda aktif DISM işlemi mevcut, yeni işlem başlatılamaz." "Yellow"
            return
        }
    } elseif ($cmd -match "sfc") {
        $runningSfc = Get-Process -Name "sfc" -ErrorAction SilentlyContinue
        if ($runningSfc) {
            [System.Windows.MessageBox]::Show($window, "Arka planda şu anda çalışan bir SFC tarama işlemi var (PID: $(($runningSfc | Select-Object -First 1).Id))!`n`nLütfen mevcut taramanın bitmesini bekleyin.", "TemizWin - Servis Meşgul", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            Write-Terminal "[UYARI] Arka planda zaten çalışan bir SFC işlemi tespit edildi (PID: $(($runningSfc | Select-Object -First 1).Id)). Yeni işlem başlatılmadı."
            Write-CmdLog "SAĞLIK" "[UYARI] Arka planda aktif SFC işlemi mevcut, yeni işlem başlatılamaz." "Yellow"
            return
        }
    }

    $script:isHealthRunning = $true
    $btnRunSfc.IsEnabled = $false
    $btnRunDism.IsEnabled = $false
    if ($btnRunDismScan) { $btnRunDismScan.IsEnabled = $false }
    $btnRunChkdsk.IsEnabled = $false
    if ($btnRunSmartInfo) { $btnRunSmartInfo.IsEnabled = $false }
    if ($btnRunPerfmonReport) { $btnRunPerfmonReport.IsEnabled = $false }
    if ($btnRunDriverCheck) { $btnRunDriverCheck.IsEnabled = $false }
    $btnResetNetwork.IsEnabled = $false
    $btnWsReset.IsEnabled = $false

    $script:activeHealthTitle = $title
    $uniqueId = [Guid]::NewGuid().ToString("N")
    $script:healthLogFile = "$env:TEMP\temizwin_health_$uniqueId.log"
    $script:healthLogOffset = 0
    $script:healthLastLoggedPct = -1
    $script:healthLastConsoleProgress = ""
    $script:healthDownloadAnnounced = $false

    Write-CmdLog "SAĞLIK" ">>> $title Başlatıldı ($cmd $cmdArgs)" "Yellow"
    Write-Terminal "=== $title Başlatılıyor ==="

    if ($cmdArgs -match "scanhealth") {
        Write-Terminal "[BİLGİ] DISM bileşen deposunu salt okunur tarıyor (onarım gerekip gerekmediğini denetler)..."
        Write-CmdLog "SAĞLIK" "[BİLGİ] DISM bileşen deposu denetleniyor (ScanHealth)..." "Cyan"
    } elseif ($cmd -match "dism") {
        Write-Terminal "[BİLGİ] DISM Windows bileşen deposunu tarar. Bozuk dosya bulunursa (%50-%70 arasında) Windows Update'ten sağlam dosyaları indirir. Bu aşamada durmuş gibi görünebilir, işlem aktif devam eder."
        Write-CmdLog "SAĞLIK" "[BİLGİ] DISM hasarlı dosya bulursa (%50-%70 aralığında) Windows Update'ten dosya indirir, lütfen bekleyin." "Cyan"
    } elseif ($cmd -match "sfc") {
        Write-Terminal "[BİLGİ] SFC sistem dosyalarını doğrular ve onarır. Bu işlem 3-10 dakika sürebilir..."
        Write-CmdLog "SAĞLIK" "[BİLGİ] SFC sistem dosyalarını doğruluyor (3-10 dakika sürebilir)..." "Cyan"
    }

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = "cmd.exe"
    $psi.Arguments = "/c chcp 65001 >nul & ($cmd $cmdArgs) > `"$($script:healthLogFile)`" 2>&1"
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true

    try {
        $script:activeHealthProc = [System.Diagnostics.Process]::Start($psi)
        $script:healthStreamTimer.Start()
    } catch {
        Write-Terminal "HATA: $($_.Exception.Message)"
        $script:isHealthRunning = $false
        $btnRunSfc.IsEnabled = $true
        $btnRunDism.IsEnabled = $true
        if ($btnRunDismScan) { $btnRunDismScan.IsEnabled = $true }
        $btnRunChkdsk.IsEnabled = $true
        if ($btnRunSmartInfo) { $btnRunSmartInfo.IsEnabled = $true }
        if ($btnRunPerfmonReport) { $btnRunPerfmonReport.IsEnabled = $true }
        if ($btnRunDriverCheck) { $btnRunDriverCheck.IsEnabled = $true }
        $btnResetNetwork.IsEnabled = $true
        $btnWsReset.IsEnabled = $true
    }
}

# ------------------------------------------------------------------------------
# 16. Winget Güncellemelerini Sırayla Uygulama & Kurulum Doğrulama Motoru
# ------------------------------------------------------------------------------
function Test-IsVersionAtLeast([string]$installed, [string]$target) {
    if ([string]::IsNullOrWhiteSpace($installed) -or [string]::IsNullOrWhiteSpace($target)) { return $false }
    try {
        $cleanInst = ($installed -replace '^[^\d]*', '') -replace '[^\d\.]', ''
        $cleanTgt  = ($target -replace '^[^\d]*', '') -replace '[^\d\.]', ''
        $v1Parts = @($cleanInst -split '\.' | Where-Object { $_ -match '^\d+$' })
        $v2Parts = @($cleanTgt -split '\.' | Where-Object { $_ -match '^\d+$' })
        if ($v1Parts.Count -eq 0 -or $v2Parts.Count -eq 0) { return ($cleanInst -eq $cleanTgt) }
        while ($v1Parts.Count -lt 4) { $v1Parts += '0' }
        while ($v2Parts.Count -lt 4) { $v2Parts += '0' }
        $v1 = [System.Version]::Parse(($v1Parts[0..3]) -join '.')
        $v2 = [System.Version]::Parse(($v2Parts[0..3]) -join '.')
        return ($v1 -ge $v2)
    } catch {
        return ($cleanInst -eq $cleanTgt)
    }
}

function Test-PackageUpdatedSuccessfully([string]$pkgId, [string]$pkgName, [string]$targetVersion) {
    if (-not $pkgId -or -not $targetVersion) { return $false }

    # 1. Kayıt defteri (ARP) kontrolü (InnoSetup, Revo Uninstaller, MSI, EXE yükleyicileri için kesin yöntem)
    $regKeys = @(
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )
    foreach ($rk in $regKeys) {
        try {
            $matched = Get-ItemProperty -Path $rk -ErrorAction SilentlyContinue | Where-Object {
                ($_.DisplayName -and ($_.DisplayName -like "*$pkgName*" -or $_.DisplayName -like "*$pkgId*")) -or
                ($_.PSChildName -and $_.PSChildName -like "*$pkgId*")
            } | Select-Object -First 1
            if ($matched) {
                $instVer = [string]$matched.DisplayVersion
                if ($instVer -and (Test-IsVersionAtLeast $instVer $targetVersion)) {
                    return $true
                }
            }
        } catch {}
    }

    # 2. Appx / MSIX paket kontrolü (WindowsAppRuntime, Windows Terminal vb. için)
    try {
        $appx = Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*$pkgId*" -or $_.PackageFamilyName -like "*$pkgId*" } | Select-Object -First 1
        if ($appx -and $appx.Version) {
            if (Test-IsVersionAtLeast $appx.Version $targetVersion) {
                return $true
            }
        }
    } catch {}

    return $false
}

$script:updateQueue = [System.Collections.ArrayList]::new()
$script:updateTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:updateTimer.Interval = [TimeSpan]::FromMilliseconds(300)
$script:activeUpdateProc = $null
$script:activeUpdateBadge = $null
$script:activeUpdateIndex = 0
$script:activePkgId = ""
$script:activePkgName = ""
$script:activePkgTargetVer = ""

$script:updateTimer.Add_Tick({
    if ($script:activeUpdateProc) {
        if ($script:activeUpdateProc.HasExited) {
            $exitCode = $script:activeUpdateProc.ExitCode
            $script:activeUpdateProc.Dispose()
            $script:activeUpdateProc = $null

            # Winget, InnoSetup, MSI, MSIX başarı ve güncel dönüş kodları:
            # 0: Başarılı, 3010: Yeniden başlatma gerekiyor, 1641: Yeniden başlatma başlatıldı, 2359302: Zaten kurulu
            # -1978236885 (0x8A15002B): Güncelleme yok / Zaten güncel
            # -1978236883 (0x8A15002D): Paket zaten kurulu
            # -1978236920 (0x8A150008): Yeniden başlatma başlatıldı
            # -1978236921 (0x8A150007): Yeniden başlatma gerekiyor
            # -2147023258 (0x80070666): Bu ürünün daha yeni bir sürümü zaten yüklü
            $knownSuccessCodes = @(0, 3010, 1641, 2359302, -1978236885, -1978236883, -1978236920, -1978236921, -2147023258)
            $isSuccess = ($exitCode -in $knownSuccessCodes)

            # Çıkış kodu farklı ise (InnoSetup, özel installer gecikmesi vb.) gerçek durumu sistemden doğrula
            if (-not $isSuccess) {
                $verified = Test-PackageUpdatedSuccessfully $script:activePkgId $script:activePkgName $script:activePkgTargetVer
                if ($verified) {
                    $isSuccess = $true
                    Write-CmdLog "GÜNCELLEME" "✓ Sistem Doğrulandı: $($script:activePkgName) hedef sürüme güncellendi." "Green"
                }
            }

            if ($isSuccess) {
                if ($script:successfulUpdates) { $script:successfulUpdates.Add($script:activePkgName) }
                Write-CmdLog "GÜNCELLEME" "✓ Başarılı: $($script:activePkgName) [$($script:activePkgId)] başarıyla güncellendi." "Green"
            } else {
                if ($script:failedUpdates) { $script:failedUpdates.Add($script:activePkgName) }
                $errHint = ""
                if ($script:activeUpdateLog -and (Test-Path $script:activeUpdateLog)) {
                    try {
                        $logLines = [System.IO.File]::ReadAllLines($script:activeUpdateLog, [System.Text.Encoding]::UTF8)
                        $cleanLines = @($logLines | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and $_ -notmatch '^chcp' })
                        $relevantErr = $cleanLines | Where-Object { $_ -match 'hata|error|failed|bulunamadı|not found|in use|mevcut|çalışıyor|exit code|0x' } | Select-Object -Last 1
                        if ($relevantErr) {
                            $errHint = " → $($relevantErr.Trim())"
                        } elseif ($cleanLines.Count -gt 0) {
                            $errHint = " → $($cleanLines[-1].Trim())"
                        }
                    } catch {}
                }
                Write-CmdLog "GÜNCELLEME" "✗ Hata / Atlandı: $($script:activePkgName) [$($script:activePkgId)] (Kod: $exitCode)$errHint" "Red"
            }

            if ($script:activeUpdateBadge) {
                if ($isSuccess) {
                    $script:activeUpdateBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#052E16")
                    $script:activeUpdateBadge.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#16A34A")
                    $script:activeUpdateBadge.Child.Text = "Tamamlandı"
                    $script:activeUpdateBadge.Child.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#4ADE80")
                } else {
                    $script:activeUpdateBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#450A0A")
                    $script:activeUpdateBadge.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#DC2626")
                    $script:activeUpdateBadge.Child.Text = "Hata / Atlandı"
                    $script:activeUpdateBadge.Child.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F87171")
                }
            }
            $progUpdate.Value = $script:activeUpdateIndex
        } else {
            return
        }
    }

    if ($script:updateQueue.Count -gt 0) {
        $item = $script:updateQueue[0]
        $script:updateQueue.RemoveAt(0)
        $script:activeUpdateIndex++

        $pkgId = [string]$item['Tag']
        $pkgName = if ($item['Name']) { [string]$item['Name'] } else { $pkgId }
        $pkgTargetVer = if ($item['TargetVersion']) { [string]$item['TargetVersion'] } else { "" }

        $script:activePkgId = $pkgId
        $script:activePkgName = $pkgName
        $script:activePkgTargetVer = $pkgTargetVer
        $script:activeUpdateBadge = $item['Badge']

        if ($script:activeUpdateBadge) {
            $script:activeUpdateBadge.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#083344")
            $script:activeUpdateBadge.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#0284C7")
            $script:activeUpdateBadge.Child.Text = "Güncelleniyor..."
            $script:activeUpdateBadge.Child.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
        }
        $lblUpdateProgressText.Text = "Güncelleniyor ($($script:activeUpdateIndex) / $($progUpdate.Maximum)): $pkgName"

        # Arka planda açık olan çakışan süreç uyarısı (Genel)
        try {
            $matchingProc = Get-Process -ErrorAction SilentlyContinue | Where-Object { 
                $_.ProcessName -and ($pkgName -like "*$($_.ProcessName)*" -or $_.ProcessName -like "*$pkgName*")
            } | Select-Object -First 1
            if ($matchingProc) {
                Write-CmdLog "GÜNCELLEME" "BİLGİ: $($matchingProc.ProcessName) arka planda çalışıyor." "Yellow"
            }
        } catch {}

        # 4 Aşamalı Sağlam Güncelleme Motoru (Fallback Zinciri)
        # 1. Aşama: ID ile sessiz ve zorlamalı güncelleme (--silent --force --include-unknown)
        # 2. Aşama: ID bulunamazsa paket adıyla deneme
        # 3. Aşama: Tam ID (--exact) ile deneme
        # 4. Aşama: Güncelleme davranışı install olan paketler için zorlamalı in-place yükleme (winget install --force)
        $script:activeUpdateLog = "$env:TEMP\temizwin_upd_$($script:activeUpdateIndex).log"
        if (Test-Path $script:activeUpdateLog) { Remove-Item $script:activeUpdateLog -Force -ErrorAction SilentlyContinue }

        $batchFile = "$env:TEMP\temizwin_exec_upd.bat"
        $commonFlags = "--silent --force --include-unknown --accept-package-agreements --accept-source-agreements --disable-interactivity"
        $batchScript = "@echo off`r`nchcp 65001 >nul`r`n" +
            "winget upgrade --id `"$pkgId`" $commonFlags > `"$($script:activeUpdateLog)`" 2>&1`r`n" +
            "if %ERRORLEVEL% EQU 0 exit /b 0`r`n" +
            "if %ERRORLEVEL% EQU 3010 exit /b 3010`r`n" +
            "if not `"$pkgName`"==`"`" (`r`n" +
            "    winget upgrade --name `"$pkgName`" $commonFlags >> `"$($script:activeUpdateLog)`" 2>&1`r`n" +
            "    if %ERRORLEVEL% EQU 0 exit /b 0`r`n" +
            "    if %ERRORLEVEL% EQU 3010 exit /b 3010`r`n" +
            ")`r`n" +
            "winget upgrade --exact --id `"$pkgId`" $commonFlags >> `"$($script:activeUpdateLog)`" 2>&1`r`n" +
            "if %ERRORLEVEL% EQU 0 exit /b 0`r`n" +
            "if %ERRORLEVEL% EQU 3010 exit /b 3010`r`n" +
            "winget install --id `"$pkgId`" $commonFlags >> `"$($script:activeUpdateLog)`" 2>&1`r`n" +
            "exit /b %ERRORLEVEL%`r`n"

        [System.IO.File]::WriteAllText($batchFile, $batchScript, [System.Text.Encoding]::UTF8)

        Write-CmdLog "GÜNCELLEME" "winget upgrade [$pkgId | $pkgName] (4 aşamalı sessiz & zorlamalı motor)..." "Cyan"

        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = "cmd.exe"
        $psi.Arguments = "/c `"$batchFile`""
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        try {
            $script:activeUpdateProc = [System.Diagnostics.Process]::Start($psi)
        } catch {
            Write-CmdLog "GÜNCELLEME" "Başlatılamadı ($pkgId): $($_.Exception.Message)" "Red"
            $script:activeUpdateProc = $null
            if ($script:failedUpdates) { $script:failedUpdates.Add($pkgName) }
        }
    } else {
        $script:updateTimer.Stop()
        $btnExecuteUpdates.IsEnabled = $true

        $succCount = if ($script:successfulUpdates) { $script:successfulUpdates.Count } else { 0 }
        $failCount = if ($script:failedUpdates) { $script:failedUpdates.Count } else { 0 }

        if ($failCount -eq 0 -and $succCount -gt 0) {
            $lblUpdateProgressText.Text = "Seçilen tüm programlar ($succCount adet) başarıyla güncellendi! 🚀"
            Write-CmdLog "GÜNCELLEME" "✓ Seçilen tüm programlar ($succCount adet) eksiksiz güncellendi." "Green"
            Scan-WingetUpdates
            [System.Windows.MessageBox]::Show($window, "Seçilen $succCount programın tamamı başarıyla güncellendi!", "TemizWin - Güncelleme Başarılı", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
        } elseif ($succCount -gt 0 -and $failCount -gt 0) {
            $failedNames = ($script:failedUpdates | ForEach-Object { "• $_" }) -join "`n"
            $lblUpdateProgressText.Text = "Kısmi Güncelleme: $succCount başarılı, $failCount atlandı."
            Write-CmdLog "GÜNCELLEME" "Kısmi tamamlandı: $succCount başarılı, $failCount başarısız/atlandı." "Yellow"
            Scan-WingetUpdates
            $msg = "$succCount program başarıyla güncellendi.`n`nAncak şu $failCount program güncellenemedi (Program o an arka planda açık olabilir veya yönetici izni gerekebilir):`n`n$failedNames"
            [System.Windows.MessageBox]::Show($window, $msg, "TemizWin - Güncelleme Raporu", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
        } elseif ($failCount -gt 0) {
            $failedNames = ($script:failedUpdates | ForEach-Object { "• $_" }) -join "`n"
            $lblUpdateProgressText.Text = "Seçilen güncellemeler uygulanamadı ($failCount atlandı)."
            Write-CmdLog "GÜNCELLEME" "Seçilen programlar güncellenemedi (Atlandı)." "Red"
            Scan-WingetUpdates
            $msg = "Seçilen program(lar) güncellenemedi:`n`n$failedNames`n`nİpucu: Güncellemeye çalıştığınız program arka planda (saat yanında) açıksa lütfen önce programı tamamen kapatıp tekrar deneyin."
            [System.Windows.MessageBox]::Show($window, $msg, "TemizWin - Güncelleme Başarısız", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
        } else {
            $lblUpdateProgressText.Text = "Güncelleme tamamlandı."
            Scan-WingetUpdates
        }
    }
})

function Execute-PackageUpdates {
    $checkedRows = @()
    foreach ($item in $pnlUpdateList.Children) {
        if ($item -is [System.Windows.Controls.Border]) {
            $grid = $item.Child
            if ($grid -and $grid.Children.Count -gt 0) {
                $cb = $grid.Children[0]
                if ($cb -is [System.Windows.Controls.CheckBox] -and $cb.IsChecked) {
                    $pkgData = $item.DataContext
                    $progName = if ($pkgData -and $pkgData.Name) { [string]$pkgData.Name } else { [string]$item.Tag }
                    $targetVer = if ($pkgData -and $pkgData.Available) { [string]$pkgData.Available } else { "" }
                    $checkedRows += @{
                        Tag           = [string]$item.Tag
                        Name          = $progName
                        TargetVersion = $targetVer
                        Badge         = if ($grid.Children.Count -ge 4) { $grid.Children[3] } else { $null }
                    }
                }
            }
        }
    }

    if ($checkedRows.Count -eq 0) {
        [System.Windows.MessageBox]::Show($window, "Lütfen güncellenecek en az bir program seçin.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }

    Write-CmdLog "GÜNCELLEME" ">>> Güncelleme paketi başlatıldı: $($checkedRows.Count) program sırayla güncelleniyor..." "Cyan"

    $script:successfulUpdates = [System.Collections.Generic.List[string]]::new()
    $script:failedUpdates = [System.Collections.Generic.List[string]]::new()

    $btnExecuteUpdates.IsEnabled = $false
    $progUpdate.Maximum = $checkedRows.Count
    $progUpdate.Value = 0
    $script:activeUpdateIndex = 0

    $script:updateQueue.Clear()
    foreach ($row in $checkedRows) {
        $null = $script:updateQueue.Add($row)
    }

    $script:updateTimer.Start()
}

