# Başlık Çubuğu Taşıma
$pnlTitleBar.Add_MouseLeftButtonDown({
    if ($_.LeftButton -eq [System.Windows.Input.MouseButtonState]::Pressed) { $window.DragMove() }
})

# ------------------------------------------------------------------------------
# Modern Yeniden Başlatma İstemi Diyaloğu (İnce Ayarlar Çıkış Uyarı Kartı)
# ------------------------------------------------------------------------------
function Show-ModernRebootPrompt([System.Windows.Window]$ownerWin, [string[]]$changedTweaks) {
    try {
        $tweakListText = ($changedTweaks | ForEach-Object { "  • $_" }) -join "`n"

        $dialogXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="TemizWin - Yeniden Başlatma Gerekli"
        Width="500" SizeToContent="Height"
        WindowStartupLocation="CenterOwner"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        Topmost="True" ShowInTaskbar="False">
    <Border Background="#0F131F" BorderBrush="#1E2638" BorderThickness="1.5" CornerRadius="14" Padding="24">
        <Border.Effect>
            <DropShadowEffect Color="#000000" BlurRadius="25" ShadowDepth="6" Opacity="0.6"/>
        </Border.Effect>
        <StackPanel>
            <!-- Başlık Satırı -->
            <StackPanel Orientation="Horizontal" Margin="0,0,0,16">
                <Border Background="#3B2610" Width="40" Height="40" CornerRadius="10" Margin="0,0,14,0">
                    <TextBlock Text="⚠️" FontSize="20" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <StackPanel VerticalAlignment="Center">
                    <TextBlock Text="Bilgisayarı Yeniden Başlatma Gerekli" FontSize="16" FontWeight="Bold" Foreground="#FFFFFF"/>
                    <TextBlock Text="Yaptığınız sistem işlemlerinin tam geçerli olması için sistem yeniden başlatılmalı." FontSize="11" Foreground="#94A3B8"/>
                </StackPanel>
            </StackPanel>

            <!-- Değiştirilen Ayarlar Kutusu -->
            <Border Background="#161B2B" BorderBrush="#1E2638" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,18" MaxHeight="160">
                <ScrollViewer VerticalScrollBarVisibility="Auto">
                    <StackPanel>
                        <TextBlock Text="Yeniden Başlatma Bekleyen İşlemler:" FontSize="12" FontWeight="SemiBold" Foreground="#F59E0B" Margin="0,0,0,6"/>
                        <TextBlock x:Name="lblTweaksList" FontSize="12" Foreground="#E2E8F0" TextWrapping="Wrap" LineHeight="18"/>
                    </StackPanel>
                </ScrollViewer>
            </Border>

            <!-- Açıklama -->
            <TextBlock Text="Değişikliklerin etkili olması için bilgisayarı şimdi yeniden başlatmak ister misiniz?" FontSize="12" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,0,0,20"/>

            <!-- Butonlar -->
            <DockPanel LastChildFill="False">
                <Button x:Name="btnLater" Content="Daha Sonra" Width="130" Height="38"
                        Background="#1E2338" Foreground="#94A3B8" BorderThickness="0"
                        FontWeight="SemiBold" FontSize="13" Cursor="Hand" DockPanel.Dock="Left">
                    <Button.Resources>
                        <Style TargetType="Border">
                            <Setter Property="CornerRadius" Value="8"/>
                        </Style>
                    </Button.Resources>
                </Button>

                <Button x:Name="btnRestartNow" Content="⚡ Şimdi Yeniden Başlat" Width="190" Height="38"
                        Background="#2563EB" Foreground="#FFFFFF" BorderThickness="0"
                        FontWeight="Bold" FontSize="13" Cursor="Hand" DockPanel.Dock="Right">
                    <Button.Resources>
                        <Style TargetType="Border">
                            <Setter Property="CornerRadius" Value="8"/>
                        </Style>
                    </Button.Resources>
                </Button>
            </DockPanel>
        </StackPanel>
    </Border>
</Window>
"@

        $reader = [System.Xml.XmlReader]::Create([System.IO.StringReader]::new($dialogXaml))
        $dlg = [System.Windows.Markup.XamlReader]::Load($reader)
        if ($ownerWin) { $dlg.Owner = $ownerWin }

        $lblList = $dlg.FindName("lblTweaksList")
        if ($lblList) { $lblList.Text = $tweakListText }

        $btnLater = $dlg.FindName("btnLater")
        $btnRestart = $dlg.FindName("btnRestartNow")

        $script:dlgResult = "Later"

        if ($btnLater) {
            $btnLater.Add_Click({
                $script:dlgResult = "Later"
                $dlg.Close()
            })
        }

        if ($btnRestart) {
            $btnRestart.Add_Click({
                $script:dlgResult = "Restart"
                $dlg.Close()
            })
        }

        $dlg.ShowDialog() | Out-Null

        if ($script:dlgResult -eq "Restart") {
            $script:isRebootPromptHandled = $true
            Write-CmdLog "SİSTEM" "shutdown.exe /r /t 2 /f (Bilgisayar yeniden başlatılıyor...)" "Yellow"
            $shutdownExe = [System.IO.Path]::Combine($env:SystemRoot, "System32", "shutdown.exe")
            try {
                Start-Process -FilePath $shutdownExe -ArgumentList '/r /t 2 /f /c "TemizWin: Sistem ayarlarının geçerli olması için bilgisayar yeniden başlatılıyor..."' -WindowStyle Hidden -ErrorAction SilentlyContinue
            } catch {
                Restart-Computer -Force -ErrorAction SilentlyContinue
            }
            if ($ownerWin) {
                try { $ownerWin.Close() } catch {}
            }
        }

        return $script:dlgResult
    } catch {
        # WPF modal açılamazsa güvenli standart MessageBox yedeği
        $msg = "Yaptığınız şu ayarların geçerli olması için bilgisayarın yeniden başlatılması gerekiyor:`n`n" +
               (($changedTweaks | ForEach-Object { "• $_" }) -join "`n") +
               "`n`nBilgisayarı şimdi yeniden başlatmak istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($ownerWin, $msg, "TemizWin - Yeniden Başlatma Gerekli", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
        if ($ans -eq [System.Windows.MessageBoxResult]::Yes) {
            $script:isRebootPromptHandled = $true
            Write-CmdLog "SİSTEM" "shutdown.exe /r /t 2 /f (Bilgisayar yeniden başlatılıyor...)" "Yellow"
            $shutdownExe = [System.IO.Path]::Combine($env:SystemRoot, "System32", "shutdown.exe")
            try {
                Start-Process -FilePath $shutdownExe -ArgumentList '/r /t 2 /f /c "TemizWin: Sistem ayarlarının geçerli olması için bilgisayar yeniden başlatılıyor..."' -WindowStyle Hidden -ErrorAction SilentlyContinue
            } catch {
                Restart-Computer -Force -ErrorAction SilentlyContinue
            }
            if ($ownerWin) {
                try { $ownerWin.Close() } catch {}
            }
            return "Restart"
        }
        return "Later"
    }
}

