    @{ Name = "FrameServerMonitor"; Group = "Kamera & Video"; Safe = $false; DefaultStart = "Manual"; Title = "Kamera Çerçeve Sunucusu İzleyicisi"; Desc = "Kamera sunucu süreçlerini izler." },
    @{ Name = "WbioSrvc"; Group = "Biyometri"; Safe = $false; DefaultStart = "Manual"; Title = "Windows Biyometrik Hizmeti (Windows Hello)"; Desc = "Parmak izi okuyucu ve yüz tanıma (Windows Hello) donanımını yönetir." },
    @{ Name = "icssvc"; Group = "Mobil Ağ"; Safe = $false; DefaultStart = "Manual"; Title = "Windows Mobil Etkin Nokta Hizmeti (Hotspot)"; Desc = "Bilgisayarın internetini Wi-Fi hotspot olarak diğer cihazlarla paylaşır." },
    @{ Name = "SharedAccess"; Group = "Mobil Ağ"; Safe = $false; DefaultStart = "Manual"; Title = "İnternet Bağlantısı Paylaşımı (ICS)"; Desc = "Ağ bağdaştırıcıları arasında internet paylaşımını yönetir." },
    @{ Name = "TermService"; Group = "Uzak Masaüstü"; Safe = $false; DefaultStart = "Manual"; Title = "Uzak Masaüstü Hizmetleri (RDP)"; Desc = "Bilgisayarınıza uzaktan RDP bağlantısı yapılmasını sağlar." },
    @{ Name = "UmRdpService"; Group = "Uzak Masaüstü"; Safe = $false; DefaultStart = "Manual"; Title = "Uzak Masaüstü Bağlantı Noktası Yönlendiricisi"; Desc = "Uzak masaüstü oturumlarında sürücü yönlendirmesini yönetir." },
    @{ Name = "SessionEnv"; Group = "Uzak Masaüstü"; Safe = $false; DefaultStart = "Manual"; Title = "Uzak Masaüstü Yapılandırması"; Desc = "Uzak masaüstü ortamlarını yapılandırır." }
)

function Show-ModernServicesDialog([System.Windows.Window]$ownerWin) {
    try {
        $dialogXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="TemizWin - Windows Hizmetleri Yöneticisi"
        Width="750" Height="660"
        WindowStartupLocation="CenterOwner"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        Topmost="True" ShowInTaskbar="False">
    <Border Background="#0F131F" BorderBrush="#1E2638" BorderThickness="1.5" CornerRadius="14" Padding="20">
        <Border.Effect>
            <DropShadowEffect Color="#000000" BlurRadius="25" ShadowDepth="6" Opacity="0.6"/>
        </Border.Effect>
        <Grid>
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>

            <!-- Başlık Satırı -->
            <DockPanel Grid.Row="0" Margin="0,0,0,14" LastChildFill="True">
                <Button x:Name="btnSvcCloseTop" DockPanel.Dock="Right" Content="✕" Width="28" Height="28" Background="#1E2338" Foreground="#94A3B8" BorderThickness="0" Cursor="Hand" FontWeight="Bold" VerticalAlignment="Top">
                    <Button.Resources>
                        <Style TargetType="Border">
                            <Setter Property="CornerRadius" Value="6"/>
                        </Style>
                    </Button.Resources>
                </Button>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                    <Border Background="#2E1065" Width="38" Height="38" CornerRadius="10" Margin="0,0,12,0" VerticalAlignment="Center">
                        <TextBlock Text="🛠️" FontSize="18" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Windows Arka Plan Hizmetleri Yöneticisi" FontSize="16" FontWeight="Bold" Foreground="#FFFFFF"/>
                        <TextBlock Text="Kullanılmayan sistem servislerini devre dışı bırakarak RAM ve CPU yükünü hafifletin." FontSize="11" Foreground="#94A3B8"/>
                    </StackPanel>
                </StackPanel>
            </DockPanel>

            <!-- Hızlı Seçim Araç Çubuğu -->
            <Border Grid.Row="1" Background="#141826" BorderBrush="#1E2638" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,0,0,10">
                <DockPanel LastChildFill="True">
                    <TextBlock x:Name="lblSvcSelectedCount" Text="0 hizmet seçildi" DockPanel.Dock="Right" FontSize="11" Foreground="#38BDF8" FontWeight="SemiBold" VerticalAlignment="Center"/>
                    <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                        <TextBlock Text="Hızlı Seçim:" FontSize="11" FontWeight="SemiBold" Foreground="#64748B" VerticalAlignment="Center" Margin="0,0,8,0"/>
                        <Button x:Name="btnSelectSafeSvcs" Content="⚡ Güvenli Olanları Seç" Background="#1E2638" Foreground="#C084FC" BorderThickness="0" Padding="10,4" Cursor="Hand" FontWeight="SemiBold" FontSize="11" Margin="0,0,6,0">
                            <Button.Resources>
                                <Style TargetType="Border">
                                    <Setter Property="CornerRadius" Value="6"/>
                                </Style>
                            </Button.Resources>
                        </Button>
                        <Button x:Name="btnSelectAllSvcs" Content="Tümünü Seç" Background="#1E2638" Foreground="#94A3B8" BorderThickness="0" Padding="8,4" Cursor="Hand" FontSize="11" Margin="0,0,6,0">
                            <Button.Resources>
                                <Style TargetType="Border">
                                    <Setter Property="CornerRadius" Value="6"/>
                                </Style>
                            </Button.Resources>
                        </Button>
                        <Button x:Name="btnClearSvcSelection" Content="Temizle" Background="#1E2638" Foreground="#94A3B8" BorderThickness="0" Padding="8,4" Cursor="Hand" FontSize="11">
                            <Button.Resources>
                                <Style TargetType="Border">
                                    <Setter Property="CornerRadius" Value="6"/>
                                </Style>
                            </Button.Resources>
                        </Button>
                    </StackPanel>
                </DockPanel>
            </Border>

            <!-- Servisler Listesi -->
            <Border Grid.Row="2" Background="#121624" BorderBrush="#1A1F30" BorderThickness="1" CornerRadius="10" Padding="10" Margin="0,0,0,12">
                <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                    <StackPanel x:Name="pnlServicesList"/>
                </ScrollViewer>
            </Border>

            <!-- Alt Eylem Butonları -->
            <DockPanel Grid.Row="3" LastChildFill="True">
                <Button x:Name="btnRestoreServices" Content="↺ Varsayılana Döndür (Geri Al)" DockPanel.Dock="Left" Height="36" Padding="14,0"
                        Background="#1E2338" Foreground="#94A3B8" BorderThickness="0"
                        FontWeight="SemiBold" FontSize="12" Cursor="Hand">
                    <Button.Resources>
                        <Style TargetType="Border">
                            <Setter Property="CornerRadius" Value="8"/>
                        </Style>
                    </Button.Resources>
                </Button>

                <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
                    <Button x:Name="btnApplyDisableServices" Content="⚡ Seçilenleri Devre Dışı Bırak" Height="36" Padding="16,0"
                            Background="#7C3AED" Foreground="#FFFFFF" BorderThickness="0"
                            FontWeight="Bold" FontSize="13" Cursor="Hand" Margin="0,0,10,0">
                        <Button.Resources>
                            <Style TargetType="Border">
                                <Setter Property="CornerRadius" Value="8"/>
                            </Style>
                        </Button.Resources>
                    </Button>

                    <Button x:Name="btnSvcCloseBottom" Content="Kapat" Height="36" Width="80"
                            Background="#1E2338" Foreground="#94A3B8" BorderThickness="0"
                            FontWeight="SemiBold" FontSize="12" Cursor="Hand">
                        <Button.Resources>
                            <Style TargetType="Border">
                                <Setter Property="CornerRadius" Value="8"/>
                            </Style>
                        </Button.Resources>
                    </Button>
                </StackPanel>
            </DockPanel>
        </Grid>
    </Border>
</Window>
"@

        $reader = [System.Xml.XmlReader]::Create([System.IO.StringReader]::new($dialogXaml))
        $dlg = [System.Windows.Markup.XamlReader]::Load($reader)
        if ($ownerWin) { $dlg.Owner = $ownerWin }

        $pnlServicesList        = $dlg.FindName("pnlServicesList")
        $lblSvcSelectedCount    = $dlg.FindName("lblSvcSelectedCount")
        $btnSelectSafeSvcs      = $dlg.FindName("btnSelectSafeSvcs")
        $btnSelectAllSvcs       = $dlg.FindName("btnSelectAllSvcs")
        $btnClearSvcSelection   = $dlg.FindName("btnClearSvcSelection")
        $btnRestoreServices     = $dlg.FindName("btnRestoreServices")
        $btnApplyDisableServices= $dlg.FindName("btnApplyDisableServices")
        $btnSvcCloseTop         = $dlg.FindName("btnSvcCloseTop")
        $btnSvcCloseBottom      = $dlg.FindName("btnSvcCloseBottom")

        $bc = [System.Windows.Media.BrushConverter]::new()
        $rowBindings = [System.Collections.Generic.List[PSCustomObject]]::new()

        $updateSelectionCount = {
            $cnt = 0
            foreach ($rb in $rowBindings) {
                if ($rb.CheckBox.IsChecked) { $cnt++ }
            }
            if ($lblSvcSelectedCount) {
                $lblSvcSelectedCount.Text = "$cnt / $($rowBindings.Count) hizmet seçildi"
            }
        }

        # Servis satırlarını oluştur ve listeye ekle
        foreach ($item in $script:windowsServicesDefinitions) {
            $sName = $item.Name
            $svc = Get-Service -Name $sName -ErrorAction SilentlyContinue
            if (-not $svc -and $item.AltName) {
                $alt = Get-Service -Name $item.AltName -ErrorAction SilentlyContinue
                if ($alt) { $sName = $item.AltName; $svc = $alt }
            }

            $startType = if ($svc) { [string]$svc.StartType } else { "Yok" }
            $status = if ($svc) { [string]$svc.Status } else { "Kurulu Değil" }

            $row = [System.Windows.Controls.Border]::new()
            $row.Background = $bc.ConvertFromString("#161B2B")
            $row.BorderBrush = $bc.ConvertFromString("#1E2638")
            $row.BorderThickness = [System.Windows.Thickness]::new(1)
            $row.CornerRadius = [System.Windows.CornerRadius]::new(8)
            $row.Padding = [System.Windows.Thickness]::new(10, 8, 10, 8)
            $row.Margin = [System.Windows.Thickness]::new(0, 0, 0, 6)

            $dock = [System.Windows.Controls.DockPanel]::new()
            $dock.LastChildFill = $true

            # Sağ durum rozeti
            $badgeBorder = [System.Windows.Controls.Border]::new()
            $badgeBorder.CornerRadius = [System.Windows.CornerRadius]::new(6)
            $badgeBorder.Padding = [System.Windows.Thickness]::new(8, 2, 8, 2)
            $badgeBorder.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
            [System.Windows.Controls.DockPanel]::SetDock($badgeBorder, [System.Windows.Controls.Dock]::Right)

            $tbBadge = [System.Windows.Controls.TextBlock]::new()
            $tbBadge.FontSize = 11
            $tbBadge.FontWeight = [System.Windows.FontWeights]::SemiBold

            if (-not $svc) {
                $badgeBorder.Background = $bc.ConvertFromString("#181B26")
                $tbBadge.Text = "Yüklü Değil"
                $tbBadge.Foreground = $bc.ConvertFromString("#64748B")
            } elseif ($startType -eq "Disabled") {
                $badgeBorder.Background = $bc.ConvertFromString("#1F2937")
                $tbBadge.Text = "Devre Dışı"
                $tbBadge.Foreground = $bc.ConvertFromString("#94A3B8")
            } elseif ($status -eq "Running") {
                $badgeBorder.Background = $bc.ConvertFromString("#064E3B")
                $tbBadge.Text = "Çalışıyor"
                $tbBadge.Foreground = $bc.ConvertFromString("#34D399")
            } else {
                $badgeBorder.Background = $bc.ConvertFromString("#3B2610")
                $tbBadge.Text = "Durduruldu"
                $tbBadge.Foreground = $bc.ConvertFromString("#FBBF24")
            }
            $badgeBorder.Child = $tbBadge
            $dock.Children.Add($badgeBorder) | Out-Null

            # Sol Checkbox
            $cb = [System.Windows.Controls.CheckBox]::new()
            $cb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
            $cb.Margin = [System.Windows.Thickness]::new(0, 0, 10, 0)
            if ($item.Safe -and $svc -and $startType -ne "Disabled") {
                $cb.IsChecked = $true
            } else {
                $cb.IsChecked = $false
            }
            $cb.Add_Click({ & $updateSelectionCount })
            [System.Windows.Controls.DockPanel]::SetDock($cb, [System.Windows.Controls.Dock]::Left)
            $dock.Children.Add($cb) | Out-Null

            # Orta Metinler
            $sp = [System.Windows.Controls.StackPanel]::new()
            $sp.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

            $spTitle = [System.Windows.Controls.StackPanel]::new()
            $spTitle.Orientation = [System.Windows.Controls.Orientation]::Horizontal

            $tbTitle = [System.Windows.Controls.TextBlock]::new()
            $tbTitle.Text = $item.Title
            $tbTitle.FontWeight = [System.Windows.FontWeights]::Bold
            $tbTitle.FontSize = 12
            $tbTitle.Foreground = $bc.ConvertFromString("#FFFFFF")
            $spTitle.Children.Add($tbTitle) | Out-Null

            # Kategori Etiketi
            $tagBorder = [System.Windows.Controls.Border]::new()
            $tagBorder.CornerRadius = [System.Windows.CornerRadius]::new(4)
            $tagBorder.Padding = [System.Windows.Thickness]::new(6, 1, 6, 1)
            $tagBorder.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)

            $tbTag = [System.Windows.Controls.TextBlock]::new()
            $tbTag.FontSize = 10
            $tbTag.FontWeight = [System.Windows.FontWeights]::Bold

            if ($item.Safe) {
                $tagBorder.Background = $bc.ConvertFromString("#2E1065")
                $tbTag.Text = $item.Group
                $tbTag.Foreground = $bc.ConvertFromString("#C084FC")
            } else {
                $tagBorder.Background = $bc.ConvertFromString("#3B2610")
                $tbTag.Text = "⚠️ " + $item.Group
                $tbTag.Foreground = $bc.ConvertFromString("#F59E0B")
            }
            $tagBorder.Child = $tbTag
            $spTitle.Children.Add($tagBorder) | Out-Null

            $sp.Children.Add($spTitle) | Out-Null

            $tbDesc = [System.Windows.Controls.TextBlock]::new()
            $tbDesc.Text = "$sName • $($item.Desc)"
            $tbDesc.FontSize = 11
            $tbDesc.Foreground = $bc.ConvertFromString("#94A3B8")
            $tbDesc.TextWrapping = [System.Windows.TextWrapping]::Wrap
            $tbDesc.Margin = [System.Windows.Thickness]::new(0, 2, 0, 0)
            $sp.Children.Add($tbDesc) | Out-Null

            $dock.Children.Add($sp) | Out-Null
            $row.Child = $dock

            $pnlServicesList.Children.Add($row) | Out-Null

            $rowBindings.Add([PSCustomObject]@{
                Item        = $item
                ResolvedName= $sName
                CheckBox    = $cb
                BadgeBorder = $badgeBorder
                BadgeText   = $tbBadge
            })
        }

        & $updateSelectionCount

        # Hızlı Seçim Butonları
        if ($btnSelectSafeSvcs) {
            $btnSelectSafeSvcs.Add_Click({
                foreach ($rb in $rowBindings) {
                    $rb.CheckBox.IsChecked = [bool]$rb.Item.Safe
                }
                & $updateSelectionCount
            })
        }

        if ($btnSelectAllSvcs) {
            $btnSelectAllSvcs.Add_Click({
                foreach ($rb in $rowBindings) {
                    $rb.CheckBox.IsChecked = $true
                }
                & $updateSelectionCount
            })
        }

        if ($btnClearSvcSelection) {
            $btnClearSvcSelection.Add_Click({
                foreach ($rb in $rowBindings) {
                    $rb.CheckBox.IsChecked = $false
                }
                & $updateSelectionCount
            })
        }

        # Kapat Butonları
        if ($btnSvcCloseTop) { $btnSvcCloseTop.Add_Click({ $dlg.Close() }) }
        if ($btnSvcCloseBottom) { $btnSvcCloseBottom.Add_Click({ $dlg.Close() }) }

        # Sürükleme desteği
        $dlg.Add_MouseLeftButtonDown({
            if ($_.LeftButton -eq [System.Windows.Input.MouseButtonState]::Pressed) { $dlg.DragMove() }
        })

        # Seçilenleri Devre Dışı Bırak Butonu
        if ($btnApplyDisableServices) {
            $btnApplyDisableServices.Add_Click({
                $selectedRows = @($rowBindings | Where-Object { $_.CheckBox.IsChecked })
                if ($selectedRows.Count -eq 0) {
                    [System.Windows.MessageBox]::Show($dlg, "Lütfen devre dışı bırakmak için en az bir hizmet seçin.", "Hizmet Seçilmedi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                    return
                }

                $msg = "Seçilen $($selectedRows.Count) adet Windows hizmeti devre dışı bırakılacak (Disabled) ve arka planda çalışanlar anında durdurulacaktır.`n`nDevam etmek istiyor musunuz?"
                $ans = [System.Windows.MessageBox]::Show($dlg, $msg, "Hizmetleri Devre Dışı Bırak", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
                if ($ans -ne [System.Windows.MessageBoxResult]::Yes) { return }

                $btnApplyDisableServices.IsEnabled = $false
                try {
                    Write-CmdLog "SERVİS" ">>> $($selectedRows.Count) adet Windows hizmeti devre dışı bırakılıyor..." "Yellow"
                    Write-Terminal "Windows hizmetleri optimizasyonu başlatıldı ($($selectedRows.Count) hizmet)..."

                    $successCount = 0
                    foreach ($rb in $selectedRows) {
                        $sName = $rb.ResolvedName
                        $svc = Get-Service -Name $sName -ErrorAction SilentlyContinue
                        if ($svc) {
                            try {
                                Set-Service -Name $sName -StartupType Disabled -ErrorAction SilentlyContinue
                                Stop-Service -Name $sName -Force -ErrorAction SilentlyContinue
                                Write-Terminal "  [✓] Devre dışı: $($rb.Item.Title) ($sName)"
                                Write-CmdLog "SERVİS" "Set-Service -Name '$sName' -StartupType Disabled" "Green"
                                $successCount++
                            } catch {}
                        }

                        # Canlı rozet güncelle
                        $rb.BadgeBorder.Background = $bc.ConvertFromString("#1F2937")
                        $rb.BadgeText.Text = "Devre Dışı"
                        $rb.BadgeText.Foreground = $bc.ConvertFromString("#94A3B8")
                    }

                    Write-CmdLog "SERVİS" "[+] $successCount adet Windows hizmeti başarıyla devre dışı bırakıldı." "Green"
                    Write-Terminal "Optimizasyon tamamlandı! $successCount hizmet devre dışı bırakıldı."

                    [System.Windows.MessageBox]::Show($dlg, "Seçilen $successCount adet Windows hizmeti başarıyla devre dışı bırakıldı ve durduruldu.`n`nRAM ve işlemci kaynakları rahatlatıldı.", "TemizWin - Hizmetler Devre Dışı Bırakıldı", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                } finally {
                    $btnApplyDisableServices.IsEnabled = $true
                    & $updateSelectionCount
                }
            })
        }

        # Varsayılana Döndür Butonu
        if ($btnRestoreServices) {
            $btnRestoreServices.Add_Click({
                $msg = "Tüm listelenen hizmetler orijinal başlangıç türüne (Manuel / Otomatik) geri döndürülecektir.`n`nBu işlem sistemin varsayılan düzenini geri yükler. Devam etmek istiyor musunuz?"
                $ans = [System.Windows.MessageBox]::Show($dlg, $msg, "Hizmetleri Varsayılana Döndür", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
                if ($ans -ne [System.Windows.MessageBoxResult]::Yes) { return }

                $btnRestoreServices.IsEnabled = $false
                try {
                    Write-CmdLog "SERVİS" ">>> Tüm Windows hizmetleri varsayılan ayarlarına geri döndürülüyor..." "Yellow"
                    Write-Terminal "Hizmetler varsayılan ayarlarına geri döndürülüyor..."

                    $restoredCount = 0
                    foreach ($rb in $rowBindings) {
                        $sName = $rb.ResolvedName
                        $svc = Get-Service -Name $sName -ErrorAction SilentlyContinue
                        if ($svc) {
                            $defType = if ($rb.Item.DefaultStart) { $rb.Item.DefaultStart } else { "Manual" }
                            try {
                                Set-Service -Name $sName -StartupType $defType -ErrorAction SilentlyContinue
                                Write-Terminal "  [↺] Varsayılan ($defType): $($rb.Item.Title) ($sName)"
                                Write-CmdLog "SERVİS" "Set-Service -Name '$sName' -StartupType $defType" "Green"
                                $restoredCount++
                            } catch {}
                        }

                        # Canlı rozet güncelle
                        $freshSvc = Get-Service -Name $sName -ErrorAction SilentlyContinue
                        if ($freshSvc) {
                            if ([string]$freshSvc.Status -eq "Running") {
                                $rb.BadgeBorder.Background = $bc.ConvertFromString("#064E3B")
                                $rb.BadgeText.Text = "Çalışıyor"
                                $rb.BadgeText.Foreground = $bc.ConvertFromString("#34D399")
                            } else {
                                $rb.BadgeBorder.Background = $bc.ConvertFromString("#3B2610")
                                $rb.BadgeText.Text = "Durduruldu"
                                $rb.BadgeText.Foreground = $bc.ConvertFromString("#FBBF24")
                            }
                        }
                    }

                    Write-CmdLog "SERVİS" "[+] $restoredCount adet hizmet başarıyla varsayılan başlangıç türüne döndürüldü." "Green"
                    Write-Terminal "Geri alma tamamlandı! $restoredCount hizmet varsayılan ayarlarına döndürüldü."

                    [System.Windows.MessageBox]::Show($dlg, "Tüm Windows hizmetleri başarıyla varsayılan başlangıç türüne (Manuel/Otomatik) geri döndürüldü.", "TemizWin - Hizmetler Geri Yüklendi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                } finally {
                    $btnRestoreServices.IsEnabled = $true
                    & $updateSelectionCount
                }
            })
        }

        $dlg.ShowDialog() | Out-Null
    } catch {
        [System.Windows.MessageBox]::Show($ownerWin, "Hizmet yöneticisi penceresi açılırken bir hata oluştu: $($_.Exception.Message)", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
    }
}

# Minimize & Kapat
$btnWinMinimize.Add_Click({ $window.WindowState = [System.Windows.WindowState]::Minimized })
$btnWinClose.Add_Click({ $window.Close() })

# Pencere Kapanırken Yeniden Başlatma İstemi Kontrolü
$script:isRebootPromptHandled = $false
$window.Add_Closing({
    param($sender, $e)
    if ($script:isRebootPromptHandled) { return }

    if ($script:pendingRebootTweaks -and $script:pendingRebootTweaks.Count -gt 0) {
        $tweakArr = @($script:pendingRebootTweaks)
        $res = Show-ModernRebootPrompt $window $tweakArr
        $script:isRebootPromptHandled = $true
        if ($res -eq "Restart") {
            Write-CmdLog "SİSTEM" "shutdown.exe /r /t 5 (Bilgisayar yeniden başlatılıyor...)" "Yellow"
            Start-Process -FilePath "shutdown.exe" -ArgumentList '/r /t 5 /c "TemizWin: Yapılan sistem işlemlerinin geçerli olması için bilgisayar yeniden başlatılıyor..."' -WindowStyle Hidden -ErrorAction SilentlyContinue
        }
    }
})

# Pencere Kapanırken Temiz ve Kesin Çıkış
$window.Add_Closed({
    try {
        if ($script:activeHealthProc -and (-not $script:activeHealthProc.HasExited)) {
            $pId = $script:activeHealthProc.Id
            Start-Process -FilePath "taskkill.exe" -ArgumentList "/pid $pId /t /f" -NoNewWindow -Wait -ErrorAction SilentlyContinue
        }
    } catch {}
    [System.Environment]::Exit(0)
})

# Navigasyon Geçişleri
$btnNavClean.Add_Click({ Switch-View "Clean" })
$btnNavHealth.Add_Click({ Switch-View "Health" })
$btnNavUpdate.Add_Click({ Switch-View "Update" })
$btnBackFromClean.Add_Click({ Switch-View "Main" })
$btnBackFromHealth.Add_Click({ Switch-View "Main" })
$btnCloseUpdate.Add_Click({ Switch-View "Main" })
if ($btnBackFromUpdate) { $btnBackFromUpdate.Add_Click({ Switch-View "Main" }) }

# Hakkında ve Masaüstü Kısayolu Olayları
if ($btnAbout) {
    $btnAbout.Add_Click({
        if ($lblAboutStatus) { $lblAboutStatus.Text = "" }
        if ($pnlAboutOverlay) { $pnlAboutOverlay.Visibility = [System.Windows.Visibility]::Visible }
    })
}
if ($btnCloseAbout) {
    $btnCloseAbout.Add_Click({
        if ($pnlAboutOverlay) { $pnlAboutOverlay.Visibility = [System.Windows.Visibility]::Collapsed }
    })
}
if ($pnlAboutOverlay) {
