if ($btnCreateDesktopShortcut) {
    $btnCreateDesktopShortcut.Add_Click({
        try {
            $scriptPath = $MyInvocation.MyCommand.Path
            if (-not $scriptPath -or -not (Test-Path $scriptPath)) {
                $scriptPath = "C:\Users\hcorc\Desktop\TemizWin\TemizWin.ps1"
            }
            $wsh = New-Object -ComObject WScript.Shell
            $desktop = [Environment]::GetFolderPath("Desktop")
            $shortcutPath = Join-Path $desktop "TemizWin.lnk"
            $shortcut = $wsh.CreateShortcut($shortcutPath)
            $shortcut.TargetPath = "powershell.exe"
            $shortcut.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`""
            $shortcut.WorkingDirectory = Split-Path -Parent $scriptPath
            $shortcut.Description = "TemizWin v1.0 - Windows Bakım ve Performans Aracı (Geliştirici: HK)"
            # Windows Yerleşik Mavi Güvenlik Kalkanı Simgesi (Harici dosya gerektirmez)
            $shieldIcon = "$env:SystemRoot\System32\SecurityHealthSystray.exe"
            if (Test-Path $shieldIcon) {
                $shortcut.IconLocation = "$shieldIcon,0"
            } else {
                $shortcut.IconLocation = "$env:SystemRoot\System32\imageres.dll,-102"
            }
            $shortcut.Save()

            # Set Run as Administrator flag (0x15 byte bit 0x20)
            $bytes = [System.IO.File]::ReadAllBytes($shortcutPath)
            $bytes[0x15] = $bytes[0x15] -bor 0x20
            [System.IO.File]::WriteAllBytes($shortcutPath, $bytes)

            if ($lblAboutStatus) {
                $lblAboutStatus.Text = "✓ Masaüstü kısayolu yönetici yetkisiyle başarıyla oluşturuldu!"
                $lblAboutStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            }
            Write-CmdLog "KISAYOL" "Masaüstüne yönetici kısayolu oluşturuldu: $shortcutPath" "Green"
        } catch {
            if ($lblAboutStatus) {
                $lblAboutStatus.Text = "Hata: $($_.Exception.Message)"
                $lblAboutStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
            }
        }
    })
}

