# ------------------------------------------------------------------------------
# Performans Toggle ve Kontrol Tıklama Olayları (Bekleyen Değişiklik Sırası)
# ------------------------------------------------------------------------------
$perfToggleMap = [ordered]@{
    "tglPerfBackgroundApps"        = "BackgroundApps"
    "tglPerfSysMain"               = "SysMain"
    "tglPerfGameMode"              = "GameMode"
    "tglPerfWindowedOptimizations" = "WindowedOptimizations"
    "tglPerfGameDVR"               = "GameDVR"
    "tglPerfFSE"                   = "FSE"
    "tglPerfNagle"                 = "Nagle"
    "tglPerfPowerPlan"             = "PowerPlan"
    "tglPerfHAGS"                  = "HAGS"
    "tglPerfVBS"                   = "VBS"
    "tglPerfDynamicLighting"       = "DynamicLighting"
    "tglPerfVisualEffects"         = "VisualEffects"
    "tglPerfSearchIndexing"        = "SearchIndexing"
    "tglPerfNetOffload"            = "NetOffload"
}

$Script:PerfTweaksMeta = @{
    "BackgroundApps"        = @{ Name = "Arka Plan Uygulamalarını Kapat"; Req = "Instant" }
    "SysMain"               = @{ Name = "Diskten Hızlı Getirmeyi Kapat (SysMain)"; Req = "Instant" }
    "GameMode"              = @{ Name = "Oyun Modu (Windows Game Mode)"; Req = "Instant" }
    "WindowedOptimizations" = @{ Name = "Pencereli Mod İyileştirme Seçenekleri"; Req = "Instant" }
    "GameDVR"               = @{ Name = "Arka Planda Oyun Yakalama ve Kayıt (GameDVR)"; Req = "Instant" }
    "FSE"                   = @{ Name = "Doğrudan Tam Ekran İyileştirmeleri (FSE)"; Req = "Instant" }
    "Nagle"                 = @{ Name = "Nagle Ağ Algoritmasını Kapat (TCP Gecikmesi)"; Req = "Reboot" }
    "PowerPlan"             = @{ Name = "Nihai / Yüksek Performans Güç Planı"; Req = "Instant" }
    "HAGS"                  = @{ Name = "Donanım Hızlandırmalı GPU Zamanlaması (HAGS)"; Req = "Reboot" }
    "VBS"                   = @{ Name = "VBS ve Bellek Bütünlüğü (HVCI)"; Req = "Reboot" }
    "DynamicLighting"       = @{ Name = "Windows Dinamik Aydınlatma (RGB)"; Req = "Instant" }
    "VisualEffects"         = @{ Name = "Görsel Efektleri En İyi Performansa Ayarla"; Req = "Explorer" }
    "SearchIndexing"        = @{ Name = "Arama İndekslemesini Kapat (Windows Search)"; Req = "Instant" }
    "NetOffload"            = @{ Name = "Ağ Donanım Yükü Aktarımı (Task Offload)"; Req = "Reboot" }
}

foreach ($ctrlName in $perfToggleMap.Keys) {
    $ctrl = $window.FindName($ctrlName)
    if ($ctrl) {
        $ctrl.Add_Checked({
            if (-not $script:isUpdatingPerfUI) {
                Update-PendingPerfUI
            }
        })
        $ctrl.Add_Unchecked({
            if (-not $script:isUpdatingPerfUI) {
                Update-PendingPerfUI
            }
        })
    }
}

function Get-PendingPerfTweaks {
    $changes = [System.Collections.Generic.List[PSCustomObject]]::new()
    if ($perfToggleMap) {
        foreach ($ctrlName in $perfToggleMap.Keys) {
            $c = $window.FindName($ctrlName)
            if ($c -and $script:perfBaseline -and $script:perfBaseline.ContainsKey($ctrlName)) {
                $curVal = [bool]$c.IsChecked
                $baseVal = [bool]$script:perfBaseline[$ctrlName]
                if ($curVal -ne $baseVal) {
                    $changes.Add([PSCustomObject]@{
                        ControlName   = $ctrlName
                        TweakId       = $perfToggleMap[$ctrlName]
                        CurrentValue  = $curVal
                        BaselineValue = $baseVal
                    })
                }
            }
        }
    }
    if ($changes.Count -eq 0) { return @() }
    return $changes.ToArray()
}

function Update-PendingPerfUI {
    if ($script:isUpdatingPerfUI) { return }
    $changes = @(Get-PendingPerfTweaks | Where-Object { $null -ne $_ -and $_.ControlName })
    $cnt = $changes.Count

    if ($lblPendingPerfCount) {
        if ($cnt -gt 0) {
            $lblPendingPerfCount.Text = "$cnt ayar"
            $lblPendingPerfCount.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
        } else {
            $lblPendingPerfCount.Text = "0 ayar"
            $lblPendingPerfCount.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        }
    }

    if ($btnApplyPendingPerf) {
        if ($cnt -gt 0) {
            $btnApplyPendingPerf.IsEnabled = $true
            $btnApplyPendingPerf.Opacity = 1.0
            $btnApplyPendingPerf.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#2563EB")
            $btnApplyPendingPerf.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
            $btnApplyPendingPerf.Content = "⚡ $cnt değişikliği uygula"
        } else {
            $btnApplyPendingPerf.IsEnabled = $false
            $btnApplyPendingPerf.Opacity = 0.5
            $btnApplyPendingPerf.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E293B")
            $btnApplyPendingPerf.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
            $btnApplyPendingPerf.Content = "⚡ 0 değişikliği uygula"
        }
    }

    if ($btnDiscardPendingPerf) {
        $btnDiscardPendingPerf.Visibility = if ($cnt -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    }

    if ($lblPerformanceStatus) {
        if ($cnt -gt 0) {
            $lblPerformanceStatus.Text = "⚠️ $cnt değişiklik bekliyor. Uygulamak için lütfen sağdaki '⚡ $cnt değişikliği uygula' butonuna tıklayın."
            $lblPerformanceStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
        } else {
            $lblPerformanceStatus.Text = "✓ Performans ayarları senkronize edildi."
            $lblPerformanceStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
        }
    }

    if ($window -and $window.Dispatcher) {
        $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
    }
}

# ------------------------------------------------------------------------------
# Bekleyen Performans Değişikliklerini Geri Al (↺) Butonu Olayı
# ------------------------------------------------------------------------------
if ($btnDiscardPendingPerf) {
    $btnDiscardPendingPerf.Add_Click({
        $script:isUpdatingPerfUI = $true
        try {
            if ($script:perfBaseline) {
                foreach ($ctrlName in $script:perfBaseline.Keys) {
                    $c = $window.FindName($ctrlName)
                    if ($c -is [System.Windows.Controls.CheckBox]) {
                        $c.IsChecked = [bool]$script:perfBaseline[$ctrlName]
                    }
                }
            }
        } finally {
            $script:isUpdatingPerfUI = $false
        }
        Update-PendingPerfUI
        if ($lblPerformanceStatus) {
            $lblPerformanceStatus.Text = "Tüm performans değişiklikleri geri alındı, kaydedilmemiş seçimler sıfırlandı."
            $lblPerformanceStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#94A3B8")
        }
    })
}

# ------------------------------------------------------------------------------
# Bekleyen Performans Değişikliklerini Toplu Uygula (⚡) Butonu Olayı
# ------------------------------------------------------------------------------
if ($btnApplyPendingPerf) {
    $btnApplyPendingPerf.Add_Click({
        $changes = @(Get-PendingPerfTweaks | Where-Object { $null -ne $_ -and $_.ControlName })
        $total = $changes.Count
        if ($total -eq 0) { return }

        $btnApplyPendingPerf.IsEnabled = $false
        if ($btnDiscardPendingPerf) { $btnDiscardPendingPerf.IsEnabled = $false }

        $rebootTweaksList = [System.Collections.Generic.List[string]]::new()
        $needsExplorerRestart = $false

        try {
            $currIndex = 0
            foreach ($item in $changes) {
                $currIndex++
                $btnApplyPendingPerf.Content = "⏳ Uygulanıyor... ($currIndex/$total)"
                if ($lblPerformanceStatus) {
                    $lblPerformanceStatus.Text = "Uygulanıyor ($currIndex/$total): $($item.TweakId)..."
                    $lblPerformanceStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
                }
                if ($window -and $window.Dispatcher) {
                    $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
                }

                $meta = $Script:PerfTweaksMeta[$item.TweakId]
                $displayName = if ($meta) { $meta.Name } else { $item.TweakId }
                $req = if ($meta) { $meta.Req } else { "Instant" }

                # Asıl ayar fonksiyonu çağrılır
                try {
                    Set-PerformanceTweak $item.TweakId $item.CurrentValue
                } catch {
                    Write-CmdLog "HATA" "Performans ayarı uygulanamadı ($($item.TweakId)): $($_.Exception.Message)" "Red"
                }

                if ($req -eq "Reboot") {
                    $rebootTweaksList.Add($displayName)
                    if ($script:pendingRebootTweaks) {
                        $script:pendingRebootTweaks.Add($displayName) | Out-Null
                    }
                } elseif ($req -eq "Explorer") {
                    $needsExplorerRestart = $true
                }

                # Baseline'ı güncel duruma çek
                if ($script:perfBaseline) {
                    $script:perfBaseline[$item.ControlName] = $item.CurrentValue
                }
            }

            # Kabuk yenileme
            Broadcast-ShellRefresh

            if ($lblPerformanceStatus) {
                $lblPerformanceStatus.Text = "✓ $total adet performans ayarı başarıyla uygulandı!"
                $lblPerformanceStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            }
            Write-CmdLog "PERFORMANS" ">>> $total adet performans ayarı başarıyla uygulandı." "Green"

            # Yeniden başlatma gerektiren ayar varsa kullanıcıya modern prompt ile sor
            if ($rebootTweaksList.Count -gt 0) {
                $res = Show-ModernRebootPrompt $window $rebootTweaksList.ToArray()
                $script:isRebootPromptHandled = $true
            }
        } finally {
            if ($btnDiscardPendingPerf) { $btnDiscardPendingPerf.IsEnabled = $true }
            Refresh-PerformanceState
        }
    })
}

