        if ($lblBloatwareStatus) {
            $lblBloatwareStatus.Text = "🔄 Sistem uygulamaları ve bloatware listesi yeniden taranıyor..."
            $lblBloatwareStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#60A5FA")
        }

        # Arayüzün anında boyanmasını zorla (Dispatcher render)
        [System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
        Start-Sleep -Milliseconds 300

        try {
            Refresh-BloatwareList
            if ($lblBloatwareStatus) {
                $foundCount = if ($pnlBloatwareList) { ($pnlBloatwareList.Children | Where-Object { $_ -is [System.Windows.Controls.Border] }).Count } else { 0 }
                $lblBloatwareStatus.Text = "✓ Liste güncellendi. Toplam $foundCount adet yerleşik bloatware/sistem uygulaması tespit edildi."
                $lblBloatwareStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            }
        } catch {
            if ($lblBloatwareStatus) {
                $lblBloatwareStatus.Text = "Hata: Tarama sırasında bir sorun oluştu ($($_.Exception.Message))"
                $lblBloatwareStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
