if ($btnExecuteBloatwareRemoval) {
    $btnExecuteBloatwareRemoval.Add_Click({
        $checkedItems = [System.Collections.Generic.List[PSCustomObject]]::new()
        foreach ($card in $pnlBloatwareList.Children) {
            if ($card -is [System.Windows.Controls.Border]) {
                $dock = $card.Child
                if ($dock -and $dock.Children.Count -ge 2) {
                    $pnlLeft = $dock.Children[1]
                    if ($pnlLeft -and $pnlLeft.Children.Count -ge 1) {
                        $chk = $pnlLeft.Children[0]
                        if ($chk -is [System.Windows.Controls.CheckBox] -and $chk.IsChecked -eq $true -and $chk.Tag) {
                            $checkedItems.Add([PSCustomObject]@{ App = $chk.Tag; Card = $card })
                        }
                    }
                }
            }
        }

        if ($checkedItems.Count -eq 0) {
            [System.Windows.MessageBox]::Show($window, "Lütfen kaldırmak istediğiniz en az bir uygulama seçin.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
            return
        }

        $hasSystemTool = $false
        foreach ($item in $checkedItems) {
            if (-not $item.App.Safe) { $hasSystemTool = $true; break }
        }

        $warnText = if ($hasSystemTool) {
            "DİKKAT: Seçtiğiniz uygulamalar arasında temel Windows sistem araçları bulunmaktadır!`n`nSeçilen $($checkedItems.Count) adet uygulamayı kalıcı olarak kaldırmak istediğinize emin misiniz?"
        } else {
            "Seçilen $($checkedItems.Count) adet bloatware uygulamasını ve önbellek kalıntılarını sistemden kalıcı olarak kaldırmak istediğinize emin misiniz?"
        }

        $ans = [System.Windows.MessageBox]::Show($window, $warnText, "Toplu Uygulama Kaldırma Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
        if ($ans -eq [System.Windows.MessageBoxResult]::Yes) {
            $thisBulkBtn = if ($this) { $this } else { $btnExecuteBloatwareRemoval }
            if ($thisBulkBtn) { $thisBulkBtn.IsEnabled = $false }
            if ($progBloatware) { $progBloatware.Visibility = [System.Windows.Visibility]::Visible }

            $successCount = 0
            $failCount = 0
            foreach ($item in $checkedItems) {
                $ok = if ($item.App.IsOneDrive) {
                    Remove-OneDriveClean
                } elseif ($item.App.Id -like "*Edge*") {
                    Remove-MicrosoftEdgeClean
                } else {
                    Remove-SingleAppxPackageClean $item.App.Id $item.App.Name
                }
                if ($ok) {
                    if ($pnlBloatwareList -and $item.Card) {
                        $pnlBloatwareList.Children.Remove($item.Card)
                    }
                    $successCount++
                } else {
                    $failCount++
                }
            }

            if ($progBloatware) { $progBloatware.Visibility = [System.Windows.Visibility]::Collapsed }
            if ($thisBulkBtn) { $thisBulkBtn.IsEnabled = $true }
            $remCount = if ($pnlBloatwareList) { $pnlBloatwareList.Children.Count } else { 0 }
            if ($lblBloatwareCountBadge) { $lblBloatwareCountBadge.Text = "$remCount Uygulama Bulundu" }
            
            if ($failCount -eq 0) {
                if ($lblBloatwareStatus) { $lblBloatwareStatus.Text = "✓ $successCount adet uygulama ve tüm kalıntıları sistemden başarıyla kaldırıldı." }
                [System.Windows.MessageBox]::Show($window, "$successCount adet uygulama başarıyla kaldırıldı!", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
            } else {
                if ($lblBloatwareStatus) { $lblBloatwareStatus.Text = "⚠️ $successCount uygulama kaldırıldı, $failCount uygulama kaldırılamadı." }
                [System.Windows.MessageBox]::Show($window, "$successCount adet uygulama kaldırıldı.`n$failCount adet uygulama izinler veya sistem kısıtlaması nedeniyle kaldırılamadı.", "TemizWin - Kaldırma Özeti", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            }
        }
    })
}

