function Show-DiskSmartDetails {
    Write-CmdLog "S.M.A.R.T." ">>> Fiziksel disk sağlık ve S.M.A.R.T. bilgisi sorgulanıyor..." "Yellow"
    Write-Terminal "`r`n=== Disk S.M.A.R.T. Sağlık ve Aşınma Bilgisi ==="
    try {
        $disks = Get-PhysicalDisk -ErrorAction Stop
        if (-not $disks -or $disks.Count -eq 0) {
            Write-Terminal "[UYARI] Sistemde fiziksel disk tespit edilemedi veya erişim engellendi."
            Write-CmdLog "S.M.A.R.T." "[UYARI] Disk bulunamadı." "Yellow"
            return
        }

        foreach ($d in $disks) {
            $c = $null
            try { $c = $d | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue } catch {}
            
            $name = $d.FriendlyName
            $media = if ($d.MediaType) { $d.MediaType } else { "Bilinmiyor" }
            $health = if ($d.HealthStatus) { $d.HealthStatus } else { "Bilinmiyor" }
            $status = if ($d.OperationalStatus) { ($d.OperationalStatus -join ', ') } else { "Bilinmiyor" }
            $sizeGB = if ($d.Size) { [math]::Round($d.Size / 1GB, 1) } else { 0 }

            Write-Terminal "• Disk: $name ($media, $sizeGB GB)"
            Write-Terminal "  - Donanım Durumu: $health (Çalışma: $status)"
            
            if ($c) {
                $wear = if ($null -ne $c.Wear) { "$($c.Wear)%" } else { "Desteklenmiyor / N/A" }
                $temp = if ($null -ne $c.Temperature -and $c.Temperature -gt 0) { "$($c.Temperature) °C" } else { "N/A" }
                $hours = if ($null -ne $c.PowerOnHours) { "$($c.PowerOnHours) saat (~$([math]::Round($c.PowerOnHours / 24, 0)) gün)" } else { "N/A" }
                $readErr = if ($null -ne $c.ReadErrorsTotal) { $c.ReadErrorsTotal } else { "0" }
                $writeErr = if ($null -ne $c.WriteErrorsTotal) { $c.WriteErrorsTotal } else { "0" }

                Write-Terminal "  - Aşınma Seviyesi (Wear): $wear"
                Write-Terminal "  - Çalışma Sıcaklığı: $temp"
                Write-Terminal "  - Toplam Çalışma Süresi: $hours"
                Write-Terminal "  - Okuma / Yazma Hataları: $readErr / $writeErr"
            } else {
                Write-Terminal "  - S.M.A.R.T. Sayacı: Donanım/Sürücü bu sayaç sorgusunu desteklemiyor."
            }
            Write-Terminal "--------------------------------------------------"
        }
        Write-CmdLog "S.M.A.R.T." "✓ Disk sağlık ve S.M.A.R.T. bilgisi başarıyla okundu." "Green"
        Write-Terminal "=== Disk Bilgisi Tamamlandı ===`r`n"
    } catch {
        Write-Terminal "[HATA] Disk bilgileri alınamadı: $($_.Exception.Message)"
        Write-CmdLog "S.M.A.R.T." "[HATA] Disk bilgisi sorgulanamadı: $($_.Exception.Message)" "Red"
    }
}

