function Show-DriverHealthDetails {
    Write-CmdLog "SÜRÜCÜ" ">>> Bağlı donanım ve sürücü sağlık durumu taranıyor..." "Yellow"
    Write-Terminal "`r`n=== Sürücü ve Donanım Aygıt Sağlık Denetimi ==="
    try {
        $allDevices = Get-PnpDevice -PresentOnly -ErrorAction Stop
        $totalCount = $allDevices.Count
        
        # Hatalı / Sarı Ünlemli Aygıtları Filtrele
        $problemDevices = @($allDevices | Where-Object { 
            ($_.Status -ne "OK") -or 
            ($null -ne $_.Problem -and $_.Problem -ne "CM_PROB_NONE" -and $_.Problem -ne 0)
        })

        if ($problemDevices.Count -gt 0) {
            Write-Terminal "[!] DİKKAT: $($problemDevices.Count) adet aygıtta sürücü sorunu veya çakışma tespit edildi:`r`n"
            Write-CmdLog "SÜRÜCÜ" "[!] $($problemDevices.Count) adet sorunlu aygıt/sürücü tespit edildi!" "Red"
            
            foreach ($dev in $problemDevices) {
                $pName = if ($dev.FriendlyName) { $dev.FriendlyName } else { $dev.InstanceId }
                $pClass = if ($dev.Class) { $dev.Class } else { "Bilinmiyor" }
                $pStatus = if ($dev.Status) { $dev.Status } else { "Hata" }
                $pCode = if ($dev.Problem) { $dev.Problem } else { "Belirtilmemiş" }
                $pDesc = if ($dev.ProblemDescription) { $dev.ProblemDescription } else { "Aygıt düzgün çalışmıyor." }
                
                Write-Terminal "  • [$pClass] $pName"
                Write-Terminal "    Durum: $pStatus | Hata Kodu: $pCode"
                Write-Terminal "    Açıklama: $pDesc"
                Write-Terminal "    --------------------------------------------------"
            }
        } else {
            Write-Terminal "[✓] MÜKEMMEL: Sistemdeki tüm bağlı donanım aygıtları ve sürücüler sorunsuz çalışıyor."
            Write-Terminal "    (0 Hata / 0 Sarı Ünlem tespit edildi - Toplam $totalCount aktif aygıt doğrulandı)"
            Write-CmdLog "SÜRÜCÜ" "✓ Tüm bağlı aygıt ve sürücüler sağlıklı ($totalCount aktif aygıt, 0 hata)." "Green"
        }

        # Temel Donanım Grupları Özeti
        Write-Terminal "`r`n--- Temel Donanım Özeti ---"
        $gpuList = @($allDevices | Where-Object { $_.Class -eq "Display" })
        $netList = @($allDevices | Where-Object { $_.Class -eq "Net" -and $_.FriendlyName -notmatch "WAN Miniport|Kernel Debug" })
        $diskList = @($allDevices | Where-Object { $_.Class -eq "DiskDrive" })

        if ($gpuList) {
            foreach ($g in $gpuList) {
                Write-Terminal "  • Ekran Kartı: $($g.FriendlyName) [$($g.Status)]"
            }
        }
        if ($diskList) {
            foreach ($d in $diskList) {
                Write-Terminal "  • Disk Sürücüsü: $($d.FriendlyName) [$($d.Status)]"
            }
        }
        if ($netList) {
            foreach ($n in $netList) {
                Write-Terminal "  • Ağ Kartı: $($n.FriendlyName) [$($n.Status)]"
            }
        }
        
        Write-Terminal "--------------------------------------------------"
        Write-Terminal "[İPUCU] Ayrıntılı sürücü yönetimi veya güncellemesi için Aygıt Yöneticisi'ni (devmgmt.msc) kullanabilirsiniz."
        Write-Terminal "=== Sürücü Denetimi Tamamlandı ===`r`n"
    } catch {
        Write-Terminal "[HATA] Sürücü ve aygıt bilgileri taranırken hata oluştu: $($_.Exception.Message)"
        Write-CmdLog "SÜRÜCÜ" "[HATA] Aygıt taraması başarısız: $($_.Exception.Message)" "Red"
    }
}

