    }
})

if ($btnApplyDns) {
    $btnApplyDns.Add_Click({
        try {
            $activeAdapter = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | Select-Object -First 1
            if (-not $activeAdapter) {
                $activeAdapter = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notlike '*Virtual*' -and $_.InterfaceDescription -notlike '*Loopback*' } | Select-Object -First 1
            }
            if (-not $activeAdapter) {
                [System.Windows.MessageBox]::Show($window, "Aktif bir internet / ağ bağdaştırıcısı bulunamadı.", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                return
            }

            $idx = if ($cmbDnsProfiles) { $cmbDnsProfiles.SelectedIndex } else { 0 }
            $btnApplyDns.IsEnabled = $false
            
            switch ($idx) {
                0 {
                    # Otomatik (DHCP)
                    Write-CmdLog "DNS" "Set-DnsClientServerAddress -ResetServerAddresses (Ağ: $($activeAdapter.Name))" "Yellow"
                    Write-Terminal "DNS ayarları varsayılan (Otomatik DHCP) durumuna döndürülüyor..."
                    Set-DnsClientServerAddress -InterfaceIndex $activeAdapter.InterfaceIndex -ResetServerAddresses -ErrorAction SilentlyContinue
                    try { Start-Process "netsh.exe" -ArgumentList "interface ipv4 set dnsservers name=`"$($activeAdapter.Name)`" source=dhcp" -Wait -WindowStyle Hidden } catch {}
                    Clear-DnsClientCache -ErrorAction SilentlyContinue
                    Write-CmdLog "DNS" "[+] DNS ayarları varsayılan fabrika/modem (DHCP) durumuna döndürüldü ve önbellek temizlendi." "Green"
                    Write-Terminal "DNS ayarları varsayılana (DHCP) döndürüldü."
                    Update-DnsDisplay
                    [System.Windows.MessageBox]::Show($window, "DNS ayarları başarıyla varsayılan (Otomatik DHCP) durumuna döndürüldü.`n`nBağdaştırıcı: $($activeAdapter.Name)`nDNS Önbelleği temizlendi.", "TemizWin - DNS Güncellendi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                }
                1 {
                    # Cloudflare (1.1.1.1 / 1.0.0.1)
                    Write-CmdLog "DNS" "Set-DnsClientServerAddress -ServerAddresses ('1.1.1.1', '1.0.0.1') (Ağ: $($activeAdapter.Name))" "Yellow"
                    Write-Terminal "Cloudflare DNS (1.1.1.1 / 1.0.0.1) uygulanıyor..."
                    Set-DnsClientServerAddress -InterfaceIndex $activeAdapter.InterfaceIndex -ServerAddresses @("1.1.1.1", "1.0.0.1") -ErrorAction SilentlyContinue
                    Clear-DnsClientCache -ErrorAction SilentlyContinue
                    Write-CmdLog "DNS" "[+] Cloudflare DNS (1.1.1.1 / 1.0.0.1) başarıyla uygulandı ve önbellek temizlendi." "Green"
                    Write-Terminal "Cloudflare DNS (1.1.1.1 / 1.0.0.1) aktif."
                    Update-DnsDisplay
                    [System.Windows.MessageBox]::Show($window, "Cloudflare DNS başarıyla uygulandı!`n`nBirincil: 1.1.1.1`nİkincil: 1.0.0.1`nBağdaştırıcı: $($activeAdapter.Name)", "TemizWin - DNS Güncellendi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                }
                2 {
                    # Google (8.8.8.8 / 8.8.4.4)
                    Write-CmdLog "DNS" "Set-DnsClientServerAddress -ServerAddresses ('8.8.8.8', '8.8.4.4') (Ağ: $($activeAdapter.Name))" "Yellow"
                    Write-Terminal "Google DNS (8.8.8.8 / 8.8.4.4) uygulanıyor..."
                    Set-DnsClientServerAddress -InterfaceIndex $activeAdapter.InterfaceIndex -ServerAddresses @("8.8.8.8", "8.8.4.4") -ErrorAction SilentlyContinue
                    Clear-DnsClientCache -ErrorAction SilentlyContinue
                    Write-CmdLog "DNS" "[+] Google DNS (8.8.8.8 / 8.8.4.4) başarıyla uygulandı ve önbellek temizlendi." "Green"
                    Write-Terminal "Google DNS (8.8.8.8 / 8.8.4.4) aktif."
                    Update-DnsDisplay
                    [System.Windows.MessageBox]::Show($window, "Google DNS başarıyla uygulandı!`n`nBirincil: 8.8.8.8`nİkincil: 8.8.4.4`nBağdaştırıcı: $($activeAdapter.Name)", "TemizWin - DNS Güncellendi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                }
                3 {
                    # Quad9 (9.9.9.9 / 149.112.112.112)
                    Write-CmdLog "DNS" "Set-DnsClientServerAddress -ServerAddresses ('9.9.9.9', '149.112.112.112') (Ağ: $($activeAdapter.Name))" "Yellow"
                    Write-Terminal "Quad9 Güvenli DNS (9.9.9.9 / 149.112.112.112) uygulanıyor..."
                    Set-DnsClientServerAddress -InterfaceIndex $activeAdapter.InterfaceIndex -ServerAddresses @("9.9.9.9", "149.112.112.112") -ErrorAction SilentlyContinue
                    Clear-DnsClientCache -ErrorAction SilentlyContinue
                    Write-CmdLog "DNS" "[+] Quad9 Güvenli DNS (9.9.9.9 / 149.112.112.112) başarıyla uygulandı ve önbellek temizlendi." "Green"
                    Write-Terminal "Quad9 Güvenli DNS (9.9.9.9 / 149.112.112.112) aktif."
                    Update-DnsDisplay
                    [System.Windows.MessageBox]::Show($window, "Quad9 Güvenli DNS başarıyla uygulandı!`n`nBirincil: 9.9.9.9`nİkincil: 149.112.112.112`nBağdaştırıcı: $($activeAdapter.Name)", "TemizWin - DNS Güncellendi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                }
            }
        } catch {
            [System.Windows.MessageBox]::Show($window, "DNS ayarlanırken bir hata oluştu: $($_.Exception.Message)", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
        } finally {
            if ($btnApplyDns) { $btnApplyDns.IsEnabled = $true }
        }
    })
}

