if ($btnResetWinUpdate) {
    $btnResetWinUpdate.Add_Click({
        $ans = [System.Windows.MessageBox]::Show($window, "Windows Update indirme kuyruğu ve arka plan servisleri sıfırlanacaktır.`n`nBu işlem takılan güncellemeleri, indirme hatalarını (0x800...) ve bozuk güncelleme önbelleğini onarır.`n`nDevam etmek istiyor musunuz?", "TemizWin - Windows Update Onarımı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) { return }

        $btnResetWinUpdate.IsEnabled = $false
        try {
            Write-CmdLog "UPDATE" "Windows Update onarımı başlatıldı (Servisler durduruluyor, önbellek sıfırlanıyor)..." "Yellow"
            Write-Terminal "Windows Update onarımı başlatıldı..."

            # 1. Servisleri durdur
            $services = @("wuauserv", "cryptSvc", "bits", "msiserver")
            foreach ($s in $services) {
                Write-Terminal "  • Servis durduruluyor: $s..."
                try { Stop-Service -Name $s -Force -ErrorAction SilentlyContinue } catch {}
            }

            # 2. SoftwareDistribution temizliği
            $sdPath = "C:\Windows\SoftwareDistribution"
            Write-Terminal "  • Windows Update indirme önbelleği temizleniyor..."
            if (Test-Path $sdPath) {
                try {
                    Remove-Item -Path "$sdPath\Download\*" -Recurse -Force -ErrorAction SilentlyContinue
                    Remove-Item -Path "$sdPath\DataStore\*" -Recurse -Force -ErrorAction SilentlyContinue
                } catch {}
            }

            # 3. Servisleri yeniden başlat
            foreach ($s in $services) {
                Write-Terminal "  • Servis başlatılıyor: $s..."
                try { Start-Service -Name $s -ErrorAction SilentlyContinue } catch {}
            }

            # 4. Windows Update keşif tetiklemesi
            try {
                Start-Process "usoclient.exe" -ArgumentList "StartScan" -WindowStyle Hidden -ErrorAction SilentlyContinue
            } catch {}

            Write-CmdLog "UPDATE" "[+] Windows Update başarıyla sıfırlandı ve servisler yeniden başlatıldı." "Green"
            Write-Terminal "Windows Update onarımı tamamlandı! Artık güncellemeleri Ayarlar > Windows Update üzerinden temiz bir şekilde denetleyebilirsiniz."
            [System.Windows.MessageBox]::Show($window, "Windows Update onarımı başarıyla tamamlandı!`n`nServisler (wuauserv, bits, cryptsvc) ve indirme önbelleği sıfırlandı.`n`nArtık Windows Update'i sorunsuz şekilde çalıştırabilirsiniz.", "TemizWin - Update Onarıldı", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
        } catch {
            Write-CmdLog "UPDATE" "[HATA] Windows Update onarımı sırasında hata: $($_.Exception.Message)" "Red"
            Write-Terminal "[HATA] $($_.Exception.Message)"
            [System.Windows.MessageBox]::Show($window, "Hata oluştu: $($_.Exception.Message)", "TemizWin", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
        } finally {
            $btnResetWinUpdate.IsEnabled = $true
        }
    })
}

