# ShellHelper - Gezgin ve Kabuk Bildirimleri (Kaspersky & Windows Uyumlu Kibar Yenileme)
# (ShellNotifyHelper sınıfı program başında tek seferde derlenmiştir)

function Broadcast-ShellRefresh {
    Write-CmdLog "SHELL" "Broadcast WM_SETTINGCHANGE & SHChangeNotify (Kabuk yenileme sinyali)" "Green" 
    try {
        [ShellNotifyHelper]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
        $res = [UIntPtr]::Zero
        [ShellNotifyHelper]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, "TraySettings", 2, 1000, [ref]$res) | Out-Null
        [ShellNotifyHelper]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, "Environment", 2, 1000, [ref]$res) | Out-Null
        [ShellNotifyHelper]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, "Policy", 2, 1000, [ref]$res) | Out-Null
        [ShellNotifyHelper]::UpdatePerUserSystemParameters() | Out-Null
    } catch {}
}

# Tüm Kullanıcılar ve Makine Geneli İçin Kayıt Defteri Ayarlayıcısı
function Set-AllUsersRegistryValue([string]$subKey, [string]$name, $value, [string]$type = "DWord") {
    $written = $false
    try {
        # 1. Mevcut Kullanıcı (HKCU) - Birincil hedef
        $hkcuPath = "HKCU:\$subKey"
        if (-not (Test-Path $hkcuPath)) { New-Item -Path $hkcuPath -Force -ErrorAction Stop | Out-Null }
        Set-ItemProperty -Path $hkcuPath -Name $name -Value $value -Type $type -Force -ErrorAction Stop
        Write-CmdLog "REG-YAZ" "Set-ItemProperty -Path '$hkcuPath' -Name '$name' -Value '$value' ($type)" "Cyan"
        $written = $true
    } catch {
        Write-CmdLog "REG-UYARI" "Yazılamadı ($hkcuPath -> $name): $($_.Exception.Message)" "Yellow"
    }

    try {
        # 2. Varsayılan Kullanıcı Profili (.DEFAULT - Gelecekteki Yeni Kullanıcılar)
        $defPath = "Registry::HKEY_USERS\.DEFAULT\$subKey"
        if (-not (Test-Path $defPath)) { New-Item -Path $defPath -Force -ErrorAction SilentlyContinue | Out-Null }
        Set-ItemProperty -Path $defPath -Name $name -Value $value -Type $type -Force -ErrorAction SilentlyContinue

        # 3. Yüklü Diğer Kullanıcı Profilleri
        Get-ChildItem -Path "Registry::HKEY_USERS" -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-\d+-\d+-\d+-\d+$' } | ForEach-Object {
            $userPath = "$($_.PSPath)\$subKey"
            if (-not (Test-Path $userPath)) { New-Item -Path $userPath -Force -ErrorAction SilentlyContinue | Out-Null }
            Set-ItemProperty -Path $userPath -Name $name -Value $value -Type $type -Force -ErrorAction SilentlyContinue
        }
    } catch {}
}

function Remove-AllUsersRegistryValue([string]$subKey, [string]$name = "") {
    # HKCU - Primary
    try {
        $hkcuPath = "HKCU:\$subKey"
        if ($name -ne "") {
            $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($subKey, $true)
            if ($k) {
                $k.DeleteValue($name, $false)
                $k.Close()
            }
            if (Test-Path $hkcuPath) {
                Remove-ItemProperty -Path $hkcuPath -Name $name -Force -ErrorAction SilentlyContinue
            }
            Write-CmdLog "REG-SİL" "Remove-ItemProperty -Path '$hkcuPath' -Name '$name'" "Magenta"
        } else {
            if (Test-Path $hkcuPath) {
                Remove-Item -Path $hkcuPath -Recurse -Force -ErrorAction SilentlyContinue
                Write-CmdLog "REG-SİL" "Remove-Item -Path '$hkcuPath' -Recurse" "Magenta"
            }
        }
    } catch {}

    # .DEFAULT ve diğer kullanıcılar (İkincil / Best effort)
    try {
        $defPath = "Registry::HKEY_USERS\.DEFAULT\$subKey"
        if (Test-Path $defPath) {
            if ($name -ne "") { Remove-ItemProperty -Path $defPath -Name $name -Force -ErrorAction SilentlyContinue }
            else { Remove-Item -Path $defPath -Recurse -Force -ErrorAction SilentlyContinue }
        }
        Get-ChildItem -Path "Registry::HKEY_USERS" -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-\d+-\d+-\d+-\d+$' } | ForEach-Object {
            $userPath = "$($_.PSPath)\$subKey"
            if (Test-Path $userPath) {
                if ($name -ne "") { Remove-ItemProperty -Path $userPath -Name $name -Force -ErrorAction SilentlyContinue }
                else { Remove-Item -Path $userPath -Recurse -Force -ErrorAction SilentlyContinue }
            }
        }
    } catch {}
}

function Set-MachinePolicyValue([string]$subKey, [string]$name, $value, [string]$type = "DWord") {
    $path = "HKLM:\$subKey"
    try {
        if (-not (Test-Path $path)) { New-Item -Path $path -Force -ErrorAction SilentlyContinue | Out-Null }
        Set-ItemProperty -Path $path -Name $name -Value $value -Type $type -Force -ErrorAction Stop
        Write-CmdLog "POLICY" "Set-ItemProperty -Path '$path' -Name '$name' -Value '$value' ($type)" "Blue"
    } catch {
        Write-CmdLog "POLICY-UYARI" "Yazılamadı ($path -> $name): $($_.Exception.Message)" "Yellow"
    }
}

function Remove-MachinePolicyValue([string]$subKey, [string]$name = "") {
    $path = "HKLM:\$subKey"
    try {
        if ($name -ne "") {
            $regKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($subKey, $true)
            if ($regKey) {
                $regKey.DeleteValue($name, $false)
                $regKey.Close()
            }
            if (Test-Path $path) {
                Remove-ItemProperty -Path $path -Name $name -Force -ErrorAction SilentlyContinue
            }
            Write-CmdLog "POLICY-SİL" "Remove-ItemProperty -Path '$path' -Name '$name'" "DarkMagenta"
        } else {
            if (Test-Path $path) {
                Remove-Item -Path $path -Recurse -Force -ErrorAction SilentlyContinue
                Write-CmdLog "POLICY-SİL" "Remove-Item -Path '$path' -Recurse" "DarkMagenta"
            }
        }
    } catch {
        Write-CmdLog "POLICY-HATA" "Kaldırılamadı ($path -> $name): $($_.Exception.Message)" "Red"
    }
}

function Test-StoreDbSuggestionsLocked([string]$storeDbPath = "") {
    if (-not $storeDbPath) {
        $storeDbPath = "$env:LOCALAPPDATA\Packages\Microsoft.WindowsStore_8wekyb3d8bbwe\LocalState\store.db"
    }
    if (-not (Test-Path -Path $storeDbPath)) { return $false }
    try {
        $acl = Get-Acl -Path $storeDbPath -ErrorAction Stop
        $everyoneSid = [System.Security.Principal.SecurityIdentifier]::new('S-1-1-0')
        foreach ($rule in @($acl.Access)) {
            $isDeny = ($rule.AccessControlType -eq [System.Security.AccessControl.AccessControlType]::Deny) -and
                (($rule.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::FullControl) -ne 0)
            if (-not $isDeny) { continue }
            try {
                if ($rule.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $everyoneSid) {
                    return $true
                }
            } catch {}
        }
    } catch {}
    return $false
}

function Set-StoreDbSuggestionsLock([bool]$locked) {
    $storeDbPaths = [System.Collections.Generic.List[string]]::new()
    $curPath = "$env:LOCALAPPDATA\Packages\Microsoft.WindowsStore_8wekyb3d8bbwe\LocalState\store.db"
    if ($curPath) { $storeDbPaths.Add($curPath) }

    $userPackages = Get-ChildItem -Path "C:\Users\*\AppData\Local\Packages" -ErrorAction SilentlyContinue
    foreach ($pkg in $userPackages) {
        $p = Join-Path $pkg.FullName "Microsoft.WindowsStore_8wekyb3d8bbwe\LocalState\store.db"
        if (-not $storeDbPaths.Contains($p)) { $storeDbPaths.Add($p) }
    }

    $everyoneSid = [System.Security.Principal.SecurityIdentifier]::new('S-1-1-0')

    foreach ($dbPath in $storeDbPaths) {
        try {
            if ($locked) {
                $dbDir = Split-Path -Path $dbPath -Parent
                if (-not (Test-Path -Path $dbDir)) {
                    New-Item -Path $dbDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
                }
                if (-not (Test-Path -Path $dbPath)) {
                    New-Item -Path $dbPath -ItemType File -Force -ErrorAction SilentlyContinue | Out-Null
                }
                $acl = Get-Acl -Path $dbPath -ErrorAction SilentlyContinue
                if ($acl) {
                    $ace = [System.Security.AccessControl.FileSystemAccessRule]::new($everyoneSid, 'FullControl', 'Deny')
                    $acl.SetAccessRule($ace) | Out-Null
                    Set-Acl -Path $dbPath -AclObject $acl -ErrorAction SilentlyContinue | Out-Null
                }
                Write-CmdLog "STORE-DB" "Erişim kilitlendi (Everyone Deny): '$dbPath'" "Cyan"
            } else {
                if (Test-Path -Path $dbPath) {
                    takeown /F "$dbPath" /A 2>$null | Out-Null
                    icacls "$dbPath" /grant "*S-1-5-32-544:F" /C 2>$null | Out-Null
                    $acl = Get-Acl -Path $dbPath -ErrorAction SilentlyContinue
                    if ($acl) {
                        $denyRules = @(
                            $acl.Access | Where-Object {
                                $_.AccessControlType -eq [System.Security.AccessControl.AccessControlType]::Deny -and
                                (($_.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::FullControl) -ne 0) -and
                                $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $everyoneSid
                            }
                        )
                        foreach ($r in $denyRules) {
                            $acl.RemoveAccessRuleSpecific($r) | Out-Null
                        }
                        Set-Acl -Path $dbPath -AclObject $acl -ErrorAction SilentlyContinue | Out-Null
                    }
                    Remove-Item -Path $dbPath -Force -ErrorAction SilentlyContinue | Out-Null
                    Write-CmdLog "STORE-DB" "Kilit kaldırıldı ve dosya temizlendi: '$dbPath'" "Green"
                }
            }
        } catch {
            Write-CmdLog "STORE-DB-UYARI" "İşlem yapılamadı ($dbPath): $($_.Exception.Message)" "DarkYellow"
        }
    }
}

$script:isUpdatingTweaksUI = $false

# ------------------------------------------------------------------------------
# Mevcut Sistem Durumunu Canlı Olarak Oku ve Arayüze Yansıt
# ------------------------------------------------------------------------------

# ------------------------------------------------------------------------------
# Performans ve Oyun Modu Mantığı
# ------------------------------------------------------------------------------
$script:isUpdatingPerfUI = $false

function Refresh-PerformanceState {
    $script:isUpdatingPerfUI = $true
    try {
        # 1. Arka Plan Uygulamaları (GlobalUserDisabled = 1 ise kapatılmış / optimize edilmiş)
        $bg = (Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications" -ErrorAction SilentlyContinue).GlobalUserDisabled
        if ($tglPerfBackgroundApps) { $tglPerfBackgroundApps.IsChecked = ($bg -eq 1) }

        # 2. SysMain (Superfetch) Hizmeti
        $svc = Get-Service -Name SysMain -ErrorAction SilentlyContinue
        if ($tglPerfSysMain) { $tglPerfSysMain.IsChecked = ($svc -ne $null -and $svc.StartType -eq "Disabled") }

        # 3. Oyun Modu (AutoGameModeEnabled = 1, Windows varsayılanı AÇIK'tır)
        $gm = (Get-ItemProperty "HKCU:\Software\Microsoft\GameBar" -ErrorAction SilentlyContinue).AutoGameModeEnabled
        $isGameModeOn = if ($null -eq $gm) { $true } else { $gm -ne 0 }
        if ($tglPerfGameMode) { $tglPerfGameMode.IsChecked = $isGameModeOn }

        # 4. Pencereli Mod İyileştirmeleri (SwapEffectUpgradeEnable=1)
        $d3d = (Get-ItemProperty "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings
        if ($tglPerfWindowedOptimizations) { $tglPerfWindowedOptimizations.IsChecked = ($d3d -like "*SwapEffectUpgradeEnable=1*") }

        # 5. Arka Planda Kayıt (GameDVR_Enabled = 0 ise kayıt kapalı / FPS optimize)
        $dvr = (Get-ItemProperty "HKCU:\System\GameConfigStore" -ErrorAction SilentlyContinue).GameDVR_Enabled
        if ($tglPerfGameDVR) { $tglPerfGameDVR.IsChecked = ($dvr -eq 0) }

        # 6. Doğrudan Tam Ekran (FSEBehaviorMode = 2)
        $fse = (Get-ItemProperty "HKCU:\System\GameConfigStore" -ErrorAction SilentlyContinue).GameDVR_FSEBehaviorMode
        if ($tglPerfFSE) { $tglPerfFSE.IsChecked = ($fse -eq 2) }

        # 7. Nagle Algoritması (TcpAckFrequency = 1)
        $nagleActive = $false
        try {
            $adapters = Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\*" -ErrorAction SilentlyContinue
            foreach ($ad in $adapters) {
                if ($ad.TcpAckFrequency -eq 1 -and $ad.TCPNoDelay -eq 1) { $nagleActive = $true; break }
            }
        } catch {}
        if ($tglPerfNagle) { $tglPerfNagle.IsChecked = $nagleActive }

        # 8. Yüksek / Nihai Performans Güç Planı
        $activePlan = powercfg /getactivescheme
        $isHighPerf = ($activePlan -like "*8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c*" -or $activePlan -like "*e9a42b02-d5df-448d-aa00-03f14749eb61*" -or $activePlan -like "*Yüksek*" -or $activePlan -like "*High*" -or $activePlan -like "*Nihai*" -or $activePlan -like "*Ultimate*")
        if ($tglPerfPowerPlan) { $tglPerfPowerPlan.IsChecked = $isHighPerf }

        # 9. HAGS (HwSchMode = 2 ise açık)
        $hwSch = (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" -ErrorAction SilentlyContinue).HwSchMode
        if ($tglPerfHAGS) { $tglPerfHAGS.IsChecked = ($hwSch -eq 2) }

        # 10. VBS (EnableVirtualizationBasedSecurity = 0 ise kapatılmış / optimize edilmiş)
        $vbs = (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" -ErrorAction SilentlyContinue).EnableVirtualizationBasedSecurity
        if ($tglPerfVBS) { $tglPerfVBS.IsChecked = ($vbs -eq 0) }

        # 10.1 Dinamik Aydınlatma (AmbientLightingEnabled = 0 ise kapatılmış / optimize edilmiş)
        $dl = (Get-ItemProperty "HKCU:\Software\Microsoft\Lighting" -ErrorAction SilentlyContinue).AmbientLightingEnabled
        if ($tglPerfDynamicLighting) { $tglPerfDynamicLighting.IsChecked = ($dl -eq 0) }

        # 11. Görsel Efektler (Animasyonlar ve görsel efektler kapalı mı?)
        $minAnim = (Get-ItemProperty "HKCU:\Control Panel\Desktop\WindowMetrics" -ErrorAction SilentlyContinue).MinAnimate
        $tbAnim = (Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -ErrorAction SilentlyContinue).TaskbarAnimations
        $vfx = (Get-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" -ErrorAction SilentlyContinue).VisualFXSetting
        $isVfxOptimized = ($minAnim -eq "0" -and $tbAnim -eq 0) -or ($vfx -in 2, 3)
        if ($tglPerfVisualEffects) { $tglPerfVisualEffects.IsChecked = $isVfxOptimized }

        # 12. Windows Search (Arama İndeksleme)
        $wsearch = Get-Service -Name WSearch -ErrorAction SilentlyContinue
        if ($tglPerfSearchIndexing) { $tglPerfSearchIndexing.IsChecked = ($wsearch -ne $null -and $wsearch.StartType -eq "Disabled") }

        # 13. Ağ Bağdaştırıcısı Donanım Yükü Aktarımı (Task Offload)
        $dto = (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" -ErrorAction SilentlyContinue).DisableTaskOffload
        if ($tglPerfNetOffload) { $tglPerfNetOffload.IsChecked = ($dto -ne 1) }

        if (-not $script:perfBaseline) {
            $script:perfBaseline = [System.Collections.Hashtable]::Synchronized(@{})
        }
        if ($perfToggleMap) {
            foreach ($ctrlName in $perfToggleMap.Keys) {
                $c = $window.FindName($ctrlName)
                if ($c) {
                    $script:perfBaseline[$ctrlName] = [bool]$c.IsChecked
                }
            }
        }

        if ($lblPerformanceStatus) { $lblPerformanceStatus.Text = "✓ Performans ayarları senkronize edildi." }
    } catch {
        if ($lblPerformanceStatus) { $lblPerformanceStatus.Text = "Hata: $($_.Exception.Message)" }
    } finally {
        $script:isUpdatingPerfUI = $false
        if (Get-Command "Update-PendingPerfUI" -ErrorAction SilentlyContinue) {
            Update-PendingPerfUI
        }
    }
}

function Set-PerformanceTweak([string]$name, [bool]$turnOn) {
    $prevEAP = $ErrorActionPreference
    $ErrorActionPreference = 'Stop'
    try {
        switch ($name) {
            "BackgroundApps" {
                $val = if ($turnOn) { 1 } else { 0 }
                $kPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                Set-ItemProperty -Path $kPath -Name "GlobalUserDisabled" -Value $val -Type DWord -Force
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "Arka plan uygulamaları kapatıldı (RAM/CPU tasarrufu sağlandı)" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "Arka plan uygulamalarına izin verildi" "Yellow"
                }
            }
            "SysMain" {
                if ($turnOn) {
                    Set-Service -Name SysMain -StartupType Disabled -ErrorAction SilentlyContinue
                    Stop-Service -Name SysMain -Force -ErrorAction SilentlyContinue
                    Write-CmdLog "PERFORMANS" "SysMain (SuperFetch) hizmeti devre dışı bırakıldı ve durduruldu" "Green"
                } else {
                    Set-Service -Name SysMain -StartupType Automatic -ErrorAction SilentlyContinue
                    Start-Service -Name SysMain -ErrorAction SilentlyContinue
                    Write-CmdLog "PERFORMANS" "SysMain (SuperFetch) hizmeti otomatik başlatmaya alındı" "Yellow"
                }
            }
            "GameMode" {
                $val = if ($turnOn) { 1 } else { 0 }
                $kPath = "HKCU:\Software\Microsoft\GameBar"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                Set-ItemProperty -Path $kPath -Name "AutoGameModeEnabled" -Value $val -Type DWord -Force
                Set-ItemProperty -Path $kPath -Name "AllowAutoGameMode" -Value $val -Type DWord -Force
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "Windows Oyun Modu (Game Mode) etkinleştirildi" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "Windows Oyun Modu kapatıldı" "Yellow"
                }
            }
            "WindowedOptimizations" {
                $kPath = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                $curSettings = (Get-ItemProperty -Path $kPath -Name "DirectXUserGlobalSettings" -ErrorAction SilentlyContinue).DirectXUserGlobalSettings
                $targetFlag = if ($turnOn) { "SwapEffectUpgradeEnable=1;" } else { "SwapEffectUpgradeEnable=0;" }
                if ([string]::IsNullOrWhiteSpace($curSettings)) {
                    $newSettings = $targetFlag
                } elseif ($curSettings -match 'SwapEffectUpgradeEnable=[01];?') {
                    $newSettings = $curSettings -replace 'SwapEffectUpgradeEnable=[01];?', $targetFlag
                } else {
                    $newSettings = $curSettings.TrimEnd(';') + ';' + $targetFlag
                }
                Set-ItemProperty -Path $kPath -Name "DirectXUserGlobalSettings" -Value $newSettings -Type String -Force
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "Pencereli mod oyun iyileştirmeleri (Flip Model / Düşük Gecikme) açıldı" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "Pencereli mod oyun iyileştirmeleri kapatıldı" "Yellow"
                }
            }
            "GameDVR" {
                $kPath = "HKCU:\System\GameConfigStore"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                $val = if ($turnOn) { 0 } else { 1 } # turnOn = kapat (optimize et)
                Set-ItemProperty -Path $kPath -Name "GameDVR_Enabled" -Value $val -Type DWord -Force
                
                $kPath2 = "HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR"
                if (-not (Test-Path $kPath2)) { New-Item -Path $kPath2 -Force | Out-Null }
                Set-ItemProperty -Path $kPath2 -Name "AppCaptureEnabled" -Value $val -Type DWord -Force
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "Arka planda video kaydı (Xbox Game DVR) kapatıldı (FPS artırıldı)" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "Arka planda video kaydı etkinleştirildi" "Yellow"
                }
            }
            "FSE" {
                $kPath = "HKCU:\System\GameConfigStore"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                $val = if ($turnOn) { 2 } else { 0 }
                $flagVal = if ($turnOn) { 1 } else { 0 }
                Set-ItemProperty -Path $kPath -Name "GameDVR_FSEBehaviorMode" -Value $val -Type DWord -Force
                Set-ItemProperty -Path $kPath -Name "GameDVR_HonorUserFSEBehaviorMode" -Value $flagVal -Type DWord -Force
                Set-ItemProperty -Path $kPath -Name "GameDVR_DXGIHonorFSEWindowsCompatible" -Value $flagVal -Type DWord -Force
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "Doğrudan Tam Ekran (FSE) modu açıldı (DWM atlandı)" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "Standart tam ekran yönetimine dönüldü" "Yellow"
                }
            }
            "Nagle" {
                $interfaces = Get-ChildItem "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces" -ErrorAction SilentlyContinue
                foreach ($intf in $interfaces) {
                    $p = $intf.PSPath
                    if ($turnOn) {
                        Set-ItemProperty -LiteralPath $p -Name "TcpAckFrequency" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                        Set-ItemProperty -LiteralPath $p -Name "TCPNoDelay" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    } else {
                        Remove-ItemProperty -LiteralPath $p -Name "TcpAckFrequency" -ErrorAction SilentlyContinue
                        Remove-ItemProperty -LiteralPath $p -Name "TCPNoDelay" -ErrorAction SilentlyContinue
                    }
                }
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "Nagle algoritması kapatıldı (Çevrimiçi oyun ping gecikmesi düşürüldü)" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "Ağ Nagle algoritması varsayılana döndürüldü" "Yellow"
                }
            }
            "PowerPlan" {
                if ($turnOn) {
                    # Önce varsa Nihai Performans'ı (Ultimate) seç, yoksa Yüksek Performans'ı aktif et
                    $schemes = powercfg /list
                    $ult = ($schemes | Where-Object { $_ -like "*Nihai*" -or $_ -like "*Ultimate*" } | Select-Object -First 1)
                    if ($ult -and ($ult -match '([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})')) {
                        $ultGuid = $Matches[1]
                        powercfg /setactive $ultGuid 2>$null
                        Write-CmdLog "PERFORMANS" "Nihai Performans (Ultimate Performance) güç planı aktif edildi" "Green"
                    } else {
                        powercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c 2>$null
                        Write-CmdLog "PERFORMANS" "Yüksek Performans güç planı aktif edildi" "Green"
                    }
                } else {
                    # Dengeli güç planı
                    powercfg /setactive 381b4222-f694-41f0-9685-ff5bb260df2e 2>$null
                    Write-CmdLog "PERFORMANS" "Dengeli güç planına geri dönüldü" "Yellow"
                }
            }
            "HAGS" {
                $kPath = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                $val = if ($turnOn) { 2 } else { 1 }
                Set-ItemProperty -Path $kPath -Name "HwSchMode" -Value $val -Type DWord -Force
                if ($turnOn) {
                    Write-CmdLog "PERFORMANS" "HAGS açıldı (GTX 16xx/RTX veya RX 5000+ gerektirir, yeniden başlatma şart)" "Green"
                } else {
                    Write-CmdLog "PERFORMANS" "HAGS kapatıldı (Yeniden başlatma gerekir)" "Yellow"
                }
            }
            "VBS" {
                if ($turnOn) {
                    $kPath = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard"
                    if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                    $kPath2 = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity"
                    if (-not (Test-Path $kPath2)) { New-Item -Path $kPath2 -Force | Out-Null }
                    Set-ItemProperty -Path $kPath -Name "EnableVirtualizationBasedSecurity" -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path $kPath2 -Name "Enabled" -Value 0 -Type DWord -Force
                    Write-CmdLog "PERFORMANS" "VBS ve Bellek Bütünlüğü kapatıldı (FPS artırıldı, WSL/Sandbox korunur, yeniden başlatma gerekir)" "Green"
                } else {
                    $kPath = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard"
                    if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                    $kPath2 = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity"
                    if (-not (Test-Path $kPath2)) { New-Item -Path $kPath2 -Force | Out-Null }
                    Set-ItemProperty -Path $kPath -Name "EnableVirtualizationBasedSecurity" -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path $kPath2 -Name "Enabled" -Value 1 -Type DWord -Force
                    cmd.exe /c "bcdedit /set hypervisorlaunchtype auto" 2>$null | Out-Null
                    Write-CmdLog "PERFORMANS" "VBS ve Bellek Bütünlüğü yeniden etkinleştirildi (Yeniden başlatma gerekir)" "Yellow"
                }
            }
            "DynamicLighting" {
                $kPath = "HKCU:\Software\Microsoft\Lighting"
                if (-not (Test-Path $kPath)) { New-Item -Path $kPath -Force | Out-Null }
                if ($turnOn) {
                    Set-ItemProperty -Path $kPath -Name "AmbientLightingEnabled" -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path $kPath -Name "ControlledByForegroundApp" -Value 0 -Type DWord -Force
                    Write-CmdLog "PERFORMANS" "Windows Dinamik Aydınlatma (RGB) kapatıldı (RGB yazılım çakışmaları ve gecikme önlendi)" "Green"
                } else {
                    Set-ItemProperty -Path $kPath -Name "AmbientLightingEnabled" -Value 1 -Type DWord -Force
                    Set-ItemProperty -Path $kPath -Name "ControlledByForegroundApp" -Value 1 -Type DWord -Force
                    Write-CmdLog "PERFORMANS" "Windows Dinamik Aydınlatma (RGB) varsayılan durumuna (Açık) getirildi" "Yellow"
                }
            }
            "VisualEffects" {
                $vfxPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"
                if (-not (Test-Path $vfxPath)) { New-Item -Path $vfxPath -Force | Out-Null }
                $wmPath = "HKCU:\Control Panel\Desktop\WindowMetrics"
                if (-not (Test-Path $wmPath)) { New-Item -Path $wmPath -Force | Out-Null }
                $dtPath = "HKCU:\Control Panel\Desktop"
                $advPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
                if (-not (Test-Path $advPath)) { New-Item -Path $advPath -Force | Out-Null }
                $dwmPath = "HKCU:\Software\Microsoft\Windows\DWM"
                if (-not (Test-Path $dwmPath)) { New-Item -Path $dwmPath -Force | Out-Null }

                if ($turnOn) {
                    # Görsel Efektler: En İyi Performans profili (Özel / VisualFXSetting = 3)
                    Set-ItemProperty -Path $vfxPath -Name "VisualFXSetting" -Value 3 -Type DWord -Force
                    Set-ItemProperty -Path $wmPath -Name "MinAnimate" -Value "0" -Type String -Force

                    # 90 12 07 80 10 00 00 00 -> Tüm menü/araç ipucu/seçim/fare gölgeleri ve kaymaları kapalı (Raphire / Win11 uyumlu)
                    $mask = [byte[]](0x90, 0x12, 0x07, 0x80, 0x10, 0x00, 0x00, 0x00)
                    Set-ItemProperty -Path $dtPath -Name "UserPreferencesMask" -Value $mask -Type Binary -Force
                    Set-ItemProperty -Path $dtPath -Name "DragFullWindows" -Value "0" -Type String -Force

                    # Ekran yazı tipi kenarlarını düzelt (Font Smoothing / ClearType) - KESİNLİKLE KORUNUR
                    Set-ItemProperty -Path $dtPath -Name "FontSmoothing" -Value "2" -Type String -Force
                    Set-ItemProperty -Path $dtPath -Name "FontSmoothingType" -Value 2 -Type DWord -Force

                    # Gelişmiş Gezgin & Görev Çubuğu animasyonları ve gölgeleri kapatılır
                    Set-ItemProperty -Path $advPath -Name "TaskbarAnimations" -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path $advPath -Name "ListviewShadow" -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path $advPath -Name "ListviewAlphaSelect" -Value 0 -Type DWord -Force

                    Set-ItemProperty -Path $dwmPath -Name "EnableAeroPeek" -Value 0 -Type DWord -Force
                    Set-ItemProperty -Path $dwmPath -Name "AlwaysHibernateThumbnails" -Value 0 -Type DWord -Force

                    # Sisteme anında canlı bildirim gönder
                    rundll32.exe user32.dll,UpdatePerUserSystemParameters 1, True
                    Write-CmdLog "PERFORMANS" "Görsel efektler en iyi performansa ayarlandı (Animasyonlar kapatıldı, yazı tipi netliği korundu)" "Green"
                } else {
                    # Varsayılan Windows Görünümü (Bilgisayarım için en iyi olanı Windows seçsin / VisualFXSetting = 0)
                    Set-ItemProperty -Path $vfxPath -Name "VisualFXSetting" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $wmPath -Name "MinAnimate" -Value "1" -Type String -Force -ErrorAction SilentlyContinue

                    $defaultMask = [byte[]](0x9E, 0x3E, 0x07, 0x80, 0x12, 0x00, 0x00, 0x00)
                    Set-ItemProperty -Path $dtPath -Name "UserPreferencesMask" -Value $defaultMask -Type Binary -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $dtPath -Name "DragFullWindows" -Value "1" -Type String -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $dtPath -Name "FontSmoothing" -Value "2" -Type String -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $dtPath -Name "FontSmoothingType" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue

                    Set-ItemProperty -Path $advPath -Name "TaskbarAnimations" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $advPath -Name "ListviewShadow" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $advPath -Name "ListviewAlphaSelect" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue

                    Set-ItemProperty -Path $dwmPath -Name "EnableAeroPeek" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    Set-ItemProperty -Path $dwmPath -Name "AlwaysHibernateThumbnails" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue

                    rundll32.exe user32.dll,UpdatePerUserSystemParameters 1, True
                    Write-CmdLog "PERFORMANS" "Görsel efektler varsayılan Windows görünümüne döndürüldü" "Yellow"
                }
            }
            "SearchIndexing" {
                if ($turnOn) {
                    Set-Service -Name WSearch -StartupType Disabled -ErrorAction SilentlyContinue
                    Stop-Service -Name WSearch -Force -ErrorAction SilentlyContinue
                    Write-CmdLog "PERFORMANS" "Windows Search (Arama İndeksleme) hizmeti kapatıldı (Disk ve CPU yükü sıfırlandı)" "Green"
                } else {
                    Set-Service -Name WSearch -StartupType Automatic -ErrorAction SilentlyContinue
                    Start-Service -Name WSearch -ErrorAction SilentlyContinue
                    Write-CmdLog "PERFORMANS" "Windows Search (Arama İndeksleme) hizmeti yeniden başlatıldı ve otomatiğe alındı" "Yellow"
                }
            }
            "NetOffload" {
                if ($turnOn) {
                    cmd.exe /c "netsh int ip set global taskoffload=enabled" 2>$null | Out-Null
                    cmd.exe /c "netsh int tcp set global rss=enabled" 2>$null | Out-Null
                    Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" -Name "DisableTaskOffload" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                    Enable-NetAdapterChecksumOffload -Name * -ErrorAction SilentlyContinue
                    Enable-NetAdapterLso -Name * -IPv4 -IPv6 -ErrorAction SilentlyContinue
                    Enable-NetAdapterRss -Name * -ErrorAction SilentlyContinue
                    Write-CmdLog "PERFORMANS" "Ağ bağdaştırıcısı donanım yükü aktarımı (Offload & RSS) etkinleştirildi" "Green"
                } else {
                    cmd.exe /c "netsh int ip set global taskoffload=disabled" 2>$null | Out-Null
                    cmd.exe /c "netsh int tcp set global rss=disabled" 2>$null | Out-Null
                    Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" -Name "DisableTaskOffload" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    Disable-NetAdapterChecksumOffload -Name * -ErrorAction SilentlyContinue
                    Disable-NetAdapterLso -Name * -IPv4 -IPv6 -ErrorAction SilentlyContinue
                    Disable-NetAdapterRss -Name * -ErrorAction SilentlyContinue
                    Write-CmdLog "PERFORMANS" "Ağ bağdaştırıcısı donanım yükü aktarımı devre dışı bırakıldı" "Yellow"
                }
            }
            default {
                throw "Bilinmeyen performans ayarı: $name"
            }
        }
        if ($lblPerformanceStatus) { $lblPerformanceStatus.Text = "✓ Ayar uygulandı: $name" }
    } catch {
        if ($lblPerformanceStatus) { $lblPerformanceStatus.Text = "Hata ($name): $($_.Exception.Message)" }
        Write-CmdLog "PERFORMANS" "[HATA] $name uygulanamadı: $($_.Exception.Message)" "Red"
    } finally {
        $ErrorActionPreference = $prevEAP
    }
}

