function Get-PendingTweaks {
    $changes = [System.Collections.Generic.List[PSCustomObject]]::new()
    if ($tweakToggleMap) {
        foreach ($ctrlName in $tweakToggleMap.Keys) {
            $c = $window.FindName($ctrlName)
            if ($c -and $script:tweaksBaseline.ContainsKey($ctrlName)) {
                $curVal = [bool]$c.IsChecked
                $baseVal = [bool]$script:tweaksBaseline[$ctrlName]
                if ($curVal -ne $baseVal) {
                    $changes.Add([PSCustomObject]@{
                        Type          = "Toggle"
                        ControlName   = $ctrlName
                        TweakId       = $tweakToggleMap[$ctrlName]
                        CurrentValue  = $curVal
                        BaselineValue = $baseVal
                    })
                }
            }
        }
    }
    if ($script:comboTweakMap) {
        foreach ($cmbName in $script:comboTweakMap.Keys) {
            $cmb = $window.FindName($cmbName)
            if ($cmb -and $script:tweaksBaseline.ContainsKey($cmbName)) {
                $curVal = [int]$cmb.SelectedIndex
                $baseVal = [int]$script:tweaksBaseline[$cmbName]
                if ($curVal -ne $baseVal) {
                    $changes.Add([PSCustomObject]@{
                        Type          = "Combo"
                        ControlName   = $cmbName
                        TweakId       = $script:comboTweakMap[$cmbName]
                        CurrentValue  = $curVal
                        BaselineValue = $baseVal
                    })
                }
            }
        }
    }
    if ($changes.Count -eq 0) {
        return @()
    }
    return $changes.ToArray()
}

function Update-PendingTweaksUI {
    if ($script:isUpdatingTweaksUI) { return }
    $changes = @(Get-PendingTweaks | Where-Object { $null -ne $_ -and $_.ControlName })
    $cnt = $changes.Count

    if ($lblPendingTweaksCount) {
        if ($cnt -gt 0) {
            $lblPendingTweaksCount.Text = "$cnt ayar"
            $lblPendingTweaksCount.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
        } else {
            $lblPendingTweaksCount.Text = "0 ayar"
            $lblPendingTweaksCount.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        }
    }

    if ($btnApplyPendingTweaks) {
        if ($cnt -gt 0) {
            $btnApplyPendingTweaks.IsEnabled = $true
            $btnApplyPendingTweaks.Opacity = 1.0
            $btnApplyPendingTweaks.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#2563EB")
            $btnApplyPendingTweaks.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
            $btnApplyPendingTweaks.Content = "✨ $cnt değişikliği uygula"
        } else {
            $btnApplyPendingTweaks.IsEnabled = $false
            $btnApplyPendingTweaks.Opacity = 0.5
            $btnApplyPendingTweaks.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E293B")
            $btnApplyPendingTweaks.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
            $btnApplyPendingTweaks.Content = "✨ 0 değişikliği uygula"
        }
    }

    if ($btnDiscardPendingTweaks) {
        $btnDiscardPendingTweaks.Visibility = if ($cnt -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    }

    if ($lblTweaksStatus) {
        if ($cnt -gt 0) {
            $lblTweaksStatus.Text = "⚠️ $cnt değişiklik bekliyor. Değişiklikleri kaydetmek için lütfen yukarıdaki '✨ $cnt değişikliği uygula' butonuna tıklayın."
            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
        } else {
            $lblTweaksStatus.Text = "Gizlilik, telemetri, yapay zeka, arayüz ve performans ayarlarını tek tıkla açın veya kapatın."
            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        }
    }

    if ($window -and $window.Dispatcher) {
        $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
    }
}

function Refresh-TweaksState {
    $script:isUpdatingTweaksUI = $true
    try {
        # 1. Gizlilik & Telemetri (Raphire / Win11Debloat Standartlarında Doğrulama)
        $advInfo     = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo" -Name "Enabled" -ErrorAction SilentlyContinue).Enabled
        $privData    = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Privacy" -Name "TailoredExperiencesWithDiagnosticDataEnabled" -ErrorAction SilentlyContinue).TailoredExperiencesWithDiagnosticDataEnabled
        $regTelem1   = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -ErrorAction SilentlyContinue).AllowTelemetry
        $regTelem2   = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" -Name "AllowTelemetry" -ErrorAction SilentlyContinue).AllowTelemetry
        $diagService = (Get-Service -Name "DiagTrack" -ErrorAction SilentlyContinue).StartType

        if ($tglTelemetry) {
            # Telemetrinin kapalı sayılması için hem reklam ve kullanıcı deneyimi takibi kapalı olmalı, hem de AllowTelemetry 0 veya DiagTrack servisi devre dışı olmalıdır
