            elseif ($regGlomMain -eq 1) { $cmbCombineMain.SelectedIndex = 2 }
            elseif ($regGlomMain -eq 2) { $cmbCombineMain.SelectedIndex = 3 }
            else { $cmbCombineMain.SelectedIndex = 0 }
        }

        $regGlomSec = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "MMTaskbarGlomLevel" -ErrorAction SilentlyContinue).MMTaskbarGlomLevel
        if ($cmbCombineSecondary) {
            if ($regGlomSec -eq 0) { $cmbCombineSecondary.SelectedIndex = 1 }
            elseif ($regGlomSec -eq 1) { $cmbCombineSecondary.SelectedIndex = 2 }
            elseif ($regGlomSec -eq 2) { $cmbCombineSecondary.SelectedIndex = 3 }
            else { $cmbCombineSecondary.SelectedIndex = 0 }
        }

        $regAutoTray = (Get-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer" -Name "EnableAutoTray" -ErrorAction SilentlyContinue).EnableAutoTray
        if ($tglShowAllTrayIcons) { $tglShowAllTrayIcons.IsChecked = ($regAutoTray -eq 0) }

        # 11. Gaming
        $regDVR = (Get-ItemProperty -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_Enabled" -ErrorAction SilentlyContinue).GameDVR_Enabled
        if ($tglGameDVR) { $tglGameDVR.IsChecked = ($regDVR -eq 0) }

        $regGameBar = (Get-ItemProperty -Path "HKCU:\SOFTWARE\Microsoft\GameBar" -Name "UseNexusForGameBarEnabled" -ErrorAction SilentlyContinue).UseNexusForGameBarEnabled
        if ($tglGameBar) { $tglGameBar.IsChecked = ($regGameBar -eq 0) }

        # 12. Diğer (Other)
        $regHideSet = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Name "SettingsPageVisibility" -ErrorAction SilentlyContinue).SettingsPageVisibility
        if ($tglHideSettingsHome) { $tglHideSettingsHome.IsChecked = ($regHideSet -match "hide:home") }

        $regBrave = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\BraveSoftware\Brave" -Name "BraveRewardsDisabled" -ErrorAction SilentlyContinue).BraveRewardsDisabled
        if ($tglBraveBloat) { $tglBraveBloat.IsChecked = ($regBrave -eq 1) }

        if ($lblTweaksStatus) {
            $lblTweaksStatus.Text = "Sistem ayarları güncel. Değiştirmek istediğiniz ayarları seçip alttaki 'Değişikliği Uygula' butonuna tıklayın."
        }

        # Baseline (Orijinal Sistem Durumu) Senkronizasyonu
        $script:tweaksBaseline.Clear()
        if ($tweakToggleMap) {
            foreach ($ctrlName in $tweakToggleMap.Keys) {
                $c = $window.FindName($ctrlName)
                if ($c) { $script:tweaksBaseline[$ctrlName] = [bool]$c.IsChecked }
            }
        }
        if ($script:comboTweakMap) {
            foreach ($cmbName in $script:comboTweakMap.Keys) {
                $c = $window.FindName($cmbName)
                if ($c) { $script:tweaksBaseline[$cmbName] = [int]$c.SelectedIndex }
            }
        }
    } finally {
        $script:isUpdatingTweaksUI = $false
        Update-PendingTweaksUI
    }
}


