# ------------------------------------------------------------------------------
# Çift Yönlü İnce Ayar Uygulama / Geri Alma Fonksiyonu
# ------------------------------------------------------------------------------
function Execute-TweakToggle([string]$id, [bool]$turnOn) {
    if ($script:isUpdatingTweaksUI) { return }

    $meta = if ($Script:TweaksMeta) { $Script:TweaksMeta[$id] } else { $null }
    $twName = if ($meta) { $meta.Name } else { $id }
    $stateWordConsole = if ($turnOn) { "[AÇIK / ETKİN]" } else { "[KAPALI / VARSAYILAN]" }
    Write-CmdLog "İNCE AYAR" ">>> $twName -> $stateWordConsole" "Yellow"

    try {
        switch ($id) {
            "Telemetry" {
                if ($turnOn) {
                    # Raphire/Win11Debloat DisableTelemetry: AllowTelemetry (HKLM 2x), Gizlilik, Reklam, Giris ve Edge (15/15)
                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\DataCollection" "AllowTelemetry" 0
                    Set-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" "AllowTelemetry" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo" "Enabled" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Privacy" "TailoredExperiencesWithDiagnosticDataEnabled" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Speech_OneCore\Settings\OnlineSpeechPrivacy" "HasAccepted" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Input\TIPC" "Enabled" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\InputPersonalization" "RestrictImplicitInkCollection" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\InputPersonalization" "RestrictImplicitTextCollection" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\InputPersonalization\TrainedDataStore" "HarvestContacts" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Personalization\Settings" "AcceptedPrivacyPolicy" 0
                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\System" "PublishUserActivities" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "NumberOfSIUFInPeriod" 0
                    Remove-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "PeriodInNanoSeconds"
                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Edge" "PersonalizationReportingEnabled" 0
                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Edge" "DiagnosticData" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "Start_TrackProgs" 0

                    # Servisler
                    Stop-Service "DiagTrack" -WarningAction SilentlyContinue -ErrorAction SilentlyContinue
                    Set-Service "DiagTrack" -StartupType Disabled -ErrorAction SilentlyContinue
                    Write-CmdLog "SERVİS" "Stop-Service 'DiagTrack' & StartupType -> Disabled" "DarkYellow"
                    Stop-Service "dmwappushservice" -WarningAction SilentlyContinue -ErrorAction SilentlyContinue
                    Set-Service "dmwappushservice" -StartupType Disabled -ErrorAction SilentlyContinue
                    Write-CmdLog "SERVİS" "Stop-Service 'dmwappushservice' & StartupType -> Disabled" "DarkYellow"

                    # Zamanlanmis gorevler
                    @(
                        "\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser",
                        "\Microsoft\Windows\Application Experience\ProgramDataUpdater",
                        "\Microsoft\Windows\Customer Experience Improvement Program\Consolidator",
                        "\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip",
                        "\Microsoft\Windows\DiskDiagnostic\Microsoft-Windows-DiskDiagnosticDataCollector"
                    ) | ForEach-Object {
                        try {
                            $tPath = $_ -replace '[^\\]+$',''
                            $tName = $_ -replace '^.*\\',''
                            Disable-ScheduledTask -TaskPath $tPath -TaskName $tName -ErrorAction SilentlyContinue | Out-Null
                            Write-CmdLog "GÖREV" "Disable-ScheduledTask: '$tName'" "DarkCyan"
                        } catch {}
                    }
                } else {
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\DataCollection" "AllowTelemetry"
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" "AllowTelemetry"
                    Set-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" "MaxTelemetryAllowed" 3
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Diagnostics\DiagTrack" "ShowedToastAtLevel" 3
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo" "Enabled" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Privacy" "TailoredExperiencesWithDiagnosticDataEnabled" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\Speech_OneCore\Settings\OnlineSpeechPrivacy" "HasAccepted" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\Input\TIPC" "Enabled" 1
                    Remove-AllUsersRegistryValue "Software\Microsoft\InputPersonalization" "RestrictImplicitInkCollection"
                    Remove-AllUsersRegistryValue "Software\Microsoft\InputPersonalization" "RestrictImplicitTextCollection"
                    Set-AllUsersRegistryValue "Software\Microsoft\InputPersonalization\TrainedDataStore" "HarvestContacts" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\Personalization\Settings" "AcceptedPrivacyPolicy" 1
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\System" "PublishUserActivities"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "NumberOfSIUFInPeriod"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "PeriodInNanoSeconds"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Edge" "PersonalizationReportingEnabled"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Edge" "DiagnosticData"
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "Start_TrackProgs" 1

                    Set-Service "DiagTrack" -StartupType Automatic -ErrorAction SilentlyContinue
                    Start-Service "DiagTrack" -ErrorAction SilentlyContinue
                    Write-CmdLog "SERVİS" "Start-Service 'DiagTrack' & StartupType -> Automatic" "DarkYellow"
                    Set-Service "dmwappushservice" -StartupType Automatic -ErrorAction SilentlyContinue
                    Start-Service "dmwappushservice" -ErrorAction SilentlyContinue
                    Write-CmdLog "SERVİS" "Start-Service 'dmwappushservice' & StartupType -> Automatic" "DarkYellow"

                    @(
                        "\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser",
                        "\Microsoft\Windows\Application Experience\ProgramDataUpdater",
                        "\Microsoft\Windows\Customer Experience Improvement Program\Consolidator",
                        "\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip",
                        "\Microsoft\Windows\DiskDiagnostic\Microsoft-Windows-DiskDiagnosticDataCollector"
                    ) | ForEach-Object {
                        try {
                            $tPath = $_ -replace '[^\\]+$',''
                            $tName = $_ -replace '^.*\\',''
                            Enable-ScheduledTask -TaskPath $tPath -TaskName $tName -ErrorAction SilentlyContinue | Out-Null
                            Write-CmdLog "GÖREV" "Enable-ScheduledTask: '$tName'" "DarkCyan"
                        } catch {}
                    }
                }
            }
            "DiagtrackListener" {
                $alPath = "HKLM\SYSTEM\CurrentControlSet\Control\WMI\AutoLogger\Diagtrack-Listener"
                $val = if ($turnOn) { 0 } else { 1 }

                # 1. Standart doğrudan yazmayı dene
                try {
                    Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\WMI\AutoLogger\Diagtrack-Listener" -Name "Start" -Value $val -Type DWord -Force -ErrorAction SilentlyContinue
                } catch {}
                & reg.exe add $alPath /v "Start" /t REG_DWORD /d $val /f 2>&1 | Out-Null

                # 2. Değerin yazılıp yazılmadığını kontrol et
                $readCurrentVal = {
                    $cur = -1
                    try {
                        $valProp = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\WMI\AutoLogger\Diagtrack-Listener" -Name "Start" -ErrorAction SilentlyContinue).Start
                        if ($null -ne $valProp) {
                            $cur = [int]$valProp
                        } else {
                            $regQuery = & reg.exe query $alPath /v Start 2>&1
                            if ($regQuery -match "Start\s+REG_DWORD\s+0x([0-9a-fA-F]+)") {
                                $cur = [Convert]::ToInt32($matches[1], 16)
                            }
                        }
                    } catch {}
                    return $cur
                }

                $checkVal = & $readCurrentVal

                # 3. Eğer erişim engellendiyse (Windows 11 korumalı anahtar): SYSTEM köprüsüyle yaz
                if ($checkVal -ne $val) {
                    $taskName = "TemizWin_DiagTrack"
                    try {
                        $taskCmd = "cmd.exe /c reg.exe add `"$alPath`" /v Start /t REG_DWORD /d $val /f"
                        & schtasks.exe /create /tn $taskName /tr $taskCmd /sc ONCE /st 23:59 /ru "NT AUTHORITY\SYSTEM" /rl HIGHEST /f 2>&1 | Out-Null
                        & schtasks.exe /run /tn $taskName 2>&1 | Out-Null

                        # Akıllı bekleme: Değerin güncellenmesini 2.5 saniyeye kadar kontrol et
                        $sw = [System.Diagnostics.Stopwatch]::StartNew()
                        while ($sw.ElapsedMilliseconds -lt 2500) {
                            Start-Sleep -Milliseconds 100
                            $checkVal = & $readCurrentVal
                            if ($checkVal -eq $val) { break }
                        }
                    } catch {}
                    finally {
                        & schtasks.exe /delete /tn $taskName /f 2>&1 | Out-Null
                    }
                }

                # 4. Son duruma göre logla
                if ($checkVal -eq $val) {
                    if ($turnOn) {
                        Write-CmdLog "AYAR" "AutoLogger\Diagtrack-Listener -> Start: 0 (Devre Dışı)" "Green"
                    } else {
                        Write-CmdLog "AYAR" "AutoLogger\Diagtrack-Listener -> Start: 1 (Varsayılan/Etkin)" "DarkYellow"
                    }
                } else {
                    Write-CmdLog "UYARI" "AutoLogger\Diagtrack-Listener izni korumalı, değer güncellenemedi." "Yellow"
                }
            }
            "TelemetryTasks" {
                $targetTasks = @(
                    "\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser",
                    "\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser Exp",
                    "\Microsoft\Windows\Application Experience\ProgramDataUpdater",
                    "\Microsoft\Windows\Application Experience\StartupAppTask",
                    "\Microsoft\Windows\Application Experience\PcaPatchDbTask",
                    "\Microsoft\Windows\Application Experience\MareBackup",
                    "\Microsoft\Windows\Application Experience\SdbinstMergeDbTask",
                    "\Microsoft\Windows\Customer Experience Improvement Program\Consolidator",
                    "\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip",
                    "\Microsoft\Windows\DiskDiagnostic\Microsoft-Windows-DiskDiagnosticDataCollector",
                    "\Microsoft\Windows\Feedback\Siuf\DmClient",
                    "\Microsoft\Windows\Feedback\Siuf\DmClientOnScenarioDownload",
                    "\Microsoft\Windows\Windows Error Reporting\QueueReporting"
                )

                if ($turnOn) {
                    foreach ($t in $targetTasks) {
                        try {
                            $tPath = $t -replace '[^\\]+$',''
                            $tName = $t -replace '^.*\\',''
                            Disable-ScheduledTask -TaskPath $tPath -TaskName $tName -ErrorAction SilentlyContinue | Out-Null
                            cmd.exe /c "schtasks /Change /TN `"$t`" /Disable" 2>$null | Out-Null
                            Write-CmdLog "GÖREV" "Disable-ScheduledTask: '$tName'" "DarkCyan"
                        } catch {}
                    }

                    try {
                        Get-ScheduledTask -TaskPath "\Microsoft\Windows\Application Experience\" -ErrorAction SilentlyContinue | ForEach-Object {
                            Disable-ScheduledTask -InputObject $_ -ErrorAction SilentlyContinue | Out-Null
                            cmd.exe /c "schtasks /Change /TN `"$($_.TaskPath)$($_.TaskName)`" /Disable" 2>$null | Out-Null
                        }
                    } catch {}

                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\DataCollection" "DoNotShowFeedbackNotifications" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "NumberOfSIUFInPeriod" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "PeriodInNanoSeconds" 0

                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting" "Disabled" 1
                    Set-MachinePolicyValue "SOFTWARE\Microsoft\Windows\Windows Error Reporting" "Disabled" 1

                    Write-CmdLog "AYAR" "Telemetri zamanlanmış görevleri kapatıldı ve ilkeler uygulandı." "Green"
                } else {
                    foreach ($t in $targetTasks) {
                        try {
                            $tPath = $t -replace '[^\\]+$',''
                            $tName = $t -replace '^.*\\',''
                            Enable-ScheduledTask -TaskPath $tPath -TaskName $tName -ErrorAction SilentlyContinue | Out-Null
                            cmd.exe /c "schtasks /Change /TN `"$t`" /Enable" 2>$null | Out-Null
                            Write-CmdLog "GÖREV" "Enable-ScheduledTask: '$tName'" "DarkCyan"
                        } catch {}
                    }

                    try {
                        Get-ScheduledTask -TaskPath "\Microsoft\Windows\Application Experience\" -ErrorAction SilentlyContinue | ForEach-Object {
                            Enable-ScheduledTask -InputObject $_ -ErrorAction SilentlyContinue | Out-Null
                            cmd.exe /c "schtasks /Change /TN `"$($_.TaskPath)$($_.TaskName)`" /Enable" 2>$null | Out-Null
                        }
                    } catch {}

                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\DataCollection" "DoNotShowFeedbackNotifications"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "NumberOfSIUFInPeriod"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Siuf\Rules" "PeriodInNanoSeconds"

                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting" "Disabled"
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\Windows Error Reporting" "Disabled"

                    Write-CmdLog "AYAR" "Telemetri zamanlanmış görevleri varsayılana döndürüldü (Etkin)." "DarkYellow"
                }
