            "Sandbox" {
                if ($turnOn) {
                    # 1. BIOS Donanım Sanallaştırması (VT-x / AMD-V) Kontrolü
                    $cpuVirt = (Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1).VirtualizationFirmwareEnabled
                    if ($cpuVirt -eq $false) {
                        Write-CmdLog "SANDBOX" "UYARI: BIOS/UEFI üzerinde Sanallaştırma (VT-x / AMD-V) kapalı!" "Yellow"
                        if ($lblTweaksStatus) {
                            $lblTweaksStatus.Text = "⚠️ BIOS'ta Sanallaştırma (VT-x / AMD-V) kapalı! Önce BIOS'tan açmalısınız."
                            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
                        }
                        [System.Windows.MessageBox]::Show($window, "Windows Sandbox kullanabilmeniz için işlemcinizin sanallaştırma teknolojisinin (Intel VT-x veya AMD-V) BIOS/UEFI ayarlarından açık olması gerekir.`n`nŞu anda sisteminizde donanım sanallaştırması devre dışı görünüyor.", "Sanallaştırma Kapalı", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
                        if ($tglSandbox) { $tglSandbox.IsChecked = $false }
                        return
                    }

                    $runningDism = Get-Process -Name "dism" -ErrorAction SilentlyContinue
                    if ($runningDism) {
                        Write-CmdLog "SANDBOX" "Arka planda başka bir DISM işlemi çalışıyor, sıraya alınıyor..." "Yellow"
                    }
                }

                # DISM işlemini yürüt ve tamamlanmasını bekle (Arayüz donmaması için Dispatcher pompası kullanılır)
                if ($tglSandbox) { $tglSandbox.IsEnabled = $false }
                if ($lblTweaksStatus) {
                    $lblTweaksStatus.Text = if ($turnOn) { "⏳ Windows Sandbox bileşenleri yapılandırılıyor, lütfen bekleyin..." } else { "⏳ Windows Sandbox devre dışı bırakılıyor..." }
                    $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
                }
                if ($window -and $window.Dispatcher) {
                    $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
                }
                Write-CmdLog "SANDBOX" $(if ($turnOn) { "Windows Sandbox özelliği yapılandırılıyor (DISM)..." } else { "Windows Sandbox devre dışı bırakılıyor (DISM)..." }) "Cyan"

                $sbAction = if ($turnOn) { "/enable-feature" } else { "/disable-feature" }
                $sbLogFile = [System.IO.Path]::Combine($env:TEMP, "TemizWin_Sandbox_dism.log")
                if (Test-Path $sbLogFile) { Remove-Item $sbLogFile -Force -ErrorAction SilentlyContinue }

                $psi = New-Object System.Diagnostics.ProcessStartInfo
                $psi.FileName = "dism.exe"
                $psi.Arguments = "/online $sbAction /featurename:Containers-DisposableClientVM /norestart /quiet /logpath:`"$sbLogFile`""
                $psi.UseShellExecute = $false
                $psi.CreateNoWindow = $true

                try {
                    $sbProc = [System.Diagnostics.Process]::Start($psi)
                    while (-not $sbProc.HasExited) {
                        Start-Sleep -Milliseconds 250
                        if ($window -and $window.Dispatcher) {
                            $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
                        }
                    }
                    $code = $sbProc.ExitCode
                    $sbProc.Dispose()

                    if ($tglSandbox) { $tglSandbox.IsEnabled = $true }

                    if ($code -eq 0 -or $code -eq 3010) {
                        Write-CmdLog "SANDBOX" "✓ Windows Sandbox işlemi başarıyla tamamlandı (Çıkış Kodu: $code)." "Green"
                        if ($lblTweaksStatus) {
                            $lblTweaksStatus.Text = "✅ Windows Sandbox başarıyla yapılandırıldı!"
                            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#22C55E")
                        }
                    } else {
                        Write-CmdLog "SANDBOX" "✗ Windows Sandbox DISM hatası oluştu (Kod: $code)." "Red"
                        if ($lblTweaksStatus) {
                            $lblTweaksStatus.Text = "❌ Windows Sandbox işlemi tamamlanamadı (Hata Kodu: $code)."
                            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
                        }
                        if ($tglSandbox) { $tglSandbox.IsChecked = (-not $turnOn) }
                    }
                } catch {
                    if ($tglSandbox) { $tglSandbox.IsEnabled = $true }
                    Write-CmdLog "SANDBOX" "✗ DISM başlatılamadı: $($_.Exception.Message)" "Red"
                    if ($lblTweaksStatus) {
                        $lblTweaksStatus.Text = "❌ DISM başlatılamadı: $($_.Exception.Message)"
                        $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
                    }
                }
