                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\SearchSettings" "IsDynamicSearchBoxEnabled" (1 - $val)
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\SearchSettings" "IsDeviceSearchHistoryEnabled" (1 - $val)
            }
