            "HideTaskView" {
                $val = if ($turnOn) { 0 } else { 1 }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "ShowTaskViewButton" $val
            }
            "DisableWidgets" {
                $val = if ($turnOn) { 0 } else { 1 }
                if ($turnOn) {
                    # 1. Windows 11 UCPD (User Choice Protection Driver) korumasını devre dışı bırak
                    try {
                        Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\UCPD" -Name "Start" -Value 4 -Type DWord -Force -ErrorAction SilentlyContinue
                        schtasks /Change /TN "\Microsoft\Windows\AppxDeploymentClient\UCPD velocity" /Disable 2>$null | Out-Null
                        Write-CmdLog "UCPD" "UCPD sürücüsü ve koruma görevi devre dışı bırakıldı (Start=4)" "Cyan"
                    } catch {}

                    # 2. Grup İlkeleri (Windows 11 Dsh ve Windows 10/11 Feeds)
                    try {
                        $dshPath = "HKLM:\SOFTWARE\Policies\Microsoft\Dsh"
                        if (-not (Test-Path $dshPath)) { New-Item -Path $dshPath -Force -ErrorAction SilentlyContinue | Out-Null }
                        Set-ItemProperty -Path $dshPath -Name "AllowNewsAndInterests" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                        Write-CmdLog "POLICY" "Set-ItemProperty -Path '$dshPath' -Name 'AllowNewsAndInterests' -Value 0" "Blue"
                    } catch {}

                    try {
                        $feedsPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Feeds"
                        if (-not (Test-Path $feedsPath)) { New-Item -Path $feedsPath -Force -ErrorAction SilentlyContinue | Out-Null }
                        Set-ItemProperty -Path $feedsPath -Name "EnableFeeds" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                        Write-CmdLog "POLICY" "Set-ItemProperty -Path '$feedsPath' -Name 'EnableFeeds' -Value 0" "Blue"
                    } catch {}

                    # 3. Görev Çubuğu Widget Butonu (HKCU ve Kullanıcı Profilleri)
                    try {
                        Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarDa" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                    } catch {}
                    try {
                        Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Feeds" -Name "ShellFeedsTaskbarViewMode" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue
                    } catch {}

                    # 4. Arka planda çalışan Widget süreçlerini sonlandır
                    Get-Process *Widget* -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
                } else {
                    # Geri Açma / Varsayılana Döndürme
                    try {
                        Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Dsh" "AllowNewsAndInterests"
                    } catch {}
                    try {
                        Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\Windows Feeds" "EnableFeeds"
                    } catch {}
                    try {
                        Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarDa" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                    } catch {}
                    try {
                        Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Feeds" -Name "ShellFeedsTaskbarViewMode" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
                    } catch {}
                    try {
                        Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\UCPD" -Name "Start" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
                        schtasks /Change /TN "\Microsoft\Windows\AppxDeploymentClient\UCPD velocity" /Enable 2>$null | Out-Null
                    } catch {}
                }
            }
            "HideChat" {
