                }
            }
            "ShowAllTrayIcons" {
                $val = if ($turnOn) { 0 } else { 1 }
                $promotedVal = if ($turnOn) { 1 } else { 0 }
                Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer" -Name "EnableAutoTray" -Value $val -Type DWord -Force -ErrorAction SilentlyContinue
                try {
                    Get-ChildItem -Path "HKCU:\Control Panel\NotifyIconSettings" -ErrorAction SilentlyContinue | ForEach-Object {
                        Set-ItemProperty -Path $_.PSPath -Name "IsPromoted" -Value $promotedVal -Type DWord -Force -ErrorAction SilentlyContinue
                    }
                } catch {}
                Broadcast-ShellRefresh
            }
            "GameDVR" {
                $val = if ($turnOn) { 0 } else { 1 }
                Set-AllUsersRegistryValue "System\GameConfigStore" "GameDVR_Enabled" $val
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\GameDVR" "AppCaptureEnabled" $val
                Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\GameDVR" "AllowGameDVR" $val
            }
            "GameBar" {
                $val = if ($turnOn) { 0 } else { 1 }
                # Raphire/Win11Debloat Disable_Game_Bar_Integration: UseNexusForGameBarEnabled & URL Protocol Redirection
                Set-AllUsersRegistryValue "Software\Microsoft\GameBar" "UseNexusForGameBarEnabled" $val
                Set-AllUsersRegistryValue "Software\Microsoft\GameBar" "ShowStartupPanel" $val

                $gbClasses = @("ms-gamebar", "ms-gamebarservices")
                if ($turnOn) {
                    foreach ($gbCls in $gbClasses) {
                        $clsPath = "HKCU:\Software\Classes\$gbCls"
                        if (-not (Test-Path $clsPath)) { New-Item -Path $clsPath -Force -ErrorAction SilentlyContinue | Out-Null }
                        Set-ItemProperty -Path $clsPath -Name "(Default)" -Value "URL:$gbCls" -Force -ErrorAction SilentlyContinue
                        Set-ItemProperty -Path $clsPath -Name "URL Protocol" -Value "" -Force -ErrorAction SilentlyContinue
                        Set-ItemProperty -Path $clsPath -Name "NoOpenWith" -Value "" -Force -ErrorAction SilentlyContinue
                        $cmdPath = "$clsPath\shell\open\command"
                        if (-not (Test-Path $cmdPath)) { New-Item -Path $cmdPath -Force -ErrorAction SilentlyContinue | Out-Null }
                        Set-ItemProperty -Path $cmdPath -Name "(Default)" -Value "%SystemRoot%/System32/systray.exe" -Force -ErrorAction SilentlyContinue
                    }
                } else {
                    foreach ($gbCls in $gbClasses) {
                        Remove-Item -Path "HKCU:\Software\Classes\$gbCls" -Recurse -Force -ErrorAction SilentlyContinue
                    }
                }
            }
            "HideSettingsHome" {
                if ($turnOn) {
                    Set-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "SettingsPageVisibility" "hide:home" "String"
                } else {
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "SettingsPageVisibility"
