            "BraveBloat" {
                if ($turnOn) {
                    # Raphire/Win11Debloat Disable_Brave_Bloat: 6 Brave ilkesi
                    Set-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveRewardsDisabled" 1
                    Set-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveWalletDisabled" 1
                    Set-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveAIChatEnabled" 0
                    Set-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveVPNDisabled" 1
                    Set-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveTalkDisabled" 1
                    Set-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveNewsDisabled" 1
                } else {
                    Remove-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveRewardsDisabled"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveWalletDisabled"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveAIChatEnabled"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveVPNDisabled"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveTalkDisabled"
                    Remove-MachinePolicyValue "SOFTWARE\Policies\BraveSoftware\Brave" "BraveNewsDisabled"
                }
            }
            default {
                throw "Bilinmeyen ince ayar kimliği: $id"
            }
        }


        $meta = if ($Script:TweaksMeta -and $Script:TweaksMeta.ContainsKey($id)) { $Script:TweaksMeta[$id] } else { @{ Name = $id; Req = "Instant" } }
        $twName = $meta.Name
        $stateWord = if ($turnOn) { "uygulandı" } else { "varsayılana döndürüldü" }
        $stateWordConsole = if ($turnOn) { "Aktif Edildi / Uygulandı" } else { "Varsayılana Döndürüldü" }

        if ($lblTweaksStatus) {
            if ($meta.Req -eq "Reboot") {
                if ($script:pendingRebootTweaks) { $script:pendingRebootTweaks.Add($twName) | Out-Null }
                $lblTweaksStatus.Text = "⚠️ '$twName' $stateWord. (Tam etki için bilgisayarı yeniden başlatmanız önerilir.)"
                $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#F59E0B")
            } elseif ($meta.Req -eq "Explorer") {
                $lblTweaksStatus.Text = "⚡ '$twName' $stateWord. (Görmek için '⚡ Gezgini Yeniden Başlat' butonunu kullanabilirsiniz.)"
                $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
            } else {
                $lblTweaksStatus.Text = "✓ '$twName' başarıyla $stateWord ve anında aktif edildi."
                $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            }
        }
        try {
            $timestamp = (Get-Date).ToString("HH:mm:ss")
            if ($meta.Req -eq "Reboot") {
                Write-Host "[$timestamp] [İNCE AYAR] $twName -> $stateWordConsole 💻 (BİLGİ: Tam etki için bilgisayarı yeniden başlatmanız önerilir)" -ForegroundColor Yellow
            } elseif ($meta.Req -eq "Explorer") {
                Write-Host "[$timestamp] [İNCE AYAR] $twName -> $stateWordConsole ⚡ (Gezgin yeniden başlatıldığında anında görünür)" -ForegroundColor Cyan
            } else {
                Write-Host "[$timestamp] [İNCE AYAR] $twName -> $stateWordConsole [Anında Aktif]" -ForegroundColor Green
            }
        } catch {}
    } catch {
        if ($lblTweaksStatus) {
            $lblTweaksStatus.Text = "❌ '$twName' uygulanamadı: $($_.Exception.Message)"
            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
        }
        try {
            Write-Host "[$((Get-Date).ToString('HH:mm:ss'))] [HATA] İnce ayar ($id) uygulanamadı: $($_.Exception.Message)" -ForegroundColor Red
        } catch {}
    }
}

# ------------------------------------------------------------------------------
# ComboBox Ayar İşleyicisi
# ------------------------------------------------------------------------------
function Execute-ComboTweak([string]$id, [int]$idx) {
    if ($script:isUpdatingTweaksUI -or $idx -le 0) { return }

    $meta = $Script:TweaksMeta[$id]
    $twName = if ($meta) { $meta.Name } else { $id }
    Write-CmdLog "SEÇENEK" ">>> Açılır Menü Ayarı: '$twName' -> Seçenek [$idx]" "Yellow"

    try {
        switch ($id) {
            "Spotlight" {
                # Raphire/Win11Debloat DesktopSpotlight (3 Secenek):
                if ($idx -eq 1) {
                    # Secenek 1: 'Bu resim hakkinda bilgi edinin' simgesini goster (Varsayilan)
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop"
                    Remove-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" "{2cc5ca98-6485-489a-920e-b3e88a6ccce3}"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" "BackgroundType"
                    Broadcast-ShellRefresh
                } elseif ($idx -eq 2) {
                    # Secenek 2: 'Bu resim hakkinda bilgi edinin' masaustu simgesini gizle
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop"
                    Remove-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop"
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" "{2cc5ca98-6485-489a-920e-b3e88a6ccce3}" 1
                    Broadcast-ShellRefresh
                } elseif ($idx -eq 3) {
                    # Secenek 3: Windows Spotlight masaustu arka planini tamamen kapat
                    Set-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop" 1
                    Set-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop" 1
                    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" "{2cc5ca98-6485-489a-920e-b3e88a6ccce3}"
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" "RotatingImageOverlayEnabled" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" "RotatingImageSubscribed-338388Enabled" 0
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" "BackgroundType" 0
                    Broadcast-ShellRefresh
                }
            }
            "AltTabTabs" {
                $val = switch ($idx) { 1 { 3 } 2 { 2 } 3 { 1 } 4 { 0 } default { 2 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "MultiTaskingAltTabFilter" $val
            }
            "LaunchTo" {
                $val = switch ($idx) { 1 { 2 } 2 { 1 } 3 { 3 } 4 { 4 } default { 2 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "LaunchTo" $val
            }
            "DriveLetters" {
                $val = switch ($idx) { 1 { 0 } 2 { 4 } 3 { 1 } 4 { 2 } default { 0 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer" "ShowDriveLettersFirst" $val
                Broadcast-ShellRefresh
            }
            "SearchStyle" {
                $val = switch ($idx) { 1 { 2 } 2 { 3 } 3 { 1 } 4 { 0 } default { 2 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Search" "SearchboxTaskbarMode" $val
            }
            "ShowAppsOn" {
                $val = switch ($idx) { 1 { 0 } 2 { 1 } 3 { 2 } default { 0 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "MMTaskbarMode" $val
            }
            "CombineMain" {
                $val = switch ($idx) { 1 { 0 } 2 { 1 } 3 { 2 } default { 0 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "TaskbarGlomLevel" $val
            }
            "CombineSecondary" {
                $val = switch ($idx) { 1 { 0 } 2 { 1 } 3 { 2 } default { 0 } }
                Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "MMTaskbarGlomLevel" $val
            }
            "AllAppsView" {
                # Raphire/Win11Debloat StartAllAppsView: 4 Mod (Hide, Category, Grid, List)
                if ($idx -eq 1) {
                    # 1: Hide (Tüm Uygulamaları Gizle - DisableStartAllApps)
                    Set-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms" 1
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms" 1
                } elseif ($idx -eq 2) {
                    # 2: Category (Kategori Görünümü - Varsayılan)
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Start" "AllAppsViewMode" 0
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
                } elseif ($idx -eq 3) {
                    # 3: Grid (Izgara Görünümü)
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Start" "AllAppsViewMode" 1
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
                } elseif ($idx -eq 4) {
                    # 4: List (Liste Görünümü)
                    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Start" "AllAppsViewMode" 2
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
                    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
                }
            }
            "PinnedApps" {
                $startPkgPath = "$env:LocalAppData\Packages\Microsoft.Windows.StartMenuExperienceHost_cw5n1h2txyewy\LocalState"
                if ($idx -eq 1) {
                    # Raphire/Win11Debloat ClearStart: start2.bin dosyasini yedekle ve 972 baytlik temiz sablonla degistir
                    Stop-Process -Name "StartMenuExperienceHost" -Force -ErrorAction SilentlyContinue
                    Start-Sleep -Milliseconds 250
                    if (-not (Test-Path $startPkgPath)) {
                        New-Item -Path $startPkgPath -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
                    }
                    if (Test-Path "$startPkgPath\start2.bin") {
                        Copy-Item "$startPkgPath\start2.bin" "$startPkgPath\start2.bin.temizwin.bak" -Force -ErrorAction SilentlyContinue
                    }
                    if (Test-Path "$startPkgPath\start.bin") {
                        Copy-Item "$startPkgPath\start.bin" "$startPkgPath\start.bin.temizwin.bak" -Force -ErrorAction SilentlyContinue
                    }

                    # Raphire 972 baytlik bos start2.bin sablonunu yaz
                    $blankB64 = ""
                    $blankBytes = [System.Convert]::FromBase64String($blankB64)
                    [System.IO.File]::WriteAllBytes("$startPkgPath\start2.bin", $blankBytes)

                    # Kilit olusturmayan temizleme: MDM policy kilidini kaldir ki kullanici yeni uygulama sabitleyebilsin
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\Explorer" "ConfigureStartPins"
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\PolicyManager\current\device\Start" "ConfigureStartPins"
                    Remove-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\Explorer" "ConfigureStartPins"

                    Start-Sleep -Milliseconds 100
                    Stop-Process -Name "StartMenuExperienceHost" -Force -ErrorAction SilentlyContinue
                } elseif ($idx -eq 2) {
                    # Orijinal / Onceki Sabitlenmis Uygulama Duzenini Geri Yukle
                    Stop-Process -Name "StartMenuExperienceHost" -Force -ErrorAction SilentlyContinue
                    Start-Sleep -Milliseconds 250
                    if (Test-Path "$startPkgPath\start2.bin.temizwin.bak") {
                        Copy-Item "$startPkgPath\start2.bin.temizwin.bak" "$startPkgPath\start2.bin" -Force -ErrorAction SilentlyContinue
                        Remove-Item "$startPkgPath\start2.bin.temizwin.bak" -Force -ErrorAction SilentlyContinue
                    }
                    if (Test-Path "$startPkgPath\start.bin.temizwin.bak") {
                        Copy-Item "$startPkgPath\start.bin.temizwin.bak" "$startPkgPath\start.bin" -Force -ErrorAction SilentlyContinue
                        Remove-Item "$startPkgPath\start.bin.temizwin.bak" -Force -ErrorAction SilentlyContinue
                    }
                    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\Explorer" "ConfigureStartPins"
                    Remove-MachinePolicyValue "SOFTWARE\Microsoft\PolicyManager\current\device\Start" "ConfigureStartPins"
                    Remove-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\Explorer" "ConfigureStartPins"
                    Start-Sleep -Milliseconds 100
                    Stop-Process -Name "StartMenuExperienceHost" -Force -ErrorAction SilentlyContinue
                }
            }
            default {
                throw "Bilinmeyen açılır ayar kimliği: $id"
            }
        }


        if ($lblTweaksStatus) {
            $lblTweaksStatus.Text = "⚡ Seçenek başarıyla uygulandı! (Görmek için '⚡ Gezgini Yeniden Başlat' butonunu kullanabilirsiniz.)"
            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#38BDF8")
        }
        try {
            Write-Host "[$((Get-Date).ToString('HH:mm:ss'))] [İNCE AYAR] $id -> Seçenek ($idx) uygulandı ⚡ (Gezgin yeniden başlatıldığında anında görünür)" -ForegroundColor Cyan
        } catch {}
    } catch {
        if ($lblTweaksStatus) {
            $lblTweaksStatus.Text = "❌ Seçenek ($id) uygulanamadı: $($_.Exception.Message)"
            $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#EF4444")
        }
        try {
            Write-Host "[$((Get-Date).ToString('HH:mm:ss'))] [HATA] Açılır ayar ($id) uygulanamadı: $($_.Exception.Message)" -ForegroundColor Red
        } catch {}
    }
}

# ------------------------------------------------------------------------------
# Toggle ve Kontrol Tıklama Olaylarını Bağlama (Bekleyen Değişiklik Sırası)
# ------------------------------------------------------------------------------
foreach ($ctrlName in $tweakToggleMap.Keys) {
    $ctrl = $window.FindName($ctrlName)
    if ($ctrl) {
        $ctrl.Add_Checked({
            Update-PendingTweaksUI
        })
        $ctrl.Add_Unchecked({
            Update-PendingTweaksUI
        })
    }
}

# ComboBox Olayları (Seçim değiştiğinde bekleyen değişiklik sayısını günceller)
if ($cmbSpotlight) { $cmbSpotlight.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbAltTabTabs) { $cmbAltTabTabs.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbLaunchTo) { $cmbLaunchTo.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbDriveLetters) { $cmbDriveLetters.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbSearchStyle) { $cmbSearchStyle.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbShowAppsOn) { $cmbShowAppsOn.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbCombineMain) { $cmbCombineMain.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbCombineSecondary) { $cmbCombineSecondary.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbAllAppsView) { $cmbAllAppsView.Add_SelectionChanged({ Update-PendingTweaksUI }) }
if ($cmbPinnedApps) { $cmbPinnedApps.Add_SelectionChanged({ Update-PendingTweaksUI }) }

# ------------------------------------------------------------------------------
# Bekleyen Değişiklikleri Geri Al (↺) Butonu Olayı
# ------------------------------------------------------------------------------
if ($btnDiscardPendingTweaks) {
    $btnDiscardPendingTweaks.Add_Click({
        $script:isUpdatingTweaksUI = $true
        try {
            foreach ($ctrlName in $script:tweaksBaseline.Keys) {
                $c = $window.FindName($ctrlName)
                if ($c -is [System.Windows.Controls.CheckBox]) {
                    $c.IsChecked = [bool]$script:tweaksBaseline[$ctrlName]
                } elseif ($c -is [System.Windows.Controls.ComboBox]) {
                    $c.SelectedIndex = [int]$script:tweaksBaseline[$ctrlName]
                }
            }
        } finally {
            $script:isUpdatingTweaksUI = $false
        }
        Update-PendingTweaksUI
        if ($lblTweaksStatus) {
            $lblTweaksStatus.Text = "Tüm değişiklikler geri alındı, kaydedilmemiş seçimler sıfırlandı."
        }
    })
}

# ------------------------------------------------------------------------------
# Bekleyen Değişiklikleri Toplu Uygula (✨) Butonu Olayı
# ------------------------------------------------------------------------------
if ($btnApplyPendingTweaks) {
    $btnApplyPendingTweaks.Add_Click({
        $changes = @(Get-PendingTweaks | Where-Object { $null -ne $_ -and $_.ControlName })
        $total = $changes.Count
        if ($total -eq 0) { return }

        $btnApplyPendingTweaks.IsEnabled = $false
        if ($btnDiscardPendingTweaks) { $btnDiscardPendingTweaks.IsEnabled = $false }

        $rebootTweaksList = [System.Collections.Generic.List[string]]::new()
        $needsExplorerRestart = $false

        try {
            $currIndex = 0
            foreach ($item in $changes) {
                $currIndex++
                $btnApplyPendingTweaks.Content = "⏳ Uygulanıyor... ($currIndex/$total)"
                if ($lblTweaksStatus) {
                    $lblTweaksStatus.Text = "Uygulanıyor ($currIndex/$total): $($item.TweakId)..."
                }
                if ($window -and $window.Dispatcher) {
                    $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
                }

                $meta = $Script:TweaksMeta[$item.TweakId]
                $displayName = if ($meta) { $meta.Name } else { $item.TweakId }
                $req = if ($meta) { $meta.Req } else { "Instant" }

                if ($item.Type -eq "Toggle") {
                    Execute-TweakToggle $item.TweakId $item.CurrentValue
                } elseif ($item.Type -eq "Combo") {
                    Execute-ComboTweak $item.TweakId $item.CurrentValue
                }

                if ($req -eq "Reboot") {
                    $rebootTweaksList.Add($displayName)
                    if ($script:pendingRebootTweaks) {
                        $script:pendingRebootTweaks.Add($displayName) | Out-Null
                    }
                } elseif ($req -eq "Explorer") {
                    $needsExplorerRestart = $true
                }

                # Baseline'ı güncel duruma çek
                $script:tweaksBaseline[$item.ControlName] = $item.CurrentValue
            }

            # Kabuk yenileme
            Broadcast-ShellRefresh

            if ($lblTweaksStatus) {
                $lblTweaksStatus.Text = "✓ $total adet ince ayar başarıyla uygulandı!"
                $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            }
            Write-CmdLog "İNCE AYAR" ">>> $total adet ince ayar başarıyla tamamlandı." "Green"

            # Yeniden başlatma gerektiren ayar varsa kullanıcıya sor
            if ($rebootTweaksList.Count -gt 0) {
                $res = Show-ModernRebootPrompt $window $rebootTweaksList.ToArray()
                $script:isRebootPromptHandled = $true
            }
        } finally {
            if ($btnDiscardPendingTweaks) { $btnDiscardPendingTweaks.IsEnabled = $true }
            Update-PendingTweaksUI
        }
    })
}

# Gezgin Yenile Butonu (Kibar Kabuk ve Masaüstü Yenileme - Kaspersky / PDM Dostu)
if ($btnRestartExplorer) {
    $btnRestartExplorer.Add_Click({
        if ($lblTweaksStatus) { $lblTweaksStatus.Text = "Dosya Gezgini ve masaüstü arayüzü yenileniyor..." }
        if ($window -and $window.Dispatcher) {
            $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
        }
        Broadcast-ShellRefresh
        Start-Sleep -Milliseconds 300
        Broadcast-ShellRefresh
        if ($lblTweaksStatus) { $lblTweaksStatus.Text = "Dosya Gezgini ve masaüstü ayarları başarıyla yenilendi!" }
    })
}

# Gezgini Yeniden Başlat Butonu (explorer.exe sürecini baştan başlatır - Tüm görsel ayarları zorlar)
if ($btnKillRestartExplorer) {
    $btnKillRestartExplorer.Add_Click({
        if ($lblTweaksStatus) { $lblTweaksStatus.Text = "Dosya Gezgini (explorer.exe) yeniden başlatılıyor..." }
        try {
            Write-CmdLog "GEZGİN" "Stop-Process -Name 'explorer' -Force & Start-Process 'explorer.exe'" "Yellow"
            Stop-Process -Name "explorer" -Force -ErrorAction SilentlyContinue
            Start-Sleep -Milliseconds 800
            if (-not (Get-Process -Name "explorer" -ErrorAction SilentlyContinue)) {
                Start-Process "explorer.exe" -ErrorAction SilentlyContinue
            }
            if ($lblTweaksStatus) { $lblTweaksStatus.Text = "Dosya Gezgini başarıyla yeniden başlatıldı!" }
            Write-CmdLog "GEZGİN" "Dosya Gezgini başarıyla yeniden başlatıldı." "Green"
        } catch {
            if ($lblTweaksStatus) { $lblTweaksStatus.Text = "Hata: $($_.Exception.Message)" }
        }
    })
}

# Önerilenleri Uygula Butonu (⭐ En güvenli gizlilik ve performans ayarları)
if ($btnApplyRecommendedTweaks) {
    $btnApplyRecommendedTweaks.Add_Click({
        $confirmMsg = "⭐ Önerilen Ayarlar Topluca Uygulanacak:`n`n" +
            "• Telemetri ve tanılama verilerini kısıtlama`n" +
            "• Windows ipuçları ve kilit ekranı önerilerini kapatma`n" +
            "• Klasik sağ tık menüsünü etkinleştirme (Win 11)`n" +
            "• Copilot & Recall önizleme araçlarını kapatma`n" +
            "• Dosya uzantılarını görünür yapma`n" +
            "• Hızlı Başlatmayı kapatma (Temiz çekirdek açılışı)`n`n" +
            "(Not: Dilediğiniz zaman '↺ Tüm Ayarları Sıfırla' ile fabrika ayarlarına dönebilirsiniz.)`n`n" +
            "Önerilen ayarları uygulamak istiyor musunuz?"
        $ans = [System.Windows.MessageBox]::Show($window, $confirmMsg, "TemizWin - Önerilen Ayarları Uygula", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
        if ($ans -ne [System.Windows.MessageBoxResult]::Yes) { return }

        Write-CmdLog "ÖNERİLEN" ">>> Önerilen ince ayarlar topluca uygulanıyor..." "Green" 
        $recommendedList = @(
            "Telemetry", "DiagtrackListener", "TelemetryTasks", "Tips", "EdgeAds", "CopilotSettings", "Copilot", "Recall", "AdvancedAI",
            "ClassicContextMenu", "MouseAccel", "StickyKeys", "FastStartup",
            "PreventAutoRestart", "DeliveryOptimization", "CompanionApps",
            "FileExtensions", "DuplicateDrives", "DisableBingSearch", "DisableStoreSearch",
            "EndTask", "GameDVR"
        )
        foreach ($t in $recommendedList) {
            Execute-TweakToggle $t $true
        }
        Refresh-TweaksState
        if ($lblTweaksStatus) {
            $lblTweaksStatus.Text = "Tüm önerilen ayarlar başarıyla uygulandı! (Gezgini yenileyebilirsiniz)"
        }
    })
}

function Reset-AllComboTweaksToDefault {
    # 1. Spotlight -> Varsayilan: Simgesi Goster (Index 1) ve Spotlight aktif
    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop"
    Remove-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\CloudContent" "DisableSpotlightCollectionOnDesktop"
    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" "{2cc5ca98-6485-489a-920e-b3e88a6ccce3}"
    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" "BackgroundType"

    # 2. AltTab -> Varsayilan: Son 5 Sekme (Index 2, MultiTaskingAltTabFilter = 2)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "MultiTaskingAltTabFilter" 2

    # 3. LaunchTo -> Varsayilan: Baslangic / Giris (Index 1, LaunchTo = 2)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "LaunchTo" 2

    # 4. DriveLetters -> Varsayilan: Harfi Isimden Sonra Goster (Index 2, ShowDriveLettersFirst = 0)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer" "ShowDriveLettersFirst" 0

    # 5. SearchStyle -> Varsayilan: Arama Kutusu (Index 1, SearchboxTaskbarMode = 2)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Search" "SearchboxTaskbarMode" 2

    # 6. ShowAppsOn -> Varsayilan: Tum Gorev Cubuklarinda (Index 1, MMTaskbarMode = 0)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "MMTaskbarMode" 0

    # 7. CombineMain -> Varsayilan: Her Zaman (Index 1, TaskbarGlomLevel = 0)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "TaskbarGlomLevel" 0

    # 8. CombineSecondary -> Varsayilan: Her Zaman (Index 1, MMTaskbarGlomLevel = 0)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "MMTaskbarGlomLevel" 0

    # 9. AllAppsView -> Varsayılan: Kategori Görünümü (AllAppsViewMode = 0, NoStartMenuMorePrograms kaldır)
    Set-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Start" "AllAppsViewMode" 0
    Remove-MachinePolicyValue "SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"
    Remove-AllUsersRegistryValue "Software\Microsoft\Windows\CurrentVersion\Policies\Explorer" "NoStartMenuMorePrograms"

    # 10. PinnedApps -> Varsayilan / Onceki Duzeni Geri Yukle
    $startPkgPath = "$env:LocalAppData\Packages\Microsoft.Windows.StartMenuExperienceHost_cw5n1h2txyewy\LocalState"
    if (Test-Path "$startPkgPath\start2.bin.temizwin.bak") {
        Copy-Item "$startPkgPath\start2.bin.temizwin.bak" "$startPkgPath\start2.bin" -Force -ErrorAction SilentlyContinue
        Remove-Item "$startPkgPath\start2.bin.temizwin.bak" -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path "$startPkgPath\start.bin.temizwin.bak") {
        Copy-Item "$startPkgPath\start.bin.temizwin.bak" "$startPkgPath\start.bin" -Force -ErrorAction SilentlyContinue
        Remove-Item "$startPkgPath\start.bin.temizwin.bak" -Force -ErrorAction SilentlyContinue
    }
    Remove-MachinePolicyValue "SOFTWARE\Policies\Microsoft\Windows\Explorer" "ConfigureStartPins"
    Remove-MachinePolicyValue "SOFTWARE\Microsoft\PolicyManager\current\device\Start" "ConfigureStartPins"
    Remove-AllUsersRegistryValue "Software\Policies\Microsoft\Windows\Explorer" "ConfigureStartPins"
    Stop-Process -Name "StartMenuExperienceHost" -Force -ErrorAction SilentlyContinue

    Broadcast-ShellRefresh
}


# Sıfırla Butonu (↺ Windows Fabrika Varsayılanlarına Dön)
if ($btnResetAllTweaks) {
    $btnResetAllTweaks.Add_Click({
        $confirm = [System.Windows.MessageBox]::Show($window, "Tüm ayarlar Windows fabrika varsayılanlarına döndürülecek.`n`nBu işlem tüm optimizasyonları ve açılır menü seçeneklerini standart Windows ayarlarına çeker. Devam edilsin mi?", "Fabrika Ayarlarına Sıfırlama Onayı", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
        if ($confirm -eq [System.Windows.MessageBoxResult]::Yes) {
            Write-CmdLog "SIFIRLA" ">>> Tüm ayarlar Windows fabrika varsayılanlarına sıfırlanıyor..." "Red"
            if ($script:pendingRebootTweaks) { $script:pendingRebootTweaks.Add("Tüm İnce Ayarlar (Fabrika Varsayılanlarına Sıfırlama)") | Out-Null }
            foreach ($t in $tweakToggleMap.Values) {
                Execute-TweakToggle $t $false
            }
            # ComboBox ayarlarını da gerçek Windows varsayılanlarına sıfırla:
            Reset-AllComboTweaksToDefault

            # Arayüz durumunu canlı kayıt defterinden baştan oku (Tüm kutular ve ComboBox'lar gerçek varsayılanlarına geçsin):
            Refresh-TweaksState
            if ($lblTweaksStatus) {
                $lblTweaksStatus.Text = "✓ Tüm ayarlar ve açılır seçenekler Windows fabrika varsayılanlarına sıfırlandı."
                $lblTweaksStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#10B981")
            }
        }
    })
}

# Canlı Arama ve Filtreleme
if ($txtSearchTweaks) {
    $txtSearchTweaks.Text = "Ayar ara..."
    $txtSearchTweaks.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
    
    $txtSearchTweaks.Add_GotFocus({
        if ($txtSearchTweaks.Text -eq "Ayar ara...") {
            $txtSearchTweaks.Text = ""
            $txtSearchTweaks.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
        }
    })
    
    $txtSearchTweaks.Add_LostFocus({
        if ([string]::IsNullOrWhiteSpace($txtSearchTweaks.Text)) {
            $txtSearchTweaks.Text = "Ayar ara..."
            $txtSearchTweaks.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#64748B")
        }
    })

    $txtSearchTweaks.Add_TextChanged({
        $q = $txtSearchTweaks.Text.Trim()
        if ($q -eq "Ayar ara...") { $q = "" }
        $q = $q.ToLower()

        if ($pnlTweaksCategories) {
            foreach ($card in $pnlTweaksCategories.Children) {
                if ([string]::IsNullOrWhiteSpace($q)) {
                    $card.Visibility = [System.Windows.Visibility]::Visible
                    $sp = $card.Child
                    if ($sp -is [System.Windows.Controls.StackPanel]) {
                        foreach ($sub in $sp.Children) {
                            $sub.Visibility = [System.Windows.Visibility]::Visible
                        }
                    }
                } else {
                    $cardMatched = $false
                    $sp = $card.Child
                    if ($sp -is [System.Windows.Controls.StackPanel]) {
                        foreach ($sub in $sp.Children) {
                            if ($sub -is [System.Windows.Controls.Border]) {
                                # Check text in border
                                $itemText = ""
                                $queue = New-Object System.Collections.Queue
                                $queue.Enqueue($sub)
                                while ($queue.Count -gt 0) {
                                    $cur = $queue.Dequeue()
                                    if ($cur -is [System.Windows.Controls.TextBlock]) {
                                        $itemText += " " + $cur.Text
                                    }
                                    foreach ($ch in [System.Windows.LogicalTreeHelper]::GetChildren($cur)) {
                                        if ($ch -is [System.Windows.DependencyObject]) {
                                            $queue.Enqueue($ch)
                                        }
                                    }
                                }
                                if ($itemText.ToLower().Contains($q)) {
                                    $sub.Visibility = [System.Windows.Visibility]::Visible
                                    $cardMatched = $true
                                } else {
                                    $sub.Visibility = [System.Windows.Visibility]::Collapsed
                                }
                            }
                        }
                    }
                    if ($cardMatched) {
                        $card.Visibility = [System.Windows.Visibility]::Visible
                    } else {
                        $card.Visibility = [System.Windows.Visibility]::Collapsed
                    }
                }
            }
        }
    })
}

