if ($btnRestartExplorerFromCtx) {
    $btnRestartExplorerFromCtx.Add_Click({
        if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "Dosya Gezgini (explorer.exe) yeniden başlatılıyor..." }
        try {
            Write-CmdLog "GEZGİN" "Stop-Process -Name 'explorer' -Force & Start-Process 'explorer.exe'" "Yellow"
            Stop-Process -Name "explorer" -Force -ErrorAction SilentlyContinue
            Start-Sleep -Milliseconds 800
            if (-not (Get-Process -Name "explorer" -ErrorAction SilentlyContinue)) {
                Start-Process "explorer.exe" -ErrorAction SilentlyContinue
            }
            Broadcast-ShellRefresh
            if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "✓ Dosya Gezgini başarıyla yeniden başlatıldı! Tüm sağ tık menü değişiklikleri uygulandı." }
            Write-CmdLog "GEZGİN" "Dosya Gezgini başarıyla yeniden başlatıldı." "Green"
        } catch {
            if ($lblContextMenuStatus) { $lblContextMenuStatus.Text = "Hata: $($_.Exception.Message)" }
        }
    })
}

