# Özel Program Ekleme Butonları
if ($btnBrowseCustomApp) {
    $btnBrowseCustomApp.Add_Click({
        $dlg = New-Object Microsoft.Win32.OpenFileDialog
        $dlg.Title = "Sağ Tık Menüsüne Eklenecek Programı Seçin"
        $dlg.Filter = "Programlar (*.exe)|*.exe|Tüm Dosyalar (*.*)|*.*"
        if ($dlg.ShowDialog() -eq $true) {
            $txtCustomAppPath.Text = $dlg.FileName
            if ([string]::IsNullOrWhiteSpace($txtCustomAppName.Text)) {
                $txtCustomAppName.Text = [System.IO.Path]::GetFileNameWithoutExtension($dlg.FileName)
            }
        }
    })
}

if ($btnAddCustomApp) {
    $btnAddCustomApp.Add_Click({
        $name = if ($txtCustomAppName) { $txtCustomAppName.Text.Trim() } else { "" }
        $exe = if ($txtCustomAppPath) { $txtCustomAppPath.Text.Trim() } else { "" }
        $targetIdx = if ($cmbCustomAppTarget) { $cmbCustomAppTarget.SelectedIndex } else { 0 }
        if ($targetIdx -lt 0) { $targetIdx = 0 }

        if ([string]::IsNullOrWhiteSpace($name)) {
            [System.Windows.MessageBox]::Show("Lütfen sağ tık menüsünde görünecek bir menü başlığı girin.", "Eksik Bilgi", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            return
        }
        if ([string]::IsNullOrWhiteSpace($exe) -or -not (Test-Path $exe)) {
            [System.Windows.MessageBox]::Show("Lütfen geçerli bir çalıştırılabilir dosya (.exe) seçin veya tam yolunu yazın.", "Geçersiz Dosya", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            return
        }

        Add-CustomContextMenuItem $name $exe $targetIdx
        if ($txtCustomAppName) { $txtCustomAppName.Text = "" }
        if ($txtCustomAppPath) { $txtCustomAppPath.Text = "" }
        Refresh-ContextMenuList
    })
}

# WPF Penceresini Başlat (Ön Plana Getir ve Odakla)
$window.Add_SourceInitialized({
    $window.Topmost = $true
    $window.Topmost = $false
})
$window.Add_Loaded({
    $window.Activate()
    $window.Focus()
    Write-Host ""
    Write-Host "==========================================================================" -ForegroundColor Cyan
    Write-Host "             TEMIZWIN CANLI KOMUT VE OPERASYON KONSOLU (DEBUG LOG)         " -ForegroundColor White
    Write-Host "==========================================================================" -ForegroundColor Cyan
    Write-Host "[*] Grafik Arayüz Hazır! Arayüzde yaptığınız her işlem burada komut seviyesinde anında akacaktır." -ForegroundColor Green
    Write-Host "[*] Canlı komut akışı (Temizlik, Güncelleme, İnce Ayar, Servis, Sağlık) aktif..." -ForegroundColor DarkGray
    Write-Host "--------------------------------------------------------------------------" -ForegroundColor DarkGray
})
$window.ShowDialog() | Out-Null

Write-Host ""
Write-Host "[*] TemizWin kapatıldı. Canlı oturum sonlandırılıyor..." -ForegroundColor Yellow
Start-Sleep -Milliseconds 600
